pub(crate) struct CarriedSpellProgress {
    pub family: u8,
    pub persistent_experience: i32,
    pub runtime_experience: i32,
    pub unlocked_tier: i8,
    pub selected_tier: i8,
}

/// `sub_574A0` scans the remaining authored spell rows after group zero has
/// been consumed, excluding families already enabled or retained as learned.
fn source_spell_census(
    mission: &MissionContentSession,
    player: &PlayerSnapshot,
    consumed: &BTreeSet<u16>,
) -> [bool; 26] {
    let mut available = [false; 26];
    for feature in mission.authored_features() {
        let Ok(family) = usize::try_from(feature.subtype) else { continue };
        if feature.index != 0 && feature.kind == 15 && feature.activation_group != 0
            && !consumed.contains(&feature.index) && family < available.len()
            && player.enabled_spell_holders[family] == 0
            && player.spell_enabled_flags[family] == 0
        {
            available[family] = true;
        }
    }
    available
}

/// sub6D8B0 accepts a human wizard owner. Keep all player projections at
/// the same progression boundary as the source hit award. A counted award
/// adds its signed amount once, then performs one source tier visit.
fn award_source_spell_experience(live: &mut Mc2LiveState, owner: u16, family: u8, amount: i32) {
    if !live.shared_spells.mission_rewards().allows_experience() || !live
        .economy
        .entities
        .get(usize::from(owner))
        .is_some_and(|row| row.active && row.class == 3 && row.model == 0)
        || !live
            .shared_spells
            .players
            .iter()
            .any(|player| player.entity_index == owner)
    {
        return;
    }
    if family == CASTLE_SPELL_FAMILY {
        live.refresh_castle_spell_profile(owner, false, None);
    }
    award_family_spell_experience(
        &live.economy,
        &mut live.shared_spells,
        &mut live.core.players,
        live.core.context.spell_fire.as_mut(),
        owner,
        family,
        amount,
    );
}

fn publish_spell_progression(live: &mut Mc2LiveState, owner: u16, family: u8) {
    publish_family_spell_progression(
        &live.shared_spells,
        &mut live.core.players,
        live.core.context.spell_fire.as_mut(),
        owner,
        family,
    );
}

pub(super) fn award_family_spell_experience(
    arena: &SourceArena,
    shared: &mut Level2SharedSpellResetSession,
    players: &mut [PlayerSnapshot],
    fire: Option<&mut crate::SpellFireContext>,
    owner: u16,
    family: u8,
    amount: i32,
) {
    // NewEvent marks the raw player active;57F20 clears class with active.
    // A typed replacement cannot inherit that old human packet's reward.
    if owner == 0
        || !shared.mission_rewards().allows_experience()
        || arena.economy.live_arena_cursor_row(owner).is_some()
        || !arena
            .entities
            .get(usize::from(owner))
            .is_some_and(|row| row.active && row.class == 3 && row.model == 0)
        || !shared
            .players
            .iter()
            .any(|player| player.entity_index == owner)
    {
        return;
    }
    // sub_6D8B0 takes a signed source word, even when a producer counts
    // damage hits in an unsigned or wider accumulator.
    shared.award_spell_experience(owner, family, i32::from(amount as i16));
    publish_family_spell_progression(shared, players, fire, owner, family);
}

pub(super) fn publish_family_spell_progression(
    shared: &Level2SharedSpellResetSession,
    players: &mut [PlayerSnapshot],
    mut fire: Option<&mut crate::SpellFireContext>,
    owner: u16,
    family: u8,
) {
    shared.publish_spell_progression_family(players, fire.as_deref_mut(), owner, family);
    if family != CASTLE_SPELL_FAMILY {
        // sub_6D9C0 also caps Castle experience during every family visit.
        shared.publish_spell_progression_family(players, fire, owner, CASTLE_SPELL_FAMILY);
    }
}

/// Typed payload selected from the fixed numeric source slot at visit time.
///
/// This replaces the former friendly `u8` route tags.  The payload locates
/// the authoritative carrier; the compiled registry remains the authority
/// that selects which accepted handler family may receive it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SourceRoute {
    SpeedPickup,
    BadStone,
    House,
    Villager,
    Dolmen,
    ExitSwitch,
    CastleRoot,
    Dynamic(Level2DynamicArenaCursorRow),
    Goat,
    /// A package-imported class-15 row. The row starts as an ordinary pickup
    /// and becomes the active spell holder in place after acquisition.
    ImportedSpellSource,
    Player,
    Nyphur,
    PossessionHolder,
    CastleHolder,
    FireballHolder,
    /// A descriptor-backed lossless source row whose behavior is selected by
    /// its exact registry key rather than a level-specific typed slot.
    Imported,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ResolvedSourceVisit {
    key: BehaviorKey,
    handler: ExistingHandler,
    route: SourceRoute,
    phase: Option<u8>,
    /// Source-time resources for the existing scheduler receipts. This lets
    /// temporal integration checks distinguish a charge from a later transfer.
    #[cfg(test)]
    player_resources:
        Option<(crate::campaign::source_arena::SourceEntityHandle, i32, i32, i32)>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
#[allow(private_interfaces)]
pub(crate) enum Level2ResolvedSourcePlan {
    Callback(ResolvedSourceVisit),
    /// A live selector whose UpdateEntities table word matches but whose
    /// callback address is null. The numeric cursor retains it unchanged.
    NoCallback {
        key: BehaviorKey,
        route: SourceRoute,
        phase: Option<u8>,
    },
    /// A live row whose class/action selector does not match any entry in its
    /// source action table. `UpdateEntities_57730` disables drawing without
    /// invoking a callback or advancing byte 0x3E, then the following pass
    /// prologue reclaims the row.
    InvalidSelectorHide {
        key: BehaviorKey,
        route: SourceRoute,
        phase: Option<u8>,
    },
    /// A live row whose selector is not admitted by the compiled registry, or
    /// whose retained carrier cannot lawfully feed the selected handler.
    Unknown {
        key: BehaviorKey,
        route: SourceRoute,
        phase: Option<u8>,
        message: String,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Level2EpiloguePolicy {
    /// The source callback body is deliberately phase-free; the scheduler
    /// advances the current occupant after callback return.
    SchedulerAdvance {
        before: u8,
        route: SourceRoute,
        generation: u32,
    },
    /// Retained delegates still contain their historical common increment.
    /// The scheduler verifies exactly one advance and supplies it only when a
    /// bounded callback exit returned before that common tail. Dynamic slot
    /// generation distinguishes a retained row from NewEvent replacement.
    EnsureDelegateAdvanced {
        before: u8,
        route: SourceRoute,
        generation: Option<u32>,
    },
}

fn validate_semantic_creature_dispatch(
    source_slot: u16,
    creature_identity: Option<crate::campaign::source_arena::CreatureRuntimeIdentity>,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    match (creature_identity, handler) {
        (Some(identity), actual) => {
            if identity.role == crate::campaign::source_arena::CreatureRuntimeRole::Root
                && identity.raw_model.and_then(
                    crate::campaign::mc2_level_definition::Mc2LevelDefinition::creature_for_model,
                ) != Some(identity.kind)
            {
                return Err(format!(
                    "creature source slot {source_slot} is semantic {}, but the MC2 row carries raw model {:?}",
                    identity.kind.as_str(),
                    identity.raw_model
                ));
            }
            let expected = match (identity.kind, identity.role) {
                (CreatureKind::Creature18, _) => Some(&[ExistingHandler::Creature18][..]),
                (CreatureKind::Creature21, _) => Some(&[ExistingHandler::Creature21][..]),
                (CreatureKind::Creature27, _) => Some(&[ExistingHandler::Creature27][..]),
                (CreatureKind::FinalBoss, _) => Some(&[ExistingHandler::FinalBoss][..]),
                (CreatureKind::Wyvern, _) => Some(&[ExistingHandler::Wyvern][..]),
                (CreatureKind::Creature17, _) => Some(&[ExistingHandler::Creature17][..]),
                (CreatureKind::Creature23, _) => Some(&[ExistingHandler::Creature23][..]),
                (CreatureKind::Creature26, _) => Some(&[ExistingHandler::Creature26][..]),
                (CreatureKind::Creature28, _) => Some(&[ExistingHandler::Creature28][..]),
                (CreatureKind::Cymmerian, _) => Some(&[ExistingHandler::Cymmerian][..]),
                (CreatureKind::Spider, _) => Some(&[ExistingHandler::Spider][..]),
                (CreatureKind::Creature22, _) => Some(&[ExistingHandler::Creature22][..]),
                (CreatureKind::Creature24, _) => Some(&[ExistingHandler::Creature24][..]),
                (
                    CreatureKind::Dragon,
                    crate::campaign::source_arena::CreatureRuntimeRole::MultipartPart,
                ) => Some(
                    &[
                        ExistingHandler::MultipartFamily,
                        ExistingHandler::DragonFamily,
                    ][..],
                ),
                (_, crate::campaign::source_arena::CreatureRuntimeRole::MultipartPart) => {
                    Some(&[ExistingHandler::MultipartFamily][..])
                }
                (CreatureKind::Dragon, _) => Some(&[ExistingHandler::DragonFamily][..]),
                (CreatureKind::Goat, _) => Some(&[ExistingHandler::GoatFamily][..]),
                (CreatureKind::Bee, _) => Some(&[ExistingHandler::BeeFamily][..]),
                (CreatureKind::Worm, _) => Some(&[ExistingHandler::MultipartFamily][..]),
                (CreatureKind::Archer, _) => Some(&[ExistingHandler::ArcherFamily][..]),
                (CreatureKind::CastleDefender, _) => Some(&[ExistingHandler::CastleAuxiliary][..]),
                (CreatureKind::Skeleton, _) => Some(&[ExistingHandler::Model9Family][..]),
                (CreatureKind::Builder, _) => Some(
                    &[
                        ExistingHandler::BuilderFamily,
                        ExistingHandler::BuilderVillagerPostBuild,
                        // Source action 96 hands model 12 to action 105;
                        // its unchanged model then uses townie 104..111.
                        ExistingHandler::VillagerFamily,
                    ][..],
                ),
                (CreatureKind::Villager, _) => Some(
                    &[
                        ExistingHandler::VillagerFamily,
                        ExistingHandler::BuilderVillagerPostBuild,
                    ][..],
                ),
                (CreatureKind::Trader, _) => Some(&[ExistingHandler::TraderFamily][..]),
                (CreatureKind::Firefly, _) => Some(&[ExistingHandler::FireflyFamily][..]),
            };
            if expected.is_some_and(|handlers| handlers.contains(&actual)) {
                Ok(())
            } else {
                Err(format!(
                    "creature source slot {source_slot} is semantic {}, but the MC2 selector resolved {actual:?}",
                    identity.kind.as_str()
                ))
            }
        }
        (
            None,
            ExistingHandler::GoatFamily
            | ExistingHandler::DragonFamily
            | ExistingHandler::BeeFamily
            | ExistingHandler::MultipartFamily
            | ExistingHandler::ArcherFamily
            | ExistingHandler::Model9Family
            | ExistingHandler::BuilderFamily
            | ExistingHandler::VillagerFamily
            | ExistingHandler::BuilderVillagerPostBuild
            | ExistingHandler::TraderFamily
            | ExistingHandler::Wyvern
            | ExistingHandler::Creature17
            | ExistingHandler::Creature18
            | ExistingHandler::Creature21
            | ExistingHandler::Creature27
            | ExistingHandler::FinalBoss
            | ExistingHandler::Creature23
            | ExistingHandler::Creature26
            | ExistingHandler::Creature28
            | ExistingHandler::Cymmerian
            | ExistingHandler::Creature22
            | ExistingHandler::Creature24
            | ExistingHandler::Spider
            | ExistingHandler::FireflyFamily,
        ) => Err(format!(
            "creature source slot {source_slot} has no package-authored semantic identity"
        )),
        _ => Ok(()),
    }
}

fn validate_semantic_scenery_dispatch(
    source_slot: u16,
    scenery_kind: Option<SceneryKind>,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    match (scenery_kind, handler) {
        (Some(SceneryKind::Tree), ExistingHandler::TreeLifecycle)
        | (Some(SceneryKind::Mushroom), ExistingHandler::Mushrooms)
        | (Some(SceneryKind::BallisticObject), ExistingHandler::BallisticScenery)
        | (Some(SceneryKind::Dolmen), ExistingHandler::Dolmen)
        | (Some(SceneryKind::StaticObject), ExistingHandler::StaticScenery)
        | (Some(SceneryKind::Stone), ExistingHandler::Stone | ExistingHandler::BadStone)
        | (
            Some(SceneryKind::ExitPortal | SceneryKind::SecretPortal),
            ExistingHandler::Class14Events,
        ) => Ok(()),
        (Some(kind), actual) => Err(format!(
            "scenery source slot {source_slot} is semantic {}, but the MC2 selector resolved {actual:?}",
            kind.as_str()
        )),
        (None, ExistingHandler::TreeLifecycle) => Err(format!(
            "tree source slot {source_slot} has no package-authored semantic identity"
        )),
        _ => Ok(()),
    }
}

fn validate_semantic_item_dispatch(
    source_slot: u16,
    item_kind: Option<ItemKind>,
    raw_model: u8,
    raw_action: u8,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    match (item_kind, raw_model, raw_action, handler) {
        (Some(ItemKind::PassiveItem), 0, 0, ExistingHandler::Class14Events) => Ok(()),
        (Some(ItemKind::ExperienceScroll), 5, 10, ExistingHandler::Class14Events) => Ok(()),
        (Some(kind), _, _, actual) => Err(format!(
            "item source slot {source_slot} is semantic {}, but the MC2 selector resolved model {raw_model} action {raw_action} through {actual:?}",
            kind.as_str()
        )),
        (None, 5, 10, ExistingHandler::Class14Events) => Err(format!(
            "experience-scroll source slot {source_slot} has no package-authored semantic identity"
        )),
        _ => Ok(()),
    }
}

fn validate_semantic_switch_dispatch(
    source_slot: u16,
    switch_kind: Option<SwitchKind>,
    raw_class: u8,
    raw_model: u8,
    raw_action: u8,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    match (switch_kind, raw_class, raw_model, raw_action, handler) {
        (Some(kind), 11, model, action, actual)
            if model == action
                && countdown_switch::mc2::rule_for_selector(model)
                    == Some(countdown_switch::ActivationRule::from_semantic_kind(kind))
                && matches!(
                    actual,
                    ExistingHandler::SwitchProducers
                        | ExistingHandler::ObjectiveSwitch
                        | ExistingHandler::CountdownSwitch
                ) =>
        {
            Ok(())
        }
        (Some(kind), _, _, _, actual) => Err(format!(
            "switch source slot {source_slot} is semantic {}, but the MC2 selector resolved class {raw_class} model {raw_model} action {raw_action} through {actual:?}",
            kind.as_str()
        )),
        (None, 11, 32, 32, ExistingHandler::ObjectiveSwitch) => Err(format!(
            "objective-gate source slot {source_slot} has no package-authored semantic identity"
        )),
        (None, 11, 0..=15 | 18..=44, _, _) => Err(format!(
            "switch source slot {source_slot} has package-supported model {raw_model} action {raw_action} but no semantic identity"
        )),
        _ => Ok(()),
    }
}

fn validate_semantic_spell_dispatch(
    source_slot: u16,
    spell_kind: Option<SpellKind>,
    expected_family: Option<u8>,
    raw_family: u8,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    match (spell_kind, expected_family, handler) {
        (Some(_kind), Some(family), ExistingHandler::SpellHolderAndPickup)
            if family == raw_family =>
        {
            Ok(())
        }
        (Some(kind), expected, actual) => Err(format!(
            "spell source slot {source_slot} is semantic {}, but the MC2 selector resolved family {raw_family} through {actual:?} (expected package family {expected:?})",
            kind.as_str()
        )),
        (None, _, ExistingHandler::SpellHolderAndPickup) => Err(format!(
            "spell source slot {source_slot} has no package-authored semantic identity"
        )),
        _ => Ok(()),
    }
}

fn validate_semantic_building_dispatch(
    source_slot: u16,
    building_kind: Option<BuildingKind>,
    route: SourceRoute,
    raw_action: u8,
    handler: ExistingHandler,
) -> std::result::Result<(), String> {
    let source_is_house = matches!(route, SourceRoute::House);
    let source_is_house_construction = matches!(
        route,
        SourceRoute::Dynamic(Level2DynamicArenaCursorRow {
            kind: Level2DynamicArenaKind::AuthoredModel45,
            ..
        })
    );
    match (building_kind, handler) {
        (Some(BuildingKind::House), ExistingHandler::Class10Effects)
            if (source_is_house && matches!(raw_action, 51..=53))
                || (source_is_house_construction && raw_action == 51) =>
        {
            Ok(())
        }
        (Some(kind), actual) => Err(format!(
            "building source slot {source_slot} is semantic {}, but the MC2 selector resolved action {raw_action} through {actual:?}",
            kind.as_str()
        )),
        (None, ExistingHandler::Class10Effects)
            if source_is_house || source_is_house_construction =>
        {
            Err(format!(
                "house source slot {source_slot} has no package-authored semantic identity"
            ))
        }
        _ => Ok(()),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Level2CleanupPolicy {
    HideInvalidSelector,
}

impl Mc2Simulation {
    /// Source `sub_159E0`, scheduled after class-list rebuild and before the
    /// numeric `UpdateEntities` cursor. The qualified Level-2 package reaches
    /// both class-9/model-0 Fireball pressure against class-3 targets and
    /// class-9/model-1 Possession pressure against class-10/model-39 mana.
    /// Each resolved projectile is marked before model/owner admission and
    /// can contribute at most once.
    fn step_level2_projectile_threat_prepass(&mut self) {
        #[derive(Clone, Copy)]
        struct ThreatWrite {
            target_owner: u16,
            attacker_color: u8,
            delta: i32,
            latch_threshold: Option<i32>,
        }

        #[derive(Clone, Copy)]
        enum ThreatProjectile {
            Possession(usize),
            Fireball(usize),
        }

        #[derive(Clone, Copy)]
        enum ThreatTarget {
            Class3 { model: u8, owner: u16 },
            ManaSphere { owner: u16, mana: i32 },
            Other,
        }

        let (entities, players, spheres, castles) = {
            let live = &self.session.state.live;
            (
                live.economy.entities.clone(),
                live.core.players.clone(),
                live.economy.economy.spheres().to_vec(),
                live.economy
                    .economy
                    .live_castles()
                    .copied()
                    .collect::<Vec<_>>(),
            )
        };
        let mut projectile_indices = self
            .session
            .state
            .live
            .economy
            .economy
            .possession_projectiles
            .iter()
            .enumerate()
            .filter(|(_, projectile)| projectile.active && !projectile.threat_accounted)
            .map(|(index, projectile)| {
                (
                    projectile.source_entity_index,
                    ThreatProjectile::Possession(index),
                )
            })
            .collect::<Vec<_>>();
        projectile_indices.extend(
            self.session
                .state
                .live
                .economy
                .economy
                .fireball_projectiles
                .iter()
                .enumerate()
                .filter(|(_, projectile)| projectile.active && !projectile.threat_accounted)
                .map(|(index, projectile)| {
                    (
                        projectile.source_entity_index,
                        ThreatProjectile::Fireball(index),
                    )
                }),
        );
        projectile_indices.sort_unstable_by_key(|(source_slot, _)| *source_slot);

        let mut writes = Vec::new();
        for (_, projectile_source) in projectile_indices {
            let (projectile_model, projectile_owner, target_slot) = match projectile_source {
                ThreatProjectile::Possession(index) => {
                    let projectile = self
                        .session
                        .state
                        .live
                        .economy
                        .economy
                        .possession_projectiles[index];
                    (
                        projectile.source_model,
                        projectile.source_id_entity_index,
                        projectile.target_source_entity_index,
                    )
                }
                ThreatProjectile::Fireball(index) => {
                    let projectile =
                        self.session.state.live.economy.economy.fireball_projectiles[index];
                    (
                        projectile.source_model,
                        projectile.owner_entity_index,
                        projectile.target_source_entity_index,
                    )
                }
            };
            let owner_is_live_player = entities
                .get(usize::from(projectile_owner))
                .is_some_and(|owner| owner.active && owner.class == 3);
            let target = entities
                .get(usize::from(target_slot))
                .filter(|target| target.index != 0 && target.active)
                .map(|target| match (target.class, target.model) {
                    (3, model) => ThreatTarget::Class3 {
                        model,
                        owner: target.source_id,
                    },
                    (10, 39) => ThreatTarget::ManaSphere {
                        owner: target.source_player_entity_index(),
                        mana: target.mana,
                    },
                    _ => ThreatTarget::Other,
                })
                .or_else(|| {
                    castles
                        .iter()
                        .find(|target| target.active && target.source_entity_index == target_slot)
                        .map(|target| ThreatTarget::Class3 {
                            model: 2,
                            owner: target.source_id_entity_index,
                        })
                })
                .or_else(|| {
                    spheres
                        .iter()
                        .find(|sphere| {
                            sphere.active
                                && !sphere.pending_delete
                                && sphere.source_entity_index == target_slot
                        })
                        .map(|target| ThreatTarget::ManaSphere {
                            owner: target.player_entity_index,
                            mana: target.mana,
                        })
                });
            if !owner_is_live_player || target.is_none() {
                continue;
            }

            // The source sets byte-1 bit 0x20 immediately after resolving the
            // owner and target, before checking the projectile/target models.
            match projectile_source {
                ThreatProjectile::Possession(index) => {
                    self.session
                        .state
                        .live
                        .economy
                        .economy
                        .possession_projectiles[index]
                        .threat_accounted = true;
                }
                ThreatProjectile::Fireball(index) => {
                    self.session.state.live.economy.economy.fireball_projectiles[index]
                        .threat_accounted = true;
                }
            }

            let Some(attacker) = players
                .iter()
                .find(|player| player.entity_index == projectile_owner)
            else {
                continue;
            };
            let attacker_color = attacker.player_color_index();
            let attacker_max_mana = entities
                .get(usize::from(projectile_owner))
                .map_or(0, |owner| owner.max_mana);
            match target.expect("resolved above") {
                ThreatTarget::Class3 { model, owner } => {
                    let Some(target_owner) =
                        players.iter().find(|player| player.entity_index == owner)
                    else {
                        continue;
                    };
                    let heavy = matches!(projectile_model, 3 | 4 | 11);
                    let delta = if model == 2 {
                        if heavy { 5_000 } else { 1_000 }
                    } else if heavy {
                        3_000
                    } else {
                        500
                    };
                    let latch_threshold = (model == 2).then(|| {
                        let pressure = target_owner
                            .type_str_164_auxiliary()
                            .map_or(0, |auxiliary| auxiliary.word_0x242_578);
                        creatures::rival_wizards::source_mana_pressure_score(attacker_max_mana, pressure)
                    });
                    writes.push(ThreatWrite {
                        target_owner: owner,
                        attacker_color,
                        delta,
                        latch_threshold,
                    });
                }
                ThreatTarget::ManaSphere { owner, mana } => {
                    if projectile_model != POSSESSION_PROJECTILE_MODEL
                        || !entities
                            .get(usize::from(owner))
                            .is_some_and(|owner| owner.active && owner.class == 3)
                    {
                        continue;
                    }
                    writes.push(ThreatWrite {
                        target_owner: owner,
                        attacker_color,
                        // Signed division truncates toward zero, matching the
                        // source's sign-corrected quarter-mana expression.
                        delta: mana / 4,
                        latch_threshold: None,
                    });
                }
                ThreatTarget::Other => {}
            }
        }

        for write in writes {
            let live = &mut self.session.state.live;
            if let Some(dispatcher) = live.nyphur_dispatcher.get_mut_in_arena(&live.economy, write.target_owner) {
                dispatcher.apply_projectile_threat(write.attacker_color, write.delta);
                continue;
            }

            let index = 4 * usize::from(write.attacker_color) + 4;
            let Some(target_player) = live
                .core
                .players
                .iter_mut()
                .find(|player| player.entity_index == write.target_owner)
            else {
                continue;
            };
            let Some(current) = target_player.type_str_164_array_word(index) else {
                continue;
            };
            let next = i32::from(current)
                .saturating_add(write.delta)
                .clamp(0, i32::from(u16::MAX)) as u16;
            let _ = target_player.set_type_str_164_array_word(index, next);
            let set_latch = write
                .latch_threshold
                .is_some_and(|threshold| i32::from(next) > threshold);
            if set_latch {
                let _ = target_player.set_type_str_164_array_word(index + 1, 1);
            }
            for player in &mut live.shared_spells.players {
                if player.entity_index == write.target_owner {
                    let _ = player.set_type_str_164_array_word(index, next);
                    if set_latch {
                        let _ = player.set_type_str_164_array_word(index + 1, 1);
                    }
                }
            }
            if live.shared_spells.local_player.entity_index == write.target_owner {
                let _ = live
                    .shared_spells
                    .local_player
                    .set_type_str_164_array_word(index, next);
                if set_latch {
                    let _ = live
                        .shared_spells
                        .local_player
                        .set_type_str_164_array_word(index + 1, 1);
                }
            }
        }
    }

    fn hide_level2_invalid_selector(
        &mut self,
        source_slot: u16,
    ) -> std::result::Result<(), String> {
        self.session
            .state
            .live
            .economy
            .hide_dynamic_invalid_selector(source_slot)
            .then_some(())
            .ok_or_else(|| {
                format!(
                    "invalid-selector cleanup lost the current typed occupant at source slot {source_slot}"
                )
            })
    }

    #[cfg(test)]
    pub(crate) fn cf10_probe_invalid_selector_cleanup(
        &mut self,
        source_slot: u16,
    ) -> std::result::Result<(), String> {
        self.hide_level2_invalid_selector(source_slot)
    }
}

