    pub(crate) fn bind_frame_zero_switch_overlap_variant(
        &mut self,
        source_slot: u16,
        package_extent: u16,
        authored_extent: u16,
    ) -> std::result::Result<(), NativeWorldError> {
        let root_index = self
            .session
            .state
            .live
            .level2_imported_switch_roots
            .iter()
            .position(|root| root.source_slot == source_slot)
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "semantic switch source slot {source_slot} has no imported overlap carrier"
                ))
            })?;
        let root = self.session.state.live.level2_imported_switch_roots[root_index];
        if root.word_10.cast_unsigned() != package_extent {
            return Err(NativeWorldError::new(format!(
                "semantic switch source slot {source_slot} package overlap extent diverges: live {}, semantic {package_extent}",
                root.word_10
            )));
        }
        let package_half_extent = package_extent.wrapping_shl(8).cast_signed();
        let entity = self
            .session
            .state
            .live
            .economy
            .entities
            .get_mut(usize::from(source_slot))
            .filter(|entity| entity.active && entity.index == source_slot)
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "semantic switch source slot {source_slot} lost its imported live row"
                ))
            })?;
        let live_half_width = i16::from_le_bytes(
            entity.record_bytes()[88..90]
                .try_into()
                .expect("imported switch half-width bytes"),
        );
        let live_half_depth = i16::from_le_bytes(
            entity.record_bytes()[90..92]
                .try_into()
                .expect("imported switch half-depth bytes"),
        );
        if live_half_width != package_half_extent || live_half_depth != package_half_extent {
            return Err(NativeWorldError::new(format!(
                "semantic switch source slot {source_slot} package overlap carrier diverges: live {live_half_width}/{live_half_depth}, semantic {package_half_extent}"
            )));
        }
        let authored_half_extent = authored_extent.wrapping_shl(8).cast_signed();
        entity.set_source_overlap_half_extents(authored_half_extent, authored_half_extent);
        self.session.state.live.level2_imported_switch_roots[root_index].word_10 =
            authored_extent.cast_signed();
        Ok(())
    }

    pub(crate) fn creature_identity_for_source_slot(
        &self,
        source_slot: u16,
    ) -> Option<crate::campaign::source_arena::CreatureRuntimeIdentity> {
        let identity = self.session.state.live.economy.creature_runtime_identity(
            source_slot,
            self.session.definition.initial_creature_bindings(),
            self.session.definition.authored_creature_bindings(),
        )?;

        if let crate::campaign::source_arena::CreatureRootOrigin::MorphSpell { holder_slot } =
            identity.origin
        {
            let source = self
                .session
                .state
                .live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .find(|source| source.source_entity_index == source_slot)?;
            if source.active
                && !source.drawing_enabled
                && self
                    .session
                    .state
                    .live
                    .economy
                    .economy
                    .is_deferred_bee_reclaim(source_slot)
            {
                return Some(identity);
            }
            let live = &self.session.state.live;
            // Rival Morph callbacks update their raw holder, whereas the
            // local held spell uses its shared carrier. Death scattering
            // advances action12 to action13 without clearing word96; the
            // independently scheduled follower still runs its source tail.
            let holder = if self.morph_holder_is_raw(holder_slot) {
                live.economy.entities.get(usize::from(holder_slot))
            } else {
                live.shared_spells.pickup(holder_slot)
            };
            let current_birth = live.economy.handle(holder_slot).is_some_and(|holder| {
                live.economy.economy.morph.body_for_holder(holder) == Some(identity.handle)
            });
            return holder.filter(|holder| {
                holder.active
                    && holder.class == 15
                    && holder.model == 4
                    && matches!(holder.action, 12 | 13)
                    && holder.source_word_96() == source_slot
                    && holder.source_spell_parent_entity_index() == source.parent_entity_index
                    && current_birth
            }).map(|_| identity);
        }

        Some(identity)
    }

    #[cfg(test)]
    pub(crate) fn creature_kind_for_source_slot(&self, source_slot: u16) -> Option<CreatureKind> {
        self.creature_identity_for_source_slot(source_slot)
            .map(|identity| identity.kind)
    }

