    pub(crate) fn creature_runtime_census(
        &self,
    ) -> crate::campaign::source_arena::CreatureRuntimeCensus {
        self.session.state.live.economy.creature_runtime_census(
            self.session.definition.initial_creature_bindings(),
            self.session.definition.authored_creature_bindings(),
        )
    }

    pub(crate) fn scenery_kind_for_source_slot(&self, source_slot: u16) -> Option<SceneryKind> {
        self.session
            .state
            .live
            .economy
            .authored_trees()
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .and_then(|source| {
                self.session
                    .definition
                    .scenery_for_authored_record(source.authored_index)
            })
            .or_else(|| {
                self.session
                    .state
                    .live
                    .economy
                    .economy
                    .authored_class14()
                    .iter()
                    .find(|source| source.active && source.source_entity_index == source_slot)
                    .and_then(|source| {
                        self.session
                            .definition
                            .scenery_for_authored_record(source.authored_index)
                    })
            })
            .or_else(|| {
                // Initial package bindings belong to the original occupant.
                // A reclaimed mushroom slot can now contain a live creature
                // or projectile with a different semantic identity.
                (self.session.state.live.economy.slot_generation(source_slot) == 0)
                    .then(|| {
                        self.session
                            .definition
                            .scenery_for_initial_source_slot(source_slot)
                    })
                    .flatten()
            })
            .or_else(|| {
                let row = self.session.state.live.economy.entities.get(usize::from(source_slot))?;
                row.active.then_some(())?;
                crate::campaign::mc2_level_definition::Mc2LevelDefinition::scenery_for_reset_selector(
                    row.class, u16::from(row.model), row.action,
                ).filter(|kind| *kind == SceneryKind::StaticObject)
            })
    }

    fn item_kind_for_source_slot(&self, source_slot: u16) -> Option<ItemKind> {
        self.session
            .state
            .live
            .economy
            .economy
            .authored_class14()
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .and_then(|source| {
                self.session
                    .definition
                    .item_for_authored_record(source.authored_index)
            })
            .or_else(|| {
                let source = self.session.state.live.economy.entities.get(usize::from(source_slot))?;
                let binding = sim_definition::adapter::PASSIVE_ITEM_SOURCE_BINDING;
                (source.active && (source.class, source.model, source.action)
                    == (binding.class, binding.model, binding.action))
                    .then_some(ItemKind::PassiveItem)
            })
    }

    fn spell_kind_for_source_slot(&self, source_slot: u16) -> Option<SpellKind> {
        self.session
            .state
            .live
            .economy
            .economy
            .spell_pickups()
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .and_then(|source| {
                self.session
                    .definition
                    .spell_for_authored_record(source.authored_index)
            })
    }

    fn building_kind_for_source_slot(
        &self,
        source_slot: u16,
        route: SourceRoute,
    ) -> Option<BuildingKind> {
        match route {
            SourceRoute::House => self
                .session
                .definition
                .building_for_initial_source_slot(source_slot)
                .or_else(|| {
                    self.session
                        .state
                        .live
                        .economy
                        .economy
                        .authored_house_record(source_slot)
                        .and_then(|record| {
                            self.session.definition.building_for_authored_record(record)
                        })
                })
                .or_else(|| {
                    self.session
                        .state
                        .live
                        .ordinary
                        .houses()
                        .iter()
                        .any(|house| house.active && house.entity_index == source_slot)
                        .then_some(BuildingKind::House)
                }),
            SourceRoute::Dynamic(Level2DynamicArenaCursorRow {
                kind: Level2DynamicArenaKind::AuthoredModel45,
                ..
            }) => self
                .session
                .state
                .live
                .economy
                .economy
                .authored_model45()
                .iter()
                .find(|source| source.active && source.source_entity_index == source_slot)
                .and_then(|source| {
                    self.session
                        .definition
                        .building_for_authored_record(source.authored_index)
                }),
            _ => None,
        }
    }

    pub(crate) fn switch_kind_for_source_slot(&self, source_slot: u16) -> Option<SwitchKind> {
        self.session
            .state
            .live
            .economy
            .economy
            .authored_model32()
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .and_then(|source| {
                self.session
                    .definition
                    .switch_for_authored_record(source.authored_index)
            })
            .or_else(|| {
                self.session
                    .state
                    .live
                    .economy
                    .economy
                    .authored_switch_producers()
                    .iter()
                    .find(|source| source.active && source.source_entity_index == source_slot)
                    .and_then(|source| {
                        self.session
                            .definition
                            .switch_for_authored_record(source.authored_index)
                    })
            })
            .or_else(|| {
                (self
                    .session
                    .state
                    .live
                    .economy
                    .economy
                    .slot_generation(source_slot)
                    == 0)
                    .then(|| {
                        self.session
                            .definition
                            .switch_for_initial_source_slot(source_slot)
                    })
                    .flatten()
            })
    }

    fn mechanic_kind_for_source_slot(&self, source_slot: u16) -> Option<MechanicKind> {
        self.session
            .state
            .live
            .economy
            .economy
            .authored_switch_producers
            .iter()
            .find(|source| source.source_entity_index == source_slot)
            .and_then(|source| {
                self.session
                    .definition
                    .mechanic_for_authored_record(source.authored_index)
            })
            .or_else(|| {
                self.session
                    .definition
                    .mechanic_for_initial_source_slot(source_slot)
            })
    }

    fn countdown_arming_ticks_for_source_slot(
        &self,
        source_slot: u16,
    ) -> std::result::Result<i32, String> {
        let Some(level) = self.session.definition.semantic_level() else {
            return Ok(16);
        };
        let authored_record = self
            .session
            .state
            .live
            .economy
            .economy
            .authored_switch_producers
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .map(|source| source.authored_index);
        if let Some(ticks) = self
            .session
            .definition
            .switch_countdown_arming_ticks(authored_record, source_slot)
        {
            return i32::try_from(ticks).map_err(|_| {
                format!(
                    "countdown source slot {source_slot} arming delay {ticks} exceeds source width"
                )
            });
        }
        let entity_id = authored_record
            .and_then(|authored_record| {
                self.session
                    .definition
                    .mechanic_entity_for_authored_record(authored_record)
            })
            .or_else(|| {
                self.session
                    .definition
                    .mechanic_entity_for_initial_source_slot(source_slot)
            })
            .ok_or_else(|| {
                format!("countdown source slot {source_slot} has no package-bound semantic entity")
            })?;
        let ticks = level
            .entity(entity_id)
            .and_then(|entity| entity.absence_countdown())
            .ok_or_else(|| {
                format!(
                    "countdown source slot {source_slot} semantic entity {} has no countdown configuration",
                    entity_id.as_str()
                )
            })?
            .arming_ticks();
        i32::try_from(ticks).map_err(|_| {
            format!("countdown source slot {source_slot} arming delay {ticks} exceeds source width")
        })
    }

    fn countdown_observed_creature_present(
        &self,
        source_slot: u16,
        pass_start_class5_model_slots: &[Vec<u16>; 29],
    ) -> std::result::Result<bool, String> {
        if self.session.definition.semantic_level().is_none() {
            // The pre-descriptor owner-export adapter has no semantic
            // definition to bind. Preserve its two private source selectors
            // until those compatibility callers move to the campaign package.
            let legacy_model = self
                .session
                .state
                .live
                .economy
                .entities
                .get(usize::from(source_slot))
                .filter(|source| {
                    source.active && source.class == 11 && source.model == 16 && source.action == 16
                })
                .map(|_| 3_usize)
                .or_else(|| {
                    self.session
                        .state
                        .live
                        .economy
                        .economy
                        .authored_switch_producers
                        .iter()
                        .find(|source| {
                            source.active
                                && source.source_entity_index == source_slot
                                && source.source_class == 11
                                && source.model == 17
                                && source.action == 17
                        })
                        .map(|_| 4_usize)
                })
                .ok_or_else(|| {
                    format!(
                        "legacy countdown source slot {source_slot} has no accepted MC2 selector"
                    )
                })?;
            return Ok(pass_start_class5_model_slots
                .get(legacy_model)
                .is_some_and(|slots| !slots.is_empty()));
        }
        let MechanicKind::AbsenceCountdown { creature } = self
            .mechanic_kind_for_source_slot(source_slot)
            .ok_or_else(|| {
                format!(
                    "countdown source slot {source_slot} has no package-derived semantic mechanic"
                )
            })?
        else {
            return Err(format!(
                "countdown source slot {source_slot} is not an absence countdown"
            ));
        };
        let model = self
            .session
            .definition
            .creature_model(creature)
            .ok_or_else(|| {
                format!(
                    "countdown source slot {source_slot} observes {}, but the package has no creature-model binding",
                    creature.as_str()
                )
            })?;
        Ok(pass_start_class5_model_slots
            .get(usize::from(model))
            .is_some_and(|slots| !slots.is_empty()))
    }

