    /// Append to the canonical journal before updating the legacy Level 2
    /// event slice. The latter remains a compatibility projection until the
    /// generic CF-12 reader replaces it.
    fn push_dispatch_effect(&mut self, event: Mc2DispatchEvent) {
        self.push_dispatch_effect_with_economy(event, None);
    }

    fn push_dispatch_effect_with_economy(
        &mut self,
        event: Mc2DispatchEvent,
        economy: Option<crate::campaign::journal::EconomyEffect>,
    ) {
        self.flush_shared_effects();
        let turn = self.session.state.live.core.runtime.global_turn;
        let tick = self.state.tick;
        self.effect_journal_mut()
            .append_economy_dispatch(turn, event.clone(), tick, economy);
        Vec::push(&mut self.session.state.scratch.dispatch_events, event);
    }

    /// Record an authoritative flight/audio effect before retaining the old
    /// per-subsystem projection consumed by existing qualification tools.
    fn push_flight_effect(&mut self, event: FlightEvent) {
        self.flush_shared_effects();
        let turn = self.session.state.live.core.runtime.global_turn;
        let audio = self.prepare_campaign_audio(event);
        self.effect_journal_mut()
            .append_prepared_flight(turn, event, audio);
        Vec::push(&mut self.session.state.live.shared_spells.events, event);
    }

    fn prepare_campaign_audio(
        &self,
        event: FlightEvent,
    ) -> Option<crate::PreparedEventSoundCommand> {
        let (entity_index, sound_id) = match event {
            FlightEvent::PrepareSound {
                entity_index,
                sound_id,
                ..
            }
            | FlightEvent::EndLoop {
                entity_index,
                sound_id,
                ..
            } => (entity_index, sound_id),
            _ => return None,
        };
        if matches!(sound_id, 1 | 2 | 5 | 31) {
            return Some(crate::PreparedEventSoundCommand {
                command: crate::PositionalSoundCommand {
                    relative_x: 0,
                    relative_y: 0,
                    relative_z: 0,
                    distance_xy: 0,
                    relative_yaw: 0,
                    volume_q15: 0,
                    pan_q16: 0x7fff,
                    rate_delta_percent: 0,
                    sound_flags: 0,
                    audible: true,
                },
                play_type: crate::POSITIONAL_SOUND_PLAY_IF_NOT_PLAYING,
            });
        }
        if entity_index == 0 {
            // PrepareEventSound's null source row bypasses position and uses
            // full centred volume. Objective announcements use this branch.
            let mut prepared = crate::prepare_event_sound_command(
                self.state.position,
                self.state.yaw,
                self.state.position,
                sound_id,
                self.session.state.live.economy.global_rng,
                0,
                0,
            )?;
            prepared.command.volume_q15 = 0x7fff;
            prepared.command.pan_q16 = 0x7fff;
            prepared.command.relative_x = 0;
            prepared.command.relative_y = 0;
            prepared.command.relative_z = 0;
            prepared.command.rate_delta_percent = 0;
            prepared.command.sound_flags = 0;
            prepared.command.audible = true;
            return Some(prepared);
        }
        let arena = &self.session.state.live.economy;
        // Authored Wind can own the current slot without a raw projection.
        // Resolve it through the same live carrier as the source scheduler.
        let wind = if sound_id == 49
            && arena.live_arena_kind(entity_index) == Some(Level2DynamicArenaKind::AuthoredModel22)
        {
            arena.authored_model22().iter()
                .find(|wind| wind.active && wind.source_entity_index == entity_index)
        } else {
            None
        };
        let (position, flags, source_id, action) = if let Some(wind) = wind {
            (wind.position, wind.control_flags, wind.entity_id, wind.action)
        } else {
            let source = arena.entities.get(usize::from(entity_index))?;
            (source.position, source.control_flags, source.source_id, source.action)
        };
        if flags & 0x80 != 0 {
            return None;
        }
        let source_position = if entity_index == self.state.entity_index {
            self.state.position
        } else {
            position
        };
        crate::prepare_event_sound_command(
            self.state.position,
            self.state.yaw,
            source_position,
            sound_id,
            arena.global_rng,
            source_id,
            action,
        )
    }

    fn push_scene_change_effect(&mut self, scene: u8) {
        self.flush_shared_effects();
        let turn = self.session.state.live.core.runtime.global_turn;
        self.effect_journal_mut().append_scene_change(turn, scene);
    }

    fn append_context_effects(&mut self, events: Vec<FlightEvent>) {
        if events.is_empty() {
            return;
        }
        self.flush_shared_effects();
        let turn = self.session.state.live.core.runtime.global_turn;
        for event in events {
            let audio = self.prepare_campaign_audio(event);
            self.effect_journal_mut()
                .append_prepared_flight(turn, event, audio);
        }
    }

    fn flush_shared_effects(&mut self) {
        let effects = self
            .session
            .state
            .live
            .shared_spells
            .drain_pending_effects();
        if effects.is_empty() {
            return;
        }
        let turn = self.session.state.live.core.runtime.global_turn;
        for effect in effects {
            let audio = match &effect {
                crate::campaign::journal::CampaignEffect::Flight(event) => {
                    self.prepare_campaign_audio(*event)
                }
                _ => None,
            };
            let journal = self.effect_journal_mut();
            match effect {
                crate::campaign::journal::CampaignEffect::Dispatch(event) => {
                    journal.append_dispatch(turn, event);
                }
                crate::campaign::journal::CampaignEffect::SharedSpell(event) => {
                    journal.append_shared_spell(turn, event);
                }
                crate::campaign::journal::CampaignEffect::Flight(event) => {
                    journal.append_prepared_flight(turn, event, audio);
                }
                crate::campaign::journal::CampaignEffect::SceneChange { scene } => {
                    journal.append_scene_change(turn, scene);
                }
                crate::campaign::journal::CampaignEffect::ObjectivePresentation(actions) => {
                    journal.append_objective_presentation(turn, actions);
                }
            }
        }
    }

