    /// Project live renderable entities through the package's particle table.
    /// The camera-relative selector rules are the same source rules used by
    /// the indexed Rust renderer; unknown modes and missing parameter rows
    /// fail closed instead of becoming a neighboring or client-guessed TMAP.
    /// World draw candidates use the same source near plane and range as the
    /// indexed sprite renderer. The selector census remains separately usable
    /// for lifecycle inspection, regardless of the player's current location.
    pub fn campaign_visible_entity_presentations(
        &self,
        camera_yaw: i16,
    ) -> Result<Vec<CampaignEntityPresentation>> {
        let camera = self.source_camera_pose();
        Ok(self
            .campaign_entity_presentations(camera_yaw)?
            .into_iter()
            .filter(|row| {
                crate::goat_sprite_raster::source_sprite_view(
                    camera.x,
                    camera.y,
                    camera_yaw,
                    row.position.x,
                    row.position.y,
                    crate::goat_sprite_raster::Mode20SpriteProjectionLimits::exact()
                        .render_cutoff_squared,
                )
                .is_ok()
            })
            .collect())
    }

    /// DrawSorcererName reads the current class3 A4 color, not the sprite's
    /// selected asset, a cached ownership list or its source ID.
    pub fn campaign_player_label(&self, entity_index: u16) -> Result<Option<crate::native_world::CampaignPlayerLabel>> {
        let live = &self.session.state.live;
        let Some(header) = live.economy.entities.get(usize::from(entity_index)) else { return Ok(None); };
        // Ordinary constructors publish class/model in the actual source
        // header. Other families need no player-status/A4 interpretation.
        if !header.active || header.class != 3 || !matches!(header.model, 0 | 1) {
            return Ok(None);
        }
        let mut context = source_target::Context::from_ordinary(&live.goats, &live.ordinary);
        context.spells = Some(&live.shared_spells);
        context.particles = Some(&self.session.definition.presentation.particles);
        context.player = Some((live.core.state.entity_index, live.core.state.position, live.player_life));
        let Some(body) = source_target::status_parent(&live.economy, context, entity_index)
            .map_err(NativeWorldError::new)? else { return Ok(None); };
        if !body.active || body.class != 3 || !matches!(body.model, 0 | 1) {
            return Ok(None);
        }
        let player_color_index = match body.special_relation {
            EntitySpecialRelation::PlayerState(slot) => live.shared_spells.players()
                .iter().chain(live.core.players.iter()).find(|player| player.slot == slot)
                .map(PlayerSnapshot::player_color_index)
                .ok_or_else(|| NativeWorldError::new("sorcerer label has no current A4 player"))?,
            // NewEvent's shared unk_F42B0x byte38 is zero-initialized; only
            // the real player constructor writes a per-player color.
            EntitySpecialRelation::GlobalSpecialState => 0,
            EntitySpecialRelation::None => return Err(NativeWorldError::new("sorcerer label has no A4 relation")),
        };
        let source_name = crate::campaign::backend::source_scoreboard::source_name_bytes(player_color_index)
            .ok_or_else(|| NativeWorldError::new("sorcerer label color is outside the source roster"))?;
        let mut name_bytes = [0; 32];
        if source_name.len() >= name_bytes.len() {
            return Err(NativeWorldError::new("source sorcerer name exceeds the label buffer"));
        }
        name_bytes[..source_name.len()].copy_from_slice(source_name);
        Ok(Some(crate::native_world::CampaignPlayerLabel { player_color_index, name_bytes,
            name_len: source_name.len() as u8, life: body.life, max_life: body.max_life }))
    }

    pub fn campaign_entity_presentations(
        &self,
        camera_yaw: i16,
    ) -> Result<Vec<CampaignEntityPresentation>> {
        let dynamic_slots = self
            .economy()
            .live_arena_slots()
            .into_iter()
            .map(|(slot, _)| slot)
            .collect::<BTreeSet<_>>();
        let house_slots = self
            .ordinary()
            .houses()
            .iter()
            .filter(|house| house.active)
            .map(|house| house.entity_index)
            .collect::<BTreeSet<_>>();
        let mut candidates = self
            .entities()
            .iter()
            .filter(|entity| {
                entity.active
                    && !entity.drawing_disabled()
                    && !dynamic_slots.contains(&entity.index)
                    && !house_slots.contains(&entity.index)
                    && crate::native_world::effects::renderable_source(entity)
            })
            // Both DrawSprites_3E360 and the reflected sub_3FD60 reject
            // control-byte bits 0 and 5 before selecting a particle. These
            // lifecycle hide flags are distinct from DisableEntityDrawing04.
            .filter(|entity| entity.control_flags & 0x21 == 0)
            .filter_map(|entity| {
                entity.particle_parameter_index.map(|particle| {
                    (
                        entity.index,
                        entity.source_id,
                        particle,
                        entity.yaw,
                        entity.position,
                        entity.control_flags,
                    )
                })
            })
            .collect::<Vec<_>>();
        // Authored spell pickups own live shared-spell records in arena
        // slots; the imported table is shadowed above. Use their constructor
        // particle and current source hide flags through acquisition/reclaim.
        candidates.extend(
            self.ordinary()
                .houses()
                .iter()
                .filter(|house| house.active && house.control_flags & 0x421 == 0)
                .map(|house| {
                    // AddHouse0A_2D_38330 selects particle177 plus the raw
                    // owning player's color after consuming Possession.
                    let color = self
                        .players()
                        .iter()
                        .find(|player| {
                            house.owner_entity_index != 0
                                && player.entity_index == house.owner_entity_index
                        })
                        .map_or(0, |player| u16::from(player.player_color_index()));
                    (
                        house.entity_index,
                        house.source_id,
                        177 + color,
                        0,
                        house.position,
                        house.control_flags,
                    )
                }),
        );
        candidates.extend(
            self.shared_spells()
                .dynamic_pickups()
                .iter()
                .filter(|entity| {
                    entity.active
                        && entity.class == 15
                        && !entity.drawing_disabled()
                        && entity.control_flags & 0x21 == 0
                        && dynamic_slots.contains(&entity.index)
                })
                .filter_map(|entity| {
                    entity.particle_parameter_index.map(|particle| {
                        (
                            entity.index,
                            entity.source_id,
                            particle,
                            entity.yaw,
                            entity.position,
                            entity.control_flags,
                        )
                    })
                }),
        );
        candidates.extend(
            self.economy()
                .authored_class5()
                .iter()
                .filter(|source| source.active && source.drawing_enabled)
                .filter(|source| source.model != 3)
                .filter(|source| {
                    self.economy()
                        .authored_fireflies()
                        .iter()
                        .find(|runtime| runtime.source_entity_index == source.source_entity_index)
                        .is_none_or(|runtime| runtime.control_flags & 0x21 == 0)
                })
                .filter(|source| {
                    self.economy()
                        .authored_dragons()
                        .iter()
                        .find(|runtime| runtime.source_entity_index == source.source_entity_index)
                        .is_none_or(|runtime| runtime.control_flags & 0x21 == 0)
                })
                .map(|source| {
                    // Typed class-5 owners retain the live source identity,
                    // including summoned creatures whose ID is their caster.
                    // The imported slot is only the fallback for other models.
                    let source_id = self
                        .economy()
                        .authored_class5_archer()
                        .iter()
                        .find(|row| row.source_entity_index == source.source_entity_index)
                        .map(|row| row.entity_id)
                        .or_else(|| {
                            self.economy()
                                .authored_fireflies()
                                .iter()
                                .find(|row| row.source_entity_index == source.source_entity_index)
                                .map(|row| row.entity_id)
                        })
                        .or_else(|| {
                            self.economy()
                                .authored_dragons()
                                .iter()
                                .find(|row| row.source_entity_index == source.source_entity_index)
                                .map(|row| row.entity_id)
                        })
                        .unwrap_or(source.source_entity_index);
                    (
                        source.source_entity_index,
                        source_id,
                        source.particle_index,
                        source.yaw,
                        source.position,
                        self.economy()
                            .authored_fireflies()
                            .iter()
                            .find(|row| row.source_entity_index == source.source_entity_index)
                            .map(|row| row.control_flags)
                            .or_else(|| {
                                self.economy()
                                    .authored_dragons()
                                    .iter()
                                    .find(|row| {
                                        row.source_entity_index == source.source_entity_index
                                    })
                                    .map(|row| row.control_flags)
                            })
                            .unwrap_or_else(|| {
                                self.entities()[usize::from(source.source_entity_index)]
                                    .control_flags
                            }),
                    )
                }),
        );
        candidates.extend(
            self.economy()
                .house_residents()
                .iter()
                .filter(|row| row.active && row.drawing_enabled && row.control_flags & 0x21 == 0)
                .map(|row| {
                    (
                        row.source_entity_index,
                        row.source_id,
                        row.render_parameter_index,
                        row.yaw,
                        row.position,
                        row.control_flags,
                    )
                }),
        );
        candidates.extend(
            self.economy()
                .bee_creatures()
                .iter()
                .filter(|source| {
                    source.active && source.drawing_enabled && source.control_flags & 0x21 == 0
                })
                .map(|source| {
                    (
                        source.source_entity_index,
                        source.entity_id,
                        source.particle_index,
                        source.yaw,
                        source.position,
                        source.control_flags,
                    )
                }),
        );
        // These are live arena occupants, not imported entity rows. Keep
        // constructor particle identities in the MC2 adapter and read poses
        // from the same carriers stepped by the ordinary source scheduler.
        candidates.extend(
            self.economy()
                .fireball_projectiles()
                .iter()
                .filter(|source| {
                    source.active && !source.drawing_disabled && source.control_flags & 0x21 == 0
                })
                .map(|source| {
                    (
                        source.source_entity_index,
                        source.owner_entity_index,
                        source.visual_index,
                        source.yaw,
                        source.position,
                        source.control_flags,
                    )
                }),
        );
        candidates.extend(
            self.economy()
                .possession_projectiles()
                .iter()
                .filter(|source| source.active)
                .map(|source| {
                    (
                        source.source_entity_index,
                        source.source_id_entity_index,
                        crate::level1_mission::POSSESSION_PROJECTILE_RENDER_INDEX,
                        source.yaw,
                        source.position,
                        u32::from(source.acquisition_attempted) * 2
                            | u32::from(source.threat_accounted) * 0x2000,
                    )
                }),
        );
        candidates.extend(
            self.economy()
                .model17_spawned_children()
                .iter()
                .filter(|source| {
                    source.active
                        && source.control_flags & 0x421 == 0
                        && (source.source_class, source.model, source.action) == (10, 0, 0)
                })
                .map(|source| {
                    (
                        source.source_entity_index,
                        source.parent_entity_id,
                        crate::level1_mission::FIREBALL_IMPACT_RENDER_INDEX,
                        source.yaw,
                        source.position,
                        source.control_flags,
                    )
                }),
        );
        // NewAdd0A0C's Possession mailbox effect deliberately has hide bit 1;
        // it is not a visible explosion, even while its ownership pulse lives.
        for castle in self.economy().live_castles().filter(|castle| {
            castle.active && castle.control_flags & (ENTITY_DRAW_DISABLED_BIT | 0x21) == 0
        }) {
            candidates.push((
                castle.source_entity_index,
                castle.source_id_entity_index,
                castle.source_particle_parameter,
                castle.shift_yaw,
                castle.position,
                castle.control_flags,
            ));
        }
        // Spheres retain their particle from the actual model-39 callback.
        // Castle balloons still resolve their current raw player relation
        // through TransformPlayerColorIndex's offline permutation here.
        let source_owner_color = |relation: u16| -> Result<Option<u16>> {
            self.players()
                .iter()
                .find(|player| relation != 0 && player.entity_index == relation)
                .map(|player| {
                    [0_u16, 1, 4, 3, 2, 5, 7, 6]
                        .get(usize::from(player.player_color_index()))
                        .copied()
                        .ok_or_else(|| {
                            NativeWorldError::new("campaign owner color is out of bounds")
                        })
                })
                .transpose()
        };
        for sphere in self.economy().spheres().iter().filter(|sphere| {
            sphere.active
                && !sphere.pending_delete
                && sphere.control_flags & (ENTITY_DRAW_DISABLED_BIT | 0x21) == 0
        }) {
            candidates.push((
                sphere.source_entity_index,
                sphere.source_entity_index,
                sphere.particle_index,
                sphere.yaw,
                sphere.position,
                sphere.control_flags,
            ));
        }
        for balloon in self.economy().castle_children().iter().filter(|child| {
            child.active
                && !child.drawing_disabled()
                && child.control_flags & 0x21 == 0
                && (child.source_class, child.model, child.action) == (3, 3, 9)
        }) {
            let owner_color = source_owner_color(balloon.id_entity_index)?.ok_or_else(|| {
                NativeWorldError::new("campaign Castle balloon has no qualified player color")
            })?;
            candidates.push((
                balloon.source_entity_index,
                balloon.id_entity_index,
                balloon.visual_index + owner_color,
                balloon.yaw.cast_signed(),
                balloon.position,
                balloon.control_flags,
            ));
        }
        candidates.extend(crate::native_world::effects::sprite_sources(
            &self.session.state.live.economy,
        ));
        candidates.extend(creatures::player_lifecycle::presentation_candidates(
            self.economy().player_death_markers(),
        ));
        candidates.extend(crate::world::scenery::trees::sprite_sources(
            self.economy().authored_trees(),
        ));
        candidates.extend(crate::world::items::sprite_sources(
            self.economy().authored_class14(),
        ));
        candidates.extend(self.session.state.live.economy.fields.sprite_sources());
        candidates.extend(creatures::creature_15::mc2::presentation_candidates(
            self.economy().castle_defenders(),
        ));
        candidates.extend(creatures::worm::dynamic::presentation_candidates(
            self.source_arena(),
        ));
        candidates.extend(level2_class5::dragon::presentation_candidates(
            self.source_arena(),
        ));
        candidates.sort_unstable_by_key(|(slot, ..)| *slot);
        candidates
            .into_iter()
            .map(
                |(
                    entity_index,
                    source_id,
                    render_parameter_index,
                    yaw,
                    position,
                    control_flags,
                )| {
                    let parameter = self
                        .session
                        .definition
                        .presentation
                        .particles
                        .get(usize::from(render_parameter_index))
                        .ok_or_else(|| {
                            NativeWorldError::new(format!(
                                "campaign entity {} particle parameter {} is absent",
                                entity_index, render_parameter_index
                            ))
                        })?;
                    let (orientation_sector, selected_tmap, mirrored) = match parameter.render_mode
                    {
                        17 => crate::goat_sprite_raster::mode17_selector_for_base(
                            parameter.base_tmap,
                            yaw,
                            camera_yaw,
                        ),
                        19 => crate::goat_sprite_raster::mode19_selector_for_base(
                            parameter.base_tmap,
                            yaw,
                            camera_yaw,
                        ),
                        20 => crate::goat_sprite_raster::mode20_selector_for_base(
                            parameter.base_tmap,
                            yaw,
                            camera_yaw,
                        ),
                        // Direct source modes ignore the entity animation byte;
                        // mode21 still retains its special pivot downstream.
                        0 | 1 | 21 => (0, parameter.base_tmap, false),
                        11 | 36 => {
                            let frame = u16::from(crate::native_world::effects::animation_frame(
                                &self.session.state.live.economy,
                                entity_index,
                                render_parameter_index,
                            ));
                            (0, parameter.base_tmap.wrapping_add(frame), false)
                        }
                        mode => {
                            return Err(NativeWorldError::new(format!(
                                "campaign entity {} uses unsupported render mode {mode}",
                                entity_index
                            )));
                        }
                    };
                    let camera = self.source_camera_pose();
                    let distance_squared =
                        crate::campaign::sprite_render::source_sprite_distance_squared(
                            camera.x, camera.y, camera_yaw, position.x, position.y,
                        );
                    let pixels = crate::campaign::sprite_render::source_sprite_pixel_metadata(
                        parameter.byte_10,
                        distance_squared,
                    )
                    .map_err(NativeWorldError::new)?;
                    let tile = ((position.x >> 8) as u8, (position.y >> 8) as u8);
                    let draw_order = self
                        .economy()
                        .map_chains
                        .entity_chain(tile.0, tile.1)
                        .iter()
                        .position(|slot| *slot == entity_index)
                        .map_or(u32::MAX, |ordinal| ordinal as u32);
                    let primary_depth_adjustment = if control_flags & 0x2000_0000 != 0 {
                        let body =
                            self.entities()
                                .get(usize::from(entity_index))
                                .ok_or_else(|| {
                                    NativeWorldError::new("multipart sprite has no source entity")
                                })?;
                        let parent_slot = u16::from_le_bytes(
                            body.record_bytes()[54..56]
                                .try_into()
                                .expect("source word32"),
                        );
                        let parent =
                            self.entities()
                                .get(usize::from(parent_slot))
                                .ok_or_else(|| {
                                    NativeWorldError::new(
                                        "multipart sprite parent is outside the source arena",
                                    )
                                })?;
                        crate::campaign::sprite_render::source_multipart_primary_depth_adjustment(
                            body.record_bytes()[63],
                            parent.yaw as u16,
                            camera_yaw,
                        )
                        .map_err(NativeWorldError::new)?
                    } else {
                        0
                    };
                    Ok(CampaignEntityPresentation {
                        entity_index,
                        source_id,
                        render_parameter_index,
                        base_tmap: parameter.base_tmap,
                        selected_tmap,
                        logical_height: parameter.rotation_speed,
                        render_mode: parameter.render_mode,
                        orientation_sector,
                        mirrored,
                        position,
                        yaw,
                        pixel_mode: pixels.pixel_mode,
                        // sub_48120 initializes playersColors[*][2] to 0x7B
                        // for all eight players in Day, Night and Cave.
                        owner_color: 0x7b,
                        brightness: pixels.brightness,
                        draw_order,
                        control_flags,
                        primary_depth_adjustment,
                        player_label: self.campaign_player_label(entity_index)?,
                    })
                },
            )
            .collect()
    }

    /// Normal completed-objective arrow from GameUI::DrawMinimapMarks_64A10.
    /// The source chooses the first exit-sequence trigger in its source-slot
    /// ordered collision list, not the nearest portal or an authored position.
    pub fn campaign_exit_objective_target(&self) -> Option<(u16, crate::Position)> {
        let local = usize::from(self.runtime().local_player_slot);
        if self.runtime().objectives.get(local)?.is_level_end == 0 {
            return None;
        }
        let dynamic_slots = self
            .economy()
            .live_arena_slots()
            .into_iter()
            .map(|(slot, _)| slot)
            .collect::<BTreeSet<_>>();
        self.entities()
            .iter()
            .filter(|entity| {
                entity.active
                    && !dynamic_slots.contains(&entity.index)
                    && self.switch_kind_for_source_slot(entity.index)
                        == Some(SwitchKind::ExitSequenceTrigger)
            })
            .map(|entity| (entity.index, entity.position))
            .chain(
                self.economy()
                    .authored_switch_producers()
                    .iter()
                    .filter(|source| {
                        source.active
                            && self.switch_kind_for_source_slot(source.source_entity_index)
                                == Some(SwitchKind::ExitSequenceTrigger)
                    })
                    .map(|source| (source.source_entity_index, source.position)),
            )
            .min_by_key(|(slot, _)| *slot)
    }

    /// Return the source `str_D93C0` byte-2 flags for one entity-parameter
    /// selector. Level 2 presentation carries the selector from the raw
    /// entity record's byte 74; consumers need this single source-owned byte
    /// for model-45 help admission and must not inspect the table or
    /// substitute an entity-pool slot.
    #[must_use]
    pub fn level2_entity_parameter_flags(&self, selector: u8) -> Option<u8> {
        self.session
            .definition
            .presentation
            .entity_parameters
            .get(usize::from(selector))
            .map(|record| record[2])
    }

    /// Project live buildings selected by the semantic objective's validated
    /// BLDGPRM chain. Presentation shares the objective evaluator's definition;
    /// it must not infer this chain from scene objects or a neighboring level.
    #[must_use]
    pub fn campaign_building_objective_targets(&self, stage_index: usize) -> Vec<(u16, Position)> {
        let Some(objective) = self
            .session
            .definition
            .semantic_level()
            .and_then(|level| level.objectives().get(stage_index))
        else {
            return Vec::new();
        };
        let Some(chain) = self
            .session
            .definition
            .standing_building_chain(objective.id())
        else {
            return Vec::new();
        };
        self.session
            .state
            .live
            .ordinary
            .current_building_rows(&self.session.state.live.economy)
            .into_iter()
            .filter(|(_, selector, _)| chain.contains(selector))
            .map(|(slot, _, position)| (slot, position))
            .collect()
    }

    #[must_use]
    pub fn players(&self) -> &[PlayerSnapshot] {
        &self.session.state.live.core.players
    }

    /// Set the selected objective stage value consumed by source model-32
    /// switches. Values other than the source's completion sentinel are
    /// retained for negative-path testing but never complete the switch.
    pub fn set_level2_selected_objective_stage_state(&mut self, state: u8) -> Result<()> {
        if state > 2 {
            return Err(NativeWorldError::new(format!(
                "Level 2 objective stage state {state} is out of bounds"
            )));
        }
        self.session
            .state
            .live
            .level2_selected_objective_stage_state = state;
        self.session
            .state
            .live
            .core
            .runtime
            .set_level2_objective_stage_state(state);
        Ok(())
    }

    /// Stage one real package activation-group boundary for a focused
    /// downstream production test. Constructors, allocator behavior, source
    /// ordering, callbacks, epilogues, and cleanup remain owned by the normal
    /// shared engine path.
    #[cfg(test)]
    pub(crate) fn activate_authored_group_prerequisite_for_test(
        &mut self,
        target_group: u16,
    ) -> std::result::Result<(), String> {
        self.consume_authored_group(0, 0, target_group)
    }

    /// Stage one already-arrived Fireball pulse at a real imported Skeleton.
    /// The ordinary model-9 callback still owns mailbox consumption, damage
    /// branching, epilogue, death outputs, and later reclaim.
    #[cfg(test)]
    pub(crate) fn stage_imported_skeleton_fireball_damage_for_test(
        &mut self,
        source_slot: u16,
        owner_entity_index: u16,
        damage: u16,
    ) -> std::result::Result<(), String> {
        let position = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|source| {
                source.active
                    && source.index == source_slot
                    && source.class == 5
                    && source.model == 9
            })
            .map(|source| source.position)
            .ok_or_else(|| format!("source slot {source_slot} is not a live imported Skeleton"))?;
        self.apply_level2_class10_model0_damage(level2_dynamic_economy::Level2Class10Model0Step {
            live: true,
            first_impact: true,
            damage_pulse: true,
            owner_entity_index,
            payload: damage,
            position,
        });
        let source = &self.session.state.live.economy.entities[usize::from(source_slot)];
        if source.source_upkeep_word_62() != owner_entity_index
            || source.source_upkeep_payload() != i32::from(damage)
        {
            return Err(format!(
                "Skeleton source slot {source_slot} did not receive the Fireball damage mailbox"
            ));
        }
        Ok(())
    }

    /// Stage only the qualified Level-1 objective boundary immediately before
    /// the final Firefly-absence predicate. Production creature callbacks,
    /// objective evaluation, the reset-live level-end gate, and group 4 remain
    /// owned by the ordinary scheduler.
    #[cfg(test)]
    pub(crate) fn stage_level_one_final_objective_prerequisite_for_test(
        &mut self,
    ) -> std::result::Result<(), String> {
        const FINAL_STAGE: usize = 4;
        let objective_id =
            crate::level_definition::LevelObjectiveId::parse("objective.clear.lethal_fireflies")
                .map_err(|error| error.to_string())?;
        let semantic = self
            .session
            .definition
            .semantic_level()
            .and_then(|level| level.objectives().get(FINAL_STAGE))
            .ok_or_else(|| "qualified Level-1 final objective is missing".to_owned())?;
        if semantic.id() != &objective_id
            || semantic.condition() != ObjectiveCondition::NoLivingCreatures(CreatureKind::Firefly)
        {
            return Err("qualified Level-1 final objective is not Firefly absence".to_owned());
        }
        let stage_count = self.session.state.live.core.runtime.objectives[0]
            .stage_selectors
            .len();
        for stage_index in 0..stage_count {
            let state = if stage_index < FINAL_STAGE { 2 } else { 0 };
            self.session
                .state
                .live
                .core
                .runtime
                .set_level2_objective_stage_selector_for(0, stage_index, state);
        }
        self.session
            .state
            .live
            .core
            .runtime
            .set_level2_objective_stage_selector_for(0, FINAL_STAGE, 1);
        self.session
            .state
            .live
            .core
            .runtime
            .set_level2_objective_text_selector_for(0, FINAL_STAGE);
        self.session
            .state
            .live
            .core
            .runtime
            .set_level2_objective_level_end_for(0, 0);
        while self.session.state.live.core.runtime.objectives[0].done != 0 {
            self.session
                .state
                .live
                .core
                .runtime
                .consume_objective_done_pause_for(0);
        }
        self.session.state.live.level2_objective_pause = 0;
        self.session.state.live.level2_objective_done = false;
        Ok(())
    }

    /// Declare only local player funding and capacity for focused gameplay
    /// checks. No objective, NPC, RNG or lifetime state is changed.
    #[cfg(test)]
    pub(crate) fn stage_player_mana_for_test(&mut self, mana: i32) -> std::result::Result<(), String> {
        if mana < 0 {
            return Err("player mana prerequisite must be nonnegative".into());
        }
        let live = &mut self.session.state.live;
        let player = live.core.state.entity_index;
        live.economy.economy.owner_base_max_mana.insert(player, mana);
        live.economy.economy.rebuild_source_owner_max_mana_projection();
        let capacity = live.economy.economy.owner_max_mana_capacity(player);
        live.shared_spells.set_local_player_mana_for_test(mana);
        let parent = &mut live.economy.entities[usize::from(player)];
        parent.set_mana(mana);
        parent.max_mana = capacity;
        parent.record[144..148].copy_from_slice(&capacity.to_le_bytes());
        parent.set_mana_regen(0);
        let parent = parent.clone();
        live.shared_spells.sync_player_entity_from_authority(&parent);
        live.shared_spells.sync_typed_spell_parent_caches_from_player_entity();
        if let Some(fire) = live.core.context.spell_fire.as_mut() {
            fire.caster.mana = mana;
        }
        Ok(())
    }

    /// Declared player progression/resources for the focused guardian
    /// encounter. No creature, health, RNG, phase or lifetime is changed.
    #[cfg(test)]
    pub(crate) fn stage_level_three_guardian_prerequisites_for_test(
        &mut self,
        mana: i32,
    ) -> std::result::Result<(), String> {
        if mana < 0 || !self.session.definition.semantic_level()
            .and_then(|level| level.objectives().get(1))
            .is_some_and(|objective| objective.id().as_str() == "objective.clear.guardian_dragons"
                && objective.condition() == ObjectiveCondition::NoLivingCreatures(CreatureKind::Dragon))
        {
            return Err("guardian prerequisite requires the actual Level3 Dragon objective".into());
        }
        let live = &mut self.session.state.live;
        live.core.runtime.set_level2_objective_stage_selector_for(0, 0, 2);
        live.core.runtime.set_level2_objective_stage_selector_for(0, 1, 1);
        live.core.runtime.set_level2_objective_text_selector_for(0, 1);
        let player = live.core.state.entity_index;
        live.economy.economy.owner_base_max_mana.insert(player, mana);
        live.economy.economy.rebuild_source_owner_max_mana_projection();
        let capacity = live.economy.economy.owner_max_mana_capacity(player);
        live.shared_spells.set_local_player_mana_for_test(mana);
        let parent = &mut live.economy.entities[usize::from(player)];
        parent.set_mana(mana);
        parent.max_mana = capacity;
        parent.record[144..148].copy_from_slice(&capacity.to_le_bytes());
        let parent = parent.clone();
        live.shared_spells.sync_player_entity_from_authority(&parent);
        live.shared_spells.sync_typed_spell_parent_caches_from_player_entity();
        if let Some(fire) = live.core.context.spell_fire.as_mut() { fire.caster.mana = mana; }
        Ok(())
    }

    /// Stage only the four earlier objectives for the focused Level-3 final
    /// Bee combat gate. The final absence predicate and its following-pass
    /// exit-group producer remain ordinary scheduler consumers.
    #[cfg(test)]
    pub(crate) fn stage_level_three_final_bee_objective_prerequisite_for_test(
        &mut self,
    ) -> std::result::Result<(), String> {
        const FINAL_STAGE: usize = 4;
        let objective_id =
            crate::level_definition::LevelObjectiveId::parse("objective.clear.final_bees")
                .map_err(|error| error.to_string())?;
        let semantic = self
            .session
            .definition
            .semantic_level()
            .and_then(|level| level.objectives().get(FINAL_STAGE))
            .ok_or_else(|| "qualified Level-3 final objective is missing".to_owned())?;
        if semantic.id() != &objective_id
            || semantic.condition() != ObjectiveCondition::NoLivingCreatures(CreatureKind::Bee)
        {
            return Err("qualified Level-3 final objective is not Bee absence".to_owned());
        }
        let runtime = &mut self.session.state.live.core.runtime;
        for stage_index in 0..runtime.objectives[0].stage_selectors.len() {
            let state = if stage_index < FINAL_STAGE { 2 } else { 0 };
            runtime.set_level2_objective_stage_selector_for(0, stage_index, state);
        }
        runtime.set_level2_objective_stage_selector_for(0, FINAL_STAGE, 1);
        runtime.set_level2_objective_text_selector_for(0, FINAL_STAGE);
        runtime.set_level2_objective_level_end_for(0, 0);
        while runtime.objectives[0].done != 0 {
            runtime.consume_objective_done_pause_for(0);
        }
        self.session.state.live.level2_objective_pause = 0;
        self.session.state.live.level2_objective_done = false;
        Ok(())
    }

    /// Corrupt only the private terminal result byte after a completed exit,
    /// so the neutral completion projection's fail-closed branch can be
    /// discriminated without exposing that source byte in production APIs.
    #[cfg(test)]
    pub(crate) fn corrupt_completed_exit_result_for_test(&mut self, result_code: u8) {
        assert!(self.session.state.live.level_exit.complete);
        self.session.state.live.level_exit.result_code = result_code;
    }

    /// Hide the five real Level-3 stage Worm roots so the package-present
    /// imported absence countdown can be exercised through its ordinary
    /// scheduler path. The source rows and countdown carrier remain otherwise
    /// untouched.
    #[cfg(test)]
    pub(crate) fn hide_imported_stage_worm_roots_for_test(&mut self) -> usize {
        let mut hidden = 0;
        for source in &mut self.session.state.live.economy.entities {
            if source.active && source.class == 5 && source.model == 3 && source.action == 31 {
                source.disable_drawing();
                hidden += 1;
            }
        }
        hidden
    }

    /// Stage source mailbox damage on the five real imported Level-3 Worm
    /// roots. Their action-31 callbacks, action-28/29 death tail, epilogues,
    /// and following-pass reclaim remain production-owned.
    #[cfg(test)]
    pub(crate) fn stage_imported_worm_root_mailbox_for_test(
        &mut self,
        source_slot: u16,
        attacker_slot: u16,
        lethal: bool,
    ) -> bool {
        let Some(source) = self
            .session
            .state
            .live
            .economy
            .entities
            .get_mut(usize::from(source_slot))
            .filter(|source| {
                source.active
                    && source.class == 5
                    && source.model == 3
                    && matches!(source.action, 25..=31)
            })
        else {
            return false;
        };
        let damage = if lethal {
            source.life.saturating_add(1)
        } else {
            1
        };
        source.record[98..102].copy_from_slice(&damage.to_le_bytes());
        source.record[102..104].copy_from_slice(&attacker_slot.to_le_bytes());
        true
    }

    /// Stage one real imported Worm body mailbox. The ordinary action-232
    /// callback still owns predecessor following, damage consumption, map
    /// synchronization, and its scheduler epilogue.
    #[cfg(test)]
    pub(crate) fn stage_imported_worm_child_mailbox_for_test(
        &mut self,
        root_slot: u16,
        child_ordinal: u16,
        attacker_slot: u16,
        damage: i32,
    ) -> Option<u16> {
        let child_slot = root_slot.checked_add(child_ordinal)?.checked_add(1)?;
        let child = self
            .session
            .state
            .live
            .economy
            .entities
            .get_mut(usize::from(child_slot))
            .filter(|child| {
                child.active
                    && child.class == 5
                    && child.model == 3
                    && child.action == 232
                    && child.source_id == root_slot
            })?;
        child.record[98..102].copy_from_slice(&damage.to_le_bytes());
        child.record[102..104].copy_from_slice(&attacker_slot.to_le_bytes());
        Some(child_slot)
    }

    /// Put an imported action-26 Worm on its real cadence next to the bound
    /// target. The callback still owns the Fireball transaction and epilogue.
    #[cfg(test)]
    pub(crate) fn stage_imported_worm_attack_cadence_for_test(
        &mut self,
        source_slot: u16,
        target_slot: u16,
    ) -> bool {
        let Some(target) = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(target_slot))
            .filter(|target| target.active && target.life >= 0)
            .cloned()
        else {
            return false;
        };
        let Some(source) = self
            .session
            .state
            .live
            .economy
            .entities
            .get_mut(usize::from(source_slot))
            .filter(|source| {
                source.active && source.class == 5 && source.model == 3 && source.action == 26
            })
        else {
            return false;
        };
        source.set_phase(30);
        source.position = target.position;
        source.position.x = source.position.x.wrapping_sub(0x0100);
        source.record[154..156].copy_from_slice(&target_slot.to_le_bytes());
        true
    }

    /// Evaluate the authoritative owners' remaining mission objectives
    /// stage after the entity pass. This mirrors the source
    /// `sub_58F00_game_objectives` walk: stage selectors at one are eligible,
    /// a successful predicate writes two, and the first remaining one becomes
    /// the next objective-text selector (or sets `IsLevelEnd` when none remain).
    pub(super) fn advance_level2_objectives(
        &mut self,
        pass_start_class5_model_present: &[bool; 29],
        pass_start_model45_building_selectors: &[u8],
    ) -> std::result::Result<(), String> {
        let owners = self
            .session
            .state
            .live
            .core
            .players
            .iter()
            .enumerate()
            // Campaign sessions are single-player. Retained rival wizards
            // count for combat predicates, not as offline objective owners.
            .take(crate::campaign::objectives::objective_owner_count(
                false,
                self.session.state.live.core.runtime.player_count,
            ))
            .filter(|(_, player)| player.active_player_index >= 0)
            .map(|(source_slot, player)| (source_slot, usize::from(player.player_color_index())))
            .collect::<Vec<_>>();
        let stage_count = usize::from(self.session.state.live.core.runtime.stage_index)
            .min(self.session.state.live.core.runtime.stages.len());
        let player_x = i32::from(self.session.state.live.core.state.position.x as i16);
        let player_y = i32::from(self.session.state.live.core.state.position.y as i16);

        for (source_player_slot, objective_index) in owners {
            let Some(objective) = self
                .session
                .state
                .live
                .core
                .runtime
                .objectives
                .get(objective_index)
                .copied()
            else {
                continue;
            };
            if objective.done != 0 {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .consume_objective_done_pause_for(objective_index);
                continue;
            }
            if objective.is_level_end != 0 {
                continue;
            }
            let other_players_banished = crate::campaign::objectives::all_other_players_banished(
                source_player_slot,
                self.session.state.live.core.runtime.player_count,
                self.session
                    .state
                    .live
                    .core
                    .players
                    .iter()
                    .map(|player| player.objective_player_state()),
            );
            let mut completed = Vec::new();
            let mut mana_goal_percent = self.session.state.live.core.runtime.mana_goal_percent;
            for stage_index in 0..stage_count {
                if objective.stage_selectors[stage_index] != 1 {
                    continue;
                }
                let Some(stage) = self.session.state.live.core.runtime.stages.get(stage_index)
                else {
                    continue;
                };
                let semantic_objective = self
                    .session
                    .definition
                    .semantic_level()
                    .and_then(|level| level.objectives().get(stage_index))
                    .map(|objective| (objective.id().clone(), objective.condition()));
                let mana_threshold = match &semantic_objective {
                    Some((_, ObjectiveCondition::CastleManaPercent(percent))) => Some(*percent as i16),
                    None if stage.kind == 0 => match stage.relation {
                        RuntimeRelation::Scalar(percent) => Some(percent as i16),
                        _ => None,
                    },
                    _ => None,
                };
                let achieved = if let Some((objective_id, condition)) = semantic_objective {
                    match condition {
                        ObjectiveCondition::TargetDeath(ref target)
                        | ObjectiveCondition::TargetDeathWithoutFont(ref target) => {
                            use crate::campaign::objectives::target_death::{
                                Form, achieved_in_arena,
                            };
                            let form = if matches!(condition, ObjectiveCondition::TargetDeath(_)) {
                                Form::TargetDeath
                            } else {
                                Form::TargetDeathWithFontTypeZero
                            };
                            let target_exists = self
                                .session
                                .definition
                                .semantic_level()
                                .and_then(|level| level.entity(target))
                                .is_some();
                            target_exists
                                && achieved_in_arena(
                                    form,
                                    stage,
                                    &self.session.state.live.economy,
                                    source_target::Context {
                                        spells: Some(&self.session.state.live.shared_spells),
                                        particles: Some(&self.session.definition.presentation.particles),
                                        player: Some((
                                            self.session.state.live.core.state.entity_index,
                                            self.session.state.live.core.state.position,
                                            self.session.state.live.player_life,
                                        )),
                                        ..source_target::Context::from_ordinary(
                                            &self.session.state.live.goats,
                                            &self.session.state.live.ordinary,
                                        )
                                    },
                                )?
                        }
                        ObjectiveCondition::OwnedTargetAtLocation { target, location } => {
                            let RuntimeRelation::LiveEntity(slot) = stage.relation else {
                                continue;
                            };
                            let player_slot = self
                                .session
                                .state
                                .live
                                .core
                                .players
                                .get(source_player_slot)
                                .map_or(0, |player| player.entity_index);
                            let mut projected_stage = stage.clone();
                            projected_stage.axis_x = location.x.wrapping_mul(256) as i16;
                            projected_stage.axis_y = location.y.wrapping_mul(256) as i16;
                            self.session.definition.semantic_level().and_then(|level| level.entity(&target)).is_some()
                                && crate::campaign::objectives::delivery_collection::delivered_entity_in_arena(
                                    &projected_stage,
                                    slot,
                                    player_slot,
                                    &self.session.state.live.economy,
                                    source_target::Context {
                                        spells: Some(&self.session.state.live.shared_spells),
                                        particles: Some(&self.session.definition.presentation.particles),
                                        player: Some((
                                            self.session.state.live.core.state.entity_index,
                                            self.session.state.live.core.state.position,
                                            self.session.state.live.player_life,
                                        )),
                                        ..source_target::Context::from_ordinary(
                                            &self.session.state.live.goats,
                                            &self.session.state.live.ordinary,
                                        )
                                    },
                                )?
                        }
                        ObjectiveCondition::CollectedTarget(target) => {
                            let RuntimeRelation::LiveEntityIndex(slot) = stage.relation else {
                                continue;
                            };
                            self.session.definition.semantic_level().and_then(|level| level.entity(&target)).is_some()
                                && self.session.state.live.core.runtime.collected_entity_indices_for_player(source_player_slot)
                                .is_some_and(|indices| crate::campaign::objectives::delivery_collection::collected_entity_at_current_stage(
                                    stage, stage_index, objective.text_selector, slot, indices,
                                ))
                        }
                        ObjectiveCondition::CastleManaPercent(required_percent) => {
                            let required_percent = i32::from(required_percent);
                            let player_entity_index = self
                                .session
                                .state
                                .live
                                .core
                                .players
                                .iter()
                                .find(|player| {
                                    usize::from(player.player_color_index()) == objective_index
                                })
                                .map_or(0, |player| player.entity_index);
                            let economy = &self.session.state.live.economy.economy;
                            let denominator = economy.owner_mana_global();
                            denominator > 0
                                && economy.castle_for_owner(player_entity_index).is_some_and(
                                    |castle| {
                                        100_i32
                                            * economy
                                                .owner_mana_aggregate(player_entity_index)
                                                .saturating_add(castle.mana)
                                            / denominator
                                            >= required_percent
                                    },
                                )
                        }
                        ObjectiveCondition::DefeatRivalWizard(target) => {
                            // The source type-3 predicate is independent of
                            // ObjectiveText and reads the bound player's
                            // Type_str_0x2BDE byte, not the compact
                            // ActPlayerIndex bytes or linked entity life/drawing
                            // fields.
                            if stage.flags & 1 == 0 {
                                false
                            } else if let Some(target_index) =
                                self.session.definition.rival_wizard_entity(&target).filter(
                                    |target_index| {
                                        stage.relation == RuntimeRelation::LiveEntity(*target_index)
                                    },
                                )
                            {
                                self.session
                                    .state
                                    .live
                                    .core
                                    .players
                                    .iter()
                                    .find(|player| player.entity_index == target_index)
                                    .is_some_and(|player| {
                                        player.objective_player_state() == Some(0)
                                    })
                            } else {
                                false
                            }
                        }
                        ObjectiveCondition::AllOtherPlayersBanished => {
                            objective.text_selector as usize == stage_index
                                && other_players_banished
                        }
                        ObjectiveCondition::ReachLocation(location) => {
                            if objective.text_selector as usize != stage_index {
                                false
                            } else {
                                let stage_x = i32::from(i16::from_le_bytes(
                                    location.x.wrapping_mul(256).to_le_bytes(),
                                ));
                                let stage_y = i32::from(i16::from_le_bytes(
                                    location.y.wrapping_mul(256).to_le_bytes(),
                                ));
                                (stage_x - player_x).abs() <= LEVEL2_OBJECTIVE_POINT_RADIUS
                                    && (stage_y - player_y).abs() <= LEVEL2_OBJECTIVE_POINT_RADIUS
                            }
                        }
                        ObjectiveCondition::NoLivingCreatures(kind) => {
                            objective.text_selector as usize == stage_index
                            // Admit a semantic absence objective only after
                            // that creature's complete production, damage,
                            // hide, and following-pass cleanup lifecycle is
                            // shared by the authoritative arena.
                            && sim_definition::level_definition::supports_complete_creature_lifecycle(kind)
                            && self
                                .session
                                .definition
                                .creature_model(kind)
                                .and_then(|model| {
                                    pass_start_class5_model_present.get(usize::from(model))
                                })
                                .is_some_and(|present| !present)
                        }
                        ObjectiveCondition::NoStandingBuildings => {
                            objective.text_selector as usize == stage_index
                                && self.session.state.live.source_frame_timing_index & 0x0f == 0
                                && self
                                    .session
                                    .definition
                                    .standing_building_chain(&objective_id)
                                    .is_some_and(|chain| {
                                        !chain.is_empty()
                                            && !pass_start_model45_building_selectors
                                                .iter()
                                                .any(|selector| chain.contains(selector))
                                    })
                        }
                    }
                } else {
                    // Legacy owner-export sessions predate the campaign
                    // definition envelope. Keep their private MC2 objective
                    // adapter until those compatibility callers are retired;
                    // descriptor sessions above always use semantic input.
                    match stage.kind {
                        1 | 2 => {
                            use crate::campaign::objectives::target_death::{
                                Form, achieved_in_arena,
                            };
                            let form = if stage.kind == 1 {
                                Form::TargetDeath
                            } else {
                                Form::TargetDeathWithFontTypeZero
                            };
                            achieved_in_arena(
                                form,
                                stage,
                                &self.session.state.live.economy,
                                source_target::Context {
                                    spells: Some(&self.session.state.live.shared_spells),
                                    particles: Some(&self.session.definition.presentation.particles),
                                    player: Some((
                                        self.session.state.live.core.state.entity_index,
                                        self.session.state.live.core.state.position,
                                        self.session.state.live.player_life,
                                    )),
                                    ..source_target::Context::from_ordinary(
                                        &self.session.state.live.goats,
                                        &self.session.state.live.ordinary,
                                    )
                                },
                            )?
                        }
                        4 => {
                            let RuntimeRelation::LiveEntity(slot) = stage.relation else {
                                continue;
                            };
                            let player_slot = self
                                .session
                                .state
                                .live
                                .core
                                .players
                                .get(source_player_slot)
                                .map_or(0, |player| player.entity_index);
                            crate::campaign::objectives::delivery_collection::delivered_entity_in_arena(
                                stage,
                                slot,
                                player_slot,
                                &self.session.state.live.economy,
                                source_target::Context {
                                    spells: Some(&self.session.state.live.shared_spells),
                                    particles: Some(&self.session.definition.presentation.particles),
                                    player: Some((
                                        self.session.state.live.core.state.entity_index,
                                        self.session.state.live.core.state.position,
                                        self.session.state.live.player_life,
                                    )),
                                    ..source_target::Context::from_ordinary(
                                        &self.session.state.live.goats,
                                        &self.session.state.live.ordinary,
                                    )
                                },
                            )?
                        }
                        6 => {
                            let RuntimeRelation::LiveEntityIndex(slot) = stage.relation else {
                                continue;
                            };
                            self.session.state.live.core.runtime.collected_entity_indices_for_player(source_player_slot)
                                .is_some_and(|indices| crate::campaign::objectives::delivery_collection::collected_entity_at_current_stage(
                                    stage, stage_index, objective.text_selector, slot, indices,
                                ))
                        }
                        0 => {
                            let RuntimeRelation::Scalar(required_percent) = stage.relation else {
                                continue;
                            };
                            let Ok(required_percent) = i32::try_from(required_percent) else {
                                continue;
                            };
                            let player_entity_index = self
                                .session
                                .state
                                .live
                                .core
                                .players
                                .iter()
                                .find(|player| {
                                    usize::from(player.player_color_index()) == objective_index
                                })
                                .map_or(0, |player| player.entity_index);
                            let economy = &self.session.state.live.economy.economy;
                            let denominator = economy.owner_mana_global();
                            denominator > 0
                                && economy.castle_for_owner(player_entity_index).is_some_and(
                                    |castle| {
                                        100_i32
                                            * economy
                                                .owner_mana_aggregate(player_entity_index)
                                                .saturating_add(castle.mana)
                                            / denominator
                                            >= required_percent
                                    },
                                )
                        }
                        3 => {
                            if stage.flags & 1 == 0 {
                                false
                            } else if let RuntimeRelation::LiveEntity(target_index) = stage.relation
                            {
                                self.session
                                    .state
                                    .live
                                    .core
                                    .players
                                    .iter()
                                    .find(|player| player.entity_index == target_index)
                                    .is_some_and(|player| {
                                        player.objective_player_state() == Some(0)
                                    })
                            } else {
                                false
                            }
                        }
                        5 => {
                            objective.text_selector as usize == stage_index
                                && (i32::from(stage.axis_x) - player_x).abs()
                                    <= LEVEL2_OBJECTIVE_POINT_RADIUS
                                && (i32::from(stage.axis_y) - player_y).abs()
                                    <= LEVEL2_OBJECTIVE_POINT_RADIUS
                        }
                        8 => {
                            objective.text_selector as usize == stage_index
                                && other_players_banished
                        }
                        7 => {
                            objective.text_selector as usize == stage_index
                                && match stage.relation {
                                    RuntimeRelation::Scalar(model) if matches!(model, 2 | 4) => {
                                        usize::try_from(model)
                                            .ok()
                                            .and_then(|model| {
                                                pass_start_class5_model_present.get(model)
                                            })
                                            .is_some_and(|present| !present)
                                    }
                                    _ => false,
                                }
                        }
                        9 => false,
                        _ => false,
                    }
                };
                if let Some(threshold) = mana_threshold {
                    if achieved {
                        mana_goal_percent = 0;
                    } else if mana_goal_percent == 0
                        && stage_index == usize::from(objective.text_selector)
                        && completed.is_empty()
                    {
                        mana_goal_percent = threshold;
                    }
                }
                if achieved {
                    completed.push(stage_index);
                }
            }
            self.session.state.live.core.runtime.mana_goal_percent = mana_goal_percent;
            if completed.is_empty() {
                continue;
            }
            for &stage_index in &completed {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .set_level2_objective_stage_selector_for(objective_index, stage_index, 2);
                if objective_index == 0 && stage_index == LEVEL2_SELECTED_OBJECTIVE_STAGE_INDEX {
                    self.session
                        .state
                        .live
                        .level2_selected_objective_stage_state = 2;
                }
            }
            let next_stage = self.session.state.live.core.runtime.objectives[objective_index]
                .stage_selectors
                .iter()
                .take(stage_count)
                .position(|selector| *selector == 1);
            if crate::campaign::objectives::should_present_after_completion(
                &completed,
                objective.text_selector,
                next_stage.is_none(),
            ) {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .request_objective_presentation();
            }
            if let Some(next_stage) = next_stage {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .set_level2_objective_text_selector_for(objective_index, next_stage);
            } else {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .set_level2_objective_level_end_for(objective_index, 1);
            }
        }
        Ok(())
    }

