    /// Bind the actual completed-entry context before the candidate is
    /// published. Reset returns to this same initial policy.
    pub(crate) fn install_initial_mission_rewards(
        &mut self,
        policy: crate::campaign::rewards::MissionRewards,
    ) -> std::result::Result<(), String> {
        if self.campaign_tick() != 0 || self.session.generation != 0 {
            return Err("mission rewards require an unpublished mission".to_owned());
        }
        if self.mission_rewards() != policy {
            self.session.state.live.shared_spells.set_mission_rewards(policy);
            self.session.rebase();
        }
        Ok(())
    }

    /// Install the validated campaign-map continuation before publishing or
    /// replaying a candidate. Reset must restore the same source exit route.
    pub(crate) fn install_initial_ordinary_exit_route(
        &mut self,
        route: crate::world::portals::OrdinaryExitRoute,
    ) -> std::result::Result<(), String> {
        let exit = self.session.state.live.level_exit;
        if self.campaign_tick() != 0 || self.session.generation != 0 || exit.active || exit.complete
        {
            return Err("ordinary exit route requires an unpublished mission".to_owned());
        }
        if exit.ordinary_exit_route != route {
            self.session.state.live.level_exit.ordinary_exit_route = route;
            self.session.rebase();
        }
        Ok(())
    }

    /// A completed source secret result from action 11 or a validated
    /// unfinished-secret continuation through the ordinary action-12 portal.
    /// The package adapter still resolves and verifies its mission association.
    #[must_use]
    pub(crate) fn secret_entry_ready(&self) -> bool {
        let live = &self.session.state.live;
        live.level_exit.complete
            && live.level_exit.result_code == 26
            && live.source_player_result.result_byte() == 26
            && self.exit_player_action().is_some_and(|action| {
                action == crate::world::portals::SECRET_EXIT_PLAYER_ACTION
                    || (action == crate::world::portals::EXIT_PLAYER_ACTION
                        && live.level_exit.ordinary_exit_route
                            == crate::world::portals::OrdinaryExitRoute::UnfinishedSecretContinuation)
            })
    }

