    /// Move one imported source entity through the lossless Level 2 seam.
    /// Callers cannot create an entity or alter its class/model identity. The
    /// local player's flight state and entity projection are one public input
    /// carrier; keep them coherent so source overlap callbacks observe the
    /// same position whichever projection they use.
    pub fn set_level2_entity_position(
        &mut self,
        entity_index: u16,
        position: Position,
    ) -> Result<()> {
        let Some(entity) = self
            .session
            .state
            .live
            .economy
            .entities
            .get_mut(usize::from(entity_index))
        else {
            return Err(NativeWorldError::new(format!(
                "Level 2 entity index {entity_index} is out of bounds"
            )));
        };
        let active = entity.active;
        entity.set_position(position);
        let canonical_entity = entity.clone();
        self.session
            .state
            .live
            .economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index,
                active,
                x: position.x,
                y: position.y,
            })
            .map_err(NativeWorldError::new)?;
        if entity_index == self.session.state.live.core.state.entity_index {
            self.session.state.live.core.state.position = position;
            self.session
                .state
                .live
                .shared_spells
                .sync_player_entity_from_authority(&canonical_entity);
        }
        if let Some(root) = self
            .session
            .state
            .live
            .level2_imported_switch_roots
            .iter_mut()
            .find(|root| root.source_slot == entity_index)
        {
            root.position = position;
        }
        if self
            .session
            .state
            .live
            .shared_spells
            .pickups()
            .iter()
            .any(|pickup| pickup.index == entity_index)
        {
            self.session
                .state
                .live
                .shared_spells
                .sync_pickup_from_authority(&canonical_entity);
        }
        Ok(())
    }

    /// Keep the already-proven incoming-combat player carrier coherent while
    /// a focused campaign test positions and aims a real cast. Gameplay still
    /// constructs and schedules the spell, flyer, impact, and damage normally.
    #[cfg(test)]
    pub(crate) fn set_level2_player_aim_for_test(&mut self, yaw: i16, pitch: i16) {
        let auxiliary = self
            .session
            .state
            .live
            .shared_spells
            .beyond_sight_auxiliary();
        let player_yaw = yaw.wrapping_sub(auxiliary.next_entity) & 0x07ff;
        let player_pitch = pitch.wrapping_sub(auxiliary.entity_index2) & 0x07ff;
        let player_slot = self.session.state.live.core.state.entity_index;
        let player = &mut self.session.state.live.economy.entities[usize::from(player_slot)];
        player.set_yaw(player_yaw);
        player.set_pitch(player_pitch);
        player.set_control_flags(player.control_flags | 0x800);
        let snapshot = player.clone();
        let state = &mut self.session.state.live.core.state;
        state.yaw = player_yaw;
        state.display_pitch = player_pitch;
        state.effective_pitch = player_pitch;
        state.pitch_accumulator = player_pitch;
        state.roll_accumulator = 0;
        state.skip_flight_once = true;
        self.session
            .state
            .live
            .shared_spells
            .sync_player_entity_from_authority(&snapshot);
    }

    /// Bind one package-imported class-5/model-3 root and its exact sixteen-row
    /// action-232 body chain to a semantic position and maximum life. The
    /// private package adapter has already joined the semantic entity to these
    /// source slots; this boundary revalidates every live reset carrier before
    /// atomically publishing position, health, and map membership.
    pub(crate) fn bind_level2_imported_multipart_variant(
        &mut self,
        root_source_slot: u16,
        body_source_slots: &[u16],
        package_tile: TilePosition,
        authored_tile: TilePosition,
        package_max_life: i32,
        authored_max_life: i32,
    ) -> Result<()> {
        const BODY_COUNT: usize = 16;
        if body_source_slots.len() != BODY_COUNT {
            return Err(NativeWorldError::new(format!(
                "multipart root source slot {root_source_slot} has {} bound body rows, expected {BODY_COUNT}",
                body_source_slots.len()
            )));
        }
        let live = &mut self.session.state.live;
        let entities = &live.economy.entities;
        let root = entities
            .get(usize::from(root_source_slot))
            .filter(|entity| {
                entity.active
                    && entity.index == root_source_slot
                    && entity.source_id == root_source_slot
                    && entity.class == 5
                    && entity.model == 3
                    && entity.action == 31
                    && entity.position.x >> 8 == package_tile.x
                    && entity.position.y >> 8 == package_tile.y
                    && entity.max_life == package_max_life
                    && entity.life == package_max_life
            })
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "multipart root source slot {root_source_slot} diverges from its package carrier"
                ))
            })?;
        let root_z = root.position.z;
        let mut expected_slot = u16::from_le_bytes(
            root.record_bytes()[56..58]
                .try_into()
                .expect("entity record contains word-0x34"),
        );
        for &body_source_slot in body_source_slots {
            if body_source_slot != expected_slot {
                return Err(NativeWorldError::new(format!(
                    "multipart root source slot {root_source_slot} body chain expected {expected_slot}, found {body_source_slot}"
                )));
            }
            let body = entities
                .get(usize::from(body_source_slot))
                .filter(|entity| {
                    entity.active
                        && entity.index == body_source_slot
                        && entity.source_id == root_source_slot
                        && entity.class == 5
                        && entity.model == 3
                        && entity.action == 232
                        && entity.position.z == root_z
                        && entity.max_life == package_max_life
                        && entity.life == package_max_life
                })
                .ok_or_else(|| {
                    NativeWorldError::new(format!(
                        "multipart root source slot {root_source_slot} body source slot {body_source_slot} diverges"
                    ))
                })?;
            expected_slot = u16::from_le_bytes(
                body.record_bytes()[56..58]
                    .try_into()
                    .expect("entity record contains word-0x34"),
            );
        }
        if expected_slot != 0 {
            return Err(NativeWorldError::new(format!(
                "multipart root source slot {root_source_slot} body chain does not terminate"
            )));
        }

        let delta_x = authored_tile.x.wrapping_sub(package_tile.x).wrapping_shl(8);
        let delta_y = authored_tile.y.wrapping_sub(package_tile.y).wrapping_shl(8);
        let family_slots = std::iter::once(root_source_slot)
            .chain(body_source_slots.iter().copied())
            .collect::<Vec<_>>();
        let targets = family_slots
            .iter()
            .map(|source_slot| {
                let position = entities[usize::from(*source_slot)].position;
                (
                    *source_slot,
                    Position {
                        x: position.x.wrapping_add(delta_x),
                        y: position.y.wrapping_add(delta_y),
                        z: position.z,
                    },
                )
            })
            .collect::<Vec<_>>();
        let mut map_chains = live.economy.map_chains.clone();
        for (source_slot, position) in &targets {
            map_chains
                .sync_entity(RenderableMapSeed {
                    entity_index: *source_slot,
                    active: true,
                    x: position.x,
                    y: position.y,
                })
                .map_err(NativeWorldError::new)?;
        }
        for (source_slot, position) in targets {
            let source = &mut live.economy.entities[usize::from(source_slot)];
            source.set_position(position);
            source.bind_frame_zero_max_life(authored_max_life);
        }
        live.economy.map_chains = map_chains;
        Ok(())
    }

    /// Project the canonical imported row into the typed spell view before
    /// dispatch. The family view is a convenience carrier, never a second
    /// independently mutable entity authority.
    fn refresh_imported_spell_source_projection(&mut self, source_slot: u16) -> Result<()> {
        let source = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|entity| entity.active && entity.index == source_slot)
            .cloned()
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "imported spell pickup source slot {source_slot} is not live"
                ))
            })?;
        self.session
            .state
            .live
            .shared_spells
            .sync_pickup_from_authority(&source);
        Ok(())
    }

    /// Commit a typed spell callback back into the imported arena row and
    /// refresh the canonical player record. Scheduler cleanup and later
    /// source slots consume these canonical rows.
    fn bind_rival_acquisition(&mut self, outcome: SpellHolderAcquisitionOutcome) -> Result<()> {
        if outcome.family == BEYOND_SIGHT_FAMILY
            && outcome.parent_entity_index == self.session.state.live.shared_spells.local_player.entity_index
        {
            self.commit_imported_spell_source_projection(outcome.source_slot)?;
            let live = &mut self.session.state.live;
            live.player_visibility.bind_beyond_sight(&live.economy, &live.shared_spells.local_player);
        }
        let Some(player) = self.session.state.live.shared_spells.players().iter()
            .find(|player| player.is_ai && player.entity_index == outcome.parent_entity_index)
            .cloned() else { return Ok(()) };
        // The acquisition owner publishes the actual holder before the roster
        // binds this generation, including an allocation that reused a slot.
        self.commit_imported_spell_source_projection(outcome.source_slot)?;
        let live = &mut self.session.state.live;
        if let Some(core_player) = live.core.players.iter_mut().find(|row| row.entity_index == player.entity_index) {
            core_player.sync_spell_acquisition_from(&player);
        }
        let handle = live.economy.handle(player.entity_index)
            .ok_or_else(|| NativeWorldError::new("acquiring rival lost its source handle"))?;
        if !live.nyphur_dispatcher.bind_acquired_holder(handle, &player, &live.economy, usize::from(outcome.family)) {
            return Err(NativeWorldError::new("acquired rival holder did not bind its source generation"));
        }
        Ok(())
    }

    fn commit_imported_spell_source_projection(&mut self, source_slot: u16) -> Result<()> {
        let source = self
            .session
            .state
            .live
            .shared_spells
            .pickups()
            .iter()
            .chain(self.session.state.live.shared_spells.holders.iter())
            .chain(self.session.state.live.shared_spells.dynamic_pickups())
            .find(|entity| entity.index == source_slot)
            .cloned()
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "generic spell pickup source slot {source_slot} lost its typed projection"
                ))
            })?;
        let live = &mut self.session.state.live;
        let target = live
            .economy
            .entities
            .get_mut(usize::from(source_slot))
            .filter(|entity| entity.index == source_slot)
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "generic spell pickup source slot {source_slot} lost its imported row"
                ))
            })?;
        target.clone_from(&source);
        live.economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: source_slot,
                active: source.active,
                x: source.position.x,
                y: source.position.y,
            })
            .map_err(NativeWorldError::new)?;

        if source.drawing_disabled() {
            live.economy.economy.retire_hidden_spell_source(source_slot);
        }

        // These active typed callbacks own parent upkeep/status writes. The
        // next player visit reloads the numeric carrier before consuming them.
        // Publish only the changed fields; pose and life remain authoritative
        // in their existing gameplay owners.
        let status_mask = match (source.model, source.action) {
            (SHIELD_FAMILY, 18) => {
                Some(
                    crate::spell_activation::SHIELD_MANA_STATUS_BIT
                        | crate::spell_activation::SHIELD_INVULNERABLE_STATUS_BIT,
                )
            }
            (INVISIBLE_FAMILY, 33) => {
                Some(crate::spell_activation::INVISIBLE_STATUS_BIT)
            }
            (BEYOND_SIGHT_FAMILY, 36) => Some(0),
            _ => None,
        };
        if let Some(mask) = status_mask {
            let parent_slot = source.source_spell_parent_entity_index();
            let owner_handle = live.economy.handle(parent_slot);
            if let Some(parent) = live
                .shared_spells
                .player_entities
                .iter()
                .find(|parent| parent.index == parent_slot)
                && let Some(target) = live
                    .economy
                    .entities
                    .get_mut(usize::from(parent_slot))
                    .filter(|target| target.active && target.class == 3 && target.index == parent_slot)
            {
                target.set_mana_regen(parent.mana_regen);
                target.set_mana(parent.mana);
                target.set_control_flags(
                    (target.control_flags & !mask) | (parent.control_flags & mask),
                );
                if let Some(dispatcher) =
                    owner_handle.and_then(|handle| live.nyphur_dispatcher.get_mut(handle))
                    && dispatcher.sync_spell_target_resources(target)
                {
                    dispatcher.apply_holder_mana_regen(target.mana_regen);
                }
            }
            publish_spell_progression(live, parent_slot, source.model);
        }

        let shared_players = live.shared_spells.players().to_vec();
        for player in &mut live.core.players {
            if let Some(source_player) = shared_players
                .iter()
                .find(|source_player| source_player.entity_index == player.entity_index)
            {
                player.sync_spell_acquisition_from(source_player);
            }
        }
        Ok(())
    }

    pub(super) fn level2_model0_overlap_matches<F>(
        &self,
        switch_position: Position,
        switch_half_width: i16,
        switch_half_depth: i16,
        expected_overlap: bool,
        mut entity_position: F,
    ) -> bool
    where
        F: FnMut(&EntitySnapshot) -> Position,
    {
        let overlap = self
            .session
            .state
            .live
            .economy
            .entities
            .iter()
            .any(|entity| {
                entity.active
                    && entity.class == 3
                    && entity.model == 0
                    && entity.life >= 0
                    && crate::level1_mission::source_entities_overlap_xy(
                        switch_position,
                        switch_half_width,
                        switch_half_depth,
                        entity_position(entity),
                        i16::from_le_bytes(
                            entity.record_bytes()[88..90]
                                .try_into()
                                .expect("player render half-width extent"),
                        ),
                        i16::from_le_bytes(
                            entity.record_bytes()[90..92]
                                .try_into()
                                .expect("player render half-depth extent"),
                        ),
                    )
            });
        overlap == expected_overlap
    }

    pub(super) fn level2_model0_overlap_owner<F>(
        &self,
        switch_position: Position,
        switch_half_width: i16,
        switch_half_depth: i16,
        mut entity_position: F,
    ) -> Option<u16>
    where
        F: FnMut(&EntitySnapshot) -> Position,
    {
        self.session
            .state
            .live
            .economy
            .entities
            .iter()
            .find(|entity| {
                entity.active
                    && entity.class == 3
                    && entity.model == 0
                    && entity.life >= 0
                    && crate::level1_mission::source_entities_overlap_xy(
                        switch_position,
                        switch_half_width,
                        switch_half_depth,
                        entity_position(entity),
                        i16::from_le_bytes(
                            entity.record_bytes()[88..90]
                                .try_into()
                                .expect("player render half-width extent"),
                        ),
                        i16::from_le_bytes(
                            entity.record_bytes()[90..92]
                                .try_into()
                                .expect("player render half-depth extent"),
                        ),
                    )
            })
            .map(|entity| entity.index)
    }

    /// Evaluate one authored model-0/model-1 switch against the live model-0
    /// source list using remc2's strict XY comparator. The source scan is the
    /// live class-3/model-0 arena rebuilt by the source turn pre-pass; dead
    /// rows (`life < 0`) are not linked into that player list. Model 0 requires
    /// an overlap; model 1 requires a strict non-overlap. No Z value
    /// participates in this source callback.
    pub fn level2_authored_switch_matches(&self, authored_index: u16) -> Result<bool> {
        let feature = self
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .copied()
            .find(|feature| feature.index == authored_index)
            .ok_or_else(|| {
                NativeWorldError::new(format!(
                    "Level 2 authored switch row {authored_index} is absent"
                ))
            })?;
        let expected_overlap = match feature.subtype {
            0 => true,
            1 => false,
            other => {
                return Err(NativeWorldError::new(format!(
                    "Level 2 authored switch row {authored_index} has unsupported model {other}"
                )));
            }
        };
        let switch_position = feature.world_position(0);
        let switch_extent = feature.word_10.wrapping_shl(8).cast_signed();
        Ok(self.level2_model0_overlap_matches(
            switch_position,
            switch_extent,
            switch_extent,
            expected_overlap,
            |entity| entity.position,
        ))
    }

    /// Validate and expose the authored Level 2 Nyphur participant chain for
    /// the mutable reset session. The typed view is deliberately fallible so
    /// a stale or cross-player holder relation cannot become authority.
    pub fn nyphur_participant(&self) -> Result<Level2NyphurParticipant> {
        level2_nyphur_participant(
            &self.session.state.live.core.players,
            &self.session.state.live.economy.entities,
            &self.session.state.live.core.runtime,
            &self.session.baseline.economy.entities,
            |source_slot| {
                self.session
                    .state
                    .live
                    .economy
                    .relation_identity(source_slot)
            },
        )
    }

    fn validate_campaign_presentation_selection(&self, selection: CampaignSelection) -> Result<()> {
        let profile = self.session.state.live.mission.profile();
        let known_selection = CampaignSelection::ordinary(selection.external_level)
            == Some(selection)
            || CampaignSelection::secret_destination(selection.internal_level) == Some(selection);
        if !known_selection
            || profile.external_level != selection.external_level
            || profile.internal_level != selection.internal_level
            || profile.map_type_id != selection.map_type_id
        {
            return Err(NativeWorldError::new(
                "campaign presentation opponent profile is unknown or mismatched",
            ));
        }
        Ok(())
    }

    /// Resolve the package-authored AI participant used by common campaign
    /// presentation. Bind its current holder chain after runtime transitions;
    /// the reset-only Nyphur census remains available through
    /// `nyphur_participant`, but cannot validate dying/banished live rows.
    pub fn campaign_presentation_opponent(
        &self,
        selection: CampaignSelection,
    ) -> Result<Level2NyphurParticipant> {
        self.validate_campaign_presentation_selection(selection)?;
        if self.session.state.live.core.runtime.player_count <= 1 {
            return Ok(Level2NyphurParticipant {
                player_slot: u8::MAX,
                entity_index: u16::MAX,
                is_ai: false,
                color_index: 0,
                entity_class: 0,
                entity_model: 0,
                entity_action: 0,
                entity_source_id: u16::MAX,
                entity_next_relation: None,
                entity_next_entity: 0,
                entity_control_flags: 0,
                entity_life: 0,
                entity_max_life: 0,
                entity_mana: 0,
                entity_max_mana: 0,
                fireball_holder_index: 0,
                fireball_action: 0,
                fireball_parent_entity_index: 0,
                fireball_next_entity: 0,
                possession_holder_index: 0,
                possession_action: 0,
                possession_parent_entity_index: 0,
                possession_next_entity: 0,
                objective_stage_relation: RuntimeRelation::Null,
            });
        }
        let player = self
            .session
            .state
            .live
            .core
            .players
            .get(1)
            .ok_or_else(|| NativeWorldError::new("campaign AI player row 1 is absent"))?;
        let entity = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(player.entity_index))
            .ok_or_else(|| NativeWorldError::new("campaign AI entity row is absent"))?;
        if player.slot != 1
            || !player.is_ai
            || !entity.active
            || entity.index != player.entity_index
            || entity.class != 3
            || entity.model != 1
            || entity.source_id != entity.index
            || entity.special_relation != EntitySpecialRelation::PlayerState(1)
        {
            return Err(NativeWorldError::new(
                "campaign AI player/entity ownership census is invalid",
            ));
        }
        let holder = |raw: i16| -> Result<Option<&EntitySnapshot>> {
            if raw < 0 {
                return Ok(None);
            }
            let family = usize::try_from(raw)
                .map_err(|_| NativeWorldError::new("campaign AI spell family is invalid"))?;
            let index = *player.enabled_spell_holders.get(family).ok_or_else(|| {
                NativeWorldError::new("campaign AI spell family is outside the package census")
            })?;
            if index == 0 {
                return Err(NativeWorldError::new(
                    "campaign AI selected spell has no package holder",
                ));
            }
            // Grounded sub_5E310 releases both local and remote holders.
            // The hidden dead wizard keeps relation 1 as a learned-spell
            // marker, not as a reference to a currently held spell.
            if index == 1 && entity.control_flags & 0x20 != 0 {
                return Ok(None);
            }
            self.session
                .state
                .live
                .economy
                .entities
                .get(usize::from(index))
                .into_iter()
                .chain(self.session.state.live.shared_spells.holders.iter())
                .chain(self.session.state.live.shared_spells.pickups().iter())
                .chain(
                    self.session
                        .state
                        .live
                        .shared_spells
                        .dynamic_pickups()
                        .iter(),
                )
                .find(|holder| holder.index == index && holder.active && holder.class == 15)
                .map(Some)
                .ok_or_else(|| NativeWorldError::new("campaign AI selected holder is absent"))
        };
        let left = holder(player.left_spell_slot_raw)?;
        let right = holder(player.right_spell_slot_raw)?;
        let holder_fields = |row: Option<&EntitySnapshot>| {
            row.map_or((0, 0, 0, 0), |row| {
                (
                    row.index,
                    row.action,
                    row.source_spell_parent_entity_index(),
                    row.next_entity(),
                )
            })
        };
        let (left_index, left_action, left_parent, left_next) = holder_fields(left);
        let (right_index, right_action, right_parent, right_next) = holder_fields(right);
        if [left_parent, right_parent]
            .into_iter()
            .any(|parent| parent != 0 && parent != entity.index)
        {
            return Err(NativeWorldError::new(
                "campaign AI selected holder belongs to another entity",
            ));
        }
        let objective_stage_relation = self
            .session
            .state
            .live
            .core
            .runtime
            .objectives
            .get(1)
            .and_then(|objective| {
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .stages
                    .get(usize::from(objective.text_selector))
            })
            .map_or(RuntimeRelation::Null, |stage| stage.relation);
        Ok(Level2NyphurParticipant {
            player_slot: player.slot,
            entity_index: entity.index,
            is_ai: player.is_ai,
            color_index: player.player_color_index(),
            entity_class: entity.class,
            entity_model: entity.model,
            entity_action: entity.action,
            entity_source_id: entity.source_id,
            entity_next_relation: entity.next_relation,
            entity_next_entity: entity.next_entity(),
            entity_control_flags: entity.control_flags,
            entity_life: entity.life,
            entity_max_life: entity.max_life,
            entity_mana: entity.mana,
            entity_max_mana: entity.max_mana,
            fireball_holder_index: left_index,
            fireball_action: left_action,
            fireball_parent_entity_index: left_parent,
            fireball_next_entity: left_next,
            possession_holder_index: right_index,
            possession_action: right_action,
            possession_parent_entity_index: right_parent,
            possession_next_entity: right_next,
            objective_stage_relation,
        })
    }

    /// Build the generation-bound Day HUD projection from the live shared
    /// spell/session state. Unknown hand selectors and broken parent links are
    /// rejected so presentation cannot fall back to a neighboring asset row.
    pub(crate) fn help_enabled(&self) -> bool {
        self.session.state.live.core.context.spell_fire.as_ref().is_some_and(|fire| fire.help_enabled)
    }

    pub(crate) fn set_help_enabled(&mut self, enabled: bool) {
        if let Some(fire) = self.session.state.live.core.context.spell_fire.as_mut() {
            fire.help_enabled = enabled;
        }
    }

    /// The same source sub_68D50/Castle exception used by HUD hint41 and
    /// the spell-menu cycle. This read never activates or reprices a holder.
    fn spell_help_unavailable(&self, holder: &EntitySnapshot, family: u8) -> Result<bool> {
        let live = &self.session.state.live;
        let caster = live.shared_spells.player_entity();
        let caster_mana = live.shared_spells.player_mana();
        if family == 2 {
            return Ok(caster_mana < holder.max_mana);
        }
        let castle_mana = if holder.mana_regen != 0 {
            source_target::status_castle_mana(&live.economy, &live.shared_spells, caster)
                .map_err(NativeWorldError::new)?
        } else {
            None
        };
        Ok(crate::spell_activation::beyond_sight_admission(
            caster_mana, caster.life, holder.max_mana, holder.mana_regen,
            holder.active_value == holder.activation_value as i16, castle_mana,
        ) != crate::spell_activation::BeyondSightAdmission::Allowed)
    }

    /// Source88D40 reads the raw enabled relation independently of the
    /// semantic actor's acquisition validity. Broken Castle ownership refuses
    /// this optional binding rather than inventing affordable menu tiers.
    pub(crate) fn spell_menu_help(&self, family: u8) -> Option<sim_session::SpellMenuHelp> {
        let live = &self.session.state.live;
        let map_type = self.canonical_terrain().map_type().id();
        let title_records = crate::spell_activation::spell_menu_title_records(family, map_type)?;
        let player = live.shared_spells.local_player();
        let index = usize::from(family);
        let holder_slot = *player.enabled_spell_holders.get(index)?;
        let holder = if holder_slot != 0 {
            Some(source_target::status_parent(
                &live.economy,
                source_target::Context {
                    spells: Some(&live.shared_spells),
                    ..Default::default()
                },
                holder_slot,
            ).ok()??)
        } else {
            None
        };
        let castle = source_target::status_castle(
            &live.economy, &live.shared_spells, live.shared_spells.player_entity(),
        ).ok()?;
        let castle = castle.filter(|row| row.index != 0);
        let castle_mana = castle.as_ref().map(|row| row.mana);
        Some(sim_session::SpellMenuHelp {
            is_standard: holder_slot != 0 && (family != 25 || map_type == 2),
            title_records,
            castle_blocked: std::array::from_fn(|tier| {
                let required = crate::spell_activation::level2_set_spell_profile(family, tier as u8)
                    .expect("validated physical family and tier").mana_regen;
                required != 0 && castle_mana.is_none_or(|mana| mana < required)
            }),
            mana_unavailable: match holder.as_ref() {
                Some(holder) => self.spell_help_unavailable(holder, family).ok()?,
                None => false,
            },
            // Every retained source definition has byte_0 != 0; only the
            // explicit Cave-family rule changes DrawSpellMenu's admission.
            definition_enabled: family != 25 || map_type == 2,
            blink_hidden: holder.as_ref().is_some_and(|row| {
                !level2_day_spell_draw_admitted(
                    row.model, row.active_value,
                    self.session.state.scratch.level2_day_hud_color_phase_1,
                )
            }),
            discovered: player.spell_enabled_flags[index] != 0
                || player.acquired_spell_flags[index] != 0,
            tier_mana_costs: std::array::from_fn(|tier| {
                let cost = crate::spell_activation::level2_set_spell_profile(family, tier as u8)
                    .expect("validated physical family and tier").max_mana;
                if family == 2 {
                    super::player_spell_state::castle_mana_cost(
                        cost, tier as u8, castle.as_ref().map(EntitySnapshot::source_dword_10),
                        player.castle_destroyed != 0,
                    )
                } else {
                    cost
                }
            }),
            experience: player.persistent_spell_experience[index]
                .wrapping_add(player.runtime_spell_experience[index]),
            experience_thresholds: LEVEL2_SPELL_TIER_THRESHOLDS[index],
            selected_tier: player.family_selected_tiers[index],
        })
    }

    pub fn day_hud(&self) -> Result<Level2DayHudSnapshot> {
        self.day_hud_for(CampaignSelection::LEVEL2)
    }

    pub fn day_hud_for(&self, selection: CampaignSelection) -> Result<Level2DayHudSnapshot> {
        self.validate_campaign_presentation_selection(selection)?;
        let local_player_slot = self.session.state.live.core.runtime.local_player_slot;
        let local_player = &self.session.state.live.shared_spells.local_player;
        let local_entity = &self.session.state.live.shared_spells.player_entity;
        if local_player.slot != local_player_slot
            || local_player.entity_index != self.session.state.live.core.state.entity_index
            || local_entity.index != self.session.state.live.core.state.entity_index
        {
            return Err(NativeWorldError::new(
                "Level 2 Day HUD local player/entity relation is invalid",
            ));
        }

        let global_mana_denominator = self.session.state.live.economy.owner_mana_global();
        if global_mana_denominator <= 0 {
            return Err(NativeWorldError::new(
                "Level 2 Day HUD global mana denominator is not positive",
            ));
        }

        let local_player_color_index = local_player.player_color_index();
        let [
            mana_palette_index,
            mana_max_palette_index,
            life_palette_index,
        ] = campaign_hud_palette_indices(
            local_player_color_index,
            self.canonical_terrain().map_type(),
        )?;
        let spell_slot = |raw_spell_selector: i16| -> Result<Level2DayHudSpellSlot> {
            if raw_spell_selector < 0 {
                return Ok(Level2DayHudSpellSlot::empty(
                    raw_spell_selector,
                    local_player_color_index,
                ));
            }
            let family_index = usize::try_from(raw_spell_selector).map_err(|_| {
                NativeWorldError::new("Level 2 Day HUD spell selector does not fit usize")
            })?;
            let holder_index = *local_player
                .enabled_spell_holders
                .get(family_index)
                .ok_or_else(|| {
                    NativeWorldError::new(format!(
                        "Level 2 Day HUD spell selector {raw_spell_selector} is unknown"
                    ))
                })?;
            if holder_index == 0 {
                return Err(NativeWorldError::new(format!(
                    "Level 2 Day HUD spell selector {raw_spell_selector} has no holder"
                )));
            }
            // sub_5E310 releases the grounded player's holders and replaces
            // their relations with 1 before hiding the dead player (bit 0x20).
            // That death-state marker is not a live spell entity. Preserve a
            // real slot-1 holder during play; only the released state is empty.
            if holder_index == 1 && local_entity.control_flags & 0x20 != 0 {
                return Ok(Level2DayHudSpellSlot::empty(-1, local_player_color_index));
            }
            let holder = self
                .session
                .state
                .live
                .shared_spells
                .holders
                .iter()
                .chain(self.session.state.live.shared_spells.pickups().iter())
                .chain(
                    self.session
                        .state
                        .live
                        .shared_spells
                        .dynamic_pickups()
                        .iter(),
                )
                .find(|holder| holder.index == holder_index)
                .ok_or_else(|| {
                    NativeWorldError::new(format!(
                        "Level 2 Day HUD holder {holder_index} is absent"
                    ))
                })?;
            let parent_entity_index = holder.source_spell_parent_entity_index();
            if parent_entity_index != local_entity.index {
                return Err(NativeWorldError::new(format!(
                    "Level 2 Day HUD holder {holder_index} is owned by entity {parent_entity_index}"
                )));
            }
            let level_text_selector = u8::try_from(holder.level_gate).map_err(|_| {
                NativeWorldError::new(format!(
                    "Level 2 Day HUD holder {holder_index} has an unknown level selector"
                ))
            })?;
            let icon_selector = 123_u16
                .checked_add(u16::from(holder.model))
                .ok_or_else(|| {
                    NativeWorldError::new(format!(
                        "Level 2 Day HUD holder {holder_index} icon selector overflow"
                    ))
                })?;
            let caster_mana = self.session.state.live.shared_spells.player_mana();
            let help_unavailable = self.spell_help_unavailable(holder, holder.model)?;
            Ok(Level2DayHudSpellSlot {
                holder_entity_index: holder.index,
                parent_entity_index,
                raw_spell_selector,
                color_index: local_player_color_index,
                model: holder.model,
                tier: holder.level_gate,
                action: holder.action,
                action_marker: holder.action_marker,
                active_value: holder.active_value,
                activation_value: holder.activation_value,
                control_flags: holder.control_flags,
                max_mana: holder.max_mana,
                mana_regen: holder.mana_regen,
                caster_mana,
                frame_selector: if holder.active_value == 0 { 1 } else { 2 },
                icon_selector,
                level_text_selector,
                help_unavailable,
                draw_admitted: level2_day_spell_draw_admitted(
                    holder.model,
                    holder.active_value,
                    self.session.state.scratch.level2_day_hud_color_phase_1,
                ),
            })
        };

        Ok(Level2DayHudSnapshot {
            tick: self.session.state.live.core.state.tick,
            local_player_slot,
            local_player_entity_index: local_entity.index,
            local_player_color_index,
            local_player_active: local_player.active_player_index >= 0 && local_entity.active,
            hit_frame_time_pre_draw: self
                .session
                .state
                .scratch
                .level2_day_hud_hit_frame_time_pre_draw,
            color_phase_1: self.session.state.scratch.level2_day_hud_color_phase_1,
            color_phase_2: self.session.state.scratch.level2_day_hud_color_phase_2,
            local_player_control_flags: local_entity.control_flags,
            local_player_life: local_entity.life,
            local_player_max_life: local_entity.max_life,
            local_player_mana: self.session.state.live.shared_spells.player_mana(),
            local_player_max_mana: local_entity.max_mana,
            global_mana_denominator,
            // DrawTopStatusBar_2D710's direct MSPRD0-0 roots and geometry.
            minimap_panel_selector: 40,
            castle_panel_selector: 54,
            balloon_panel_selector: 54,
            player_panel_selector: self
                .session
                .state
                .scratch
                .level2_day_hud_player_panel_selector,
            player_icon_selector: 43,
            life_mana_icon_selector: 42,
            life_palette_index,
            mana_palette_index,
            mana_max_palette_index,
            left: spell_slot(local_player.left_spell_slot_raw)?,
            right: spell_slot(local_player.right_spell_slot_raw)?,
            nyphur: self.campaign_presentation_opponent(selection)?,
            nyphur_visibility: self.campaign_presentation_visibility(selection)?,
        })
    }

    /// Observational DrawTopStatusBar inputs from this exact live owner.
    /// Stage zero still owns the balloon panel; it does not own Castle bars.
    #[must_use]
    pub fn source_top_status(&self) -> sim_session::SourceTopStatus {
        use sim_session::{SourceBalloonStatus, SourceCastleStatus, SourceTopStatus};
        let live = &self.session.state.live;
        let owner = live.core.state.entity_index;
        let [mana, mana_max, _] = campaign_hud_palette_indices(
            live.shared_spells.local_player.player_color_index(), self.canonical_terrain().map_type(),
        ).expect("validated current source HUD palette");
        let mut result = SourceTopStatus { mana_goal_percent: live.core.runtime.mana_goal_percent,
            goal_palette_index: if self.session.state.scratch.level2_day_hud_color_phase_2 == 0 { mana } else { mana_max },
            ..SourceTopStatus::default() };
        let Some(castle) = live.economy.castle_for_owner(owner) else { return result; };
        result.castle = Some(SourceCastleStatus { stage: castle.level,
            panel_selector: if castle.level == 0 { 54 } else {
                match self.session.state.scratch.source_castle_panel_selector { 55 => 55, _ => 41 }
            },
            icon_selector: if castle.level == 0 { 0 } else { u16::from(castle.level) + 43 },
            life: castle.life, max_life: castle.max_life,
            mana: castle.mana, max_mana: castle.mana_capacity,
            owner_mana_aggregate: live.economy.owner_mana_aggregate(owner),
        });
        result.balloon_panel_selector = match self.session.state.scratch.source_balloon_panel_selector { 55 => 55, _ => 41 };
        let count = match castle.level { 1..=3 => 1, 4..=5 => 2, 6..=7 => 3, _ => 0 };
        result.balloon_icon_selector = 50 + count;
        for index in 0..usize::from(count) {
            let slot = castle.defender_slots[index];
            let Some(child) = live.economy.castle_children().iter().find(|child|
                slot != 0 && child.active && child.source_entity_index == slot
                && child.source_class == 3 && child.model == 3 && child.owner_entity_index == owner
                && live.economy.live_arena_kind(slot) == Some(Level2DynamicArenaKind::CastleDefender))
            else { continue; };
            result.balloons[index] = SourceBalloonStatus { present: true, life: child.life,
                max_life: child.max_life, mana: child.mana, max_mana: child.max_mana };
        }
        result
    }

