    /// Materialize one authored class-10/model-22 Wind row through the
    /// pinned `AddWind_4F040` constructor. The generic authored path derives
    /// the chain axis from parameter-2/parameter-1 before entering the
    /// model-specific constructor.
    pub fn allocate_level2_authored_model22(
        &mut self,
        authored_index: u16,
    ) -> Option<Level2AuthoredModel22Source> {
        let feature = self
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .copied()
            .find(|feature| {
                feature.index == authored_index && feature.kind == 10 && feature.subtype == 22
            })?;
        let position = feature.world_position(
            self.canonical_terrain()
                .ground_height(feature.world_position(0)),
        );
        let axis_position = Position {
            x: feature.parameter_2.wrapping_shl(8).wrapping_add(128),
            y: feature.parameter_1.wrapping_shl(8).wrapping_add(128),
            z: position.z,
        };
        let semantic = self
            .session
            .definition
            .mechanic_entity_for_authored_record(authored_index)?;
        let properties = self
            .session
            .definition
            .semantic_level()?
            .entity(semantic)?
            .field()?;
        let definition = crate::world::fields::wind::Definition::from_particles(
            &self.session.definition.presentation.particles,
        )
        .ok()?
        .with_content(properties)
        .ok()?;
        let live = &mut self.session.state.live;
        let root = live.economy.allocate_authored_wind(
            authored_index,
            axis_position,
            position,
            &live.terrain,
            definition,
        )?;
        crate::world::fields::register_authored_wind(
            &mut live.economy,
            &mut live.terrain,
            root.source_entity_index,
        );
        Some(root)
    }

    /// Materialize one authored class-10/model-76 Fire Spheres row through
    /// the pinned `AddFireSpheres_4F2A0` constructor.
    pub fn allocate_level2_authored_model76(
        &mut self,
        authored_index: u16,
    ) -> Option<Level2AuthoredModel76Source> {
        let feature = self
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .copied()
            .find(|feature| {
                feature.index == authored_index && feature.kind == 10 && feature.subtype == 76
            })?;
        let position = feature.world_position(
            self.canonical_terrain()
                .ground_height(feature.world_position(0)),
        );
        let source = self.session.state.live.economy.allocate_authored_model76(
            authored_index,
            position,
            &self.session.state.live.terrain,
        )?;
        // `AddFireSpheres_4F2A0` calls `SetEntityIndexAndRot_49CD0` with
        // particle 340 for every linked child. The presentation table is the
        // authoritative owner of that selector row, so bind its four axes
        // once after the atomic economy allocation.
        if let Some(particle) = self.session.definition.presentation.particles.get(340) {
            let collision_yaw =
                i16::try_from(particle.rotation_speed / 2).expect("model-76 particle yaw fits i16");
            let collision_pitch =
                i16::try_from(particle.speed / 2).expect("model-76 particle pitch fits i16");
            let collision_roll = collision_pitch;
            let collision_fov = collision_yaw;
            let axes_bound = self.economy.bind_model76_collision_axes(
                source.source_entity_index,
                collision_yaw,
                collision_pitch,
                collision_roll,
                collision_fov,
            );
            debug_assert!(axes_bound);
        }
        let live = &mut self.session.state.live;
        let sectors = live
            .economy
            .model76_children()
            .iter()
            .filter(|child| child.active && child.parent_entity_index == source.source_entity_index)
            .map(|child| (child.source_entity_index, child.position))
            .collect::<Vec<_>>();
        for (slot, position) in sectors {
            crate::world::effects::sync_position(
                &mut live.economy, &mut live.terrain, slot, position, true, false,
            ).expect("source Fire Sphere sectors retain valid map membership");
            crate::world::effects::lighting::admit_source(
                &mut live.economy,
                &live.terrain,
                slot,
                position,
                crate::world::effects::lighting::SourceLight::Fireball,
            );
        }
        crate::world::effects::sync_position(
            &mut live.economy, &mut live.terrain, source.source_entity_index,
            source.position, true, false,
        ).expect("source Fire Spheres root retains valid map membership");
        Some(source)
    }

