    fn authored_firefly_stage_route(
        &self,
        feature: AuthoredFeature,
    ) -> Option<u8> {
        if feature.kind != 5 || feature.subtype != i16::from(level2_class5::firefly::FIREFLY_MODEL)
        {
            return None;
        }
        let stage_var = self
            .session
            .state
            .live
            .mission
            .level2_authored_stage_variable_for(
                feature,
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .active_stage_variable_count(),
            )?;
        if !matches!(stage_var.kind, 1..=9) {
            return None;
        }
        let runtime_stage_var = self
            .session
            .state
            .live
            .core
            .runtime
            .stage_variables
            .get(usize::from(stage_var.index))?;
        if runtime_stage_var.kind != i8::try_from(stage_var.kind).expect("StageVar kind fits i8")
            || (matches!(stage_var.kind, 1 | 2 | 6)
                && !matches!(runtime_stage_var.relation, RuntimeRelation::AxisScalar(_)))
        {
            return None;
        }
        Some(stage_var.index)
    }

    fn allocate_authored_firefly_feature(
        &mut self,
        feature: AuthoredFeature,
    ) -> std::result::Result<Option<Level2AuthoredClass5Source>, String> {
        let route = self.authored_firefly_stage_route(feature);
        if route.is_none()
            && self
                .session
                .state
                .live
                .mission
                .level2_authored_stage_variable_for(
                    feature,
                    self.runtime().active_stage_variable_count(),
                )
                .is_some()
        {
            return Ok(None);
        }
        let position = feature.world_position(
            self.canonical_terrain()
                .ground_height(feature.world_position(0)),
        );
        let Some(max_life) = self
            .session
            .definition
            .authored_creature_max_life(feature.index)
        else {
            return Ok(None);
        };
        let live = &mut self.session.state.live;
        // GenerateEvents constructs before sub_12100 binds and thins a route.
        // Failed allocation must leave the shared StageVar counter unchanged.
        let Some(source) = live.economy.allocate_authored_firefly_unbound(
            feature.index,
            position,
            max_life,
            &live.terrain,
        ) else {
            return Ok(None);
        };
        if let Some(index) = route {
            level2_class5::firefly::bind_authored_stage_in_arena(
                &mut live.economy,
                &mut live.core.runtime,
                source.source_entity_index,
                index,
            )?;
        }
        live.economy
            .economy
            .authored_class5()
            .iter()
            .find(|row| row.source_entity_index == source.source_entity_index)
            .copied()
            .map(Some)
            .ok_or_else(|| {
                format!("authored Firefly {} lost its constructed source", feature.index)
            })
    }

    pub(super) fn allocate_level2_authored_bee_feature(
        &mut self,
        feature: AuthoredFeature,
    ) -> Option<BeeCreatureRuntime> {
        let stage_index = self
            .session
            .state
            .live
            .mission
            .level2_authored_stage_variable_for(
                feature,
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .active_stage_variable_count(),
            )
            .map(|stage| stage.index);
        let position = feature.world_position(
            self.canonical_terrain()
                .ground_height(feature.world_position(0)),
        );
        let max_life = self
            .session
            .definition
            .authored_creature_max_life(feature.index)
            .and_then(|value| i32::try_from(value).ok())?;
        let live = &mut self.session.state.live;
        let source = creatures::bee::mc2::allocate_authored(
            &mut live.economy,
            &mut live.terrain,
            feature.index,
            position,
            max_life,
        )?;
        if let Some(index) = stage_index {
            let live = &mut self.session.state.live;
            creatures::bee::mc2::bind_authored_route(
                &mut live.economy,
                &mut live.core.runtime,
                source.source_entity_index,
                index,
            );
        }
        let offset = self
            .session
            .definition
            .presentation
            .particles
            .get(3)?
            .rotation_speed
            / 2;
        let current = self
            .session
            .state
            .live
            .economy
            .bee_creatures
            .iter_mut()
            .find(|current| current.source_entity_index == source.source_entity_index)?;
        current.collision_vertical_offset = offset as i16;
        Some(*current)
    }

    /// Materialize one authored Day Bee row through remc2's class-5/model-2
    /// constructor. Mission activation owns the producer/group predicate;
    /// this seam performs the source-arena allocation and exact defaults.
    pub fn allocate_level2_authored_bee(
        &mut self,
        authored_index: u16,
    ) -> Option<BeeCreatureRuntime> {
        let feature = self
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .copied()
            .find(|feature| {
                feature.index == authored_index
                    && feature.kind == 5
                    && feature.subtype == 2
                    && matches!(feature.activation_group, 4 | 17 | 21 | 29)
            })?;
        self.allocate_level2_authored_bee_feature(feature)
    }

