#[cfg(test)]
macro_rules! terrain_method {
    ($name:ident, ($($arg:ident : $ty:ty),* $(,)?) -> $ret:ty) => {
        pub(crate) fn $name(&mut self, $($arg: $ty),*) -> $ret {
            self.with_terrain(|economy, terrain| economy.$name($($arg),*, terrain))
        }
    };
}

