    fn step_imported_model9_action79(
        &mut self,
        source_slot: u16,
        frozen_model9_slots: &[u16],
    ) -> std::result::Result<(), String> {
        let reaction_pose =
            self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.reaction_particle))?;
        let (stage_index, mut source) = {
            let live = &self.session.state.live;
            let source = &live.economy.entities[usize::from(source_slot)];
            (usize::from(source.record_bytes()[76]), source.clone())
        };
        let descriptor_flags = source.parameter_relation
            .and_then(|index| self.session.definition.presentation.entity_parameters.get(usize::from(index)))
            .map(|descriptor| descriptor[32]);
        let outcome = {
            let live = &self.session.state.live;
            let arena = &live.economy;
            let context = source_target::Context {
                spells: Some(&live.shared_spells),
                map_type: Some(live.terrain.map_type()),
                player: Some((
                    live.core.state.entity_index,
                    live.core.state.position,
                    live.player_life,
                )),
                player_orientation: Some((live.core.state.yaw, live.core.state.roll_accumulator)),
                particles: Some(&self.session.definition.presentation.particles),
                ..source_target::Context::from_ordinary(&live.goats, &live.ordinary)
            };
            campaign_shared_families::step_model9_action79(
                &mut source,
                &live.terrain,
                || match live.core.runtime.stage_variables.get(stage_index).map(|stage| stage.relation) {
                    Some(RuntimeRelation::AxisScalar(packed)) => Ok(Position {
                        x: packed as u16,
                        y: (packed >> 16) as u16,
                        z: 0,
                    }),
                    relation => Err(format!(
                        "StageVar1 {stage_index} needs a packed axis target, found {relation:?}"
                    )),
                },
                &arena.entities,
                frozen_model9_slots,
                |slot| {
                    source_target::read(arena, context, slot).map(|peer| {
                        peer.map(|peer| campaign_shared_families::Model9Peer {
                            source_slot: slot,
                            source_id: peer.source_id,
                            position: peer.position,
                        })
                    })
                },
                |slot| Self::model9_current_damage_target(arena, context, slot),
                descriptor_flags,
                reaction_pose,
            )
        };
        let position = source.position;
        let completed = match &outcome {
            Ok(completed)
            | Err(campaign_shared_families::Model9Action79Error::StageAxisRead { completed, .. })
            | Err(campaign_shared_families::Model9Action79Error::PeerRead { completed, .. }) => {
                Some(*completed)
            }
            Err(_) => None,
        };
        // Publish movement and population writes even when a reached read fails.
        self.session.state.live.economy.entities[usize::from(source_slot)] = source;
        if let Some(completed) = completed {
            if completed.population_decrement {
                self.session
                    .state
                    .live
                    .economy
                    .decrement_source_creature_population();
            }
            self.session
                .state
                .live
                .economy
                .economy
                .map_chains
                .sync_entity(RenderableMapSeed {
                    entity_index: source_slot,
                    active: true,
                    x: position.x,
                    y: position.y,
                })
                .map_err(|error| {
                    let map_error =
                        format!("model-9 source slot {source_slot} map sync failed: {error}");
                    match &outcome {
                        Err(primary) => format!("{primary}; {map_error}"),
                        Ok(_) => map_error,
                    }
                })?;
        }
        outcome.map(|_| ()).map_err(|error| error.to_string())
    }

    fn step_imported_model9_action73(
        &mut self,
        source_slot: u16,
        pass_start_class5_model_slots: &[Vec<u16>; 29],
        pass_start_class3_slots: &[u16],
    ) -> std::result::Result<(), String> {
        let movement_pose =
            self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.movement_particle))?;
        let reaction_pose =
            self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.reaction_particle))?;
        let parameter = &self.session.definition.presentation.entity_parameters
            [usize::from(MC2_SKELETON_ASSETS.descriptor)];
        let scan_period = u16::from_le_bytes([parameter[26], parameter[27]]);
        if scan_period == 0 {
            return Err("Skeleton descriptor scan period is zero".into());
        }
        let awareness_radius = i32::from(i16::from_le_bytes([parameter[28], parameter[29]]));
        let sight_angle = u16::from_le_bytes([parameter[30], parameter[31]]);
        let live = &self.session.state.live;
        let mut targets = Vec::new();
        for (model, slots) in pass_start_class5_model_slots.iter().enumerate() {
            if !matches!(model, 4 | 12 | 13) {
                continue;
            }
            for &slot in slots {
                let Some(position) = live.economy.class5_position(slot) else {
                    continue;
                };
                let raw = &live.economy.entities[usize::from(slot)];
                let (source_id, half_width, control_flags) = if let Some(row) = live
                    .economy
                    .economy
                    .authored_class5
                    .iter()
                    .find(|row| row.source_entity_index == slot)
                {
                    (slot, row.shift_rot_x, 8)
                } else if let Some(row) = live
                    .economy
                    .economy
                    .bee_creatures
                    .iter()
                    .find(|row| row.source_entity_index == slot)
                {
                    (
                        row.entity_id,
                        LEVEL2_BEE_COLLISION_HALF_EXTENT,
                        row.control_flags,
                    )
                } else if let Some(row) = live
                    .economy
                    .house_residents()
                    .iter()
                    .find(|row| row.active && row.source_entity_index == slot)
                {
                    (row.source_id, row.collision_half_width, row.control_flags)
                } else if raw.active && raw.class == 5 {
                    (raw.source_id, raw.array_pitch(), raw.control_flags)
                } else {
                    return Err(format!(
                        "Skeleton acquisition has no authoritative target geometry for slot {slot}"
                    ));
                };
                targets.push(campaign_shared_families::Model9ScanTarget {
                    identity: campaign_shared_families::Model9DamageTarget {
                        source_slot: slot,
                        source_id,
                        class: 5,
                        model: model as u8,
                    },
                    position,
                    half_width,
                    control_flags,
                });
            }
        }
        // dword_38519 is the frozen class-3 player list, not the class-5
        // creature list. In particular its model 2 is a player selector.
        for &slot in pass_start_class3_slots {
            let raw = &live.economy.entities[usize::from(slot)];
            targets.push(campaign_shared_families::Model9ScanTarget {
                identity: campaign_shared_families::Model9DamageTarget {
                    source_slot: slot,
                    source_id: raw.source_id,
                    class: 3,
                    model: raw.model,
                },
                position: raw.position,
                half_width: raw.array_pitch(),
                control_flags: raw.control_flags,
            });
        }
        targets.sort_by_key(|target| target.identity.source_slot);
        let mut source = live.economy.entities[usize::from(source_slot)].clone();
        let context = source_target::Context {
            spells: Some(&live.shared_spells), map_type: Some(live.terrain.map_type()),
            player: Some((live.core.state.entity_index, live.core.state.position, live.player_life)),
            player_orientation: Some((live.core.state.yaw, live.core.state.roll_accumulator)),
            particles: Some(&self.session.definition.presentation.particles),
            ..source_target::Context::from_ordinary(&live.goats, &live.ordinary)
        };
        let outcome = campaign_shared_families::step_model9_action73(
            &mut source, &live.terrain, &live.economy.entities,
            |slot| Self::model9_current_damage_target(&live.economy, context, slot),
            movement_pose, reaction_pose, scan_period, awareness_radius, sight_angle, &targets,
        );
        let position = source.position;
        let live = &mut self.session.state.live;
        live.economy.entities[usize::from(source_slot)] = source;
        let outcome = outcome.map_err(|error| error.to_string())?;
        if outcome.population_decrement {
            live.economy.decrement_source_creature_population();
        }
        live.economy
            .economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: source_slot,
                active: true,
                x: position.x,
                y: position.y,
            })
            .map_err(|error| format!("Skeleton movement map sync failed: {error}"))?;
        if let Some(prey_slot) = outcome.prey_to_consume {
            // Unlike action 74, action 73 inherits identity only for a
            // player-owned producer (`sub_203D0`, LABEL_79).
            let id = live.economy.entities[usize::from(source_slot)].source_id;
            let inherit = outcome.inherit_identity
                || live
                    .economy
                    .entities
                    .get(usize::from(id))
                    .is_some_and(|row| row.class == 3);
            self.convert_model9_prey(source_slot, prey_slot, scan_period, inherit)?;
        }
        Ok(())
    }

    #[cfg(test)]
    fn step_imported_model9_inner_20940(
        &mut self,
        source_slot: u16,
        pass_start_class5_model_slots: &[Vec<u16>; 29],
    ) -> std::result::Result<(), String> {
        let movement_pose =
            self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.movement_particle))?;
        let reaction_pose =
            self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.reaction_particle))?;
        let (scan_period, awareness_radius, scanned_model) = {
            let live = &self.session.state.live;
            let source = &live.economy.entities[usize::from(source_slot)];
            let parameter_index = source.parameter_relation.ok_or_else(|| {
                format!("model-9 source slot {source_slot} has no descriptor relation")
            })?;
            let parameter = self
                .session
                .definition
                .presentation
                .entity_parameters
                .get(usize::from(parameter_index))
                .ok_or_else(|| {
                    format!(
                        "model-9 source slot {source_slot} descriptor {parameter_index} is out of bounds"
                    )
                })?;
            let scan_period = u16::from_le_bytes([parameter[26], parameter[27]]);
            if scan_period == 0 {
                return Err(format!(
                    "model-9 source slot {source_slot} descriptor scan period is zero"
                ));
            }
            let awareness_radius = i32::from(i16::from_le_bytes([parameter[28], parameter[29]]));
            let scanned_model =
                [4_u8, 12, 13][usize::from((u16::from(source.phase) / scan_period) % 3)];
            (scan_period, awareness_radius, scanned_model)
        };
        let candidates = pass_start_class5_model_slots[usize::from(scanned_model)]
            .iter()
            .copied()
            .filter_map(|candidate_slot| {
                self.session
                    .state
                    .live
                    .economy
                    .class5_position(candidate_slot)
                    .map(
                        |position| campaign_shared_families::Model9ReactionCandidate {
                            source_slot: candidate_slot,
                            position,
                        },
                    )
            })
            .collect::<Vec<_>>();
        let (position, source, outcome) = {
            let live = &self.session.state.live;
            // Only this row changes during the kernel. Borrow the original
            // table as the frozen callback view, including its old source row.
            let mut source = live.economy.entities[usize::from(source_slot)].clone();
            let outcome = campaign_shared_families::step_model9_inner_20940(
                &mut source,
                &live.terrain,
                &live.economy.entities,
                |slot| Self::model9_current_damage_target(&live.economy, source_target::Context {
                    spells: Some(&live.shared_spells), map_type: Some(live.terrain.map_type()),
                    player: Some((live.core.state.entity_index, live.core.state.position, live.player_life)),
                    player_orientation: Some((live.core.state.yaw, live.core.state.roll_accumulator)),
                    particles: Some(&self.session.definition.presentation.particles),
                    ..source_target::Context::from_ordinary(&live.goats, &live.ordinary)
                }, slot),
                movement_pose,
                reaction_pose,
                scan_period,
                awareness_radius,
                &candidates,
            );
            let position = source.position;
            // Damage consumption can mutate the row before a child/attacker
            // error. Preserve those writes before propagating the result.
            (position, source, outcome)
        };
        self.session.state.live.economy.entities[usize::from(source_slot)] = source;
        let outcome = outcome.map_err(|error| error.to_string())?;
        if let Some(prey_slot) = outcome.prey_to_consume {
            self.convert_model9_prey(source_slot, prey_slot, scan_period, true)?;
        }
        self.session
            .state
            .live
            .economy
            .economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: source_slot,
                active: true,
                x: position.x,
                y: position.y,
            })
            .map_err(|error| {
                format!("model-9 source slot {source_slot} map sync failed: {error}")
            })?;
        Ok(())
    }

    fn convert_model9_prey(
        &mut self,
        producer_slot: u16,
        prey_slot: u16,
        scan_period: u16,
        inherit_identity: bool,
    ) -> std::result::Result<(), String> {
        let pose = self.model9_particle_pose(usize::from(MC2_SKELETON_ASSETS.initial_particle))?;
        let parameter = &self.session.definition.presentation.entity_parameters
            [usize::from(MC2_SKELETON_ASSETS.descriptor)];
        let material_mask =
            u32::from_le_bytes(parameter[20..24].try_into().expect("descriptor dword"));
        let ground_clearance = i16::from_le_bytes([parameter[12], parameter[13]]);
        let live = &mut self.session.state.live;
        let mut position = live
            .economy
            .class5_position(prey_slot)
            .ok_or_else(|| format!("Skeleton conversion lost prey {prey_slot}"))?;
        let producer_id = live.economy.entities[usize::from(producer_slot)].source_id;
        #[cfg(test)]
        let record_conversion = {
            // Capture both identities before hide or NewEvent can retire or
            // replace their fixed source addresses.
            let producer = live
                .economy
                .handle(producer_slot)
                .expect("live conversion producer");
            let prey = live
                .economy
                .handle(prey_slot)
                .expect("live conversion prey");
            move |outcome| {
                MODEL9_CONVERSION_RECEIPTS.with(|receipts| {
                    receipts.borrow_mut().push(Model9ConversionReceipt {
                        producer,
                        prey,
                        outcome,
                    });
                })
            }
        };
        // DisableEntityDrawing04 precedes NewEvent even when allocation fails.
        if let Some(prey) = live
            .economy
            .economy
            .authored_class5
            .iter_mut()
            .find(|row| row.active && row.source_entity_index == prey_slot)
        {
            prey.drawing_enabled = false;
        } else if let Some(prey) = live
            .economy
            .economy
            .house_residents
            .iter_mut()
            .find(|row| row.active && row.source_entity_index == prey_slot)
        {
            prey.drawing_enabled = false;
            prey.control_flags |= crate::level1_mission::SOURCE_DISABLED_FLAG;
        } else if let Some(prey) = live
            .economy
            .economy
            .castle_defenders
            .iter_mut()
            .find(|row| row.active && row.source_entity_index == prey_slot)
        {
            prey.hide();
        } else {
            live.ordinary.disable_villager_source(prey_slot);
        }
        live.economy.entities[usize::from(prey_slot)].disable_drawing();
        let Some(slot) = live.economy.economy.allocate_slot() else {
            #[cfg(test)]
            record_conversion(Model9ConversionOutcome::AllocationFailed);
            return Ok(());
        };
        let rng = live.economy.economy.new_event_rng(slot);
        let phase = live.economy.economy.class5_model9_constructor_phase;
        live.economy.economy.class5_model9_constructor_phase = phase.wrapping_add(1);
        position.z = live.terrain.ground_height(position);
        let mut child = campaign_shared_families::construct_skeleton_source(
            slot,
            rng,
            position,
            phase,
            scan_period,
            pose,
        );
        if let Err(error) = live
            .economy
            .economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: slot,
                active: true,
                x: position.x,
                y: position.y,
            })
        {
            live.economy
                .economy
                .release_slot(slot, Some(child.entity_rng));
            #[cfg(test)]
            record_conversion(Model9ConversionOutcome::MapInsertionFailed);
            return Err(format!("Skeleton conversion map insertion failed: {error}"));
        }
        let old_head = live.economy.economy.map_chains.old_map_entity(slot);
        child.record[26..28].copy_from_slice(&old_head.to_le_bytes());
        child.record[28..30].copy_from_slice(
            &live
                .economy
                .economy
                .map_chains
                .next_entity(slot)
                .to_le_bytes(),
        );
        if campaign_shared_families::skeleton_placement_blocked(
            &live.terrain,
            position,
            material_mask,
            ground_clearance,
        ) {
            live.economy
                .economy
                .release_slot(slot, Some(child.entity_rng));
            #[cfg(test)]
            record_conversion(Model9ConversionOutcome::PlacementBlocked);
            return Ok(());
        }
        if old_head != 0
            && !live
                .economy
                .economy
                .live_arena_slots()
                .iter()
                .any(|(slot, _)| *slot == old_head)
            && let Some(head) = live
                .economy
                .entities
                .get_mut(usize::from(old_head))
                .filter(|row| row.active)
        {
            head.record[28..30].copy_from_slice(&slot.to_le_bytes());
        }
        if inherit_identity {
            child.source_id = producer_id;
            child.record[30..32].copy_from_slice(&producer_id.to_le_bytes());
        }
        live.economy
            .economy
            .source_rng
            .insert(slot, child.entity_rng);
        live.economy
            .economy
            .converted_skeleton_origins
            .insert(slot, producer_slot);
        live.economy.entities[usize::from(slot)] = child;
        #[cfg(test)]
        record_conversion(Model9ConversionOutcome::Published {
            child: live
                .economy
                .handle(slot)
                .expect("published conversion child"),
        });
        Ok(())
    }

    fn step_imported_model9_pre_kill(
        &mut self,
        source_slot: u16,
    ) -> std::result::Result<(), String> {
        let mut child_slot =
            self.session.state.live.economy.entities[usize::from(source_slot)].word_34();
        let mut visited = 0_usize;
        while child_slot != 0 {
            let child = self
                .session
                .state
                .live
                .economy
                .entities
                .get_mut(usize::from(child_slot))
                .filter(|child| child.active && child.index == child_slot)
                .ok_or_else(|| {
                    format!(
                        "model-9 source slot {source_slot} has invalid pre-kill child {child_slot}"
                    )
                })?;
            child.set_source_action(77);
            child_slot = child.word_34();
            visited += 1;
            if visited >= self.session.state.live.economy.entities.len() {
                return Err(format!(
                    "model-9 source slot {source_slot} has a cyclic pre-kill child chain"
                ));
            }
        }
        self.session.state.live.economy.entities[usize::from(source_slot)].set_source_action(77);
        Ok(())
    }

    fn step_imported_model9_kill(&mut self, source_slot: u16) -> std::result::Result<(), String> {
        let source = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|source| {
                source.active
                    && source.index == source_slot
                    && source.class == 5
                    && source.model == 9
                    && source.action == 77
            })
            .cloned()
            .ok_or_else(|| format!("model-9 kill callback lost source slot {source_slot}"))?;
        if source.phase & 7 != 0 {
            return Ok(());
        }

        let source_rng = if source.mana > 0 {
            campaign_shared_families::next_source_rng16(source.entity_rng)
        } else {
            source.entity_rng
        };
        self.session.state.live.economy.entities[usize::from(source_slot)]
            .set_entity_rng(source_rng);
        if source.mana > 0 {
            let live = &mut self.session.state.live;
            live.economy.source_rng.insert(source_slot, source_rng);
            crate::world::effects::spawn_death_mana_sphere(
                &mut live.economy, &mut live.terrain, source_slot, source.position,
                source.yaw, source.mana, source.source_player_entity_index(),
            )?;
            if !crate::world::effects::clear_replacement_mana_owner(&mut live.economy, source_slot)? {
                live.economy.entities[usize::from(source_slot)].set_source_player_entity_index(0);
            }
            live.economy.source_owner.insert(source_slot, 0);
        }
        let newborn = self.spawn_level2_source_death_burst(source_slot)?;
        if !crate::world::effects::hide_birth_replacement(
            &mut self.session.state.live.economy,
            source_slot,
            newborn,
        )? {
            self.session.state.live.economy.entities[usize::from(source_slot)].disable_drawing();
        }
        Ok(())
    }

    fn step_imported_multipart(
        &mut self,
        source_slot: u16,
        pass_start_class5_model_slots: &[Vec<u16>; 29],
    ) -> std::result::Result<(), String> {
        let selector = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|source| {
                source.active
                    && source.index == source_slot
                    && source.class == 5
                    && (source.model == 3 || (source.model == 0 && source.action == 232))
            })
            .map(|source| source.action)
            .ok_or_else(|| format!("multipart callback lost source slot {source_slot}"))?;

        match selector {
            29 => {
                let source = self
                    .session
                    .state
                    .live
                    .economy
                    .entities
                    .get(usize::from(source_slot))
                    .filter(|source| {
                        source.active
                            && source.index == source_slot
                            && source.class == 5
                            && source.model == 3
                            && source.action == 29
                    })
                    .cloned()
                    .ok_or_else(|| format!("Worm kill callback lost source slot {source_slot}"))?;
                if source.phase & 7 == 0 {
                    let source_rng = if source.mana > 0 {
                        campaign_shared_families::next_source_rng16(source.entity_rng)
                    } else {
                        source.entity_rng
                    };
                    self.session.state.live.economy.entities[usize::from(source_slot)]
                        .set_entity_rng(source_rng);
                    if source.mana > 0 {
                        let live = &mut self.session.state.live;
                        live.economy.source_rng.insert(source_slot, source_rng);
                        crate::world::effects::spawn_death_mana_sphere(
                            &mut live.economy, &mut live.terrain, source_slot, source.position,
                            source.yaw, source.mana, source.source_player_entity_index(),
                        )?;
                        if !crate::world::effects::clear_replacement_mana_owner(&mut live.economy, source_slot)? {
                            live.economy.entities[usize::from(source_slot)].set_source_player_entity_index(0);
                        }
                        live.economy.source_owner.insert(source_slot, 0);
                    }
                    let newborn = self.spawn_level2_source_death_burst(source_slot)?;
                    if !crate::world::effects::hide_birth_replacement(
                        &mut self.session.state.live.economy,
                        source_slot,
                        newborn,
                    )? {
                        self.session.state.live.economy.entities[usize::from(source_slot)]
                            .disable_drawing();
                    }
                }
            }
            232 => {
                let outcome = campaign_multipart::step_raw_multipart_action232(
                    &mut self.session.state.live.economy.entities,
                    source_slot,
                )
                .map_err(|error| error.to_string())?;
                if let Some(predicted) = outcome.predicted_position {
                    self.session.state.live.terrain.set_source_predicted_position(predicted);
                }
            }
            action => {
                return Err(format!(
                    "multipart handler rejects action {action} at source slot {source_slot}"
                ));
            }
        }

        let source = &self.session.state.live.economy.entities[usize::from(source_slot)];
        self.session
            .state
            .live
            .economy
            .economy
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: source_slot,
                active: true,
                x: source.position.x,
                y: source.position.y,
            })
            .map_err(|error| {
                format!("multipart source slot {source_slot} map sync failed: {error}")
            })?;
        Ok(())
    }

    fn step_activation_switch(
        &mut self,
        pass: u8,
        source_slot: u16,
        source_player_order: &[usize],
        frozen_player_slots: &[u16],
        frozen_creature_slots: &[Vec<u16>; 29],
    ) -> std::result::Result<(), String> {
        use countdown_switch::{
            ActivationBounds, ActivationObservations, ActivationRule, ActivationSound,
            ActivationTarget, PlayerTransition, PublicationLifetime, matching_target,
        };
        let authored = self
            .session
            .state
            .live
            .economy
            .authored_switch_producers()
            .iter()
            .find(|row| row.active && row.source_entity_index == source_slot)
            .copied();
        let imported = authored
            .is_none()
            .then(|| {
                self.session
                    .state
                    .live
                    .economy
                    .entities
                    .get(usize::from(source_slot))
                    .filter(|row| row.active && row.class == 11)
                    .cloned()
            })
            .flatten();
        let (model, phase, group, mut timer, bounds) = if let Some(source) = authored {
            if source.model != source.action {
                return Err(format!(
                    "activation slot {source_slot} has mismatched selector"
                ));
            }
            let extent = source.word_10.cast_unsigned().wrapping_shl(8).cast_signed();
            (
                source.model,
                source.phase,
                source.stage_tag,
                source.dword_0x10,
                ActivationBounds {
                    position: source.position,
                    half_width: extent,
                    half_depth: extent,
                },
            )
        } else if let Some(source) = &imported {
            if source.model != source.action {
                return Err(format!(
                    "activation slot {source_slot} has mismatched selector"
                ));
            }
            (
                source.model,
                source.phase,
                source.source_id,
                source.source_dword_10(),
                ActivationBounds {
                    position: source.position,
                    half_width: i16::from_le_bytes(
                        source.record_bytes()[88..90]
                            .try_into()
                            .expect("switch width"),
                    ),
                    half_depth: i16::from_le_bytes(
                        source.record_bytes()[90..92]
                            .try_into()
                            .expect("switch depth"),
                    ),
                },
            )
        } else {
            return Err(format!(
                "activation callback lost source slot {source_slot}"
            ));
        };
        let rule = countdown_switch::mc2::rule_for_selector(model).ok_or_else(|| {
            format!("activation slot {source_slot} has unsupported model {model}")
        })?;
        let target = |slot: u16| {
            let entity = self
                .session
                .state
                .live
                .economy
                .entities
                .get(usize::from(slot))?;
            Some(ActivationTarget {
                source_slot: slot,
                bounds: ActivationBounds {
                    position: if slot == self.session.state.live.core.state.entity_index {
                        self.session.state.live.core.state.position
                    } else {
                        entity.position
                    },
                    half_width: i16::from_le_bytes(
                        entity.record_bytes()[88..90]
                            .try_into()
                            .expect("player width"),
                    ),
                    half_depth: i16::from_le_bytes(
                        entity.record_bytes()[90..92]
                            .try_into()
                            .expect("player depth"),
                    ),
                },
            })
        };
        let expected_overlap = rule.expected_overlap().unwrap_or(true);
        let matching_human = matching_target(
            bounds,
            expected_overlap,
            frozen_player_slots
                .iter()
                .copied()
                .filter(|slot| {
                    self.session
                        .state
                        .live
                        .economy
                        .entities
                        .get(usize::from(*slot))
                        .is_some_and(|entity| entity.model == 0)
                })
                .filter_map(target),
        );
        let matching_participant = matching_target(
            bounds,
            expected_overlap,
            self.session
                .state
                .live
                .core
                .players
                .iter()
                .take(usize::from(
                    self.session.state.live.core.runtime.player_count,
                ))
                .filter_map(|player| target(player.entity_index)),
        )
        .is_some();
        let completed_objective_owner = if model == 32 {
            let stage = imported
                .as_ref()
                .and_then(|source| u8::try_from(source.level_gate).ok());
            stage
                .filter(|stage| *stage < self.session.state.live.core.runtime.stage_index)
                .and_then(|stage| {
                    self.session
                        .state
                        .live
                        .core
                        .players
                        .iter()
                        .take(1)
                        .filter(|player| player.active_player_index >= 0)
                        .find_map(|player| {
                            let color = player.player_color_index();
                            (self
                                .session
                                .state
                                .live
                                .core
                                .runtime
                                .objectives
                                .get(usize::from(color))?
                                .stage_selectors
                                .get(usize::from(stage))
                                == Some(&2))
                            .then_some(color)
                        })
                })
        } else {
            None
        };
        let completion = if rule == ActivationRule::LevelComplete {
            frozen_player_slots.iter().copied().any(|slot| {
                let Some(entity) = self
                    .session
                    .state
                    .live
                    .economy
                    .entities
                    .get(usize::from(slot))
                else {
                    return false;
                };
                entity.model == 0
                    && source_player_order.iter().copied().any(|index| {
                        self.session
                            .state
                            .live
                            .core
                            .players
                            .get(index)
                            .is_some_and(|player| {
                                player.entity_index == slot
                                    && self
                                        .session
                                        .state
                                        .live
                                        .core
                                        .runtime
                                        .objectives
                                        .get(usize::from(player.player_color_index()))
                                        .is_some_and(|objective| objective.is_level_end != 0)
                            })
                    })
            })
        } else {
            completed_objective_owner.is_some()
        };
        let blocking_family_present = if rule == ActivationRule::AbsenceCountdown {
            if self.mechanic_kind_for_source_slot(source_slot).is_some() {
                self.countdown_observed_creature_present(source_slot, frozen_creature_slots)?
            } else {
                countdown_switch::mc2::blocking_family_present(
                    model,
                    &std::array::from_fn(|index| !frozen_creature_slots[index].is_empty()),
                )
                .unwrap_or(false)
            }
        } else {
            false
        };
        let arming_ticks = if rule == ActivationRule::AbsenceCountdown
            && self.session.definition.semantic_level().is_some()
        {
            self.countdown_arming_ticks_for_source_slot(source_slot)?
        } else {
            16
        };
        let observations = ActivationObservations {
            matching_human: matching_human.is_some(),
            matching_participant,
            completion,
            blocking_family_present,
            suppress_secret: self
                .session
                .state
                .live
                .economy
                .activation_settings
                .secret_entry_suppressed,
        };
        let step = if authored.is_some() {
            self.session
                .state
                .live
                .economy
                .economy
                .authored_switch_producers
                .iter_mut()
                .find(|row| row.source_entity_index == source_slot)
                .expect("resolved activation carrier")
                .visit(rule, observations, arming_ticks)
        } else {
            let step = countdown_switch::step_activation(
                rule,
                phase,
                &mut timer,
                observations,
                arming_ticks,
            );
            self.session.state.live.economy.entities[usize::from(source_slot)]
                .set_source_dword_10(timer);
            step
        };
        if step.hide_before_visit {
            if authored.is_some() {
                self.session
                    .state
                    .live
                    .economy
                    .complete_authored_switch_producer_slot(source_slot);
            } else {
                self.session.state.live.economy.entities[usize::from(source_slot)]
                    .disable_drawing();
            }
        }
        if step.follow_terrain {
            let mut position = bounds.position;
            position.z = self.session.state.live.terrain.ground_height(position);
            if authored.is_some() {
                self.session
                    .state
                    .live
                    .economy
                    .economy
                    .authored_switch_producers
                    .iter_mut()
                    .find(|row| row.source_entity_index == source_slot)
                    .expect("resolved activation carrier")
                    .position = position;
            } else {
                self.session.state.live.economy.entities[usize::from(source_slot)]
                    .set_position(position);
            }
        }
        match step.sound {
            ActivationSound::None => {}
            ActivationSound::Controller => {
                if model == 16 {
                    mark_source_audio_call(SourceAudioCallTag::CountdownSwitchModel16);
                } else if model == 17 {
                    mark_source_audio_call(SourceAudioCallTag::CountdownSwitchModel17);
                }
                self.push_flight_effect(FlightEvent::PrepareSound {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::CountdownSwitch,
                    entity_index: source_slot,
                    player_index: -1,
                    sound_id: 41,
                });
            }
            ActivationSound::MatchingPlayer => {
                self.push_flight_effect(FlightEvent::PrepareSound {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::ExitOverlap,
                    entity_index: matching_human.expect("transition requires matching human"),
                    player_index: -1,
                    sound_id: 41,
                });
            }
        }
        if let Some(transition) = step.transition {
            let player_slot = matching_human.expect("transition requires matching human");
            let portal_slot = match transition {
                PlayerTransition::OrdinaryExit => {
                    self.session.state.live.economy.class14_model3_handle
                }
                PlayerTransition::SecretEntry => {
                    self.session.state.live.economy.class14_model4_handle
                }
            };
            {
                self.session
                    .state
                    .live
                    .level_exit
                    .start(source_slot, portal_slot);
                mark_source_audio_call(SourceAudioCallTag::ExitOverlapSwitch);
                self.push_dispatch_effect(Mc2DispatchEvent::LevelExitSequenceStarted {
                    pass,
                    trigger_entity_index: source_slot,
                    portal_entity_index: portal_slot,
                });
            }
            let player = &mut self.session.state.live.economy.entities[usize::from(player_slot)];
            player.set_source_action(if transition == PlayerTransition::OrdinaryExit {
                12
            } else {
                11
            });
            player.set_source_byte_46(0);
            if portal_slot != 0
                && !self
                    .session
                    .state
                    .live
                    .economy
                    .reveal_authored_class14_slot(portal_slot)
            {
                if let Some(portal) = self
                    .session
                    .state
                    .live
                    .economy
                    .entities
                    .get_mut(usize::from(portal_slot))
                {
                    portal.set_control_flags(portal.control_flags & !1);
                }
            }
        }
        if let Some(lifetime) = step.publication {
            if let Some(owner_color) = completed_objective_owner {
                self.session.state.live.level2_objective_pause = 1;
                self.session.state.live.level2_objective_done = true;
                self.session
                    .state
                    .live
                    .core
                    .runtime
                    .mark_level2_objective_done_for(owner_color);
            }
            self.publish_authored_group(
                pass,
                source_slot,
                group,
                lifetime == PublicationLifetime::Consume,
            )?;
        }
        if authored.is_some() {
            self.session
                .state
                .live
                .economy
                .economy
                .authored_switch_producers
                .iter_mut()
                .find(|row| row.source_entity_index == source_slot)
                .expect("publication preserves activation carrier")
                .finish_publication(step);
        } else {
            let source = &mut self.session.state.live.economy.entities[usize::from(source_slot)];
            if let Some(timer) = step.timer_after_publication {
                source.set_source_dword_10(timer);
            }
            if step.hide_after_visit {
                source.disable_drawing();
            }
        }
        Ok(())
    }

    /// Dispatch one reset-imported class-11 switch at its numeric source
    /// slot. This replaces the old pre-dispatch side wrapper: source player
    /// membership is rebuilt before the scan, the live selector is read at
    /// visit time, and the scheduler owns the common phase epilogue.

    fn step_imported_terrain_strip(&mut self, source_slot: u16) -> std::result::Result<(), String> {
        let selector = self
            .session
            .state
            .live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|source| source.active && source.index == source_slot)
            .map(|source| (source.class, source.model, source.action))
            .ok_or_else(|| format!("terrain-strip callback lost source slot {source_slot}"))?;
        match selector {
            (14, 1, 6) => self.step_imported_terrain_strip_controller(source_slot),
            (14, 2, 7) => {
                let definition = &self.session.definition;
                let properties = definition
                    .mechanic_entity_for_initial_source_slot(source_slot)
                    .and_then(|id| definition.semantic_level()?.entity(id)?.cave_corridor());
                let visit = {
                    let live = &mut self.session.state.live;
                    if live.economy.economy.slot_generation(source_slot) == 0
                        && let Some(properties) = properties
                    {
                        terrain_strip::cave_corridors::bind_properties(
                            &mut live.economy.entities[usize::from(source_slot)],
                            properties,
                        );
                    }
                    terrain_strip::cave_corridors::visit(
                        &mut live.economy,
                        &mut live.terrain,
                        source_slot,
                    )
                };
                for effect in visit.effects(source_slot) {
                    self.push_flight_effect(effect);
                }
                Ok(())
            }
            (10, 63, 68) => self.step_imported_terrain_strip_trigger(source_slot, 2),
            (10, 64, 69) => self.step_imported_terrain_strip_trigger(source_slot, 1),
            _ => Err(format!(
                "terrain-strip handler rejects source selector {}/{}/{} at slot {source_slot}",
                selector.0, selector.1, selector.2
            )),
        }
    }

    fn step_imported_terrain_strip_controller(
        &mut self,
        source_slot: u16,
    ) -> std::result::Result<(), String> {
        let live = &mut self.session.state.live;
        let source = &mut live.economy.entities[usize::from(source_slot)];
        let life_before = source.life;
        let visit = terrain_strip::visit_source(source, &mut live.terrain);
        match visit.audio {
            Some(terrain_strip::TerrainStripAudioOutcome::Prepare47) => {
                mark_source_audio_call(if life_before == 1 {
                    SourceAudioCallTag::TerrainStripOpening
                } else {
                    SourceAudioCallTag::TerrainStripClosing
                });
                self.push_flight_effect(FlightEvent::PrepareSound {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::TerrainStrip,
                    entity_index: source_slot,
                    player_index: -1,
                    sound_id: 47,
                });
            }
            Some(terrain_strip::TerrainStripAudioOutcome::EndLoop47) => {
                self.push_flight_effect(FlightEvent::EndLoop {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::TerrainStrip,
                    entity_index: source_slot,
                    player_index: -1,
                    sound_id: 47,
                });
            }
            None => {}
        }
        Ok(())
    }

    fn step_imported_terrain_strip_trigger(
        &mut self,
        source_slot: u16,
        target_life: i32,
    ) -> std::result::Result<(), String> {
        let trigger_position =
            self.session.state.live.economy.entities[usize::from(source_slot)].position;
        self.set_terrain_strip_controller_life_at(trigger_position, target_life);
        self.session.state.live.economy.entities[usize::from(source_slot)].disable_drawing();
        Ok(())
    }

    fn step_dynamic_terrain_strip_close_trigger(
        &mut self,
        source_slot: u16,
    ) -> std::result::Result<(), String> {
        let trigger_position = self
            .session
            .state
            .live
            .economy
            .economy
            .terrain_strip_close_triggers()
            .iter()
            .find(|source| source.active && source.source_entity_index == source_slot)
            .map(|source| source.position)
            .ok_or_else(|| {
                format!("terrain-strip close callback lost dynamic source slot {source_slot}")
            })?;
        self.set_terrain_strip_controller_life_at(trigger_position, 2);
        if !self
            .session
            .state
            .live
            .economy
            .economy
            .complete_terrain_strip_close_trigger(source_slot)
        {
            return Err(format!(
                "terrain-strip close callback could not retain source slot {source_slot}"
            ));
        }
        Ok(())
    }

    fn set_terrain_strip_controller_life_at(
        &mut self,
        trigger_position: Position,
        target_life: i32,
    ) {
        let tile_x = trigger_position.x.wrapping_sub(128).to_be_bytes()[0];
        let tile_y = trigger_position.y.wrapping_sub(128).to_be_bytes()[0];
        let chain = self
            .session
            .state
            .live
            .economy
            .economy
            .map_chains()
            .entity_chain(tile_x, tile_y);
        let target = chain.into_iter().find(|candidate| {
            self.session.state.live.economy.entities[usize::from(*candidate)].active
                && self.session.state.live.economy.entities[usize::from(*candidate)].class == 14
                && matches!(
                    self.session.state.live.economy.entities[usize::from(*candidate)].model,
                    1 | 2
                )
        });
        if let Some(target) = target {
            self.session.state.live.economy.entities[usize::from(target)].set_life(target_life);
        }
    }

    /// Run the production Level 2 entity pass through the literal source
    /// scheduler. The adapter owns phase placement, live resolution, registry
    /// selection, callback invocation, epilogue policy, and following cleanup;
    /// retained family methods own only their typed callback bodies.
    pub(crate) fn step_level2_source_pass_with_player(
        &mut self,
        pass: u8,
        latched_command: crate::LatchedCommand,
        flight_tuning: crate::FlightTuning,
        evidence: &mut Vec<crate::StepEvidence>,
    ) -> std::result::Result<([bool; 29], Vec<u8>), (u16, String)> {
        let player_entity_index = self.session.state.live.core.state.entity_index;
        let player_position = self.session.state.live.core.state.position;
        let mut world = Level2SourceSchedulerWorld {
            owner: self,
            pass,
            latched_command,
            flight_tuning,
            evidence,
            source_player_order: Vec::new(),
            player_entity_index,
            player_position,
            goat_players: Vec::new(),
            pass_start_mana_sphere_slots: BTreeSet::new(),
            pass_start_class5_model_slots: std::array::from_fn(|_| Vec::new()),
            pass_start_class3_slots: Vec::new(),
            pass_start_class9_slots: Vec::new(),
            pass_start_capture_slots: Vec::new(),
            effect_lists: Default::default(),
            pass_start_settlement_building_slots: Vec::new(),
            pass_start_class5_model_present: [false; 29],
            pass_start_model45_building_selectors: Vec::new(),
            pass_start_castle_auxiliary_membership: Default::default(),
            pass_start_castle_root_slots: BTreeSet::new(),
            goat_begin_events: BTreeMap::new(),
        };
        run_update_entities(&mut world)
            .map(|_| {
                (
                    world.pass_start_class5_model_present,
                    world.pass_start_model45_building_selectors,
                )
            })
            .map_err(|error| match error {
                ScheduleError::UnknownDispatch { slot, selector, .. } => {
                    let message = match selector {
                        Level2ResolvedSourcePlan::Unknown { message, .. } => message,
                        selector => format!("unadmitted production selector {selector:?}"),
                    };
                    (slot, message)
                }
                ScheduleError::Adapter { slot, source, .. } => (slot.unwrap_or(0), source),
                ScheduleError::ApplyNoProgress { .. } | ScheduleError::ApplyScanLimit { .. } => (
                    0,
                    "ordinary UpdateEntities unexpectedly returned an ApplyEvents error".to_owned(),
                ),
            })
    }

    pub(super) fn step_level2_dynamic_spell_pickup(
        &mut self,
        pass: u8,
        source_slot: u16,
        player_entity_index: u16,
        player_position: Position,
        source_player_order: &[usize],
    ) -> bool {
        let Some(family) = self
            .session
            .state
            .live
            .economy
            .spell_pickups()
            .iter()
            .find(|source| source.source_entity_index == source_slot && source.active)
            .map(|source| source.family)
        else {
            return false;
        };
        let terrain = &self.session.state.live.terrain;
        match self
            .session
            .state
            .live
            .shared_spells
            .step_level2_spell_acquisition_with_economy_in_source_order(
                &mut self.session.state.live.economy,
                family,
                player_entity_index,
                player_position,
                terrain,
                source_player_order,
            ) {
            Ok(result) => {
                if let Some(outcome) = result
                    && let Err(error) = self.bind_rival_acquisition(outcome)
                {
                    self.push_dispatch_effect(Mc2DispatchEvent::Error { pass, source_slot, message: error.to_string() });
                    return false;
                }
                self.push_dispatch_effect(Mc2DispatchEvent::SpellAcquisition { pass, source_slot, family, result });
            }
            Err(error) => self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: error.to_string(),
            }),
        }
        if let Some(pickup) = self
            .session
            .state
            .live
            .shared_spells
            .pickup_mut(source_slot)
        {
            pickup.phase = pickup.phase.wrapping_add(1);
            pickup.record[66] = pickup.phase;
        }
        let Some((action, position)) = self
            .session
            .state
            .live
            .shared_spells
            .pickup(source_slot)
            .map(|pickup| (pickup.action, pickup.position))
        else {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: "dynamic spell pickup lost its shared entity projection".to_owned(),
            });
            return false;
        };
        if !self
            .session
            .state
            .live
            .economy
            .sync_spell_pickup_projection(source_slot, action, position)
        {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: "dynamic spell pickup lost its source-arena projection".to_owned(),
            });
            return false;
        }
        let remains_live = self
            .session
            .state
            .live
            .economy
            .step_spell_pickup_slot(source_slot);
        if let Err(error) = self.commit_imported_spell_source_projection(source_slot) {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: error.to_string(),
            });
            return false;
        }
        remains_live
    }

    /// Fixed-address parent input for sub_6A030, including retained and typed
    /// occupants. The holder never substitutes a cached player singleton.
    fn current_morph_parent(&self, owner: u16) -> Result<Option<EntitySnapshot>> {
        let live = &self.session.state.live;
        let mut context = source_target::Context::from_ordinary(&live.goats, &live.ordinary);
        context.spells = Some(&live.shared_spells);
        context.particles = Some(&self.session.definition.presentation.particles);
        source_target::status_parent(&live.economy, context, owner).map_err(NativeWorldError::new)
    }

    fn morph_parent_is_local(&self, parent: &EntitySnapshot) -> Result<bool> {
        let live = &self.session.state.live;
        let color = match parent.special_relation {
            EntitySpecialRelation::PlayerState(index) => live
                .shared_spells
                .players
                .iter()
                .chain(live.core.players.iter())
                .find(|player| player.slot == index)
                .map(PlayerSnapshot::player_color_index)
                .ok_or_else(|| {
                    NativeWorldError::new("Morph current parent A4 player record is absent")
                })?,
            // NewEvent uses the static zero-initialized unk_F42B0x. Source
            // writes playerColorIndex only in the player constructor.
            EntitySpecialRelation::GlobalSpecialState => 0,
            EntitySpecialRelation::None => {
                return Err(NativeWorldError::new(
                    "Morph current parent has no A4 relation",
                ));
            }
        };
        Ok(color == live.shared_spells.local_player.slot)
    }

    fn morph_holder_is_raw(&self, slot: u16) -> bool {
        self.session
            .state
            .live
            .shared_spells
            .local_player
            .enabled_spell_holders[4]
            != slot
    }

    /// One active Morph holder visit, with the source award → constructor →
    /// current-address control/payment → flicker → countdown/expiry order.
    fn step_morph_holder_source_slot(&mut self, source_slot: u16) -> Result<bool> {
        let raw = self.morph_holder_is_raw(source_slot);
        let live = &self.session.state.live;
        let holder = if raw {
            live.economy.entities.get(usize::from(source_slot))
        } else {
            live.shared_spells.pickup(source_slot)
        }
        .filter(|row| row.active && row.class == 15 && row.model == 4 && row.action == 12)
        .cloned()
        .ok_or_else(|| NativeWorldError::new("Morph holder source row is not live"))?;
        let owner = holder.source_spell_parent_entity_index();
        let mut parent = self.current_morph_parent(owner)?;
        let first = holder.active_value == holder.activation_value.cast_signed();
        let castle = parent
            .as_ref()
            .map(|parent| {
                source_target::status_castle_mana(&live.economy, &live.shared_spells, parent)
            })
            .transpose()
            .map_err(NativeWorldError::new)?
            .flatten();
        let gate = parent.as_ref().is_some_and(|parent| {
            parent.life >= 0
                && parent.mana >= 0
                && (holder.mana_regen == 0 || castle.is_some_and(|mana| mana >= holder.mana_regen))
                && (!first || parent.mana >= holder.max_mana)
        });
        let transition = crate::spell_activation::step_morph_spell(
            crate::spell_activation::MorphSpellStepInput {
                active_value: holder.active_value,
                activation_value: holder.activation_value.cast_signed(),
                presentation_timer: u16::from_le_bytes([holder.record[58], holder.record[59]]),
                parent_valid: parent.is_some(),
                source_gate_passed: gate,
                parent_mana_regen: parent.as_ref().map_or(0, |row| row.mana_regen),
                mana_cost: holder.max_mana,
            },
        );
        let holder_handle = live.economy.handle(source_slot);
        if transition.award_experience {
            award_source_spell_experience(&mut self.session.state.live, owner, 4, 1);
        }
        let mut spawned = None;
        if transition.request_creature
            && let Some(before) = parent.as_ref()
        {
            let tier = u8::try_from(holder.level_gate)
                .ok()
                .filter(|tier| *tier < 3)
                .ok_or_else(|| NativeWorldError::new("Morph holder has invalid physical tier"))?;
            let product = creatures::morph::select_product(
                self.session.state.live.terrain.map_type,
                tier,
                self.session.definition.morph_properties,
            )
            .ok_or_else(|| NativeWorldError::new("Morph has no configured source product"))?;
            let live = &mut self.session.state.live;
            spawned = if product == 2 {
                creatures::bee::mc2::allocate_morph(
                    &mut live.economy,
                    &mut live.terrain,
                    source_slot,
                    owner,
                    before.source_id,
                    before.position,
                )
                .map(|body| body.source_entity_index)
            } else {
                creatures::morph::allocate(
                    &mut live.economy,
                    &mut live.core.runtime,
                    &mut live.terrain,
                    &self.session.definition.presentation.particles,
                    product,
                    before,
                    before.position,
                )
                .map_err(NativeWorldError::new)?
            };
            // NewEvent may replace either pointer. The source reads both again
            // after construction instead of copying the predecessor's payload.
            parent = self.current_morph_parent(owner)?;
        }
        let current_holder = if spawned == Some(source_slot) {
            self.current_morph_parent(source_slot)?.ok_or_else(|| {
                NativeWorldError::new("Morph replacement holder address is absent")
            })?
        } else {
            holder.clone()
        };
        let mut active = if gate {
            current_holder.active_value
        } else if parent.is_some() && holder.active_value > 0 {
            1
        } else {
            holder.active_value
        };
        let mut child_slot = current_holder.source_word_96();
        if let Some(slot) = spawned {
            let live = &mut self.session.state.live;
            let parent_id = parent.as_ref().map_or(0, |row| row.source_id);
            let child_parent = current_holder.source_spell_parent_entity_index();
            let body = &mut live.economy.entities[usize::from(slot)];
            let model = live
                .economy
                .economy
                .bee_creatures
                .iter()
                .find(|row| row.active && row.source_entity_index == slot)
                .map_or(body.model, |row| row.model);
            body.set_source_action(model.wrapping_mul(8).wrapping_add(7));
            body.record[77] = 12;
            body.record[44..46].copy_from_slice(&child_parent.to_le_bytes());
            body.source_id = parent_id;
            body.record[30..32].copy_from_slice(&parent_id.to_le_bytes());
            body.set_control_flags(body.control_flags | 1);
            if let Some(bee) = live
                .economy
                .economy
                .bee_creatures
                .iter_mut()
                .find(|row| row.active && row.source_entity_index == slot)
            {
                bee.parent_entity_index = child_parent;
                bee.entity_id = parent_id;
                bee.control_flags |= 1;
            }
            if let (Some(child), Some(parent)) =
                (live.economy.handle(slot), live.economy.handle(child_parent))
            {
                live.economy.bind_creature_parent(child, parent);
            }
            child_slot = slot;
            if let (Some(holder_handle), Some(body_handle)) =
                (holder_handle, live.economy.handle(slot))
                && live.economy.resolve(holder_handle).is_some()
            {
                live.economy
                    .economy
                    .morph
                    .bind_body(holder_handle, body_handle);
            }
            if let Some(current_parent) = parent.as_mut() {
                let flags = current_parent.control_flags | 0x21;
                self.commit_source_parent_control(current_parent, flags)?;
                current_parent.set_control_flags(flags);
                if !self.morph_parent_is_local(current_parent)? {
                    self.set_morph_body_hidden(slot, false);
                }
            }
            mark_source_audio_call(SourceAudioCallTag::MorphSpellStart);
            self.session
                .state
                .live
                .shared_spells
                .emit_flight_effect(FlightEvent::PrepareSound {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::MorphSpellActivation,
                    entity_index: owner,
                    player_index: -1,
                    sound_id: 60,
                });
        }
        if holder.active_value > 0
            && let Some(current_parent) = parent.as_mut()
        {
            if gate {
                let fresh =
                    current_holder.active_value == current_holder.activation_value.cast_signed();
                if fresh || current_parent.mana_regen > 0 {
                    #[cfg(test)]
                    let payment_before = (current_parent.mana, current_parent.mana_regen);
                    let regen = if fresh {
                        if current_parent.mana_regen >= 0 {
                            current_holder.max_mana.wrapping_neg()
                        } else {
                            current_parent
                                .mana_regen
                                .wrapping_sub(current_holder.max_mana)
                        }
                    } else {
                        0
                    };
                    let mut after = current_parent.clone();
                    after.set_mana_regen(regen);
                    let live = &mut self.session.state.live;
                    source_target::commit_status_parent(
                        &mut live.economy,
                        &mut live.shared_spells,
                        None,
                        current_parent,
                        &after,
                    )
                    .map_err(NativeWorldError::new)?;
                    if current_parent.class == 3
                        && matches!(current_parent.model, 0 | 1)
                        && live.economy.economy.live_arena_kind(owner).is_none()
                        && matches!(current_parent.special_relation, EntitySpecialRelation::PlayerState(index)
                            if live.shared_spells.players.get(usize::from(index)).is_some_and(|player| player.entity_index == owner))
                    {
                        self.commit_spell_parent_mana_regen(owner, regen);
                    }
                    current_parent.set_mana_regen(regen);
                    #[cfg(test)]
                    if fresh && CREATURE17_TRACE.with(|trace| trace.borrow().is_some()) {
                        let arena = &self.session.state.live.economy;
                        if let (Some(holder), Some(parent)) =
                            (arena.handle(source_slot), arena.handle(current_parent.index))
                        {
                            let body = arena.economy.morph.body_for_holder(holder)
                                .filter(|body| arena.resolve(*body).is_some());
                            let committed = self.current_morph_parent(current_parent.index)
                                .map(|row| row.map(|row| (row.mana, row.mana_regen)))
                                .map_err(|error| error.to_string());
                            CREATURE17_TRACE.with(|trace| {
                                if let Some(trace) = trace.borrow_mut().as_mut() {
                                    trace.morph_payments.push(MorphPaymentReceipt {
                                        holder,
                                        parent,
                                        body,
                                        cost: current_holder.max_mana,
                                        before_mana: payment_before.0,
                                        before_regen: payment_before.1,
                                        after_regen: current_parent.mana_regen,
                                        committed,
                                    });
                                }
                            });
                        }
                    }
                }
            }
            let local = self.morph_parent_is_local(current_parent)?;
            let body_current = holder_handle.is_some_and(|handle| {
                self.session
                    .state
                    .live
                    .economy
                    .economy
                    .morph
                    .body_for_holder(handle)
                    .is_some_and(|child| {
                        child.source_slot == child_slot
                            && self.session.state.live.economy.resolve(child).is_some()
                    })
            });
            if !local && body_current {
                let hidden = crate::spell_activation::morph::remote_body_hidden(
                    active,
                    current_holder.activation_value.cast_signed(),
                );
                if let Some(hidden) = hidden {
                    self.set_morph_body_hidden(child_slot, hidden);
                    let flags = if hidden {
                        current_parent.control_flags & !1
                    } else {
                        current_parent.control_flags | 1
                    };
                    self.commit_source_parent_control(current_parent, flags)?;
                    current_parent.set_control_flags(flags);
                }
            }
            active = active.wrapping_sub(1);
            if active == 0 {
                let live = &mut self.session.state.live;
                let body = holder_handle
                    .and_then(|handle| live.economy.economy.morph.take_body(handle))
                    .filter(|body| {
                        body.source_slot == child_slot && live.economy.resolve(*body).is_some()
                    });
                if let Some(body) = body {
                    creatures::morph::expire(&mut live.economy, body.source_slot);
                    let _ = live.economy.economy.disable_morph_bee(body.source_slot);
                }
                child_slot = 0;
                let flags = if local {
                    current_parent.control_flags & !0x20
                } else {
                    current_parent.control_flags & !0x21
                };
                self.commit_source_parent_control(current_parent, flags)?;
                if local {
                    mark_source_audio_call(SourceAudioCallTag::MorphSpellExpiry);
                    self.session.state.live.shared_spells.emit_flight_effect(
                        FlightEvent::PrepareSound {
                            #[cfg(test)]
                            audio_site: crate::MissionAudioSite::MorphSpellActivation,
                            entity_index: owner,
                            player_index: -1,
                            sound_id: 60,
                        },
                    );
                }
            }
        }
        let presentation_timer = if spawned == Some(source_slot) {
            u16::from_le_bytes([current_holder.record[58], current_holder.record[59]])
                .saturating_sub(1)
        } else {
            transition.presentation_timer
        };
        let queued_profile = if active == 0
            && holder.active_value > 0
            && parent.is_some()
            && current_holder.source_word_2c() != 0
        {
            let tier = u8::try_from(current_holder.source_word_2c() - 1)
                .ok()
                .filter(|tier| *tier < 3)
                .ok_or_else(|| NativeWorldError::new("Morph holder has invalid queued tier"))?;
            Some((
                tier,
                self.session
                    .state
                    .live
                    .source_spell_profile(
                        4,
                        tier,
                        current_holder.source_spell_parent_entity_index(),
                    )
                    .ok_or_else(|| NativeWorldError::new("Morph queued profile is absent"))?,
            ))
        } else {
            None
        };
        let live = &mut self.session.state.live;
        let row = if raw || spawned == Some(source_slot) {
            live.economy.entities.get_mut(usize::from(source_slot))
        } else {
            live.shared_spells.pickup_mut(source_slot)
        };
        if let Some(row) = row {
            row.active_value = active;
            row.record[50..52].copy_from_slice(&active.to_le_bytes());
            row.record[58..60].copy_from_slice(&presentation_timer.to_le_bytes());
            row.set_source_word_96(child_slot);
            if let Some((tier, profile)) = queued_profile {
                row.set_source_word_2c(0);
                row.apply_nyphur_spell_profile(profile, tier);
            }
        }
        if !raw
            && spawned != Some(source_slot)
            && let Some(fire) = live.core.context.spell_fire.as_mut()
            && let Some(holder) = fire
                .holders
                .iter_mut()
                .find(|holder| holder.entity_index == source_slot)
        {
            holder.active_value = active;
        }
        Ok(true)
    }

    fn set_morph_body_hidden(&mut self, slot: u16, hidden: bool) {
        let live = &mut self.session.state.live;
        if let Some(body) = live.economy.entities.get_mut(usize::from(slot)) {
            body.set_control_flags(if hidden {
                body.control_flags | 1
            } else {
                body.control_flags & !1
            });
        }
        if let Some(body) = live
            .economy
            .economy
            .bee_creatures
            .iter_mut()
            .find(|row| row.active && row.source_entity_index == slot)
        {
            if hidden {
                body.control_flags |= 1;
            } else {
                body.control_flags &= !1;
            }
        }
    }

    fn current_dragon_projectile_threats(
        &self,
    ) -> Vec<level2_class5::dragon::DragonProjectileThreat> {
        use level2_class5::dragon::DragonProjectileThreat;
        let arena = &self.session.state.live.economy;
        let dynamic_slots = arena
            .live_arena_slots()
            .into_iter()
            .map(|(slot, _)| slot)
            .collect::<BTreeSet<_>>();
        let mut rows = arena
            .entities
            .iter()
            .filter(|row| row.active && row.class == 9 && !dynamic_slots.contains(&row.index))
            .map(|row| DragonProjectileThreat {
                source_slot: row.index,
                target: row.source_word_96(),
                life: row.life,
                flags: row.control_flags,
                yaw: row.yaw,
            })
            .collect::<Vec<_>>();
        rows.extend(
            arena
                .fireball_projectiles()
                .iter()
                .filter(|row| row.active)
                .map(|row| DragonProjectileThreat {
                    source_slot: row.source_entity_index,
                    target: row.target_source_entity_index,
                    life: i32::from(row.life),
                    yaw: row.yaw,
                    flags: row.control_flags
                        | if row.drawing_disabled {
                            ENTITY_DRAW_DISABLED_BIT
                        } else {
                            0
                        },
                }),
        );
        rows.extend(
            arena
                .possession_projectiles()
                .iter()
                .filter(|row| row.active)
                .map(|row| DragonProjectileThreat {
                    source_slot: row.source_entity_index,
                    target: row.target_source_entity_index,
                    life: i32::from(row.life),
                    yaw: row.yaw,
                    flags: 0,
                }),
        );
        rows.extend(
            arena
                .castle_projectiles()
                .iter()
                .filter(|row| row.active)
                .map(|row| DragonProjectileThreat {
                    source_slot: row.source_entity_index,
                    target: row.source_word_96,
                    life: row.life,
                    yaw: row.yaw,
                    flags: row.control_flags
                        | if row.drawing_disabled {
                            ENTITY_DRAW_DISABLED_BIT
                        } else {
                            0
                        },
                }),
        );
        rows.extend(
            arena
                .authored_class5_archer_children()
                .iter()
                .filter(|row| row.active && row.source_class == 9)
                .map(|row| DragonProjectileThreat {
                    source_slot: row.source_entity_index,
                    target: row.word_0x96,
                    life: i32::from(row.life),
                    yaw: row.yaw,
                    flags: row.control_flags
                        | if row.drawing_enabled {
                            0
                        } else {
                            ENTITY_DRAW_DISABLED_BIT
                        },
                }),
        );
        rows.extend(
            arena
                .model6_spawned_children()
                .iter()
                .filter(|row| row.active && row.source_class == 9)
                .map(|row| DragonProjectileThreat {
                    source_slot: row.source_entity_index,
                    target: 0,
                    life: i32::from(row.life),
                    yaw: row.yaw,
                    flags: row.control_flags,
                }),
        );
        rows
    }

    fn commit_spell_parent_mana_regen(&mut self, parent_entity_index: u16, mana_regen: i32) {
        if self.session.state.live.shared_spells.player_entity.index == parent_entity_index {
            self.session
                .state
                .live
                .shared_spells
                .player_entity
                .set_mana_regen(mana_regen);
        }
        for entity in &mut self.session.state.live.shared_spells.player_entities {
            if entity.index == parent_entity_index {
                entity.set_mana_regen(mana_regen);
            }
        }
        let live = &mut self.session.state.live;
        let handle = live.economy.handle(parent_entity_index);
        if let Some(entity) = live.economy.entities.iter_mut().find(|entity| entity.index == parent_entity_index)
        {
            entity.set_mana_regen(mana_regen);
            if let Some(dispatcher) = handle.and_then(|handle| live.nyphur_dispatcher.get_mut(handle))
                && dispatcher.sync_spell_target_resources(entity)
            {
                dispatcher.apply_holder_mana_regen(mana_regen);
            }
        }
    }

    fn validate_status_holder_owner(&self, source_slot: u16) -> std::result::Result<(), String> {
        let live = &self.session.state.live;
        let holder = live
            .economy
            .entities
            .get(usize::from(source_slot))
            .filter(|holder| holder.active && holder.class == 15)
            .ok_or_else(|| format!("status holder {source_slot} has no live source row"))?;
        let owner = holder.source_spell_parent_entity_index();
        if owner == live.core.state.entity_index {
            return Ok(());
        }
        // A vanished parent follows the existing callback's null-parent
        // countdown/cleanup. A different live actor must never inherit it.
        if !live.economy.entities.get(usize::from(owner))
            .is_some_and(|parent| parent.active && parent.class == 3)
        {
            return Ok(());
        }
        let handle = live
            .economy
            .handle(owner)
            .ok_or_else(|| format!("status holder {source_slot} lost owner {owner}"))?;
        let player = live
            .core
            .players
            .iter()
            .find(|player| player.entity_index == owner)
            .ok_or_else(|| format!("status holder {source_slot} has no owner player row"))?;
        let bound = live.nyphur_dispatcher.bound_live_holder(
            handle,
            player,
            &live.economy,
            usize::from(holder.model),
        );
        if bound.is_some_and(|holder| holder.source_slot == source_slot) {
            Ok(())
        } else {
            Err(format!(
                "status holder {source_slot} is not bound to owner {owner}'s current generation"
            ))
        }
    }

    fn commit_support_parent_feedback(&mut self, feedback: Option<(u16, bool)>) {
        let Some((owner, stop_player)) = feedback else {
            return;
        };
        let live = &mut self.session.state.live;
        let Some(handle) = live.economy.handle(owner) else {
            return;
        };
        if let Some(dispatcher) = live.nyphur_dispatcher.get_mut(handle)
            && let Some(parent) = live.economy.entities.get(usize::from(owner))
        {
            dispatcher.sync_support_parent_resources(parent, stop_player);
        }
    }

    fn commit_source_parent_control(&mut self, parent: &EntitySnapshot, flags: u32) -> Result<()> {
        let mut after = parent.clone();
        after.set_control_flags(flags);
        let live = &mut self.session.state.live;
        source_target::commit_status_parent(
            &mut live.economy,
            &mut live.shared_spells,
            Some(&mut area_damage::ActorDomains::new(
                &mut live.goats,
                &mut live.ordinary,
            )),
            parent,
            &after,
        )
        .map_err(NativeWorldError::new)?;
        // Only the current player incarnation can update player-only caches.
        if parent.class == 3
            && matches!(parent.model, 0 | 1)
            && live.economy.economy.live_arena_kind(parent.index).is_none()
            && matches!(parent.special_relation, EntitySpecialRelation::PlayerState(index)
                if live.shared_spells.players.get(usize::from(index)).is_some_and(|player| player.entity_index == parent.index))
        {
            live.shared_spells.sync_player_entity_from_authority(&after);
            if parent.index == live.shared_spells.player_entity.index {
                live.shared_spells.caster.control_flags = flags;
            }
            if let Some(fire) = live.core.context.spell_fire.as_mut()
                && fire.caster.entity_index == parent.index
            {
                fire.caster.control_flags = flags;
            }
        }
        Ok(())
    }

    fn step_dynamic_morph_holder(&mut self, pass: u8, source_slot: u16) -> bool {
        if let Err(error) = self.step_morph_holder_source_slot(source_slot) {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: error.to_string(),
            });
            return false;
        }
        if let Some(holder) = self
            .session
            .state
            .live
            .shared_spells
            .pickup_mut(source_slot)
        {
            holder.phase = holder.phase.wrapping_add(1);
            holder.record[66] = holder.phase;
        }
        let Some((action, position)) = self
            .session
            .state
            .live
            .shared_spells
            .pickup(source_slot)
            .map(|holder| (holder.action, holder.position))
        else {
            return false;
        };
        if !self
            .session
            .state
            .live
            .economy
            .sync_spell_pickup_projection(source_slot, action, position)
        {
            return false;
        }
        let remains_live = self
            .session
            .state
            .live
            .economy
            .step_spell_pickup_slot(source_slot);
        if self
            .commit_imported_spell_source_projection(source_slot)
            .is_err()
        {
            return false;
        }
        remains_live
    }

    /// Publish a source speed write through the current A4 and body owners.
    fn write_speed_parent_speed(&mut self, parent: &EntitySnapshot, speed: i16) {
        let live = &mut self.session.state.live;
        match parent.special_relation {
            EntitySpecialRelation::GlobalSpecialState => {
                live.shared_spells.global_special_state.speed = speed
            }
            EntitySpecialRelation::PlayerState(index) => {
                if index == live.shared_spells.local_player.slot {
                    live.core.state.target_speed = speed;
                } else if let Some(player) = live.shared_spells.players.get_mut(usize::from(index)) {
                    if !live
                        .nyphur_dispatcher
                        .set_retained_speed_a4(player.entity_index, speed)
                    {
                        player.record[20..22].copy_from_slice(&speed.to_le_bytes());
                    }
                }
            }
            _ => {}
        }
        source_target::commit_status_speed(
            &mut live.economy,
            Some(area_damage::ActorDomains::new(
                &mut live.goats,
                &mut live.ordinary,
            )),
            parent,
            speed,
        );
        if parent.active
            && parent.class == 3
            && matches!(parent.model, 0 | 1)
            && live.economy.economy.live_arena_kind(parent.index).is_none()
            && live.shared_spells.players.iter().any(|player| {
                player.entity_index == parent.index
                    && parent.special_relation == EntitySpecialRelation::PlayerState(player.slot)
            })
        {
            if parent.index == live.core.state.entity_index {
                live.core.state.actual_speed = speed;
            }
            live.shared_spells
                .sync_player_entity_from_authority(&live.economy.entities[usize::from(parent.index)]);
        }
    }

    /// Dispatch the acquired family-3 holder through `GetScroll_69DB0` at
    /// its real numeric source slot.
    fn step_speed_holder_source_slot(&mut self, source_slot: u16) -> bool {
        let Some(holder) = self
            .session
            .state
            .live
            .shared_spells
            .pickup(source_slot)
            .filter(|holder| {
                holder.active && holder.class == 15 && holder.model == 3 && holder.action == 9
            })
            .cloned()
        else {
            return false;
        };
        let parent_entity_index = u16::from_le_bytes([holder.record[44], holder.record[45]]);
        let live = &self.session.state.live;
        let mut context = source_target::Context::from_ordinary(&live.goats, &live.ordinary);
        context.spells = Some(&live.shared_spells);
        let Ok(parent) = source_target::status_parent(&live.economy, context, parent_entity_index)
        else {
            return false;
        };
        let current_player = parent.as_ref().is_some_and(|parent| {
            parent.active
                && parent.class == 3
                && matches!(parent.model, 0 | 1)
                && live
                    .economy
                    .economy
                    .live_arena_kind(parent_entity_index)
                    .is_none()
                && live.shared_spells.players.iter().any(|player| {
                    player.entity_index == parent_entity_index
                        && parent.special_relation == EntitySpecialRelation::PlayerState(player.slot)
                })
        });
        let owner_is_local = current_player && parent_entity_index == live.core.state.entity_index;
        let local_a4 = parent.as_ref().is_some_and(|parent| {
            parent.special_relation
                == EntitySpecialRelation::PlayerState(live.shared_spells.local_player.slot)
        });
        let player_a4 = parent
            .as_ref()
            .and_then(|parent| match parent.special_relation {
                EntitySpecialRelation::PlayerState(index) => {
                    live.shared_spells.players.get(usize::from(index))
                }
                _ => None,
            });
        let a4_owner = player_a4.map(|player| player.entity_index);
        let global_a4 = parent
            .as_ref()
            .is_some_and(|parent| parent.special_relation == EntitySpecialRelation::GlobalSpecialState);
        let (target_speed, speed_changed) = if global_a4 {
            let global = live.shared_spells.global_special_state;
            (global.speed, global.speed_changed != 0)
        } else if local_a4 {
            let state = &self.session.state.live.core.state;
            (state.target_speed, state.speed_changed_flag != 0)
        } else if let Some(dispatcher) =
            a4_owner.and_then(|owner| live.nyphur_dispatcher.retained_speed_a4(owner))
        {
            let (speed, changed) = dispatcher;
            (speed, changed != 0)
        } else {
            // A reclaimed player retains its original A4 until NewEvent.
            // Read that compact player carrier even without a live body.
            player_a4.map_or((0, false), |player| {
                (
                    i16::from_le_bytes([player.record[20], player.record[21]]),
                    false,
                )
            })
        };
        let first_active_tick = holder.active_value == holder.activation_value.cast_signed();
        let castle_mana = match parent
            .as_ref()
            .map(|parent| source_target::status_castle_mana(&live.economy, &live.shared_spells, parent))
            .transpose()
        {
            Ok(mana) => mana.flatten(),
            Err(_) => return false,
        };
        let source_gate_passed = parent.as_ref().is_some_and(|parent| {
            parent.life >= 0
                && parent.mana >= 0
                && (holder.mana_regen == 0 || castle_mana.is_some_and(|mana| mana >= holder.mana_regen))
                && (!first_active_tick || parent.mana >= holder.max_mana)
        });
        let presentation_timer = u16::from_le_bytes([holder.record[58], holder.record[59]]);
        let parent_mana_regen = parent.as_ref().map_or(0, |parent| parent.mana_regen);
        let minimum_speed = parent
            .as_ref()
            .map_or(PLAYER_MIN_SPEED, EntitySnapshot::minimum_speed);
        let Some(tier) = level2_applied_tier(holder.level_gate).filter(|tier| *tier < 3) else {
            return false;
        };
        let multiplier = self.session.definition.speed_multipliers[usize::from(tier)];
        let transition =
            crate::spell_activation::step_speed_spell(crate::spell_activation::SpeedSpellStepInput {
                active_value: holder.active_value,
                activation_value: holder.activation_value.cast_signed(),
                holder_phase: holder.phase,
                holder_control_flags: holder.control_flags,
                presentation_timer,
                parent_valid: parent.is_some(),
                source_gate_passed,
                speed_changed,
                direction: if target_speed < 0 { -1 } else { 1 },
                minimum_speed,
                first_multiplier: multiplier.wrapping_add(1) as i16,
                sustain_multiplier: multiplier as i16,
                parent_mana_regen,
                mana_cost: holder.max_mana,
                latch_clear_offset: if parent.as_ref().is_some_and(|parent| parent.model == 1) {
                    64
                } else {
                    2
                },
            });

        if transition.prepare_sound_19 {
            mark_source_audio_call(SourceAudioCallTag::SpeedSpellActivation);
            self.session
                .state
                .live
                .shared_spells
                .emit_flight_effect(FlightEvent::PrepareSound {
                    #[cfg(test)]
                    audio_site: crate::MissionAudioSite::SpeedSpellActivation,
                    entity_index: parent_entity_index,
                    player_index: -1,
                    sound_id: 19,
                });
        }
        if transition.award_experience
            && parent
                .as_ref()
                .is_some_and(|parent| (parent.class, parent.model) == (3, 0))
        {
            let live = &mut self.session.state.live;
            live.shared_spells
                .award_speed_experience(parent_entity_index, 1);
            publish_spell_progression(live, parent_entity_index, 3);
        }
        let pulsed =
            holder.active_value > 0 && parent.is_some() && source_gate_passed && !speed_changed;
        let direction = if target_speed < 0 { -1_i16 } else { 1_i16 };
        if pulsed {
            let speed = direction
                .wrapping_mul(minimum_speed)
                .wrapping_mul(if first_active_tick {
                    multiplier.wrapping_add(1) as i16
                } else {
                    multiplier as i16
                });
            self.write_speed_parent_speed(parent.as_ref().unwrap(), speed);
        }
        if transition.request_trail
            && let Some(parent) = parent.as_ref()
        {
            let live = &mut self.session.state.live;
            if let Some(slot) = live
                .economy
                .allocate_source_slot_with_terrain(&mut live.terrain)
            {
                // NewAdd0A02 reads its position pointer after NewEvent. The
                // source argument aliases cleared storage if it reuses parent.
                let (position, source_id) = if slot == parent_entity_index {
                    let current = &live.economy.entities[usize::from(slot)];
                    (current.position, current.source_id)
                } else {
                    (parent.position, parent.source_id)
                };
                live.economy
                    .economy
                    .initialize_speed_trail_at(slot, position, source_id);
            }
        }
        let live = &self.session.state.live;
        let mut context = source_target::Context::from_ordinary(&live.goats, &live.ordinary);
        context.spells = Some(&live.shared_spells);
        let Ok(current_parent) =
            source_target::status_parent(&live.economy, context, parent_entity_index)
        else {
            return false;
        };
        if pulsed && let Some(current) = current_parent.as_ref() {
            let regen = if first_active_tick {
                Some(if current.mana_regen >= 0 {
                    holder.max_mana.wrapping_neg()
                } else {
                    current.mana_regen.wrapping_sub(holder.max_mana)
                })
            } else {
                (current.mana_regen > 0).then_some(0)
            };
            if let Some(regen) = regen {
                let live = &mut self.session.state.live;
                let is_player = current.active
                    && current.class == 3
                    && matches!(current.model, 0 | 1)
                    && live
                        .economy
                        .economy
                        .live_arena_kind(current.index)
                        .is_none()
                    && live.shared_spells.players.iter().any(|player| {
                        player.entity_index == current.index
                            && current.special_relation
                                == EntitySpecialRelation::PlayerState(player.slot)
                    });
                if is_player {
                    self.commit_spell_parent_mana_regen(current.index, regen);
                } else {
                    let mut after = current.clone();
                    after.set_mana_regen(regen);
                    if source_target::commit_status_parent(
                        &mut live.economy,
                        &mut live.shared_spells,
                        None,
                        current,
                        &after,
                    )
                    .is_err()
                    {
                        return false;
                    }
                }
            }
        }
        if transition.expired
            && let Some(current) = current_parent.as_ref()
        {
            self.write_speed_parent_speed(current, direction.wrapping_mul(current.minimum_speed()));
        }
        let queued_profile = transition
            .expired
            .then(|| {
                let queued = i16::from_le_bytes([holder.record[48], holder.record[49]]);
                let tier = (queued > 0).then(|| queued.saturating_sub(1).min(2) as u8)?;
                let profile =
                    self.session
                        .state
                        .live
                        .source_spell_profile(3, tier, parent_entity_index)?;
                Some((tier, profile))
            })
            .flatten();
        if let Some(authoritative) = self
            .session
            .state
            .live
            .shared_spells
            .pickup_mut(source_slot)
        {
            authoritative.active_value = transition.active_value;
            authoritative.record[50..52].copy_from_slice(&transition.active_value.to_le_bytes());
            authoritative.set_control_flags(transition.holder_control_flags);
            authoritative.record[58..60].copy_from_slice(&transition.presentation_timer.to_le_bytes());
            if let Some((tier, profile)) = queued_profile {
                authoritative.record[48..50].fill(0);
                authoritative.apply_nyphur_spell_profile(profile, tier);
            }
        }
        if owner_is_local
            && let Some(speed_holder) = self
                .session
                .state
                .live
                .core
                .context
                .speed_spell_holder
                .as_mut()
                .filter(|holder| holder.entity_index == source_slot)
        {
            speed_holder.active_value = transition.active_value;
        }
        if let Some(fire) = self.session.state.live.core.context.spell_fire.as_mut()
            && fire.caster.entity_index == parent_entity_index
            && let Some(holder) = fire
                .holders
                .iter_mut()
                .find(|holder| holder.entity_index == source_slot)
        {
            holder.active_value = transition.active_value;
        }
        true
    }
    fn step_dynamic_castle_holder(&mut self, pass: u8, source_slot: u16) -> bool {
        self.step_level2_castle_holder_source_slot(source_slot);
        if let Some(holder) = self
            .session
            .state
            .live
            .shared_spells
            .pickup_mut(source_slot)
        {
            holder.phase = holder.phase.wrapping_add(1);
            holder.record[66] = holder.phase;
        }
        let Some((action, position)) = self
            .session
            .state
            .live
            .shared_spells
            .pickup(source_slot)
            .map(|holder| (holder.action, holder.position))
        else {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: "dynamic Castle holder lost its shared entity projection".to_owned(),
            });
            return false;
        };
        if !self
            .session
            .state
            .live
            .economy
            .sync_spell_pickup_projection(source_slot, action, position)
        {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: "dynamic Castle holder lost its source-arena projection".to_owned(),
            });
            return false;
        }
        // The active holder and the ordinary pickup share this NewEvent
        // carrier. Keep its phase current while action6 owns the callback;
        // cleanup can return it to action7 in this same visit.
        let remains_live = self
            .session
            .state
            .live
            .economy
            .step_spell_pickup_slot(source_slot);
        if let Err(error) = self.commit_imported_spell_source_projection(source_slot) {
            self.push_dispatch_effect(Mc2DispatchEvent::Error {
                pass,
                source_slot,
                message: error.to_string(),
            });
            return false;
        }
        remains_live
    }

