    #[test]
    fn owner_effect_impact_runs_damage_animation_hide_and_next_pass_reclaim() {
        let mut session = level_two_nyphur_possession_session();
        let particles = session.session.definition.presentation.particles.clone();
        let (slot, target, before, phase) = {
            let live = &mut session.session.state.live;
            let target = live
                .goats
                .goats()
                .iter()
                .find(|s| s.active)
                .expect("owner-package Goat");
            let target_slot = target.entity_index;
            let position = target.position;
            let before = target.life;
            let slot = crate::world::effects::allocate(
                &mut live.economy,
                &mut live.terrain,
                sim_definition::adapter::mc2_effect_definition(
                    crate::level_definition::EffectKind::Impact,
                ),
                position,
                &particles,
            )
            .unwrap()
            .expect("ordinary impact constructor");
            (
                slot,
                target_slot,
                before,
                live.economy.entities[usize::from(slot)].phase,
            )
        };
        session.step_level2_source_pass(0);
        let row = &session.entities()[usize::from(slot)];
        assert_eq!(row.phase, phase.wrapping_add(1));
        assert_eq!(
            row.record[96], 1,
            "actual callback advances the retained particle frame"
        );
        assert!(
            session
                .campaign_entity_presentations(0)
                .unwrap()
                .iter()
                .any(|s| s.entity_index == slot && s.selected_tmap == s.base_tmap.wrapping_add(1))
        );
        let goat = session
            .session
            .state
            .live
            .goats
            .goats()
            .iter()
            .find(|s| s.entity_index == target)
            .unwrap();
        assert!(
            goat.pending_damage > 0 || goat.life < before,
            "actual overlap writes the existing Goat damage carrier"
        );
        let mut hidden = false;
        for pass in 1..12 {
            session.step_level2_source_pass(pass);
            let row = &session.entities()[usize::from(slot)];
            if row.active && row.drawing_disabled() {
                hidden = true;
                assert!(
                    !session
                        .campaign_entity_presentations(0)
                        .unwrap()
                        .iter()
                        .any(|s| s.entity_index == slot)
                );
                session.step_level2_source_pass(pass.wrapping_add(1));
                assert!(
                    !session.entities()[usize::from(slot)].active,
                    "following prologue reclaims hidden occupant"
                );
                break;
            }
        }
        assert!(hidden, "ordinary lifetime reaches its hide callback");
    }

    #[test]
    fn owner_fire_spheres_root_moves_all_sectors_without_child_callbacks() {
        let mut session = level_two_nyphur_possession_session();
        let particles = session.session.definition.presentation.particles.clone();
        let (slot, phases) = {
            let live = &mut session.session.state.live;
            let position = live.core.state.position;
            let slot = crate::world::effects::allocate(
                &mut live.economy,
                &mut live.terrain,
                sim_definition::adapter::mc2_effect_definition(
                    crate::level_definition::EffectKind::FireSpheres,
                ),
                position,
                &particles,
            )
            .unwrap()
            .expect("ordinary root plus25 sectors");
            let phases = live
                .economy
                .model76_children()
                .iter()
                .filter(|s| s.parent_entity_index == slot)
                .map(|s| (s.source_entity_index, s.phase, s.position))
                .collect::<Vec<_>>();
            (slot, phases)
        };
        assert_eq!(phases.len(), 25);
        session.step_level2_source_pass(0);
        let children = session
            .economy()
            .model76_children()
            .iter()
            .filter(|s| s.parent_entity_index == slot)
            .collect::<Vec<_>>();
        assert!(
            children.iter().all(|s| phases
                .iter()
                .any(|(id, phase, _)| *id == s.source_entity_index && *phase == s.phase)),
            "disabled84 has no common phase increment"
        );
        assert!(
            children.iter().any(|s| phases
                .iter()
                .any(|(id, _, position)| *id == s.source_entity_index && *position != s.position)),
            "root actually moves linked sectors"
        );
        assert_eq!(
            session
                .campaign_entity_presentations(0)
                .unwrap()
                .iter()
                .filter(|s| phases.iter().any(|(id, ..)| *id == s.entity_index))
                .count(),
            25
        );
        assert_eq!(
            session
                .economy()
                .authored_model76()
                .iter()
                .find(|s| s.source_entity_index == slot)
                .unwrap()
                .life,
            79
        );
    }

    #[test]
    fn authored_group_rebuild_drains_hidden_house_authority_before_reuse() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-1pb-16-level2-full-build-v2");
        let campaign = CampaignSession::open(package, CampaignSelection::LEVEL2).unwrap();
        let mut session = campaign.simulation().clone();
        let house = *session
            .ordinary()
            .houses()
            .iter()
            .find(|house| house.entity_index == 10)
            .unwrap();
        let attacker = session.state.entity_index;
        session
            .ordinary_mut()
            .inject_house_damage(house.entity_index, house.life + 1, attacker as i16)
            .unwrap();
        session.step_level2_source_pass(0);
        session.step_level2_source_pass(1);
        assert!(session.ordinary().houses().iter().any(|row| {
            row.entity_index == house.entity_index && !row.active && row.source_retained()
        }));

        // Even an empty GenerateEvents group runs 49F90. It must drain the
        // owning family before exposing the same source address to NewEvent.
        session
            .publish_authored_group(0, attacker, 32767, true)
            .unwrap();
        assert!(
            session
                .ordinary()
                .houses()
                .iter()
                .all(|row| { row.entity_index != house.entity_index })
        );
        let arena = &session.session.state.live.economy;
        let raw = &arena.entities[usize::from(house.entity_index)];
        assert!(!raw.active && raw.class == 0);
        assert!(arena.free_slots.contains(&house.entity_index));
        let tile = u16::from(house.position.x >> 8) | ((house.position.y >> 8) << 8);
        assert_eq!(
            session.canonical_terrain().planes().entity_indices[usize::from(tile)],
            arena.map_chains.tile_head(tile) as i16,
            "group rebuild publishes the retired House cell head"
        );
    }

    #[test]
    fn qualified_house_lazy_rollback_matches_eager_outputs_and_hashes() {
        fn eager_reference(
            compatibility: &mut Mc2Simulation,
            source_slot: u16,
        ) -> std::result::Result<Vec<HouseStepEvent>, String> {
            let live = &mut compatibility.session.state.live;
            let ordinary_before = live.ordinary.clone();
            let economy_before = live.economy.clone();
            let terrain_before = live.terrain.clone();
            let events = live
                .ordinary
                .step_house_action_52(source_slot, &live.terrain);
            match live.ordinary.apply_house_terrain_events(
                &mut live.economy,
                &mut live.goats,
                &events,
                &mut live.terrain,
            ) {
                Ok(()) => {
                    live.ordinary
                        .publish_house_source(&mut live.economy, source_slot);
                    Ok(events)
                }
                Err(error) => {
                    live.ordinary = ordinary_before;
                    live.economy = economy_before;
                    live.terrain = terrain_before;
                    Err(format!("Level 2 House sink failed: {error}"))
                }
            }
        }
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let gameplay_cache = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/level2-day-owner-cache/components/gameplay");
        let baseline = CampaignSession::open_with_owner_cache(
            &package,
            &gameplay_cache,
            CampaignSelection::LEVEL2,
        )
        .expect("qualified House rollback campaign opens with owner BUILD footprints");
        let house = &baseline.simulation().ordinary().houses()[0];
        let source_slot = house.entity_index;
        assert!(
            baseline
                .simulation()
                .ordinary()
                .house_build_footprints
                .contains_key(&house.building_index),
            "the real owner BUILD footprint used by both construction cases is bound"
        );
        for case in [
            "idle",
            "damaged",
            "construction",
            "missing-footprint",
            "removal",
            "missing-removal-footprint",
        ] {
            let mut actual = baseline.clone();
            {
                let live = &mut actual.simulation_mut().session.state.live;
                let house = live.ordinary.houses.house_mut(source_slot).unwrap();
                house.phase = 1;
                house.pending_damage = 0;
                house.pending_attacker = 0;
                house.pending_possession_payload = 0;
                house.pending_possession_owner = 0;
                match case {
                    "idle" => {}
                    "damaged" => {
                        house.pending_damage = 250;
                        house.pending_attacker = 111;
                    }
                    "construction" | "missing-footprint" => {
                        house.action = crate::house::HOUSE_TERRAIN_TO_LIVE_ACTION;
                        house.life = 2;
                    }
                    "removal" | "missing-removal-footprint" => {
                        house.action = crate::house::HOUSE_REMOVE_ACTION;
                    }
                    _ => unreachable!(),
                }
                if matches!(case, "missing-footprint" | "missing-removal-footprint") {
                    let building_index = house.building_index;
                    assert!(
                        live.ordinary
                            .house_build_footprints
                            .remove(&building_index)
                            .is_some()
                    );
                }
            }
            let before = actual.clone();
            let mut reference = actual.clone();
            let expected = eager_reference(reference.simulation_mut(), source_slot);
            let observed = actual
                .simulation_mut()
                .step_level2_house_sink_with_rollback(source_slot);
            assert_eq!(observed, expected, "ordered House events/error: {case}");
            assert_eq!(
                actual.simulation(),
                reference.simulation(),
                "all rollback and source carriers: {case}"
            );
            assert_eq!(
                actual.state_hash(),
                reference.state_hash(),
                "canonical hash: {case}"
            );
            if matches!(case, "missing-footprint" | "missing-removal-footprint") {
                assert!(observed.unwrap_err().contains("BUILD footprint"));
                assert_eq!(
                    actual.simulation(),
                    before.simulation(),
                    "failure restores every pre-callback domain"
                );
            } else {
                let events = observed.unwrap();
                match case {
                    "idle" => assert!(events.is_empty()),
                    "damaged" => assert!(
                        events
                            .iter()
                            .any(|event| matches!(event, HouseStepEvent::Damaged { .. }))
                    ),
                    "construction" => assert!(
                        events
                            .iter()
                            .any(|event| matches!(event, HouseStepEvent::ConstructionPass { .. }))
                    ),
                    "removal" => assert!(
                        events
                            .iter()
                            .any(|event| matches!(event, HouseStepEvent::RemoveFootprint { .. }))
                    ),
                    _ => unreachable!(),
                }
                assert_eq!(actual.simulation().ordinary().houses()[0].phase, 2);
                let live = &actual.simulation().session.state.live;
                let house = live
                    .ordinary
                    .houses()
                    .iter()
                    .find(|house| house.entity_index == source_slot)
                    .unwrap();
                let raw = &live.economy.entities[usize::from(source_slot)];
                assert_eq!(
                    (raw.life, raw.action, raw.phase, raw.position),
                    (house.life, house.action, house.phase, house.position),
                    "generic consumers see the completed House callback, including idle: {case}"
                );
            }
        }
    }

    #[test]
    fn qualified_public_recovery_uses_current_castle_or_source_spawn() {
        fn assert_no_dispatch_error(campaign: &CampaignSession) {
            assert!(
                campaign
                    .simulation()
                    .dispatch_events()
                    .iter()
                    .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. })),
                "{:?}",
                campaign.simulation().dispatch_events()
            );
        }
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        for (dead, with_castle) in [(true, true), (true, false), (false, true)] {
            let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2).unwrap();
            // Retain an already advanced world, rather than a reset-state-only fixture.
            let _ = campaign.step(PlayerCommand::default(), 0);
            assert_no_dispatch_error(&campaign);
            let actor_slot = campaign.simulation().state.entity_index;
            let held_before = campaign
                .simulation()
                .shared_spells()
                .local_player()
                .enabled_spell_holders;
            let castle_position = if with_castle {
                let live = &mut campaign.simulation_mut().session.state.live;
                let terrain = live.terrain.clone();
                live.economy
                    .build_castle(live.core.state.position, actor_slot, &terrain)
                    .expect("ordinary qualified Castle constructor");
                let castle = live.economy.castle.as_mut().unwrap();
                // Same source shift-AABB setup as the adjacent protection regression.
                castle.shift_yaw = -8_192;
                castle.shift_pitch = 1_664;
                castle.shift_roll = 1_664;
                castle.shift_fov = 0x4000;
                Some(castle.position)
            } else {
                None
            };
            let away = {
                let session = campaign.simulation();
                let actor = &session.entities()[usize::from(actor_slot)];
                let parameter = actor.parameter_relation.unwrap();
                let row = &session.session.definition.presentation.entity_parameters
                    [usize::from(parameter)];
                let offset = i16::from_le_bytes([row[12], row[13]]);
                let mut position = actor.position;
                position.x = position.x.wrapping_add(0x4000);
                position.z = session.terrain.ground_height(position).wrapping_add(offset);
                position
            };
            let attacker = campaign
                .simulation()
                .session
                .state
                .live
                .core
                .players
                .iter()
                .find(|player| player.is_ai)
                .unwrap()
                .entity_index;
            {
                let session = campaign.simulation_mut();
                session
                    .set_level2_entity_position(actor_slot, away)
                    .unwrap();
                let damage = if dead { session.player_life + 1 } else { 750 };
                session.queue_level2_player_contact_damage(damage, attacker);
                assert_eq!(
                    session.consume_level2_player_damage(),
                    Some((damage, attacker, dead))
                );
                if dead {
                    // Real grounded death tail releases the old holders. No direct
                    // life/action/inventory assignments manufacture the precondition.
                    let lists = area_damage::capture_effect_lists(&mut session.session.state.live.economy, None);
                    session
                        .step_level2_player_dying_action(0, actor_slot, away, lists.mana_chain())
                        .unwrap();
                    assert!(session.player_life < 0);
                    for (family, old_slot) in held_before.iter().enumerate() {
                        if *old_slot != 0 {
                            assert_eq!(
                                session.shared_spells().local_player().enabled_spell_holders
                                    [family],
                                1
                            );
                            let old = &session.entities()[usize::from(*old_slot)];
                            assert!(old.active);
                            assert_eq!(
                                (old.class, old.model, old.action),
                                (15, family as u8, family as u8 * 3 + 1)
                            );
                            assert_eq!(old.control_flags & 1, 0);
                        }
                    }
                }
            }
            let before = campaign.clone();
            let before_live = &before.simulation().session.state.live;
            let before_actor = &before_live.economy.entities[usize::from(actor_slot)];
            let before_player = before_live.shared_spells.local_player().clone();
            let castle_slot = before_live.economy.player_castle_entity_index();
            let recovery_position = castle_position.unwrap_or_else(|| {
                let source_row = before_live.source_player_result.source_player_slot();
                let mut position = before_live.mission.authored_features().iter()
                    .filter(|feature| feature.index > 0 && feature.index < 1200
                        && feature.activation_group == 0 && feature.kind == 3
                        && feature.subtype == 4 + source_row as i16)
                    .max_by_key(|feature| feature.index)
                    .map_or(Position::default(), |feature| feature.world_position(0));
                let recorded = before_live.player_spawn_positions.get(source_row).unwrap();
                assert_eq!((recorded.x, recorded.y), (position.x, position.y),
                    "real group-zero constructor seeded the current player-row spawn");
                position.z = before_live.terrain.ground_height(position).wrapping_add(256);
                position
            });
            let expected_protection = {
                let mut probe = before_actor.clone();
                probe.set_position(recovery_position);
                if before_live.economy.player_castle_shift_aabb_overlap(&probe) {
                    1
                } else {
                    99
                }
            };
            let mut neutral = before.clone();
            let _ = neutral.step(PlayerCommand::default(), 0);
            assert_no_dispatch_error(&neutral);
            let _ = campaign.step(
                PlayerCommand {
                    opcode: 0x0f,
                    ..Default::default()
                },
                0,
            );
            assert_no_dispatch_error(&campaign);
            let live = &campaign.simulation().session.state.live;
            let reference = &neutral.simulation().session.state.live;
            let actor = &live.economy.entities[usize::from(actor_slot)];
            let player = live.shared_spells.local_player();
            assert_eq!(campaign.generation(), before.generation());
            assert_eq!(
                live.core.runtime.global_turn,
                reference.core.runtime.global_turn
            );
            // This raw campaign step retains the imported source wall clock.
            // Its advancing authorities are the outer-frame index and the
            // local player's source-pass tick (including action-3 orbit).
            assert_eq!(
                live.core.runtime.global_turn,
                before_live.core.runtime.global_turn
            );
            assert_eq!(
                live.source_frame_timing_index,
                before_live.source_frame_timing_index.wrapping_add(1)
            );
            assert_eq!(
                reference.source_frame_timing_index,
                before_live.source_frame_timing_index.wrapping_add(1)
            );
            assert_eq!(
                live.source_setting_30.value(),
                before_live.source_setting_30.value().wrapping_add(1)
            );
            assert_eq!(
                reference.source_setting_30.value(),
                before_live.source_setting_30.value().wrapping_add(1)
            );
            assert_eq!(
                campaign.tick(),
                before.tick().wrapping_add(1),
                "one speed-0 player pass preserves prior progress and advances once"
            );
            assert_eq!(
                neutral.tick(),
                before.tick().wrapping_add(1),
                "dead/no-Castle action 3 also advances its camera-orbit tick"
            );
            assert!(live.core.runtime.stage_index >= before_live.core.runtime.stage_index);
            let completed = usize::from(before_live.core.runtime.stage_index);
            assert_eq!(
                &live.core.runtime.objectives[..completed],
                &before_live.core.runtime.objectives[..completed]
            );
            assert!(
                before_live
                    .authored_features_consumed
                    .is_subset(&live.authored_features_consumed)
            );
            assert_eq!(actor.index, before_actor.index);
            assert_eq!(actor.source_id, before_actor.source_id);
            assert_eq!(
                live.economy.slot_generation(actor_slot),
                before_live.economy.slot_generation(actor_slot)
            );
            assert_eq!(live.economy.player_castle_entity_index(), castle_slot);
            if with_castle {
                assert_eq!(
                    live.economy.slot_generation(castle_slot),
                    before_live.economy.slot_generation(castle_slot)
                );
                assert_eq!(
                    live.economy.castle().unwrap().mana,
                    reference.economy.castle().unwrap().mana,
                    "recovery does not debit, refill or replace the Castle"
                );
            }
            {
                let position = recovery_position;
                assert_eq!(
                    (actor.max_life, actor.life, actor.action),
                    (10_000, 10_000, 0)
                );
                assert_eq!(live.player_life, 10_000);
                assert_eq!(
                    (actor.position.x, actor.position.y),
                    (position.x, position.y)
                );
                assert_eq!(live.core.state.position, actor.position);
                // First normal source visit has already applied the old regen
                // to the exact 1000-mana revival value, then projected max mana.
                assert_eq!(
                    actor.mana,
                    1_000_i32
                        .wrapping_add(before_actor.mana_regen)
                        .clamp(0, actor.max_mana)
                );
                assert_eq!(live.shared_spells.player_mana(), actor.mana);
                assert_eq!(live.player_protection_ticks, expected_protection);
                if !with_castle {
                    assert_eq!(live.source_player_result.raw_word() & 0x0c, 0x0c);
                }
                assert_eq!(
                    player.persistent_spell_experience,
                    before_player.persistent_spell_experience
                );
                assert_eq!(
                    player.runtime_spell_experience,
                    before_player.runtime_spell_experience
                );
                assert_eq!(
                    (player.left_spell_slot_raw, player.right_spell_slot_raw),
                    (
                        before_player.left_spell_slot_raw,
                        before_player.right_spell_slot_raw
                    )
                );
                assert_eq!(
                    player.acquired_spell_flags,
                    before_player.acquired_spell_flags
                );
                let fire = live.core.context.spell_fire.as_ref().unwrap();
                for (family, old_slot) in held_before.iter().enumerate() {
                    if *old_slot == 0 {
                        continue;
                    }
                    let new_slot = player.enabled_spell_holders[family];
                    assert!(new_slot > 1 && new_slot != *old_slot);
                    let holder = &live.economy.entities[usize::from(new_slot)];
                    assert!(holder.active);
                    assert_eq!(
                        (holder.class, holder.model, holder.action),
                        (15, family as u8, family as u8 * 3)
                    );
                    assert_eq!(holder.source_spell_parent_entity_index(), actor_slot);
                    assert_eq!(fire.enabled_holder_indices[family], new_slot);
                    assert!(fire.holders.iter().any(|row| row.entity_index == new_slot));
                    let old = &live.economy.entities[usize::from(*old_slot)];
                    let expected_old = &reference.economy.entities[usize::from(*old_slot)];
                    assert_eq!(
                        (
                            old.active,
                            old.class,
                            old.model,
                            old.action,
                            old.life,
                            old.position
                        ),
                        (
                            expected_old.active,
                            expected_old.class,
                            expected_old.model,
                            expected_old.action,
                            expected_old.life,
                            expected_old.position
                        )
                    );
                    assert_eq!(
                        live.economy.slot_generation(*old_slot),
                        before_live.economy.slot_generation(*old_slot),
                        "released world holder is not reclaimed to resurrect its owner"
                    );
                }
                let core_player = live
                    .core
                    .players
                    .iter()
                    .find(|row| row.entity_index == actor_slot)
                    .unwrap();
                assert_eq!(
                    core_player.enabled_spell_holders,
                    player.enabled_spell_holders
                );
                let mut fast = before.clone();
                let _ = fast.step(
                    PlayerCommand {
                        opcode: 0x0f,
                        ..Default::default()
                    },
                    1,
                );
                assert_no_dispatch_error(&fast);
                assert_eq!(
                    fast.state_hash(),
                    campaign.state_hash(),
                    "successful source revival restores speedIndex=0 before entity dispatch"
                );
                assert_eq!(fast.simulation().source_speed_index(), 0, "the actual auxiliary speed carrier resets too");
            }
        }
    }

    #[test]
    fn qualified_castle_protection_clears_each_mailbox_and_one_departure_visit() {
        fn assert_protected_projection(campaign: &CampaignSession, counter: u16) {
            let live = &campaign.simulation().session.state.live;
            let player_slot = live.core.state.entity_index;
            for entity in [
                &live.economy.entities[usize::from(player_slot)],
                &live.shared_spells.player_entity,
            ] {
                assert_eq!(
                    &entity.record[98..134],
                    &[0; 36],
                    "the source memset clears all 36 bytes, including ownerless damage"
                );
            }
            for entity in &live.shared_spells.player_entities {
                if entity.index == player_slot {
                    assert_eq!(&entity.record[98..134], &[0; 36]);
                }
            }
            assert_eq!(
                (live.player_pending_damage, live.player_pending_attacker),
                (0, 0)
            );
            assert_eq!(live.player_protection_ticks, counter);
            assert_eq!(
                live.shared_spells.player_life_regen_cooldown, 0,
                "the protected branch must skip the normal damage consumer"
            );
        }
        fn move_player(campaign: &mut CampaignSession, position: Position) {
            let live = &mut campaign.simulation_mut().session.state.live;
            let player_slot = live.core.state.entity_index;
            live.core.state.position = position;
            live.economy.entities[usize::from(player_slot)].set_position(position);
            live.shared_spells.player_entity.set_position(position);
            for entity in &mut live.shared_spells.player_entities {
                if entity.index == player_slot {
                    entity.set_position(position);
                }
            }
        }
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("qualified Castle protection campaign opens");
        let terrain = campaign.simulation().session.state.live.terrain.clone();
        let (player_slot, attacker, castle_slot, protected_position, player_life) = {
            let live = &mut campaign.simulation_mut().session.state.live;
            let player_slot = live.core.state.entity_index;
            let attacker = live
                .core
                .players
                .iter()
                .find(|player| player.is_ai)
                .expect("real qualified hostile player carrier")
                .entity_index;
            assert_ne!(attacker, player_slot);
            let castle_slot = live
                .economy
                .build_castle(live.core.state.position, player_slot, &terrain)
                .expect("ordinary qualified Castle constructor");
            let castle = live.economy.castle.as_mut().expect("owned Castle root");
            assert_eq!(castle.source_entity_index, castle_slot);
            castle.shift_yaw = -8_192;
            castle.shift_pitch = 1_664;
            castle.shift_roll = 1_664;
            castle.shift_fov = 0x4000;
            let position = Position {
                x: castle.position.x,
                y: castle.position.y,
                z: castle.position.z.wrapping_add(1_000),
            };
            for entity in [
                &mut live.economy.entities[usize::from(player_slot)],
                &mut live.shared_spells.player_entity,
            ] {
                entity.record[86..88].copy_from_slice(&100_i16.to_le_bytes());
                entity.record[88..90].copy_from_slice(&121_i16.to_le_bytes());
                entity.record[90..92].copy_from_slice(&121_i16.to_le_bytes());
                entity.record[92..94].copy_from_slice(&100_i16.to_le_bytes());
            }
            live.shared_spells.player_entities[0] = live.shared_spells.player_entity.clone();
            (
                player_slot,
                attacker,
                castle_slot,
                position,
                live.player_life,
            )
        };
        move_player(&mut campaign, protected_position);
        assert!(
            campaign
                .simulation()
                .economy()
                .player_castle_shift_aabb_overlap(
                    &campaign
                        .simulation()
                        .session
                        .state
                        .live
                        .shared_spells
                        .player_entity
                )
        );
        // A zero-damage visit still refreshes 2 and consumes exactly one visit.
        let compact_spell_bytes =
            campaign.simulation().shared_spells().local_player().record[345..347].to_vec();
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_protected_projection(&campaign, 1);
        assert_eq!(
            &campaign.simulation().shared_spells().local_player().record[345..347],
            compact_spell_bytes.as_slice(),
            "source word159 must not overwrite compact spell bytes"
        );
        let castle_life = campaign.simulation().economy().castle().unwrap().life;
        let castle_generation = campaign.simulation().economy().slot_generation(castle_slot);
        let events_before = campaign.simulation().economy().events().len();
        for hit in 1..=2 {
            {
                let live = &mut campaign.simulation_mut().session.state.live;
                // Distinguish the source full-struct memset from payload/attacker-only clears.
                live.economy.entities[usize::from(player_slot)].record[104..134].fill(0x5a);
                live.shared_spells.player_entity.record[104..134].fill(0x5a);
                for entity in &mut live.shared_spells.player_entities {
                    if entity.index == player_slot {
                        entity.record[104..134].fill(0x5a);
                    }
                }
            }
            campaign
                .simulation_mut()
                .queue_level2_player_contact_damage(200, attacker);
            assert_eq!(
                campaign.simulation().entities()[usize::from(player_slot)].source_upkeep_payload(),
                200,
                "the next real contact starts with a cleared ownerless payload"
            );
            let _ = campaign.step(PlayerCommand::default(), 0);
            assert_protected_projection(&campaign, 1);
            let live = &campaign.simulation().session.state.live;
            assert_eq!(live.player_life, player_life);
            assert_eq!(
                live.economy.castle().unwrap().life,
                castle_life - hit * 200,
                "two contact producers must transfer 200 each, never 200 then 400"
            );
            assert_eq!(live.economy.slot_generation(castle_slot), castle_generation);
        }
        let away = Position {
            x: protected_position.x.wrapping_add(0x4000),
            y: protected_position.y,
            z: protected_position.z,
        };
        move_player(&mut campaign, away);
        assert!(
            !campaign
                .simulation()
                .economy()
                .player_castle_shift_aabb_overlap(
                    &campaign
                        .simulation()
                        .session
                        .state
                        .live
                        .shared_spells
                        .player_entity
                )
        );
        campaign
            .simulation_mut()
            .queue_level2_player_contact_damage(200, attacker);
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_protected_projection(&campaign, 0);
        assert_eq!(
            campaign.simulation().session.state.live.player_life,
            player_life,
            "the first callback after departure consumes the remaining protected visit"
        );
        assert_eq!(
            campaign.simulation().economy().castle().unwrap().life,
            castle_life - 400
        );
        campaign
            .simulation_mut()
            .queue_level2_player_contact_damage(200, attacker);
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            live.player_life,
            player_life - 200,
            "the next unprotected visit reaches the ordinary damage consumer"
        );
        assert_eq!(live.shared_spells.player_life_regen_cooldown, 15);
        assert_eq!(
            (
                live.economy.entities[usize::from(player_slot)].source_upkeep_payload(),
                live.economy.entities[usize::from(player_slot)].source_upkeep_word_62()
            ),
            (200, 0),
            "normal source damage retains its ownerless residue; contact accumulation is unchanged"
        );
        let damage: Vec<_> = live.economy.events[events_before..]
            .iter()
            .filter_map(|event| {
                if let Level2EconomyEvent::DamageApplied {
                    target_entity_index,
                    attacker_entity_index,
                    damage,
                    lethal,
                } = event
                {
                    (*attacker_entity_index == attacker).then_some((
                        *target_entity_index,
                        *damage,
                        *lethal,
                    ))
                } else {
                    None
                }
            })
            .collect();
        assert_eq!(
            damage,
            vec![
                (castle_slot, 200, false),
                (castle_slot, 200, false),
                (player_slot, 200, false)
            ],
            "protected transfer and normal damage are separate source visits"
        );
    }

    #[test]
    fn configured_player_contact_keeps_source_word_and_mailbox_semantics() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("qualified Level 2 campaign opens");
        let sim = campaign.simulation_mut();
        let player = sim.state.entity_index;
        let row = &mut sim.session.state.live.economy.entities[usize::from(player)];
        row.record[98..102].copy_from_slice(&i32::MAX.to_le_bytes());
        row.record[102..104].fill(0);

        let mailbox = |sim: &Mc2Simulation| {
            let row = &sim.entities()[usize::from(player)];
            (row.source_upkeep_payload(), row.source_upkeep_word_62())
        };
        sim.queue_level2_player_contact_damage(1, 0);
        assert_eq!(
            mailbox(sim),
            (i32::MIN, 0),
            "unowned contact adds with wrapping"
        );
        sim.queue_level2_player_contact_damage(0, 7);
        assert_eq!(
            mailbox(sim),
            (i32::MIN, 7),
            "zero payload still claims residue"
        );
        sim.queue_level2_player_contact_damage(0, 8);
        assert_eq!(
            mailbox(sim),
            (0, 8),
            "owned contact replaces even with zero"
        );
        sim.queue_level2_player_contact_damage(65_537, 9);
        assert_eq!(
            mailbox(sim),
            (1, 9),
            "source contact payload narrows to u16"
        );

        // Configured dead-player exception: 11900 still writes; 5EFA0 does
        // not consume an owned mailbox while the actual player life is negative.
        sim.session.state.live.player_life = -1;
        sim.session.state.live.economy.entities[usize::from(player)].set_life(-1);
        sim.session.state.live.shared_spells.set_player_entity_life(-1);
        sim.queue_level2_player_contact_damage(3, 0);
        assert_eq!(mailbox(sim), (3, 0));
        sim.queue_level2_player_contact_damage(-1, 6);
        assert_eq!(mailbox(sim), (65_538, 6));
        assert_eq!(sim.consume_level2_player_damage(), None);
        assert_eq!(mailbox(sim), (65_538, 6));
    }

    #[test]
    fn qualified_player_hit_suppresses_sixteen_upkeep_visits_then_regenerates() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("qualified Level 2 campaign opens");
        let baseline_hash = campaign.state_hash();
        let player_slot = campaign.simulation().state.entity_index;
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .shared_spells
                .player_life_regen_cooldown,
            0,
            "the source full-player reset clears dword_0x18D"
        );
        let starting_life = {
            let live = &mut campaign.simulation_mut().session.state.live;
            let life = live.shared_spells.player_entity.max_life / 2;
            live.player_life = life;
            live.economy.entities[usize::from(player_slot)].set_life(life);
            live.economy.entities[usize::from(player_slot)].set_mana(0);
            live.economy.entities[usize::from(player_slot)].set_mana_regen(7);
            live.shared_spells.set_player_entity_life(life);
            live.shared_spells.player_entity.set_mana(0);
            live.shared_spells.player_entity.set_mana_regen(7);
            live.shared_spells.player_entities[0] = live.shared_spells.player_entity.clone();
            live.shared_spells.player_mana = 0;
            live.shared_spells.caster.mana = 0;
            life
        };
        // One speed-zero outer turn is one actual local-player source visit.
        // It applies the old zero life rate and selects the outdoor rate.
        let _ = campaign.step(PlayerCommand::default(), 0);
        let regen = campaign
            .simulation()
            .session
            .state
            .live
            .shared_spells
            .player_life_regen;
        assert!(regen > 0);
        assert_eq!(
            campaign.simulation().canonical_player_life_for_test(),
            starting_life
        );
        assert_eq!(campaign.simulation().shared_spells().player_mana(), 7);
        // Both contact controls need a real unprotected player visit. Let the
        // source Castle-protection countdown expire rather than bypassing it.
        for turn in 0..256 {
            if campaign.simulation().session.state.live.player_protection_ticks == 0 {
                break;
            }
            let _ = campaign.step(PlayerCommand::default(), 0);
            assert!(
                campaign
                    .simulation()
                    .dispatch_events()
                    .iter()
                    .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. })),
                "contact protection turn{turn}"
            );
        }
        assert_eq!(
            campaign.simulation().session.state.live.player_protection_ticks,
            0
        );
        // Restore the already-declared half-life test setup after natural
        // upkeep during protection, retaining every authoritative projection.
        {
            let live = &mut campaign.simulation_mut().session.state.live;
            live.player_life = starting_life;
            live.economy.entities[usize::from(player_slot)].set_life(starting_life);
            live.shared_spells.set_player_entity_life(starting_life);
            live.shared_spells.player_entities[0] = live.shared_spells.player_entity.clone();
        }
        // A source-admitted zero payload is still an owned contact. The
        // player's scheduled callback consumes it, arms the normal hit
        // cooldown and leaves health unchanged. Keep a no-contact branch for
        // the independent positive-damage regeneration control below.
        let mut zero_contact = campaign.clone();
        let before_zero = zero_contact.simulation().canonical_player_life_for_test();
        assert!(
            before_zero >= 0,
            "zero-contact consumer requires a living player"
        );
        let event_start = zero_contact.simulation().economy().events().len();
        zero_contact
            .simulation_mut()
            .queue_level2_player_contact_damage(0, 1);
        {
            let row = &zero_contact.simulation().entities()[usize::from(player_slot)];
            assert_eq!(
                (row.source_upkeep_payload(), row.source_upkeep_word_62()),
                (0, 1)
            );
        }
        let _ = zero_contact.step(PlayerCommand::default(), 0);
        assert_eq!(
            zero_contact.simulation().canonical_player_life_for_test(),
            before_zero
        );
        assert_eq!(
            zero_contact.simulation().session.state.live.shared_spells.player_life_regen_cooldown,
            15
        );
        let row = &zero_contact.simulation().entities()[usize::from(player_slot)];
        assert_eq!(
            (row.source_upkeep_payload(), row.source_upkeep_word_62()),
            (0, 0)
        );
        assert!(zero_contact.simulation().economy().events()[event_start..]
            .iter()
            .any(|event| matches!(event,
                Level2EconomyEvent::DamageApplied { target_entity_index,
                    attacker_entity_index: 1, damage: 0, lethal: false }
                    if *target_entity_index == player_slot)));
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(
            campaign.simulation().canonical_player_life_for_test(),
            starting_life + regen
        );
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .shared_spells
                .player_life_regen_cooldown,
            0
        );
        let held_spells = campaign
            .simulation()
            .shared_spells()
            .local_player()
            .enabled_spell_holders;
        let selector_bytes = campaign
            .simulation()
            .shared_spells()
            .local_player()
            .record_bytes()[372..398]
            .to_vec();
        let events_before = campaign.simulation().economy().events().len();
        campaign
            .simulation_mut()
            .queue_level2_player_contact_damage(100, 1);
        let damaged_life = starting_life + regen - 100;
        for visit in 0..16 {
            let mana_before = campaign.simulation().shared_spells().player_entity.mana;
            let mana_regen = campaign
                .simulation()
                .shared_spells()
                .player_entity
                .mana_regen;
            let _ = campaign.step(PlayerCommand::default(), 0);
            let live = &campaign.simulation().session.state.live;
            assert_eq!(live.shared_spells.player_life_regen_cooldown, 15 - visit);
            assert_eq!(
                (
                    live.player_life,
                    live.shared_spells.player_entity.life,
                    live.shared_spells.player_entities[0].life,
                    live.economy.entities[usize::from(player_slot)].life
                ),
                (damaged_life, damaged_life, damaged_life, damaged_life),
                "damage visit and following fifteen source visits suppress healing"
            );
            assert_eq!(
                live.shared_spells.player_entity.mana,
                mana_before
                    .wrapping_add(mana_regen)
                    .clamp(0, live.shared_spells.player_entity.max_mana),
                "life cooldown preserves ordinary mana recharge"
            );
            assert_eq!(
                live.shared_spells.local_player.enabled_spell_holders,
                held_spells
            );
            assert_eq!(
                &live.shared_spells.local_player.record_bytes()[372..398],
                selector_bytes.as_slice()
            );
            if visit == 0 {
                let clone = campaign.clone();
                assert_eq!(clone.state_hash(), campaign.state_hash());
                let mut changed = live.shared_spells.clone();
                changed.player_life_regen_cooldown -= 1;
                assert_ne!(changed.reset_hash(), live.shared_spells.reset_hash());
                assert_ne!(
                    changed.reset_hash_with_terrain(&live.terrain),
                    live.shared_spells.reset_hash_with_terrain(&live.terrain)
                );
            }
        }
        assert_eq!(
            campaign.simulation().economy().events()[events_before..]
                .iter()
                .filter(|event| matches!(event,
                Level2EconomyEvent::DamageApplied { target_entity_index,
                    attacker_entity_index: 1, damage: 100, lethal: false }
                    if *target_entity_index == player_slot))
                .count(),
            1,
            "the retained ownerless mailbox must not reapply damage"
        );
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(
            campaign.simulation().canonical_player_life_for_test(),
            damaged_life + regen
        );
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .shared_spells
                .player_life_regen_cooldown,
            0
        );
        campaign.reset();
        assert_eq!(campaign.state_hash(), baseline_hash);
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .shared_spells
                .player_life_regen_cooldown,
            0
        );
    }

    #[test]
    fn qualified_wind_squared_distance_bands_clear_airborne_latch_and_stop_damage() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("qualified Level 2 campaign opens");
        // 1792^2 = 3211264 selects far movement; 2304^2 = 5308416
        // clears the source airborne latch. Keep the nearest inner cases.
        for (distance, near_movement, clears_latch) in [
            (1_791_u16, true, false),
            (1_792, false, false),
            (2_303, false, false),
            (2_304, false, true),
        ] {
            campaign.reset();
            let session = campaign.simulation_mut();
            let axis = Position {
                x: 20_000,
                y: 20_000,
                z: 0,
            };
            let wind = session
                .economy_mut()
                .allocate_authored_model22(110, axis, axis)
                .expect("the actual Wind constructor creates its parent and chain");
            assert_eq!(
                (
                    wind.source_class,
                    wind.model,
                    wind.action,
                    wind.subspell_index
                ),
                (10, 22, 22, 1_000)
            );
            assert_eq!(session.economy().model22_spawned_children().len(), 11);
            let player_slot = session.state.entity_index;
            let mut position = Position {
                x: axis.x.wrapping_add(distance),
                y: axis.y,
                z: 0,
            };
            position.z = session
                .canonical_terrain()
                .ground_height(position)
                .wrapping_add(2_048);
            session
                .set_level2_entity_position(player_slot, position)
                .unwrap();
            let settle_descent = {
                let target = &session.entities()[usize::from(player_slot)];
                let parameter = &session.session.definition.presentation.entity_parameters
                    [usize::from(
                        target
                            .parameter_relation
                            .expect("qualified player parameter"),
                    )];
                i16::from_le_bytes([parameter[14], parameter[15]])
            };
            {
                let target =
                    &mut session.session.state.live.economy.entities[usize::from(player_slot)];
                target.set_control_flags(target.control_flags | 0x1000_0000);
                target.set_yaw(0);
                target.set_source_word_30(0);
            }
            let life_before = session.canonical_player_life_for_test();
            session
                .step_level2_authored_model22_sub33340_eligible_targets(wind.source_entity_index)
                .unwrap();
            let target = &session.entities()[usize::from(player_slot)];
            assert_eq!(
                target.position.z,
                position
                    .z
                    .wrapping_add(if near_movement { 114 } else { settle_descent }),
                "source movement selects the squared 1792 band at distance {distance}"
            );
            assert_eq!(
                target.control_flags & 0x1000_0000 == 0,
                clears_latch,
                "source latch selects the squared 2304 band at distance {distance}"
            );
            assert_eq!(target.source_wind_spell_payload(), 1_000);
            assert_eq!(target.source_wind_spell_owner(), wind.entity_id);
            assert_eq!(
                session.consume_level2_player_damage(),
                Some((1_000, wind.entity_id, false))
            );
            assert_eq!(
                session.canonical_player_life_for_test(),
                life_before - 1_000
            );
            assert_eq!(
                session.entities()[usize::from(player_slot)].source_wind_spell_owner(),
                0
            );
            assert_eq!(
                session.entities()[usize::from(player_slot)].source_wind_spell_payload(),
                1_000
            );
            assert_eq!(
                session.consume_level2_player_damage(),
                None,
                "a retained ownerless payload does not reapply without a new producer"
            );
            if clears_latch {
                // The ordinary next Wind callback admits this same map row,
                // but the cleared latch must prevent another hit/mailbox add.
                session
                    .step_level2_authored_model22_sub33340_eligible_targets(
                        wind.source_entity_index,
                    )
                    .unwrap();
                assert_eq!(session.consume_level2_player_damage(), None);
                assert_eq!(
                    session.canonical_player_life_for_test(),
                    life_before - 1_000
                );
                assert_eq!(
                    session.entities()[usize::from(player_slot)].source_wind_spell_payload(),
                    1_000
                );
            }
        }
        // The same squared carrier selects the grounded inner/orbit branch
        // at 512 units. Its nearest negative must retain the inner turn.
        for distance in [511_u16, 512] {
            campaign.reset();
            let session = campaign.simulation_mut();
            let axis = Position {
                x: 20_000,
                y: 20_000,
                z: 0,
            };
            let wind = session
                .economy_mut()
                .allocate_authored_model22(110, axis, axis)
                .unwrap();
            let player_slot = session.state.entity_index;
            let mut position = Position {
                x: axis.x.wrapping_add(distance),
                y: axis.y,
                z: 0,
            };
            position.z = session
                .canonical_terrain()
                .ground_height(position)
                .wrapping_add(2_048);
            session
                .set_level2_entity_position(player_slot, position)
                .unwrap();
            {
                let target =
                    &mut session.session.state.live.economy.entities[usize::from(player_slot)];
                target.set_control_flags(target.control_flags & !0x1000_0000);
                target.set_yaw(0);
                target.set_source_word_30(0);
            }
            session
                .step_level2_authored_model22_sub33340_eligible_targets(wind.source_entity_index)
                .unwrap();
            let target = &session.entities()[usize::from(player_slot)];
            let orbit_yaw = wrap_source_angle(
                i16::try_from(heading_for_positions(axis, position))
                    .unwrap()
                    .wrapping_add(591),
            );
            assert_eq!(target.yaw, if distance < 512 { 56 } else { orbit_yaw });
            assert_eq!(
                target.source_word_30(),
                if distance < 512 {
                    56
                } else {
                    orbit_yaw.cast_unsigned()
                }
            );
            assert_eq!(target.control_flags & 0x1000_0000 != 0, distance < 512);
            assert_eq!(session.consume_level2_player_damage(), None);
        }
    }

    #[test]
    fn selected_cast_survives_player_movement_authority_sync() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("qualified campaign opens");
        for (flags, expected_hand) in [(0, 0), (0x40, 0x100)] {
            campaign.reset();
            campaign.step(
                PlayerCommand {
                    opcode: 6,
                    argument_1: 1,
                    flags,
                    ..PlayerCommand::default()
                },
                0,
            );
            let live = &campaign.simulation().session.state.live;
            let player = &live.economy.entities[usize::from(live.core.state.entity_index)];
            let caster = live.core.context.spell_fire.as_ref().unwrap().caster;
            assert_eq!(caster.control_flags & 0x300, expected_hand);
            assert_eq!(player.control_flags & 0x300, expected_hand);
            assert_eq!(
                live.shared_spells.player_entity.control_flags & 0x300,
                expected_hand
            );
            assert_eq!(player.mana, live.shared_spells.player_entity.mana);
            assert_eq!(player.mana, caster.mana);
            assert_eq!(
                player.mana_regen,
                live.shared_spells.player_entity.mana_regen
            );
            if flags != 0 {
                let holder = live
                    .shared_spells
                    .pickup(live.shared_spells.players()[0].enabled_spell_holders[1])
                    .unwrap();
                assert_eq!(player.mana_regen, -holder.mana_cost);
            }
            assert_eq!(
                live.economy.economy.possession_projectiles().is_empty(),
                flags == 0
            );
        }
    }

    #[test]
    fn configured_skeleton_alternate_stages_schedule_expiry_and_reclaim() {
        let seed = CampaignSession::open(
            level_three_descriptor_fixture_path(),
            CampaignSelection::LEVEL3,
        )
        .unwrap();
        let root = seed
            .simulation()
            .entities()
            .iter()
            .find(|row| row.active && (row.class, row.model, row.action) == (5, 9, 72))
            .map(|row| seed.simulation().source_arena().handle(row.index).unwrap())
            .unwrap();
        for mode in [0_u8, 13, 16] {
            let mut campaign = seed.clone();
            let session = campaign.simulation_mut();
            let player = session.state.entity_index;
            let before = session.entities()[usize::from(root.source_slot)].clone();
            assert!(session.canonical_player_life_for_test() > 0);
            // Explicit alternate-callback exception on a real reset root;
            // no ordinary alternate-mode producer is claimed. The production
            // prepass is retained: index0/mode0 returns, while13/16 retain79.
            let row =
                &mut session.session.state.live.economy.entities[usize::from(root.source_slot)];
            row.set_source_action(79);
            row.record[76] = 0;
            row.record[77] = mode;
            row.record[44..46].copy_from_slice(&player.to_le_bytes());
            row.record[50..52]
                .copy_from_slice(&(if mode == 13 { 1_u16 } else { 0_u16 }).to_le_bytes());
            session.start_model9_callback_trace(root);
            session
                .step_level2_source_pass_with_player(
                    0,
                    crate::LatchedCommand::default(),
                    crate::FlightTuning::CLASSIC,
                    &mut Vec::new(),
                )
                .unwrap();
            let visits = session.take_model9_callback_trace();
            assert_eq!(visits.len(), 1, "mode{mode}");
            let visit = &visits[0];
            assert_eq!(
                (visit.source, visit.entry.action, visit.exit.action),
                (root, 79, 79)
            );
            assert_eq!(visit.exit_handle, Some(root));
            let after = &session.entities()[usize::from(root.source_slot)];
            assert_eq!(
                after.record[77], mode,
                "the real prepass retained the configured mode"
            );
            assert_eq!(after.phase, before.phase.wrapping_add(1));
            assert_eq!(after.record[66], after.phase);
            let effects = visit
                .new_effects
                .as_ref()
                .expect("current callback effect projections");
            let presentations = session.campaign_entity_presentations(0).unwrap();
            if mode == 0 {
                // Literal default return, not point-follow/damage fallback.
                assert!(effects.is_empty());
                assert_eq!(visit.entry, visit.exit);
                assert_eq!(
                    (after.position, after.entity_rng),
                    (before.position, before.entity_rng)
                );
                assert!(!after.drawing_disabled());
                assert!(
                    presentations
                        .iter()
                        .any(|row| row.entity_index == root.source_slot)
                );
                continue;
            }
            assert_eq!(after.source_word_2e(), 0);
            assert!(after.drawing_disabled());
            assert_eq!(session.source_arena().handle(root.source_slot), Some(root));
            assert!(
                !presentations
                    .iter()
                    .any(|row| row.entity_index == root.source_slot)
            );
            let mut models = effects
                .iter()
                .map(|(_, view)| view.model)
                .collect::<Vec<_>>();
            models.sort_unstable();
            assert_eq!(models, if mode == 13 { vec![0, 73] } else { vec![0] });
            let children = effects
                .iter()
                .map(|(handle, view)| {
                    assert_eq!(view.class, 10);
                    assert!(!view.drawing_disabled());
                    assert_eq!(
                        session.source_arena().handle(handle.source_slot),
                        Some(*handle)
                    );
                    let child = &session.entities()[usize::from(handle.source_slot)];
                    assert_eq!((child.class, child.model), (view.class, view.model));
                    let plan = session.resolve_level2_source_plan(handle.source_slot, player);
                    assert!(
                        matches!(&plan, Some(Level2ResolvedSourcePlan::Callback(visit))
                        if visit.route == SourceRoute::Imported
                            && visit.handler == ExistingHandler::Class10Effects
                            && visit.phase == Some(child.phase)
                            && visit.key.selector == (BehaviorSelector::ClassAction {
                                class: 10, action: child.action,
                            })),
                        "mode{mode} child{handle:?} packet={child:?} resolved={plan:?}"
                    );
                    assert!(presentations.iter().any(|row| {
                        row.entity_index == handle.source_slot
                            && row.render_parameter_index == child.particle_parameter_index.unwrap()
                    }));
                    let callbacks = if view.model == 73 {
                        assert_eq!(view.life, 16, "unshortened source51A00 constructor life");
                        assert!(
                            (15..=16).contains(&child.life),
                            "a higher numeric newborn may already execute in its birth pass"
                        );
                        u16::try_from(16 - child.life).unwrap()
                    } else {
                        0
                    };
                    (*handle, view.model, callbacks)
                })
                .collect::<Vec<_>>();
            let mut pending = children;
            let mut reclaimed_models = Vec::new();
            // Natural source lifetimes:73 needs16 callbacks;0 retains its
            // own age gate and life<-1 hide. No post-birth fields are edited.
            for ordinal in 1_u8..=32 {
                let before = pending
                    .iter()
                    .map(|(handle, model, callbacks)| {
                        assert_eq!(
                            session.source_arena().handle(handle.source_slot),
                            Some(*handle)
                        );
                        (
                            *handle,
                            *model,
                            *callbacks,
                            session.entities()[usize::from(handle.source_slot)].clone(),
                        )
                    })
                    .collect::<Vec<_>>();
                session
                    .step_level2_source_pass_with_player(
                        ordinal % 3,
                        crate::LatchedCommand::default(),
                        crate::FlightTuning::CLASSIC,
                        &mut Vec::new(),
                    )
                    .unwrap();
                if ordinal == 1 {
                    assert_ne!(
                        session.source_arena().handle(root.source_slot),
                        Some(root),
                        "the following owning prologue reclaims the original generation"
                    );
                    assert!(
                        session
                            .source_arena()
                            .free_source_slots()
                            .contains(&root.source_slot)
                            || session.source_arena().slot_generation(root.source_slot)
                                != root.generation,
                        "the original allocation is free or was reused at a newer generation"
                    );
                }
                let presentations = session.campaign_entity_presentations(0).unwrap();
                let mut next = Vec::new();
                for (handle, model, callbacks, before) in before {
                    if before.drawing_disabled() {
                        assert_ne!(
                            session.source_arena().handle(handle.source_slot),
                            Some(handle)
                        );
                        let free = session
                            .source_arena()
                            .free_source_slots()
                            .contains(&handle.source_slot);
                        assert!(
                            free || session.source_arena().slot_generation(handle.source_slot)
                                != handle.generation
                        );
                        if free {
                            assert!(!session.economy().map_chains.is_linked(handle.source_slot));
                        }
                        reclaimed_models.push(model);
                        continue;
                    }
                    assert_eq!(
                        session.source_arena().handle(handle.source_slot),
                        Some(handle)
                    );
                    let child = &session.entities()[usize::from(handle.source_slot)];
                    assert_eq!((child.class, child.model), (10, model));
                    assert_eq!(
                        child.phase,
                        before.phase.wrapping_add(1),
                        "mode{mode} child{handle:?} model{model} action{} life{} age{}",
                        child.action,
                        child.life,
                        child.source_dword_10()
                    );
                    if model == 73 || before.source_dword_10() & 3 == 0 {
                        assert_eq!(
                            child.life,
                            before.life - 1,
                            "real expiry/impact callback work"
                        );
                    } else {
                        assert_eq!(child.life, before.life);
                        assert_eq!(
                            child.source_dword_10(),
                            before.source_dword_10().wrapping_sub(1)
                        );
                    }
                    let callbacks = callbacks + 1;
                    if child.drawing_disabled() {
                        assert_eq!(child.life, if model == 73 { 0 } else { -2 });
                        if model == 73 {
                            assert_eq!(callbacks, 16, "all16 real source3A630 callbacks");
                        }
                        assert!(
                            !presentations
                                .iter()
                                .any(|row| row.entity_index == handle.source_slot),
                            "the naturally hidden incarnation is still current but not presented"
                        );
                    } else {
                        assert!(
                            presentations
                                .iter()
                                .any(|row| row.entity_index == handle.source_slot)
                        );
                    }
                    next.push((handle, model, callbacks));
                }
                pending = next;
                if pending.is_empty() {
                    break;
                }
            }
            assert!(
                pending.is_empty(),
                "mode{mode} natural expiry did not finish: {pending:?}"
            );
            reclaimed_models.sort_unstable();
            assert_eq!(reclaimed_models, models);
        }
    }

    #[test]
    fn configured_model9_point_peer_failures_publish_completed_movement_only() {
        // These are configured wrapper failure boundaries, not an ordinary
        // missing-carrier/alias producer. The separate untouched Level3 gate
        // proves the real reset roots' emergence and point following.
        let mut seed = CampaignSession::open(
            level_three_descriptor_fixture_path(),
            CampaignSelection::LEVEL3,
        )
        .unwrap();
        let session = seed.simulation_mut();
        let source_slot = session
            .entities()
            .iter()
            .find(|row| row.active && (row.class, row.model) == (5, 9))
            .unwrap()
            .index;
        let position = Position {
            x: 0x20ff,
            y: 0x30ff,
            z: 512,
        };
        let (bad_peer, reader_reason) = {
            let live = &mut session.session.state.live;
            assert!(matches!(
                live.core.runtime.stage_variables[2].relation,
                RuntimeRelation::AxisScalar(_)
            ));
            live.terrain.planes.ground_heights.fill(0);
            live.terrain.planes.secondary_heights.fill(255);
            live.terrain.planes.terrain_types.fill(13);
            live.terrain.planes.angles.fill(0);
            let source = &mut live.economy.entities[usize::from(source_slot)];
            source.set_source_action(79);
            source.record[76] = 2;
            source.record[77] = 1;
            source.record[56..58].fill(0);
            source.set_phase(8);
            source.set_position(position);
            source.set_yaw(0);
            source.set_source_roll(0);
            source.set_actual_speed(512);
            source.set_life(1000);
            source.clear_source_upkeep_owner();
            source.set_damage_result_words(0, 0);
            source.set_control_flags(source.control_flags & !(0x40000 | 0x800));
            live.economy
                .map_chains
                .sync_entity(RenderableMapSeed {
                    entity_index: source_slot,
                    active: true,
                    x: position.x,
                    y: position.y,
                })
                .unwrap();
            // Allocate a real typed pickup, intentionally withholding its
            // shared spell record to make the current reader fail closed.
            let peer = live
                .economy
                .allocate_spell_pickup(u16::MAX, 1, 4, Position::default())
                .unwrap()
                .source_entity_index;
            assert_ne!(peer, source_slot);
            assert!(live.shared_spells.pickup(peer).is_none());
            let reason = source_target::read(
                &live.economy,
                source_target::Context {
                    spells: Some(&live.shared_spells),
                    ..source_target::Context::default()
                },
                peer,
            )
            .unwrap_err();
            assert!(reason.contains("lacks its current shared spell record"));
            (peer, reason)
        };
        let population = session.economy().source_creature_population;
        assert!(population > 0);
        let initial_map = session.economy().map_chains.clone();
        let initial_tile = initial_map.tile_of(source_slot);

        let mut moving = seed.clone();
        let session = moving.simulation_mut();
        let error = session
            .step_imported_model9_action79(source_slot, &[bad_peer])
            .unwrap_err();
        assert!(error.contains(reader_reason.as_str()), "{error}");
        let source = &session.entities()[usize::from(source_slot)];
        let mut expected = position;
        expected.z -= 128;
        crate::move_entity(&mut expected, 0, 0, 512);
        assert_eq!(source.position, expected);
        assert_eq!(source.life, 1000);
        let expected_tile = RenderableMapSeed {
            entity_index: source_slot,
            active: true,
            x: expected.x,
            y: expected.y,
        }
        .tile_index();
        assert_ne!(expected_tile, initial_tile, "movement crosses a map cell");
        assert_eq!(
            session.economy().map_chains.tile_of(source_slot),
            expected_tile
        );
        assert!(session.economy().map_chains.is_linked(source_slot));
        assert_eq!(session.economy().source_creature_population, population);

        let mut blocked = seed.clone();
        let session = blocked.simulation_mut();
        // Material0 has bit0, outside Skeleton's descriptor material mask;
        // all four source movement candidates are rejected.
        session
            .session
            .state
            .live
            .terrain
            .planes
            .terrain_types
            .fill(0);
        let error = session
            .step_imported_model9_action79(source_slot, &[bad_peer])
            .unwrap_err();
        assert!(error.contains(reader_reason.as_str()), "{error}");
        let source = &session.entities()[usize::from(source_slot)];
        assert_eq!((source.position, source.life), (position, -1));
        assert_ne!(source.control_flags & 0x40000, 0);
        assert_eq!(
            session.economy().source_creature_population,
            population - 1,
            "the authoritative source population write precedes peer failure"
        );
        assert_eq!(session.economy().map_chains, initial_map);
        assert_eq!(
            session.economy().map_chains.tile_of(source_slot),
            initial_tile
        );

        let mut before_movement = seed;
        let session = before_movement.simulation_mut();
        session.session.state.live.economy.entities[usize::from(source_slot)].record[56..58]
            .copy_from_slice(&u16::MAX.to_le_bytes());
        // An explicitly unlinked map boundary detects accidental map
        // publication after the invalid child chain's pre-movement return.
        session
            .session
            .state
            .live
            .economy
            .map_chains
            .set_map_entity_unlink(source_slot);
        let before_map = session.economy().map_chains.clone();
        let error = session
            .step_imported_model9_action79(source_slot, &[bad_peer])
            .unwrap_err();
        assert!(error.contains("invalid child-chain"), "{error}");
        assert!(!error.contains(reader_reason.as_str()));
        let source = &session.entities()[usize::from(source_slot)];
        assert_eq!(
            (source.position, source.life, source.source_roll()),
            (position, 1000, 0)
        );
        assert_eq!(session.economy().source_creature_population, population);
        assert_eq!(session.economy().map_chains, before_map);
        assert!(!session.economy().map_chains.is_linked(source_slot));
    }

    #[test]
    fn skeleton_damage_reaction_reads_retained_and_reused_current_source_address() {
        let package = std::env::var_os("MC_LEVEL23_PACKAGE").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(
                "../../../generated/creatures-20261104-integration/current-owner-package/level23"),
            PathBuf::from,
        );
        let mut campaign = CampaignSession::open(
            package, CampaignSelection::ordinary(23).unwrap(),
        ).unwrap();
        let masks = campaign.simulation().collision_mask_bank()
            .expect("qualified Level 23 retains its real collision masks").clone();
        let session = campaign.simulation_mut();
        let skeleton = 187_u16;
        let parent = 558_u16;
        let holder = 563_u16;
        let particles = session.session.definition.presentation.particles.clone();
        let frozen_models: [Vec<u16>; 29] = std::array::from_fn(|_| Vec::new());
        let mut direct74 = session.clone();
        let mut delegated73 = session.clone();
        for (probe, action, inner) in [(&mut direct74, 74, 0), (&mut delegated73, 73, 1)] {
            let live = &mut probe.session.state.live;
            let row = &mut live.economy.entities[usize::from(skeleton)];
            row.set_source_action(action);
            row.record[74] = inner;
            area_damage::contact(&mut live.economy, None, skeleton, 1, u16::MAX).unwrap();
        }
        direct74.step_imported_model9(skeleton, &frozen_models, &[]).unwrap();
        assert_eq!((direct74.entities()[usize::from(skeleton)].action,
            direct74.entities()[usize::from(skeleton)].source_word_96()), (74, u16::MAX),
            "actual 20C50 does not read the nonfatal attacker address");
        let error = delegated73.step_imported_model9(skeleton, &frozen_models, &[]).unwrap_err();
        assert!(error.contains("invalid damage target slot 65535"), "{error}");
        assert_eq!((delegated73.entities()[usize::from(skeleton)].life,
            delegated73.entities()[usize::from(skeleton)].action,
            delegated73.entities()[usize::from(skeleton)].source_word_96()), (999, 74, u16::MAX),
            "outer 203D0 reaches 20EC0 after publishing the same hit");
        let (target, original_handle) = {
            let live = &mut session.session.state.live;
            assert_eq!((live.economy.entities[usize::from(skeleton)].class,
                live.economy.entities[usize::from(skeleton)].model), (5, 9));
            assert_eq!((live.economy.entities[usize::from(parent)].class,
                live.economy.entities[usize::from(parent)].model), (3, 1));
            assert_eq!((live.economy.entities[usize::from(holder)].class,
                live.economy.entities[usize::from(holder)].model), (15, 4));
            let position = Position { x: 128, y: 128, z: 10_000 };
            let target = crate::world::effects::allocate(
                &mut live.economy, &mut live.terrain,
                sim_definition::adapter::mc2_effect_definition(crate::level_definition::EffectKind::Impact),
                position, &particles,
            ).unwrap().unwrap();
            assert_ne!(target, parent);
            assert_eq!(live.economy.entities[usize::from(target)].source_id, target);
            let handle = live.economy.handle(target).unwrap();
            // The real source contact writer leaves its mailbox pending while
            // the producing 10/0 effect runs its normal terminal lifetime.
            area_damage::contact(&mut live.economy, None, skeleton, 1, target).unwrap();
            let source = &mut live.economy.entities[usize::from(skeleton)];
            source.set_source_action(73);
            source.record[74] = 0;
            source.record[56..58].fill(0);
            let player = (live.core.state.entity_index, live.core.state.position);
            let mut actors = area_damage::ActorDomains::new(&mut live.goats, &mut live.ordinary);
            let lists = area_damage::capture_effect_lists(&mut live.economy, Some(actors.reborrow()));
            let mut effects = std::mem::take(&mut live.economy.effects);
            for _ in 0..16 {
                if live.economy.entities[usize::from(target)].drawing_disabled() { break; }
                crate::world::effects::visit(
                    &mut live.economy, &mut live.terrain, target, &particles, &mut effects,
                    |arena, pulse| area_damage::apply_effect(
                        arena, Some(actors.reborrow()), Some(player), Some(&masks), &lists, pulse,
                    ),
                ).unwrap();
            }
            live.economy.effects = effects;
            assert!(live.economy.entities[usize::from(target)].drawing_disabled());
            assert_eq!(live.economy.handle(target), Some(handle));
            live.economy.rebuild_source_arena_with_terrain(&mut live.terrain, &[]).unwrap();
            assert!(live.economy.resolve(handle).is_none());
            assert!(!live.economy.entities[usize::from(target)].active);
            (target, handle)
        };
        let mut replacement = session.clone();
        session.step_imported_model9_action73(skeleton, &frozen_models, &[]).unwrap();
        let retained = &session.entities()[usize::from(skeleton)];
        assert_eq!((retained.action, retained.life, retained.record[69], retained.record[70]),
            (74, 999, 0, 0), "20EC0 reads the reclaimed fixed-address packet");

        {
            let live = &mut replacement.session.state.live;
            // Isolate the same legitimately reclaimed address for one real
            // source Bee constructor; its current typed ID differs from raw.
            live.economy.economy.free_slots = vec![target];
            let parent_row = live.economy.entities[usize::from(parent)].clone();
            let born = creatures::bee::mc2::allocate_morph(
                &mut live.economy, &mut live.terrain, holder, parent,
                parent_row.source_id, parent_row.position,
            ).unwrap();
            assert_eq!(born.source_entity_index, target);
            assert_eq!(born.entity_id, parent_row.source_id);
            assert_ne!(live.economy.handle(target), Some(original_handle));
            assert_ne!(live.economy.entities[usize::from(target)].source_id, born.entity_id);
        }
        let mut same_owner = replacement.clone();
        {
            // Configured identity discriminator: the typed replacement's
            // copied parent ID matches the Skeleton, while its raw shadow's
            // former physical ID does not.
            let source = &mut same_owner.session.state.live.economy.entities[usize::from(skeleton)];
            source.source_id = parent;
            source.record[30..32].copy_from_slice(&parent.to_le_bytes());
        }
        same_owner.step_imported_model9_action73(skeleton, &frozen_models, &[]).unwrap();
        assert_eq!(same_owner.entities()[usize::from(skeleton)].action, 73,
            "20EC0 compares the current typed ID before selecting reaction pose");
        replacement.step_imported_model9_action73(skeleton, &frozen_models, &[]).unwrap();
        let reacted = &replacement.entities()[usize::from(skeleton)];
        assert_eq!((reacted.action, reacted.life, reacted.record[69], reacted.record[70]),
            (74, 999, 5, 2), "the reused typed Bee owns current class/model");
        let live = &replacement.session.state.live;
        let sentinel = &live.economy.entities[0];
        let actual = Mc2Simulation::model9_current_damage_target(
            &live.economy, source_target::Context::default(), 0,
        ).unwrap().unwrap();
        assert_eq!((actual.source_id, actual.class, actual.model),
            (sentinel.source_id, sentinel.class, sentinel.model));
        assert!(Mc2Simulation::model9_current_damage_target(
            &live.economy, source_target::Context::default(), u16::MAX,
        ).unwrap().is_none());
    }

    #[test]
    fn level_three_skeleton_action74_local_row_matches_frozen_table_callback() {
        let package = level_three_descriptor_fixture_path();
        let mut seed = CampaignSession::open(&package, CampaignSelection::LEVEL3).unwrap();
        let session = seed.simulation_mut();
        session.consume_authored_group(0, 0, 5).unwrap();
        let predator_slot = 122_u16;
        let (prey_slot, prey_position) = session
            .economy()
            .authored_class5()
            .iter()
            .find(|source| source.model == 4)
            .map(|source| (source.source_entity_index, source.position))
            .unwrap();
        session
            .set_level2_entity_position(
                predator_slot,
                Position {
                    x: prey_position.x.wrapping_sub(100),
                    ..prey_position
                },
            )
            .unwrap();
        let source = &mut session.session.state.live.economy.entities[usize::from(predator_slot)];
        assert_eq!((source.class, source.model), (5, 9));
        source.set_source_action(74);
        source.set_source_dword_10(0);
        source.phase = 0;
        source.record[66] = 0;
        source.record[61] = 0;
        source.record[56..58].fill(0);
        source.clear_source_upkeep_owner();
        let initial_life = source.life;

        for case in [
            "prey",
            "prey_allocation_failure",
            "dynamic_damage",
            "invalid_child",
        ] {
            let mut actual = seed.clone();
            let session = actual.simulation_mut();
            if case == "prey_allocation_failure" {
                session
                    .session
                    .state
                    .live
                    .economy
                    .economy
                    .exhaust_new_event_capacity_for_test()
                    .unwrap();
            }
            if matches!(case, "dynamic_damage" | "invalid_child") {
                let source =
                    &mut session.session.state.live.economy.entities[usize::from(predator_slot)];
                source.set_source_upkeep_payload(100);
                source.record[102..104].copy_from_slice(&prey_slot.to_le_bytes());
                if case == "invalid_child" {
                    // The kernel consumes damage before rejecting this link.
                    source.record[56..58].copy_from_slice(&u16::MAX.to_le_bytes());
                }
            }
            let model_slots = session
                .session
                .state
                .live
                .economy
                .rebuilt_class5_model_slots();
            let mut reference = actual.clone();
            let expected = {
                let session = reference.simulation_mut();
                let movement_pose = session.model9_particle_pose(201).unwrap();
                let reaction_pose = session.model9_particle_pose(202).unwrap();
                let source =
                    &session.session.state.live.economy.entities[usize::from(predator_slot)];
                let parameter = &session.session.definition.presentation.entity_parameters
                    [usize::from(source.parameter_relation.unwrap())];
                let scan_period = u16::from_le_bytes([parameter[26], parameter[27]]);
                let awareness_radius =
                    i32::from(i16::from_le_bytes([parameter[28], parameter[29]]));
                let scanned_model =
                    [4_u8, 12, 13][usize::from((u16::from(source.phase) / scan_period) % 3)];
                let candidates = model_slots[usize::from(scanned_model)]
                    .iter()
                    .copied()
                    .filter_map(|source_slot| {
                        session
                            .session
                            .state
                            .live
                            .economy
                            .class5_position(source_slot)
                            .map(
                                |position| campaign_shared_families::Model9ReactionCandidate {
                                    source_slot,
                                    position,
                                },
                            )
                    })
                    .collect::<Vec<_>>();
                let dynamic_targets = session.model9_dynamic_damage_targets();
                // Retain the previous full-table callback as the differential
                // oracle. The reference mutates the canonical source in place.
                let frozen = session.session.state.live.economy.entities.clone();
                let result = {
                    let live = &mut session.session.state.live;
                    let source = &mut live.economy.entities[usize::from(predator_slot)];
                    campaign_shared_families::step_model9_inner_20940(
                        source,
                        &live.terrain,
                        &frozen,
                        |slot| Ok(dynamic_targets.iter().copied().find(|target| target.source_slot == slot)
                            .or_else(|| frozen.get(usize::from(slot)).filter(|row| row.active)
                                .map(|row| campaign_shared_families::Model9DamageTarget {
                                    source_slot: slot, source_id: row.source_id, class: row.class, model: row.model,
                                }))),
                        movement_pose,
                        reaction_pose,
                        scan_period,
                        awareness_radius,
                        &candidates,
                    )
                    .map_err(|error| error.to_string())
                };
                result.and_then(|outcome| {
                    let position = session.session.state.live.economy.entities
                        [usize::from(predator_slot)]
                    .position;
                    if let Some(prey) = outcome.prey_to_consume {
                        session.convert_model9_prey(predator_slot, prey, scan_period, true)?;
                    }
                    session
                        .session
                        .state
                        .live
                        .economy
                        .economy
                        .map_chains
                        .sync_entity(RenderableMapSeed {
                            entity_index: predator_slot,
                            active: true,
                            x: position.x,
                            y: position.y,
                        })
                        .map_err(|error| {
                            format!("model-9 source slot {predator_slot} map sync failed: {error}")
                        })
                })
            };
            let observed = actual
                .simulation_mut()
                .step_imported_model9_inner_20940(predator_slot, &model_slots);
            assert_eq!(observed, expected, "{case}");
            let actual = actual.simulation();
            let reference = reference.simulation();
            assert_eq!(actual.entities(), reference.entities(), "{case}");
            assert_eq!(
                actual.campaign_state_hash(),
                reference.campaign_state_hash(),
                "{case}"
            );
            let source = &actual.entities()[usize::from(predator_slot)];
            if matches!(case, "dynamic_damage" | "invalid_child") {
                assert_eq!(source.life, initial_life - 100);
                assert_eq!(source.source_upkeep_word_62(), 0);
            }
            if case == "dynamic_damage" {
                assert_eq!((source.record[69], source.record[70]), (5, 4));
            }
            if case == "invalid_child" {
                assert!(observed.unwrap_err().contains("invalid child-chain"));
            } else {
                observed.unwrap();
            }
            if matches!(case, "prey" | "prey_allocation_failure") {
                assert!(
                    !actual
                        .economy()
                        .authored_class5()
                        .iter()
                        .find(|source| source.source_entity_index == prey_slot)
                        .unwrap()
                        .drawing_enabled
                );
                assert_eq!(
                    actual.economy().converted_skeleton_origins.is_empty(),
                    case == "prey_allocation_failure"
                );
            }
        }
    }

    #[test]
    fn level_three_skeleton_converts_nearby_archer_through_shared_source_arena() {
        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3).unwrap();
        let reset_hash = campaign.state_hash();
        let reset_counter = campaign
            .simulation()
            .economy()
            .class5_model9_constructor_phase;
        let runtime_bytes = std::fs::read(package.join("runtime.bin")).unwrap();
        if runtime_bytes[4] == 2 {
            assert_eq!(reset_counter, runtime_bytes[2_754 + 9]);
            assert_ne!(
                reset_counter, 0,
                "real Level 3 has already constructed Skeletons"
            );
        }
        let session = campaign.simulation_mut();
        session.consume_authored_group(0, 0, 5).unwrap();
        let predator_slot = 122_u16;
        let predator = &mut session.session.state.live.economy.entities[usize::from(predator_slot)];
        assert_eq!((predator.class, predator.model), (5, 9));
        // Incoming sub_203D0 mode-1/cadence boundary: it invokes sub_20940
        // without changing action73. Normal action74 owns sub_20C50's attack.
        predator.set_source_action(73);
        predator.set_source_byte_46(1);
        predator.set_source_dword_10(0);
        predator.set_phase(0);
        predator.record[61] = 0;
        let predator_id = predator.source_id;
        let (prey_slot, prey_position) = session
            .economy()
            .authored_class5()
            .iter()
            .find(|source| source.model == 4)
            .map(|source| (source.source_entity_index, source.position))
            .unwrap();
        session
            .set_level2_entity_position(
                predator_slot,
                Position {
                    x: prey_position.x.wrapping_sub(100),
                    ..prey_position
                },
            )
            .unwrap();
        let before_count = session
            .entities()
            .iter()
            .filter(|entity| entity.active && entity.class == 5 && entity.model == 9)
            .count();
        let mut allocation_failure = campaign.clone();
        allocation_failure
            .simulation_mut()
            .session
            .state
            .live
            .economy
            .economy
            .exhaust_new_event_capacity_for_test()
            .unwrap();
        allocation_failure.step(PlayerCommand::default(), 0);
        assert!(
            !allocation_failure
                .events()
                .iter()
                .any(|event| matches!(event, Mc2DispatchEvent::Error { .. })),
            "allocation failure is a normal conversion outcome: {:?}",
            allocation_failure.events()
        );
        let failed = allocation_failure.simulation();
        assert!(failed.economy().converted_skeleton_origins.is_empty());
        assert!(
            !failed
                .economy()
                .authored_class5()
                .iter()
                .find(|prey| prey.source_entity_index == prey_slot)
                .unwrap()
                .drawing_enabled,
            "NewEvent failure must not undo the source-ordered prey hide"
        );
        campaign.step(PlayerCommand::default(), 0);
        assert!(
            !campaign
                .events()
                .iter()
                .any(|event| matches!(event, Mc2DispatchEvent::Error { .. })),
            "conversion rejected: {:?}",
            campaign.events()
        );
        let session = campaign.simulation();
        assert_eq!(
            session
                .entities()
                .iter()
                .filter(|entity| entity.active && entity.class == 5 && entity.model == 9)
                .count(),
            before_count + 1,
            "predator={:?}, prey={:?}, events={:?}",
            session.entities()[usize::from(predator_slot)],
            session
                .economy()
                .authored_class5()
                .iter()
                .find(|source| source.source_entity_index == prey_slot),
            campaign.events()
        );
        assert!(session.entities().iter().any(|entity| entity.active
            && entity.class == 5
            && entity.model == 9
            && entity.index != predator_slot
            && entity.source_id == predator_id
            && entity.position.x == prey_position.x));
        assert!(
            !session
                .economy()
                .authored_class5()
                .iter()
                .find(|source| source.source_entity_index == prey_slot)
                .unwrap()
                .drawing_enabled
        );
        let child_slot = session
            .economy()
            .converted_skeleton_origins
            .iter()
            .find(|(_, producer)| **producer == predator_slot)
            .map(|(slot, _)| *slot)
            .unwrap();
        let identity = session
            .creature_identity_for_source_slot(child_slot)
            .unwrap();
        assert_eq!(
            session.entities()[usize::from(child_slot)].record[66],
            // UpdateEntities visits higher newly allocated slots in this same
            // pass and advances byte_0x3E_62 in their common epilogue.
            reset_counter.wrapping_add(u8::from(child_slot > predator_slot))
        );
        assert_eq!(
            session.economy().class5_model9_constructor_phase,
            reset_counter.wrapping_add(1)
        );
        assert_eq!(identity.kind, CreatureKind::Skeleton);
        assert_eq!(identity.root_slot, child_slot);
        assert!(identity.living);
        assert_eq!(
            identity.origin,
            crate::campaign::source_arena::CreatureRootOrigin::CreatureConversion {
                producer_slot: predator_slot,
            }
        );
        for _ in 0..24 {
            campaign.step(PlayerCommand::default(), 0);
            assert!(
                !campaign
                    .events()
                    .iter()
                    .any(|event| matches!(event, Mc2DispatchEvent::Error { .. })),
                "converted Skeleton lifecycle rejected: {:?}",
                campaign.events()
            );
        }
        let session = campaign.simulation();
        assert!(
            !session
                .economy()
                .authored_class5()
                .iter()
                .any(|prey| prey.source_entity_index == prey_slot && prey.active)
        );
        let child = &session.entities()[usize::from(child_slot)];
        assert!(
            child.active && !child.drawing_disabled() && matches!(child.action, 73 | 74),
            "replacement must reach a live movement/reaction callback: {child:?}"
        );
        assert_ne!(
            (child.position.x, child.position.y),
            (prey_position.x, prey_position.y),
            "replacement must move after the constructor countdown: {child:?}"
        );
        // At the common hide boundary the conversion's semantic provenance
        // must expire with its source generation, not survive slot reuse.
        campaign
            .simulation_mut()
            .session
            .state
            .live
            .economy
            .entities[usize::from(child_slot)]
        .disable_drawing();
        campaign.step(PlayerCommand::default(), 0);
        assert!(
            !campaign
                .simulation()
                .economy()
                .converted_skeleton_origins
                .contains_key(&child_slot)
        );
        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);
        assert_eq!(
            campaign
                .simulation()
                .economy()
                .class5_model9_constructor_phase,
            reset_counter
        );
        assert!(
            campaign
                .simulation()
                .economy()
                .converted_skeleton_origins
                .is_empty()
        );
    }

