    #[test]
    fn package_stone_is_not_misclassified_as_an_area_exit_switch() {
        const REUSED_SWITCH_SLOT: u16 = 150;

        let package = level_one_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL1)
            .expect("real Level 1 descriptor opens");
        let session = campaign.simulation_mut();
        assert_eq!(
            session
                .session
                .definition
                .switch_for_initial_source_slot(REUSED_SWITCH_SLOT),
            Some(SwitchKind::AreaEntryTrigger)
        );
        assert_eq!(session.economy().slot_generation(REUSED_SWITCH_SLOT), 0);
        let stone_feature = session
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .copied()
            .find(|feature| feature.index == 154)
            .expect("package group 6 contains its authored Stone");
        assert_eq!((stone_feature.kind, stone_feature.subtype), (2, 1));
        session.economy_mut().exhaust_new_event_capacity_for_test();
        assert!(
            session
                .economy_mut()
                .restore_new_event_slot_for_test(REUSED_SWITCH_SLOT)
        );
        let stone_slot = session
            .allocate_authored_stone_feature(stone_feature)
            .expect("the real package Stone reuses the semantic switch slot");
        assert_eq!(stone_slot, REUSED_SWITCH_SLOT);
        assert!(session.economy().slot_generation(stone_slot) > 0);
        let phase_before = session.entities()[usize::from(stone_slot)].phase;

        session.step_outer_turn(PlayerCommand::default(), 0);

        assert!(session.dispatch_events().iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::Error { source_slot, .. } if *source_slot == stone_slot
        )));
        let stone = &session.entities()[usize::from(stone_slot)];
        assert_eq!((stone.class, stone.model, stone.action), (2, 1, 3));
        assert_eq!(stone.phase, phase_before.wrapping_add(1));
    }

    #[test]
    fn level_two_no_standing_buildings_waits_for_reclaim_and_cadence_then_opens_group31() {
        const PRIOR_STAGE: usize = 3;
        const FINAL_STAGE: usize = 4;
        const GROUP31_ROWS: [u16; 15] = [
            209, 244, 260, 261, 262, 264, 265, 266, 267, 268, 269, 270, 271, 272, 274,
        ];

        // Stage the preceding objective boundary and supply fixed damage
        // mailboxes. Construction, successors, reclaim, objective evaluation
        // and the exit producer still run through the ordinary scheduler.
        let package = authored_vault_package_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("real Level 2 descriptor opens");
        let baseline_hash = campaign.state_hash();
        let session = campaign.simulation_mut();
        let objective_id =
            crate::level_definition::LevelObjectiveId::parse("objective.clear.payahandra_vaults")
                .unwrap();
        assert_eq!(
            session
                .session
                .definition
                .standing_building_chain(&objective_id),
            Some(&[21, 54][..])
        );
        let ordinary_house_rows = session
            .ordinary()
            .houses()
            .iter()
            .filter(|house| house.active)
            .map(|house| (house.entity_index, house.building_index))
            .collect::<Vec<_>>();
        let ordinary_houses = ordinary_house_rows
            .iter()
            .map(|(_, selector)| *selector)
            .collect::<Vec<_>>();
        assert_eq!(ordinary_houses.len(), 22);
        assert!(
            session
                .campaign_building_objective_targets(FINAL_STAGE)
                .is_empty()
        );
        assert!(
            ordinary_houses
                .iter()
                .all(|selector| ![21, 54].contains(selector))
        );
        let group31_root = session
            .entities()
            .iter()
            .find(|entity| {
                entity.active
                    && entity.class == 11
                    && entity.model == 4
                    && entity.action == 4
                    && entity.source_id == 31
            })
            .map(|entity| entity.index)
            .expect("real Level 2 group-31 root");
        assert_eq!(group31_root, 37);

        // Stage only the preceding real model-32 boundary, then invoke its
        // production group-8 constructor before the turn under test. The
        // tested turns still own every model-45 callback, epilogue, reclaim,
        // objective evaluation, and group-31 consumer.
        {
            let objective = &mut session.session.state.live.core.runtime.objectives[0];
            objective.stage_selectors.fill(0);
            objective.stage_selectors[PRIOR_STAGE] = 2;
            objective.text_selector = PRIOR_STAGE as u8;
            objective.done = 0;
            objective.is_level_end = 0;
        }
        session.activate_level2_authored_group8(0);
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: 32,
                group: 8,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [153, 154]
        )));
        let vault_slots = [153, 154].map(|record| {
            session
                .economy()
                .authored_house_source_slot(record)
                .unwrap()
        });
        let frozen_before_group8 = session
            .session
            .state
            .live
            .source_model45_building_selectors
            .clone();
        let mut expected_current_census = ordinary_houses.clone();
        expected_current_census.extend([21, 21]);
        expected_current_census.sort_unstable();
        let live = &session.session.state.live;
        let mut current_census = live
            .ordinary
            .current_building_rows(&live.economy)
            .into_iter()
            .map(|(_, selector, _)| selector)
            .collect::<Vec<_>>();
        current_census.sort_unstable();
        assert_eq!(current_census, expected_current_census);

        // A zero-pass outer turn must not rebuild the source list. The two
        // newly born targets are visible in current rows but remain absent
        // from the last UpdateEntities membership until a real pass starts.
        session.session.state.live.source_frame_timing_index = 14;
        session.step_outer_turn(PlayerCommand::default(), 3);
        assert_eq!(session.source_frame_timing_index, 15);
        let marked = session.campaign_building_objective_targets(FINAL_STAGE);
        assert_eq!(
            marked.len(),
            2,
            "completed outer-turn group-8 births are objective map targets"
        );
        assert!(
            session
                .campaign_building_objective_targets(PRIOR_STAGE)
                .is_empty(),
            "the preceding reach-location objective does not acquire building targets"
        );
        assert_eq!(
            session.session.state.live.source_model45_building_selectors,
            frozen_before_group8
        );

        for _ in 0..32 {
            session.step_outer_turn(PlayerCommand::default(), 0);
        }
        for slot in vault_slots {
            let house = session
                .ordinary()
                .houses()
                .iter()
                .find(|house| house.entity_index == slot)
                .unwrap();
            assert_eq!(
                (house.active, house.building_index, house.action, house.life),
                (true, 21, 52, 6000)
            );
        }
        {
            let live = &mut session.session.state.live;
            let objective = &mut live.core.runtime.objectives[0];
            objective.stage_selectors.fill(2);
            objective.stage_selectors[FINAL_STAGE] = 1;
            objective.text_selector = FINAL_STAGE as u8;
            objective.done = 0;
            objective.is_level_end = 0;
            live.level2_objective_pause = 0;
            live.level2_objective_done = false;
        }

        let player = session.state.entity_index;
        for slot in vault_slots {
            assert!(
                session
                    .session
                    .state
                    .live
                    .ordinary
                    .houses
                    .submit_source_damage(slot, 6001, player)
            );
        }
        for _ in 0..32 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            assert_eq!(
                session.runtime().objectives[0].stage_selectors[FINAL_STAGE],
                1
            );
        }
        let successors = session
            .ordinary()
            .houses()
            .iter()
            .filter(|house| house.active && house.building_index == 54)
            .map(|house| {
                assert_eq!((house.action, house.life), (52, 8000));
                house.entity_index
            })
            .collect::<Vec<_>>();
        assert_eq!(successors.len(), 2);
        assert_eq!(
            session
                .campaign_building_objective_targets(FINAL_STAGE)
                .into_iter()
                .map(|(slot, _)| slot)
                .collect::<Vec<_>>(),
            successors
        );

        // Leave the second successor standing across a cadence boundary.
        assert!(
            session
                .session
                .state
                .live
                .ordinary
                .houses
                .submit_source_damage(successors[0], 8001, player)
        );
        for _ in 0..16 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            assert_eq!(
                session.runtime().objectives[0].stage_selectors[FINAL_STAGE],
                1
            );
        }
        assert_eq!(
            session
                .campaign_building_objective_targets(FINAL_STAGE)
                .into_iter()
                .map(|(slot, _)| slot)
                .collect::<Vec<_>>(),
            successors[1..]
        );

        // Even when demolition runs on a due frame, its pass-start membership
        // blocks completion. The next due frame may complete after reclaim.
        session.session.state.live.source_frame_timing_index = 15;
        session.session.state.live.core.players[0].turn = 3;
        assert!(
            session
                .session
                .state
                .live
                .ordinary
                .houses
                .submit_source_damage(successors[1], 8001, player)
        );
        for frame in 16..32 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            assert_eq!(session.source_frame_timing_index, frame);
            assert_eq!(
                session.runtime().objectives[0].stage_selectors[FINAL_STAGE],
                1
            );
        }
        assert!(
            session
                .campaign_building_objective_targets(FINAL_STAGE)
                .is_empty()
        );
        assert!(
            session
                .economy()
                .spell_pickups()
                .iter()
                .any(|row| row.authored_index == 155)
        );
        assert!(
            session
                .economy()
                .spell_pickups()
                .iter()
                .any(|row| row.authored_index == 156)
        );
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.source_frame_timing_index, 32);
        assert_eq!(
            session.runtime().objectives[0].stage_selectors[FINAL_STAGE],
            2
        );
        assert_eq!(session.runtime().objectives[0].is_level_end, 1);
        assert!(
            session.campaign_exit_objective_target().is_none(),
            "completion alone must not invent an exit before its group is born"
        );
        assert_eq!(
            session
                .ordinary()
                .houses()
                .iter()
                .filter(|house| house.active)
                .count(),
            22,
            "ordinary Houses are not members of the package-bound [21,54] target chain"
        );
        assert!(session.dispatch_events().iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated { group: 31, .. }
        )));

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: 37,
                group: 31,
                authored_indices,
                ..
            } if authored_indices.as_ref() == GROUP31_ROWS
        )));
        assert!(
            session
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. }))
        );

        let target = session
            .campaign_exit_objective_target()
            .expect("ordinary group-31 birth exposes the live exit arrow target");
        let exit = session
            .economy()
            .authored_switch_producers()
            .iter()
            .find(|source| source.active && source.source_entity_index == target.0)
            .expect("target uses the dynamic source carrier, not a stale imported row");
        assert_eq!((exit.model, exit.action), (12, 12));
        assert_eq!(target.1, exit.position);
        let before_map_poll = session.campaign_state_hash();
        assert_eq!(session.campaign_exit_objective_target(), Some(target));
        assert_eq!(session.campaign_state_hash(), before_map_poll);

        campaign.reset();
        assert_eq!(campaign.state_hash(), baseline_hash);
        let reset = campaign.simulation();
        assert_eq!(reset.source_frame_timing_index, 0);
        assert_eq!(reset.runtime().objectives[0].is_level_end, 0);
        assert!(reset.campaign_exit_objective_target().is_none());
        assert!(
            reset
                .entities()
                .get(usize::from(group31_root))
                .is_some_and(|root| root.active && !root.drawing_disabled())
        );
    }

    #[test]
    fn semantic_experience_scroll_collects_and_reclaims_through_the_source_scheduler() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("real Level 2 descriptor opens");
        let reset_hash = campaign.state_hash();
        let session = campaign.simulation_mut();
        session
            .consume_authored_group(0, 0, 5)
            .expect("real package group 5 materializes through the shared arena");
        let scroll = session
            .economy()
            .authored_class14()
            .iter()
            .find(|source| source.authored_index == 248)
            .copied()
            .expect("package-authored experience scroll is present in the shared arena");
        assert_eq!(
            session.item_kind_for_source_slot(scroll.source_entity_index),
            Some(ItemKind::ExperienceScroll)
        );
        let experience_before = *session.shared_spells().spell_experience();
        let player_entity_index = session.state.entity_index;
        session
            .set_level2_entity_position(player_entity_index, scroll.position)
            .expect("stage the real player at the real package scroll position");

        session.step_outer_turn(PlayerCommand::default(), 0);

        assert!(session.shared_spells().pickup_events().iter().any(|event| {
            matches!(
                event,
                Level2SharedSpellEvent::ExperienceScrollCollected {
                    source_slot,
                    player_entity_index: observed_player,
                } if *source_slot == scroll.source_entity_index
                    && *observed_player == player_entity_index
            )
        }));
        assert_ne!(
            session.shared_spells().spell_experience(),
            &experience_before,
            "the semantic item callback must reach the existing XP consumer"
        );
        let retained = session
            .economy()
            .authored_class14()
            .iter()
            .find(|source| source.source_entity_index == scroll.source_entity_index)
            .expect("collected scroll remains allocated through its callback pass");
        assert!(retained.active);
        assert!(!retained.drawing_enabled);
        assert_eq!(retained.phase, scroll.phase.wrapping_add(1));
        assert!(
            session
                .economy()
                .map_chains()
                .is_linked(scroll.source_entity_index)
        );

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(
            !session
                .economy()
                .authored_class14()
                .iter()
                .any(|source| source.source_entity_index == scroll.source_entity_index)
        );
        assert!(
            !session
                .economy()
                .map_chains()
                .is_linked(scroll.source_entity_index)
        );
        assert!(
            session
                .economy()
                .free_slots
                .contains(&scroll.source_entity_index)
        );

        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);

        let mut mismatch = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("real Level 2 descriptor reopens for the planted negative");
        let mismatch_session = mismatch.simulation_mut();
        mismatch_session
            .consume_authored_group(0, 0, 5)
            .expect("real package group 5 materializes for the planted negative");
        let mismatch_scroll_slot = mismatch_session
            .economy()
            .authored_class14()
            .iter()
            .find(|source| source.authored_index == 248)
            .map(|source| source.source_entity_index)
            .expect("the real package scroll has a source slot");
        let mut mismatch_economy = mismatch_session.economy_mut();
        let source = mismatch_economy
            .authored_class14
            .iter_mut()
            .find(|source| source.source_entity_index == mismatch_scroll_slot)
            .expect("the semantic scroll carrier remains mutable in the shared arena");
        source.model = 3;
        source.action = 8;

        mismatch_session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(mismatch_session.dispatch_events().iter().any(|event| {
            matches!(
                event,
                Mc2DispatchEvent::Error {
                    source_slot,
                    message,
                    ..
                } if *source_slot == mismatch_scroll_slot
                    && message.contains("semantic experience_scroll")
                    && message.contains("model 3 action 8")
            )
        }));
        assert!(!mismatch_session
            .shared_spells()
            .pickup_events()
            .iter()
            .any(|event| matches!(event, Level2SharedSpellEvent::ExperienceScrollCollected { source_slot, .. } if *source_slot == mismatch_scroll_slot)));

        let mut suppressed = CampaignSession::open(&package, CampaignSelection::LEVEL2).unwrap();
        suppressed.simulation_mut().install_initial_mission_rewards(
            crate::campaign::rewards::MissionRewards::Suppressed,
        ).unwrap();
        let suppressed_reset = suppressed.state_hash();
        assert_ne!(suppressed_reset, reset_hash);
        let session = suppressed.simulation_mut();
        session.consume_authored_group(0, 0, 5).unwrap();
        let scroll = *session.economy().authored_class14().iter()
            .find(|row| row.authored_index == 248).unwrap();
        let xp = *session.shared_spells().spell_experience();
        session.set_level2_entity_position(session.state.entity_index, scroll.position).unwrap();
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.shared_spells().spell_experience(), &xp);
        assert!(!session.shared_spells().pickup_events().iter().any(|event| matches!(
            event, Level2SharedSpellEvent::ExperienceScrollCollected { source_slot, .. }
                if *source_slot == scroll.source_entity_index
        )));
        let hidden = session.economy().authored_class14().iter()
            .find(|row| row.source_entity_index == scroll.source_entity_index).unwrap();
        assert!(hidden.active && !hidden.drawing_enabled);
        assert_eq!(hidden.control_flags & 1, 1);
        assert_eq!(hidden.position, scroll.position, "suppression runs before ground snapping");
        assert_eq!(hidden.phase, scroll.phase.wrapping_add(1));
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(session.economy().free_slots.contains(&scroll.source_entity_index));
        assert!(session.install_initial_mission_rewards(crate::campaign::rewards::MissionRewards::Enabled).is_err());
        suppressed.reset();
        assert_eq!(suppressed.state_hash(), suppressed_reset);
        assert_eq!(suppressed.simulation().mission_rewards(), crate::campaign::rewards::MissionRewards::Suppressed);
    }

    #[test]
    fn semantic_objective_gate_activates_its_package_group_and_rejects_unbound_rows() {
        let package = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-cf02-campaign-package-v2-b/qualified-level2");
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL2)
            .expect("real Level 2 descriptor opens");
        let reset_hash = campaign.state_hash();
        let session = campaign.simulation_mut();
        let (gate_slot, gate_stage_index) = session
            .entities()
            .iter()
            .find(|entity| {
                entity.active
                    && entity.class == 11
                    && entity.model == 32
                    && entity.action == 32
                    && entity.source_id == 21
            })
            .map(|entity| {
                (
                    entity.index,
                    usize::try_from(entity.level_gate)
                        .expect("objective-gate stage index fits usize"),
                )
            })
            .expect("the real reset contains the group-21 objective gate");
        assert_eq!(
            session.switch_kind_for_source_slot(gate_slot),
            Some(SwitchKind::ObjectiveGate)
        );

        session.step_outer_turn(PlayerCommand::default(), 0);

        assert!(session.dispatch_events().iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated { group: 21, .. }
        )));
        assert!(!session.entities()[usize::from(gate_slot)].drawing_disabled());

        for objective_index in 0..session.session.state.live.core.runtime.objectives.len() {
            session
                .session
                .state
                .live
                .core
                .runtime
                .set_level2_objective_stage_selector_for(objective_index, gate_stage_index, 2);
        }
        session.step_outer_turn(PlayerCommand::default(), 0);

        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot,
                group: 21,
                authored_indices,
                ..
            } if *source_slot == gate_slot && authored_indices.as_ref() == [229, 230, 231]
        )));
        assert!(session.dispatch_events().iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::Error { source_slot, .. } if *source_slot == gate_slot
        )));
        assert!(session.entities()[usize::from(gate_slot)].drawing_disabled());

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(!session.entities()[usize::from(gate_slot)].active);
        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);

        let level_one = level_one_descriptor_fixture_path();
        let mut mismatch = CampaignSession::open(&level_one, CampaignSelection::LEVEL1)
            .expect("real Level 1 descriptor opens for the planted negative");
        let mismatch_session = mismatch.simulation_mut();
        mismatch_session
            .consume_authored_group(0, 0, 1)
            .expect("real package group 1 materializes its first objective gate");
        let gate = mismatch_session
            .economy()
            .authored_model32()
            .iter()
            .find(|source| source.authored_index == 99)
            .copied()
            .expect("package row 99 is a live objective gate");
        let mut mismatch_economy = mismatch_session.economy_mut();
        let source = mismatch_economy
            .authored_model32
            .iter_mut()
            .find(|source| source.source_entity_index == gate.source_entity_index)
            .expect("the objective gate remains in the shared arena");
        source.authored_index = u16::MAX;

        mismatch_session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(
            mismatch_session
                .dispatch_events()
                .iter()
                .any(|event| matches!(
                    event,
                    Mc2DispatchEvent::Error {
                        source_slot,
                        message,
                        ..
                    } if *source_slot == gate.source_entity_index
                        && message.contains("objective-gate")
                        && message.contains("no package-authored semantic identity")
                ))
        );
    }

    fn level_three_descriptor_fixture_path() -> PathBuf {
        std::env::var_os("MC_CAMPAIGN_PACKAGE_LEVEL3_V1").map_or_else(
            || {
                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../generated/mc-cf14-campaign-package-v1-a/qualified-level3")
            },
            PathBuf::from,
        )
    }

    #[test]
    fn cf14_level3_spell_pickups_share_one_entity_and_player_authority() {
        for (source_slot, family, pickup_action, active_action) in
            [(124_u16, 6_u8, 19_u8, 18_u8), (126, 11, 34, 33)]
        {
            let package = level_three_descriptor_fixture_path();
            let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
                .expect("qualified Level 3 descriptor opens");
            let baseline_hash = campaign.state_hash();
            let player_entity_index = campaign
                .simulation()
                .session
                .state
                .live
                .core
                .state
                .entity_index;
            let baseline_pickup = campaign.simulation().session.state.live.economy.entities
                [usize::from(source_slot)]
            .clone();
            assert_eq!(
                (
                    baseline_pickup.class,
                    baseline_pickup.model,
                    baseline_pickup.action
                ),
                (15, family, pickup_action)
            );
            let baseline_player = campaign
                .simulation()
                .session
                .state
                .live
                .core
                .players
                .iter()
                .find(|player| player.entity_index == player_entity_index)
                .cloned()
                .expect("local Level 3 player row");
            let family_index = usize::from(family);
            let unchanged_offsets = [398, 424, 450, 502, 528];

            campaign
                .simulation_mut()
                .set_level2_entity_position(player_entity_index, baseline_pickup.position)
                .expect("public local-player input reaches the pickup position");
            for _ in 0..4 {
                let _ = campaign.step(PlayerCommand::default(), 0);
                if campaign.simulation().session.state.live.economy.entities
                    [usize::from(source_slot)]
                .action
                    == active_action
                {
                    break;
                }
            }

            let live = &campaign.simulation().session.state.live;
            let raw_pickup = &live.economy.entities[usize::from(source_slot)];
            let typed_pickup = live
                .shared_spells
                .pickups()
                .iter()
                .find(|pickup| pickup.index == source_slot)
                .expect("typed pickup projection remains addressable");
            assert_eq!(raw_pickup.action, active_action);
            assert_eq!(raw_pickup.record_bytes(), typed_pickup.record_bytes());
            let canonical_player = live
                .core
                .players
                .iter()
                .find(|player| player.entity_index == player_entity_index)
                .expect("canonical local player remains addressable");
            let shared_player = live
                .shared_spells
                .players()
                .iter()
                .find(|player| player.entity_index == player_entity_index)
                .expect("shared local player remains addressable");
            assert_eq!(
                canonical_player.record_bytes(),
                shared_player.record_bytes()
            );
            assert_eq!(
                canonical_player.enabled_spell_holders[family_index],
                source_slot
            );
            assert_eq!(canonical_player.acquired_spell_flags[family_index], 1);
            assert_eq!(canonical_player.record_bytes()[476 + family_index], 1);
            assert_eq!(canonical_player.left_spell_slot_raw, i16::from(family));
            assert_eq!(
                canonical_player.left_subspell_index,
                baseline_player.family_selected_tiers[family_index]
            );
            for offset in unchanged_offsets {
                assert_eq!(
                    canonical_player.record_bytes()[offset + family_index],
                    baseline_player.record_bytes()[offset + family_index],
                    "sub_68FF0 must not write compact player offset {} for family {family}",
                    offset + family_index
                );
            }

            let effects = campaign
                .effects_after(
                    crate::campaign::journal::EffectCursor {
                        generation: campaign.generation(),
                        next_sequence: 0,
                    },
                    16_384,
                )
                .expect("pickup journal")
                .records;
            let sound_sequence = effects
                .iter()
                .find_map(|record| match record.effect {
                    crate::campaign::journal::CampaignEffect::Flight(
                        crate::FlightEvent::PrepareSound {
                            entity_index,
                            player_index: -1,
                            sound_id: 18,
                            ..
                        },
                    ) if entity_index == player_entity_index => Some(record.sequence),
                    _ => None,
                })
                .expect("source pickup sound 18");
            let acquisition_sequence = effects
                .iter()
                .find_map(|record| match record.effect {
                    crate::campaign::journal::CampaignEffect::SharedSpell(
                        Level2SharedSpellEvent::SpellAcquired {
                            source_slot: event_slot,
                            family: event_family,
                            ..
                        },
                    ) if event_slot == source_slot && event_family == family => {
                        Some(record.sequence)
                    }
                    _ => None,
                })
                .expect("typed spell-acquisition receipt");
            assert!(sound_sequence < acquisition_sequence);

            let phase_before = raw_pickup.phase;
            let timer_before = u16::from_le_bytes(
                raw_pickup.record_bytes()[58..60]
                    .try_into()
                    .expect("pickup timer bytes"),
            );
            let _ = campaign.step(PlayerCommand::default(), 0);
            let raw_pickup = &campaign.simulation().session.state.live.economy.entities
                [usize::from(source_slot)];
            assert_eq!(raw_pickup.action, active_action);
            assert_eq!(raw_pickup.phase, phase_before.wrapping_add(1));
            assert_eq!(
                u16::from_le_bytes(
                    raw_pickup.record_bytes()[58..60]
                        .try_into()
                        .expect("pickup timer bytes")
                ),
                timer_before.wrapping_sub(1)
            );

            campaign.reset();
            assert_eq!(campaign.state_hash(), baseline_hash);
            assert!(
                campaign
                    .effects_after(
                        crate::campaign::journal::EffectCursor {
                            generation: campaign.generation(),
                            next_sequence: 0,
                        },
                        1,
                    )
                    .expect("reset pickup journal")
                    .records
                    .is_empty()
            );
            let reset_live = &campaign.simulation().session.state.live;
            assert_eq!(
                reset_live.economy.entities[usize::from(source_slot)].record_bytes(),
                baseline_pickup.record_bytes()
            );
            assert_eq!(
                reset_live
                    .core
                    .players
                    .iter()
                    .find(|player| player.entity_index == player_entity_index)
                    .expect("reset local player")
                    .record_bytes(),
                baseline_player.record_bytes()
            );
        }
    }

    #[test]
    fn level_three_player_upkeep_syncs_canonical_life_before_one_fireball_damage() {
        const DRAGON_SLOT: u16 = 119;
        const DRAGON_FIREBALL_DAMAGE: u16 = 500;

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let player_entity_index = campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;
        let player_position = campaign.simulation().session.state.live.core.state.position;
        {
            let live = &mut campaign.simulation_mut().session.state.live;
            live.player_life = 2_000;
            live.shared_spells.set_player_entity_life(2_000);
            live.economy.entities[usize::from(player_entity_index)].set_life(2_000);
        }

        // The first source visit selects the outdoor max_life/2000 upkeep;
        // the following visit applies that exact five-point rate.
        let _ = campaign.step(PlayerCommand::default(), 0);
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            (
                live.player_life,
                live.shared_spells.player_entity.life,
                live.economy.entities[usize::from(player_entity_index)].life,
            ),
            (2_005, 2_005, 2_005),
            "source upkeep must publish the single player life to every damage carrier"
        );

        campaign
            .simulation_mut()
            .apply_level2_class10_model0_damage(level2_dynamic_economy::Level2Class10Model0Step {
                live: true,
                first_impact: true,
                damage_pulse: true,
                owner_entity_index: DRAGON_SLOT,
                payload: DRAGON_FIREBALL_DAMAGE,
                position: player_position,
            });
        let player = &campaign.simulation().session.state.live.economy.entities
            [usize::from(player_entity_index)];
        assert_eq!(
            (
                player.source_upkeep_payload(),
                player.source_upkeep_word_62()
            ),
            (i32::from(DRAGON_FIREBALL_DAMAGE), DRAGON_SLOT)
        );

        let events_before = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .events
            .len();
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            (
                live.player_life,
                live.shared_spells.player_entity.life,
                live.economy.entities[usize::from(player_entity_index)].life,
            ),
            (1_505, 1_505, 1_505),
            "one 500 pulse starts the source cooldown before same-visit outdoor upkeep"
        );
        assert_eq!(
            live.economy.events[events_before..]
                .iter()
                .filter(|event| matches!(
                    event,
                    Level2EconomyEvent::DamageApplied {
                        target_entity_index,
                        attacker_entity_index: DRAGON_SLOT,
                        damage: 500,
                        lethal: false,
                    } if *target_entity_index == player_entity_index
                ))
                .count(),
            1
        );

        let mut protected = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 Castle-protection descriptor opens");
        let protected_player = protected
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;
        let protected_terrain = protected.simulation().session.state.live.terrain.clone();
        let protected_position = {
            let live = &mut protected.simulation_mut().session.state.live;
            let castle_slot = live
                .economy
                .build_castle(
                    live.core.state.position,
                    protected_player,
                    &protected_terrain,
                )
                .expect("focused Castle protection root");
            let castle = live.economy.castle.as_mut().expect("focused Castle root");
            assert_eq!(castle.source_entity_index, castle_slot);
            castle.shift_yaw = -8_192;
            castle.shift_pitch = 1_664;
            castle.shift_roll = 1_664;
            castle.shift_fov = 0x4000;
            crate::Position {
                x: castle.position.x,
                y: castle.position.y,
                z: castle.position.z.wrapping_add(1_000),
            }
        };
        {
            let live = &mut protected.simulation_mut().session.state.live;
            live.core.state.position = protected_position;
            let set_player = |entity: &mut EntitySnapshot| {
                entity.record[86..88].copy_from_slice(&100_i16.to_le_bytes());
                entity.record[88..90].copy_from_slice(&121_i16.to_le_bytes());
                entity.record[90..92].copy_from_slice(&121_i16.to_le_bytes());
                entity.record[92..94].copy_from_slice(&100_i16.to_le_bytes());
                entity.set_position(protected_position);
            };
            set_player(&mut live.shared_spells.player_entity);
            live.shared_spells.player_entities[0] = live.shared_spells.player_entity.clone();
            set_player(&mut live.economy.entities[usize::from(protected_player)]);
        }
        let _ = protected.step(PlayerCommand::default(), 0);
        {
            let live = &mut protected.simulation_mut().session.state.live;
            assert!(
                live.economy
                    .player_castle_shift_aabb_overlap(&live.shared_spells.player_entity)
            );
            assert_eq!(
                live.shared_spells.player_life_regen,
                live.shared_spells.player_entity.max_life / 250
            );
            live.player_life = 2_000;
            live.shared_spells.set_player_entity_life(2_000);
            live.economy.entities[usize::from(protected_player)].set_life(2_000);
        }
        protected
            .simulation_mut()
            .apply_level2_class10_model0_damage(level2_dynamic_economy::Level2Class10Model0Step {
                live: true,
                first_impact: true,
                damage_pulse: true,
                owner_entity_index: DRAGON_SLOT,
                payload: DRAGON_FIREBALL_DAMAGE,
                position: protected_position,
            });
        let protected_events_before = protected
            .simulation()
            .session
            .state
            .live
            .economy
            .events
            .len();
        let _ = protected.step(PlayerCommand::default(), 0);
        let live = &protected.simulation().session.state.live;
        let castle_slot = live.economy.player_castle_entity_index();
        assert_eq!(
            (
                live.player_life,
                live.shared_spells.player_entity.life,
                live.economy.entities[usize::from(protected_player)].life,
            ),
            (2_040, 2_040, 2_040),
            "an overlapping Castle receives the hostile mailbox before player upkeep"
        );
        assert_eq!(
            live.economy.events[protected_events_before..]
                .iter()
                .filter(|event| matches!(
                    event,
                    Level2EconomyEvent::DamageApplied {
                        target_entity_index,
                        attacker_entity_index: DRAGON_SLOT,
                        ..
                    } if *target_entity_index == protected_player
                ))
                .count(),
            0,
            "Castle overlap must suppress the player damage consumer"
        );
        assert!(
            live.economy.events[protected_events_before..]
                .iter()
                .any(|event| matches!(
                    event,
                    Level2EconomyEvent::DamageApplied {
                        target_entity_index,
                        attacker_entity_index: DRAGON_SLOT,
                        damage,
                        lethal: false,
                    } if *target_entity_index == castle_slot && *damage >= 500
                )),
            "the transferred hostile mailbox must reach the Castle damage consumer"
        );
    }

    #[test]
    fn level_three_dragon_link_selector_follows_peer_then_inherits_attack() {
        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let player_entity_index = campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;

        let skeleton_slots = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .entities
            .iter()
            .filter(|entity| entity.active && entity.class == 5 && entity.model == 9)
            .map(|entity| entity.index)
            .collect::<Vec<_>>();
        assert_eq!(skeleton_slots.len(), 11);
        for source_slot in skeleton_slots {
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .entities[usize::from(source_slot)]
            .disable_drawing();
        }
        let _ = campaign.step(PlayerCommand::default(), 0);
        let _ = campaign.step(PlayerCommand::default(), 0);

        let mut dragon_slots = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .filter(|source| source.active && source.model == level2_class5::dragon::DRAGON_MODEL)
            .map(|source| source.source_entity_index)
            .collect::<Vec<_>>();
        dragon_slots.sort_unstable();
        assert_eq!(dragon_slots.len(), 2);
        let follower_slot = dragon_slots[0];
        let peer_slot = dragon_slots[1];

        let terrain = campaign.simulation().session.state.live.terrain.clone();
        let mut follower_position = Position {
            x: (79_u16 << 8).wrapping_add(128),
            y: (143_u16 << 8).wrapping_add(128),
            z: 0,
        };
        follower_position.z = terrain.ground_height(follower_position);
        let mut peer_position = follower_position;
        peer_position.x = peer_position.x.wrapping_add(512);
        peer_position.z = terrain.ground_height(peer_position);
        let peer_heading = i16::try_from(crate::heading_for_positions(
            follower_position,
            peer_position,
        ))
        .expect("Dragon peer heading fits i16");
        {
            let mut economy = campaign.simulation_mut().economy_mut();
            assert!(economy.stage_authored_dragon_attack_prerequisite_for_test(
                follower_slot,
                follower_position,
                30,
            ));
            assert!(economy.stage_authored_dragon_attack_prerequisite_for_test(
                peer_slot,
                peer_position,
                1,
            ));
        }
        {
            let mut economy = campaign.simulation_mut().economy_mut();
            let follower = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == follower_slot)
                .expect("mutable follower Dragon");
            follower.action = level2_class5::dragon::DRAGON_ROAM_ACTION;
            follower.yaw = peer_heading;
            follower.roll = peer_heading;
            let peer = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == peer_slot)
                .expect("mutable peer Dragon");
            peer.action = level2_class5::dragon::DRAGON_ROAM_ACTION;
            economy
                .authored_dragons
                .iter_mut()
                .find(|state| state.source_entity_index == follower_slot)
                .expect("follower Dragon sidecar")
                .linked_entity_index = 0;
        }

        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. }))
        );
        let follower = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == follower_slot)
            .expect("linked follower remains live");
        let follower_link = live
            .economy
            .economy
            .authored_dragons()
            .iter()
            .find(|state| state.source_entity_index == follower_slot)
            .expect("linked follower sidecar")
            .linked_entity_index;
        assert_eq!(
            (
                follower.action,
                follower.source_byte_3e,
                follower_link,
                follower.actual_speed,
            ),
            (
                level2_class5::dragon::DRAGON_LINK_ACTION,
                31,
                peer_slot,
                level2_class5::dragon::DRAGON_ACTUAL_SPEED,
            )
        );

        let (follower_before, peer_before) = {
            let economy = &live.economy.economy;
            let follower = economy
                .authored_class5()
                .iter()
                .find(|source| source.source_entity_index == follower_slot)
                .copied()
                .expect("follower before linked cadence");
            let peer = economy
                .authored_class5()
                .iter()
                .find(|source| source.source_entity_index == peer_slot)
                .copied()
                .expect("peer before linked cadence");
            (follower, peer)
        };
        {
            let mut economy = campaign.simulation_mut().economy_mut();
            let follower = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == follower_slot)
                .expect("mutable linked follower");
            follower.action = level2_class5::dragon::DRAGON_LINK_ACTION;
            follower.source_byte_3e = 60;
            let peer = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == peer_slot)
                .expect("mutable followed peer");
            peer.action = level2_class5::dragon::DRAGON_ROAM_ACTION;
            peer.source_byte_3e = 1;
            economy
                .authored_dragons
                .iter_mut()
                .find(|state| state.source_entity_index == follower_slot)
                .expect("follower Dragon sidecar")
                .linked_entity_index = peer_slot;
        }
        let follower_motion = crate::ground_creature_motion::step_ground_creature_motion(
            follower_before.position,
            follower_before.yaw,
            follower_before.roll,
            follower_before.actual_speed,
            &terrain,
            crate::ground_creature_motion::GroundCreatureMotionConfig {
                ground_clearance: 0,
                descent: -4,
                turn_limit: 34,
                terrain_mask: u32::MAX,
                maximum_tile_slope: 30,
                half_width: follower_before.shift_rot_x,
                half_height: follower_before.shift_rot_y,
            },
        );
        let expected_roll = i16::try_from(crate::heading_for_positions(
            follower_motion.position,
            peer_before.position,
        ))
        .expect("Dragon peer heading fits i16");
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        let follower = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == follower_slot)
            .expect("cadence-following Dragon remains live");
        let follower_link = live
            .economy
            .economy
            .authored_dragons()
            .iter()
            .find(|state| state.source_entity_index == follower_slot)
            .expect("cadence-following Dragon sidecar")
            .linked_entity_index;
        assert_eq!(
            (
                follower.action,
                follower.source_byte_3e,
                follower_link,
                follower.roll,
                follower.actual_speed,
            ),
            (
                level2_class5::dragon::DRAGON_LINK_ACTION,
                61,
                peer_slot,
                expected_roll,
                peer_before
                    .maximum_speed
                    .wrapping_add(peer_before.actual_speed),
            )
        );

        {
            let mut economy = campaign.simulation_mut().economy_mut();
            let follower = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == follower_slot)
                .expect("mutable linked follower");
            follower.action = level2_class5::dragon::DRAGON_LINK_ACTION;
            follower.source_byte_3e = 90;
            let peer = economy
                .authored_class5
                .iter_mut()
                .find(|source| source.source_entity_index == peer_slot)
                .expect("mutable attacking peer");
            peer.action = level2_class5::dragon::DRAGON_ATTACK_ACTION;
            peer.word_0x96_150 = player_entity_index;
            peer.source_byte_3e = 1;
            economy
                .authored_dragons
                .iter_mut()
                .find(|state| state.source_entity_index == follower_slot)
                .expect("follower Dragon sidecar")
                .linked_entity_index = peer_slot;
        }
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        let follower = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == follower_slot)
            .expect("attack-inheriting follower remains live");
        let follower_link = live
            .economy
            .economy
            .authored_dragons()
            .iter()
            .find(|state| state.source_entity_index == follower_slot)
            .expect("attack-inheriting follower sidecar")
            .linked_entity_index;
        assert_eq!(
            (
                follower.action,
                follower.word_0x96_150,
                follower.source_byte_3e,
                follower_link,
            ),
            (
                level2_class5::dragon::DRAGON_ATTACK_ACTION,
                player_entity_index,
                91,
                0,
            )
        );
    }

    #[test]
    fn cf14_level3_skeleton_and_dragon_deaths_unlock_goats_and_terrain_close() {
        use crate::game_session::ActorLifecycle;

        const SKELETON_SLOT: u16 = 93;
        const FIREBALL_DAMAGE: u16 = 500;

        fn skeleton(campaign: &CampaignSession) -> &EntitySnapshot {
            &campaign.simulation().session.state.live.economy.entities[usize::from(SKELETON_SLOT)]
        }

        fn apply_hit(campaign: &mut CampaignSession, owner_entity_index: u16) {
            let position = skeleton(campaign).position;
            campaign
                .simulation_mut()
                .apply_level2_class10_model0_damage(
                    level2_dynamic_economy::Level2Class10Model0Step {
                        live: true,
                        first_impact: true,
                        damage_pulse: true,
                        owner_entity_index,
                        payload: FIREBALL_DAMAGE,
                        position,
                    },
                );
            assert_eq!(
                skeleton(campaign).source_upkeep_word_62(),
                owner_entity_index
            );
            assert_eq!(skeleton(campaign).source_upkeep_payload(), 500);
        }

        #[track_caller]
        fn step(campaign: &mut CampaignSession) {
            let _ = campaign.step(PlayerCommand::default(), 0);
            assert!(
                campaign
                    .simulation()
                    .dispatch_events()
                    .iter()
                    .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. })),
                "Skeleton lifecycle dispatch errors: {:?}",
                campaign.simulation().dispatch_events()
            );
        }

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let baseline_hash = campaign.state_hash();
        let skeleton_handle = campaign
            .simulation()
            .source_arena()
            .handle(SKELETON_SLOT)
            .unwrap();
        let skeleton_page = |campaign: &CampaignSession| {
            campaign
                .simulation()
                .creature_page_sources()
                .find(|entry| entry.identity.handle == skeleton_handle)
        };
        let initial_skeleton = skeleton_page(&campaign).unwrap();
        assert_eq!(initial_skeleton.identity.kind, CreatureKind::Skeleton);
        assert_eq!(
            initial_skeleton.health,
            Some((1_000, skeleton(&campaign).max_life))
        );
        assert_eq!(initial_skeleton.lifecycle, ActorLifecycle::Alive);
        let player_entity_index = campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;
        assert_eq!(
            (skeleton(&campaign).class, skeleton(&campaign).model),
            (5, 9)
        );
        assert_eq!(skeleton(&campaign).life, 1_000);
        assert_eq!(skeleton(&campaign).mana, 500);

        for _ in 0..24 {
            if skeleton(&campaign).action == 79 {
                break;
            }
            step(&mut campaign);
        }
        assert_eq!(
            skeleton(&campaign).action,
            79,
            "the real Level 3 countdown reaches its source movement callback"
        );

        let first_phase = skeleton(&campaign).phase;
        let sphere_count = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .spheres()
            .len();
        let burst_count = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .events()
            .iter()
            .filter(|event| matches!(event, Level2EconomyEvent::DeathBurstSpawned {
                parent_entity_index: SKELETON_SLOT, ..
            }))
            .count();
        assert_eq!(burst_count, 0);
        apply_hit(&mut campaign, player_entity_index);
        step(&mut campaign);
        let first_hit = skeleton(&campaign);
        assert_eq!(first_hit.life, 500);
        assert_eq!(first_hit.action, 74);
        assert_eq!(first_hit.word_26(), player_entity_index);
        assert_eq!(first_hit.particle_parameter_index, Some(202));
        assert_eq!(first_hit.phase, first_phase.wrapping_add(1));
        assert_eq!(first_hit.source_upkeep_word_62(), 0);
        assert!(!first_hit.drawing_disabled());
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .spheres()
                .len(),
            sphere_count,
            "a nonlethal hit must not create death outputs"
        );
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .events()
                .iter()
                .filter(|event| matches!(event, Level2EconomyEvent::DeathBurstSpawned {
                    parent_entity_index: SKELETON_SLOT, ..
                }))
                .count(),
            burst_count
        );

        let descriptor = &campaign.simulation().session.definition.presentation.entity_parameters
            [usize::from(MC2_SKELETON_ASSETS.descriptor)];
        let scan_period = u16::from_le_bytes([descriptor[26], descriptor[27]]);
        let attack_range = u16::from_le_bytes([descriptor[28], descriptor[29]]);
        assert_eq!(scan_period, 25);
        let mut abandoned_out_of_range_target = false;
        for _ in 0..25 {
            let phase_before = skeleton(&campaign).phase;
            assert_eq!(skeleton(&campaign).source_word_96(), player_entity_index);
            step(&mut campaign);
            assert_eq!(skeleton(&campaign).life, 500);
            if u16::from(phase_before) % scan_period == 0 {
                let target = &campaign.simulation().session.state.live.economy.entities
                    [usize::from(player_entity_index)];
                assert!(target.active && target.life >= 0 && target.control_flags & 0x400 == 0);
                assert!(
                    crate::distance_3d_wrapped(skeleton(&campaign).position, target.position)
                        >= u32::from(attack_range),
                    "the current player target is outside the source attack range"
                );
                assert_eq!(skeleton(&campaign).action, 73);
                abandoned_out_of_range_target = true;
                break;
            }
            assert_eq!(skeleton(&campaign).action, 74);
        }
        assert!(
            abandoned_out_of_range_target,
            "action 74 reaches the descriptor's attack-range check and returns to action 73"
        );

        apply_hit(&mut campaign, player_entity_index);
        let second_phase = skeleton(&campaign).phase;
        step(&mut campaign);
        assert_eq!(
            (
                skeleton(&campaign).life,
                skeleton(&campaign).action,
                skeleton(&campaign).source_upkeep_word_62(),
                skeleton(&campaign).source_upkeep_payload(),
                skeleton(&campaign).phase,
            ),
            (0, 74, 0, 500, second_phase.wrapping_add(1))
        );
        assert!(!skeleton(&campaign).drawing_disabled());

        apply_hit(&mut campaign, player_entity_index);
        let lethal_phase = skeleton(&campaign).phase;
        step(&mut campaign);
        assert_eq!(skeleton(&campaign).life, -500);
        let dying_skeleton = skeleton_page(&campaign).unwrap();
        assert_eq!(
            dying_skeleton.health,
            Some((-500, skeleton(&campaign).max_life))
        );
        assert_eq!(dying_skeleton.lifecycle, ActorLifecycle::Dying);
        assert_eq!(skeleton(&campaign).action, 76);
        assert_eq!(skeleton(&campaign).word_24(), player_entity_index);
        assert_eq!(skeleton(&campaign).word_26(), player_entity_index);
        assert_eq!(skeleton(&campaign).phase, lethal_phase.wrapping_add(1));
        assert!(!skeleton(&campaign).drawing_disabled());

        let pre_kill_phase = skeleton(&campaign).phase;
        step(&mut campaign);
        assert_eq!(skeleton(&campaign).action, 77);
        assert_eq!(skeleton(&campaign).phase, pre_kill_phase.wrapping_add(1));

        let source_rng_before_kill = skeleton(&campaign).entity_rng;
        let mut kill_phase = None;
        for _ in 0..8 {
            let phase_before = skeleton(&campaign).phase;
            step(&mut campaign);
            if skeleton(&campaign).drawing_disabled() {
                kill_phase = Some(phase_before);
                break;
            }
            assert_eq!(skeleton(&campaign).action, 77);
            assert_eq!(skeleton(&campaign).phase, phase_before.wrapping_add(1));
            assert_eq!(
                campaign
                    .simulation()
                    .session
                    .state
                    .live
                    .economy
                    .economy
                    .spheres()
                    .len(),
                sphere_count
            );
        }
        let kill_phase = kill_phase.expect("action 77 reaches its eight-phase kill cadence");
        assert_eq!(kill_phase & 7, 0);
        let hidden = skeleton(&campaign);
        assert_eq!(
            skeleton_page(&campaign).unwrap().lifecycle,
            ActorLifecycle::Hidden
        );
        assert!(
            hidden.active,
            "hide is retained for the rest of the source pass"
        );
        assert_eq!(hidden.action, 77);
        assert_eq!(hidden.phase, kill_phase.wrapping_add(1));
        assert_eq!(
            hidden.entity_rng,
            campaign_shared_families::next_source_rng16(source_rng_before_kill)
        );
        assert_eq!(hidden.source_player_entity_index(), 0);

        let economy = &campaign.simulation().session.state.live.economy.economy;
        assert_eq!(economy.spheres().len(), sphere_count + 1);
        let sphere = economy.spheres().last().expect("Skeleton mana sphere");
        assert_eq!(sphere.mana, 500);
        assert_eq!(sphere.owner_entity_index, 0);
        let bursts = economy.events().iter().filter_map(|event| match event {
            Level2EconomyEvent::DeathBurstSpawned {
                source_entity_index, parent_entity_index, id_entity_index,
            } if *parent_entity_index == SKELETON_SLOT => Some((*source_entity_index, *id_entity_index)),
            _ => None,
        }).collect::<Vec<_>>();
        assert_eq!(bursts.len(), burst_count + 1);
        let (burst_slot, burst_id) = bursts[0];
        assert_eq!(burst_id, SKELETON_SLOT);
        let burst = &campaign.simulation().session.state.live.economy.entities[usize::from(burst_slot)];
        assert_eq!((burst.class, burst.model), (10, 1), "the receipt names the real source burst");

        step(&mut campaign);
        let reclaimed = skeleton(&campaign);
        assert!(skeleton_page(&campaign).is_none());
        assert!(!reclaimed.active);
        assert_eq!(reclaimed.class, 0);
        assert!(
            !campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .map_chains()
                .linked_entity_indices()
                .contains(&SKELETON_SLOT)
        );

        campaign.reset();
        assert_eq!(campaign.state_hash(), baseline_hash);
        assert_eq!(
            (skeleton(&campaign).class, skeleton(&campaign).model),
            (5, 9)
        );
        assert_eq!(skeleton(&campaign).life, 1_000);
        assert_eq!(skeleton(&campaign).action, 72);

        // The preceding production route proves one complete Skeleton death.
        // Stage the same retained hide boundary for all eleven package rows so
        // this continuation proves only the downstream frozen-census objective
        // chronology, not eleven copies of combat.
        let skeleton_slots = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .entities
            .iter()
            .filter(|entity| entity.active && entity.class == 5 && entity.model == 9)
            .map(|entity| entity.index)
            .collect::<Vec<_>>();
        assert_eq!(skeleton_slots.len(), 11);
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .core
                .runtime
                .objectives[0]
                .stage_selectors[0],
            1
        );
        for source_slot in &skeleton_slots {
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .entities[usize::from(*source_slot)]
            .disable_drawing();
        }
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert!(skeleton_slots.iter().all(|source_slot| {
            let entity = &live.economy.entities[usize::from(*source_slot)];
            !entity.active && entity.class == 0
        }));
        assert_eq!(live.core.runtime.objectives[0].stage_selectors[0], 2);
        assert_eq!(live.core.runtime.objectives[0].text_selector, 1);
        assert!(
            !live.authored_features_consumed.contains(&141)
                && !live.authored_features_consumed.contains(&142),
            "post-pass objective completion cannot activate the next group in the completed entity pass"
        );
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 1, .. }
                ))
        );

        // On the following ordinary source pass, the real imported
        // objective gate at slot 127 sees stage zero complete and activates
        // package group 1. That group contains exactly the two authored
        // Dragon rows 141/142; no level-specific spawn list is involved.
        const DRAGON_GATE_SLOT: u16 = 127;
        let global_rng_before_dragons = campaign.simulation().source_global_rng();
        let gate_phase_before = campaign.simulation().session.state.live.economy.entities
            [usize::from(DRAGON_GATE_SLOT)]
        .phase;
        step(&mut campaign);
        let dragon_events = campaign.simulation().dispatch_events();
        assert!(dragon_events.iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: DRAGON_GATE_SLOT,
                group: 1,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [141, 142]
        )));
        let live = &campaign.simulation().session.state.live;
        assert_eq!(live.core.runtime.objectives[0].stage_selectors[1], 1);
        let gate = &live.economy.entities[usize::from(DRAGON_GATE_SLOT)];
        assert!(gate.drawing_disabled());
        assert!(
            gate.active,
            "the Dragon gate hide is retained through its epilogue"
        );
        assert_eq!(gate.phase, gate_phase_before.wrapping_add(1));

        let mut dragons = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .filter(|source| source.model == level2_class5::dragon::DRAGON_MODEL)
            .copied()
            .collect::<Vec<_>>();
        dragons.sort_unstable_by_key(|source| source.authored_index);
        assert_eq!(
            dragons
                .iter()
                .map(|source| source.authored_index)
                .collect::<Vec<_>>(),
            [141, 142]
        );
        assert_eq!(live.economy.economy.authored_dragons().len(), 2);
        assert_eq!(live.economy.economy.authored_dragon_parts().len(), 32);
        let global_rng_at_new_event = global_rng_before_dragons
            .wrapping_mul(9_377)
            .wrapping_add(9_439);
        let next_rng = |rng: u16| rng.wrapping_mul(9_377).wrapping_add(9_439);
        let authored_positions = [
            Position {
                x: (79_u16 << 8).wrapping_add(128),
                y: (143_u16 << 8).wrapping_add(128),
                z: 0,
            },
            Position {
                x: (141_u16 << 8).wrapping_add(128),
                y: (144_u16 << 8).wrapping_add(128),
                z: 0,
            },
        ];
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        let mut same_pass_roots = 0;
        for (dragon_index, dragon) in dragons.iter().enumerate() {
            let root_handle = live.economy.handle(dragon.source_entity_index).unwrap();
            let root_page = campaign
                .simulation()
                .creature_page_sources()
                .find(|entry| entry.identity.handle == root_handle)
                .unwrap();
            assert_eq!(root_page.identity.kind, CreatureKind::Dragon);
            assert_eq!(root_page.health, Some((dragon.life, dragon.max_life)));
            assert_eq!(root_page.parent, None);
            let constructor_phase = u8::try_from(dragon_index).expect("two Dragons");
            let initial_rng = next_rng(
                dragon
                    .source_entity_index
                    .wrapping_add(global_rng_at_new_event as u16),
            );
            let was_visited = dragon.source_entity_index > DRAGON_GATE_SLOT;
            same_pass_roots += usize::from(was_visited);
            assert_eq!(
                (
                    dragon.action,
                    dragon.minimum_speed,
                    dragon.maximum_speed,
                    dragon.actual_speed,
                    dragon.max_life,
                    dragon.life,
                    dragon.max_mana,
                    dragon.mana,
                    dragon.subspell_index,
                    dragon.particle_index,
                    dragon.source_byte_39,
                ),
                (
                    level2_class5::dragon::DRAGON_ROAM_ACTION,
                    80,
                    16,
                    30,
                    4_000,
                    4_000,
                    4_500,
                    level2_class5::dragon::DRAGON_SEGMENT_MANA,
                    level2_class5::dragon::DRAGON_SUBSPELL_INDEX,
                    40,
                    30_u8.wrapping_sub(constructor_phase % 30).wrapping_add(4),
                )
            );
            assert_eq!(
                dragon.source_byte_3e,
                constructor_phase.wrapping_add(u8::from(was_visited))
            );
            assert_eq!(
                dragon.entity_rng,
                if was_visited && constructor_phase == 0 {
                    next_rng(next_rng(initial_rng))
                } else {
                    initial_rng
                },
                "only the phase-zero Dragon consumes the two action-1 wander draws"
            );
            let mut authored_position = authored_positions[dragon_index];
            authored_position.z = live.terrain.ground_height(authored_position);
            if was_visited {
                let heading = i16::try_from(initial_rng & 0x07ff)
                    .expect("Dragon heading")
                    .wrapping_sub(1);
                let transition = crate::ground_creature_motion::step_ground_creature_motion(
                    authored_position,
                    heading,
                    heading,
                    30,
                    &live.terrain,
                    crate::ground_creature_motion::GroundCreatureMotionConfig {
                        ground_clearance: 0,
                        descent: -4,
                        turn_limit: 34,
                        terrain_mask: u32::MAX,
                        maximum_tile_slope: 30,
                        half_width: dragon.shift_rot_x,
                        half_height: dragon.shift_rot_y,
                    },
                );
                let mut expected_position = transition.position;
                expected_position.z = expected_position
                    .z
                    .wrapping_add((dragon.source_entity_index % 100) as i16);
                assert_eq!(dragon.position, expected_position);
                assert_eq!(dragon.yaw, transition.yaw);
                assert_eq!(dragon.dword_0x10, 150);
            } else {
                assert_eq!(dragon.position, authored_position);
                assert_eq!(
                    dragon.dword_0x10,
                    i32::from(dragon.source_entity_index % 100)
                );
            }
            assert_eq!(
                receipts.iter().any(|receipt| matches!(
                    receipt,
                    ScheduleReceipt::CallbackCompleted { slot, .. }
                        if *slot == dragon.source_entity_index
                )),
                was_visited
            );
            assert_eq!(
                receipts.iter().any(|receipt| matches!(
                    receipt,
                    ScheduleReceipt::EpilogueCompleted { slot, .. }
                        if *slot == dragon.source_entity_index
                )),
                was_visited
            );

            let runtime = live
                .economy
                .economy
                .authored_class5_runtime()
                .iter()
                .find(|runtime| runtime.source_entity_index == dragon.source_entity_index)
                .expect("Dragon class-5 runtime");
            let sidecar = live
                .economy
                .economy
                .authored_dragons()
                .iter()
                .find(|state| state.source_entity_index == dragon.source_entity_index)
                .expect("Dragon runtime");
            assert_eq!(
                (
                    runtime.byte_0x38,
                    runtime.xtype,
                    runtime.descriptor_index,
                    runtime.pending_damage,
                    sidecar.word_0x36,
                    sidecar.control_flags,
                    sidecar.font_type_index,
                    sidecar.render_yaw,
                    sidecar.render_pitch,
                    sidecar.render_roll,
                    sidecar.render_fov,
                ),
                (1, 3, 71, 0, 96, 8, 0, 140, 171, 171, 140)
            );
            let mut part_slot = runtime.linked_head;
            let mut previous_position = dragon.position;
            for part_index in 0..level2_class5::dragon::DRAGON_PART_COUNT {
                let part = live
                    .economy
                    .economy
                    .authored_dragon_parts()
                    .iter()
                    .find(|part| part.source_entity_index == part_slot)
                    .expect("Dragon body chain remains complete");
                assert_eq!(part.parent_entity_index, 0);
                assert_eq!(part.entity_id, dragon.source_entity_index);
                let part_handle = live.economy.handle(part_slot).unwrap();
                let part_page = campaign
                    .simulation()
                    .creature_page_sources()
                    .find(|entry| entry.identity.handle == part_handle)
                    .unwrap();
                assert_eq!(part_page.parent, Some(root_handle));
                assert_eq!(part_page.health, None);
                assert_eq!(part.particle_index, 19 + part_index as u16);
                assert_eq!(
                    (
                        part.model,
                        part.action,
                        part.max_life,
                        part.life,
                        part.mana,
                        part.subspell_index,
                    ),
                    (
                        0,
                        232,
                        4_000,
                        4_000,
                        if part_index == 0 {
                            level2_class5::dragon::DRAGON_INITIAL_MANA
                        } else {
                            level2_class5::dragon::DRAGON_SEGMENT_MANA
                        },
                        level2_class5::dragon::DRAGON_SUBSPELL_INDEX,
                    )
                );
                assert_eq!(
                    (
                        part.source_byte_39,
                        part.pending_word_0x62,
                        part.pending_damage,
                        part.word_0x26,
                    ),
                    (dragon.source_byte_39, 0, 0, 0),
                    "NewEvent's raw Dragon copy starts with an empty segment mailbox"
                );
                assert_eq!(
                    part.source_byte_3e,
                    u8::try_from(part_index)
                        .expect("Dragon part index")
                        .wrapping_add(u8::from(part.source_entity_index > DRAGON_GATE_SLOT))
                );
                if part.source_entity_index > DRAGON_GATE_SLOT {
                    let (expected_yaw, expected_pitch) =
                        crate::level1_mission::projectile_guidance_angles(
                            authored_position,
                            previous_position,
                        );
                    let mut expected_position = previous_position;
                    crate::move_entity(
                        &mut expected_position,
                        expected_yaw,
                        expected_pitch,
                        part.word_0x36.wrapping_neg(),
                    );
                    assert_eq!(
                        (part.position, part.yaw, part.pitch),
                        (expected_position, expected_yaw, expected_pitch),
                        "an ahead-of-cursor action-232 row follows its predecessor in the birth pass"
                    );
                } else {
                    assert_eq!(part.position, authored_position);
                }
                assert_eq!(
                    receipts.iter().any(|receipt| matches!(
                        receipt,
                        ScheduleReceipt::CallbackCompleted { slot, .. }
                            if *slot == part.source_entity_index
                    )),
                    part.source_entity_index > DRAGON_GATE_SLOT
                );
                previous_position = part.position;
                part_slot = part.next_entity_index;
            }
            assert_eq!(part_slot, 0);
        }
        assert!(
            same_pass_roots > 0,
            "the real allocator must leave at least one Dragon ahead of slot 127 so action 1 runs in the birth pass"
        );

        // The following ordinary pass reclaims the hidden objective gate and
        // visits every lower-slot Dragon/part that the fixed ascending cursor
        // could not reach in the birth pass.
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert!(!live.economy.entities[usize::from(DRAGON_GATE_SLOT)].active);
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        for source_slot in live
            .economy
            .economy
            .authored_class5()
            .iter()
            .filter(|source| source.model == level2_class5::dragon::DRAGON_MODEL)
            .map(|source| source.source_entity_index)
            .chain(
                live.economy
                    .economy
                    .authored_dragon_parts()
                    .iter()
                    .map(|part| part.source_entity_index),
            )
        {
            assert!(receipts.iter().any(|receipt| matches!(
                receipt,
                ScheduleReceipt::CallbackCompleted { slot, .. } if *slot == source_slot
            )));
            assert!(receipts.iter().any(|receipt| matches!(
                receipt,
                ScheduleReceipt::EpilogueCompleted { slot, .. } if *slot == source_slot
            )));
        }

        // Drive one real body row through the shared class-10 damage adapter.
        // The root is numerically earlier, so it cannot observe the segment's
        // lower life until the following UpdateEntities pass.
        let damaged_dragon_slot = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| {
                source.model == level2_class5::dragon::DRAGON_MODEL
                    && source.action == level2_class5::dragon::DRAGON_ROAM_ACTION
            })
            .expect("a real Dragon is available for body damage")
            .source_entity_index;
        let mut damaged_part_slot = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5_runtime()
            .iter()
            .find(|runtime| runtime.source_entity_index == damaged_dragon_slot)
            .expect("damaged Dragon runtime")
            .linked_head;
        for _ in 0..8 {
            damaged_part_slot = campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_dragon_parts()
                .iter()
                .find(|part| part.source_entity_index == damaged_part_slot)
                .expect("middle Dragon segment predecessor")
                .next_entity_index;
        }
        assert_ne!(damaged_part_slot, 0, "the Dragon has sixteen body rows");
        assert!(
            damaged_dragon_slot < damaged_part_slot,
            "the constructor's first body row follows its earlier root in the numeric arena"
        );
        let mut isolated_part_position = Position {
            x: 8_u16 << 8,
            y: 8_u16 << 8,
            z: 0,
        };
        isolated_part_position.z = campaign
            .simulation()
            .session
            .state
            .live
            .terrain
            .ground_height(isolated_part_position);
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_part_position_for_test(
                    damaged_part_slot,
                    isolated_part_position,
                )
        );
        let damaged_root_position = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("damaged Dragon root")
            .position;
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_attack_prerequisite_for_test(
                    damaged_dragon_slot,
                    damaged_root_position,
                    1,
                )
        );
        let death_spheres_before_damage = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .spheres()
            .len();
        let death_bursts_before_damage = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .death_bursts()
            .len();
        campaign
            .simulation_mut()
            .apply_level2_class10_model0_damage(level2_dynamic_economy::Level2Class10Model0Step {
                live: true,
                first_impact: true,
                damage_pulse: true,
                owner_entity_index: player_entity_index,
                payload: FIREBALL_DAMAGE,
                position: isolated_part_position,
            });
        let queued_part = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_dragon_parts()
            .iter()
            .find(|part| part.source_entity_index == damaged_part_slot)
            .expect("the isolated body row receives the impact mailbox");
        assert_eq!(
            (
                queued_part.life,
                queued_part.pending_word_0x62,
                queued_part.pending_damage,
                queued_part.word_0x26,
            ),
            (4_000, player_entity_index, 500, 0)
        );
        let queued_root = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("the earlier root does not receive the isolated impact");
        assert_eq!(
            (queued_root.life, queued_root.pending_word_0x62),
            (4_000, 0)
        );

        let root_phase_before_part_hit = queued_root.source_byte_3e;
        let part_phase_before_hit = queued_part.source_byte_3e;
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let root_after_part_hit = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("Dragon root remains live before child propagation");
        let part_after_hit = live
            .economy
            .economy
            .authored_dragon_parts()
            .iter()
            .find(|part| part.source_entity_index == damaged_part_slot)
            .expect("damaged body row remains live");
        assert_eq!(
            (
                root_after_part_hit.life,
                root_after_part_hit.action,
                root_after_part_hit.source_byte_3e,
                part_after_hit.life,
                part_after_hit.pending_word_0x62,
                part_after_hit.pending_damage,
                part_after_hit.word_0x26,
                part_after_hit.source_byte_3e,
            ),
            (
                4_000,
                level2_class5::dragon::DRAGON_ROAM_ACTION,
                root_phase_before_part_hit.wrapping_add(1),
                3_500,
                0,
                0,
                player_entity_index,
                part_phase_before_hit.wrapping_add(1),
            ),
            "the earlier root visits before the later body row consumes its mailbox"
        );

        let root_phase_before_propagation = root_after_part_hit.source_byte_3e;
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let propagated_root = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("damaged Dragon root remains live");
        assert_eq!(
            (
                propagated_root.life,
                propagated_root.action,
                propagated_root.word_0x26,
                propagated_root.word_0x96_150,
                propagated_root.source_byte_3e,
            ),
            (
                3_500,
                level2_class5::dragon::DRAGON_ATTACK_ACTION,
                player_entity_index,
                player_entity_index,
                root_phase_before_propagation.wrapping_add(1),
            ),
            "the following root visit copies the first lower-life segment and attacker"
        );
        assert_eq!(
            (
                live.economy.economy.spheres().len(),
                live.economy.economy.death_bursts().len(),
            ),
            (death_spheres_before_damage, death_bursts_before_damage),
            "a nonlethal body hit has no Dragon death outputs"
        );

        // Continue that same real Dragon through its lethal body hit. The
        // impact mailbox remains private to the segment until its later
        // numeric visit; the earlier root observes the lower child life on
        // the following pass, then PreKill changes the entire linked body to
        // action 5 before any later body slot is visited.
        let mut damaged_body_slots = Vec::new();
        let mut body_slot = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5_runtime()
            .iter()
            .find(|runtime| runtime.source_entity_index == damaged_dragon_slot)
            .expect("lethal Dragon runtime")
            .linked_head;
        while body_slot != 0 {
            damaged_body_slots.push(body_slot);
            body_slot = campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_dragon_parts()
                .iter()
                .find(|part| part.source_entity_index == body_slot)
                .expect("lethal Dragon body chain")
                .next_entity_index;
        }
        assert_eq!(
            damaged_body_slots.len(),
            level2_class5::dragon::DRAGON_PART_COUNT
        );
        let kill_census_before = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_bee_kill_census(player_entity_index);
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_part_position_for_test(
                    damaged_part_slot,
                    isolated_part_position,
                )
        );
        let lethal_part_position = isolated_part_position;
        campaign
            .simulation_mut()
            .apply_level2_class10_model0_damage(level2_dynamic_economy::Level2Class10Model0Step {
                live: true,
                first_impact: true,
                damage_pulse: true,
                owner_entity_index: player_entity_index,
                payload: u16::try_from(level2_class5::dragon::DRAGON_LIFE)
                    .expect("Dragon life fits the source payload"),
                position: lethal_part_position,
            });
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let root_before_lethal_propagation = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("Dragon root precedes the lethal segment");
        let lethal_part = live
            .economy
            .economy
            .authored_dragon_parts()
            .iter()
            .find(|part| part.source_entity_index == damaged_part_slot)
            .expect("lethal segment remains allocated");
        assert_eq!(
            (
                root_before_lethal_propagation.life,
                root_before_lethal_propagation.action,
                lethal_part.life,
                lethal_part.word_0x26,
            ),
            (
                3_500,
                level2_class5::dragon::DRAGON_ATTACK_ACTION,
                -500,
                player_entity_index,
            ),
            "the root cannot consume a later segment's lethal mailbox in the same pass"
        );

        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let pre_kill_root = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("lethal Dragon reaches PreKill");
        assert_eq!(
            (
                pre_kill_root.life,
                pre_kill_root.action,
                pre_kill_root.word_0x24,
            ),
            (
                -500,
                level2_class5::dragon::DRAGON_PRE_KILL_ACTION,
                player_entity_index,
            )
        );
        let immediate_body_death = live
            .economy
            .economy
            .authored_dragon_parts()
            .iter()
            .find(|part| part.entity_id == damaged_dragon_slot && part.source_byte_3e & 7 == 0)
            .copied()
            .expect("the sixteen Dragon phases include an immediate action-5 cadence");
        let immediate_body_handle = live.economy.handle(immediate_body_death.source_entity_index)
            .expect("the real body generation is live before its kill visit");
        let dying_root_handle = live.economy.handle(damaged_dragon_slot)
            .expect("the real Dragon root generation is live before pre-kill");
        let root_phase_before_pre_kill = pre_kill_root.source_byte_3e;
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let dying_root = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("Dragon root remains allocated through the PreKill epilogue");
        let immediate_body_after = live
            .economy
            .economy
            .authored_dragon_parts()
            .iter()
            .find(|part| part.source_entity_index == immediate_body_death.source_entity_index)
            .expect("hidden body row remains allocated through its kill epilogue");
        assert_eq!(
            (
                dying_root.action,
                dying_root.active,
                dying_root.source_byte_3e,
                immediate_body_after.action,
                immediate_body_after.active,
                immediate_body_after.drawing_enabled,
                immediate_body_after.source_byte_3e,
            ),
            (
                level2_class5::dragon::DRAGON_KILL_ACTION,
                true,
                root_phase_before_pre_kill.wrapping_add(1),
                level2_class5::dragon::DRAGON_KILL_ACTION,
                true,
                false,
                immediate_body_death.source_byte_3e.wrapping_add(1),
            ),
            "PreKill changes the linked body before its later numeric action-5 visit"
        );
        assert!(live.economy.resolve(immediate_body_handle).is_some(),
            "the hidden body stays allocated through its same-pass epilogue");
        let hidden_body_page = campaign.simulation().creature_page_sources()
            .find(|entry| entry.identity.handle == immediate_body_handle).unwrap();
        assert_eq!(hidden_body_page.lifecycle, ActorLifecycle::Hidden);
        assert_eq!(hidden_body_page.parent, Some(dying_root_handle));
        assert_eq!(hidden_body_page.health, None);
        assert_eq!(
            live.economy
                .economy
                .authored_bee_kill_census(player_entity_index),
            kill_census_before.wrapping_add(1),
            "only the Dragon root's PreKill callback credits the real player"
        );
        assert!(live.economy.economy.events().iter().any(|event| matches!(
            event,
            Level2EconomyEvent::ManaSphereSpawned {
                source_entity_index,
                mana,
                ..
            } if *source_entity_index == immediate_body_death.source_entity_index
                && *mana == immediate_body_death.mana
        )));
        assert!(live.economy.economy.events().iter().any(|event| matches!(
            event,
            Level2EconomyEvent::DeathBurstSpawned {
                parent_entity_index,
                id_entity_index,
                ..
            } if *parent_entity_index == immediate_body_death.source_entity_index
                && *id_entity_index == damaged_dragon_slot
        )));

        let root_phase_at_kill_wait = dying_root.source_byte_3e;
        let callbacks_before_root_kill =
            usize::from(8_u8.wrapping_sub(root_phase_at_kill_wait & 7) & 7);
        for _ in 0..callbacks_before_root_kill {
            step(&mut campaign);
            let root = campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_class5()
                .iter()
                .find(|source| source.source_entity_index == damaged_dragon_slot)
                .expect("Dragon waits live for its action-5 cadence");
            assert!(root.active && root.action == level2_class5::dragon::DRAGON_KILL_ACTION);
        }
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let hidden_root = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == damaged_dragon_slot)
            .expect("hidden Dragon root remains allocated through its kill epilogue");
        assert!(hidden_root.active && !hidden_root.drawing_enabled);
        assert!(live.economy.resolve(dying_root_handle).is_some(),
            "the hidden root stays allocated through its same-pass epilogue");
        assert!(live.economy.resolve(immediate_body_handle).is_none(),
            "the previous hidden body generation is reclaimed at the next boundary");
        assert!(campaign.simulation().creature_page_sources()
            .all(|entry| entry.identity.handle != immediate_body_handle));
        let hidden_root_page = campaign.simulation().creature_page_sources()
            .find(|entry| entry.identity.handle == dying_root_handle).unwrap();
        assert_eq!(hidden_root_page.lifecycle, ActorLifecycle::Hidden);
        assert!(live.economy.economy.events().iter().any(|event| matches!(
            event,
            Level2EconomyEvent::ManaSphereSpawned {
                source_entity_index,
                mana,
                ..
            } if *source_entity_index == damaged_dragon_slot
                && *mana == level2_class5::dragon::DRAGON_SEGMENT_MANA
        )));
        assert!(live.economy.economy.events().iter().any(|event| matches!(
            event,
            Level2EconomyEvent::DeathBurstSpawned {
                parent_entity_index,
                id_entity_index,
                ..
            } if *parent_entity_index == damaged_dragon_slot
                && *id_entity_index == damaged_dragon_slot
        )));

        // Every body row owns an independent action-5 cadence. Within eight
        // further ordinary visits all sixteen rows have converted their own
        // mana and the following prologues reclaim the hidden root/body slots.
        for _ in 0..9 {
            let live = &campaign.simulation().session.state.live;
            let root_present = live
                .economy
                .economy
                .authored_class5()
                .iter()
                .any(|source| source.source_entity_index == damaged_dragon_slot);
            let body_present = live
                .economy
                .economy
                .authored_dragon_parts()
                .iter()
                .any(|part| part.entity_id == damaged_dragon_slot);
            if !root_present && !body_present {
                break;
            }
            step(&mut campaign);
        }
        let live = &campaign.simulation().session.state.live;
        assert!(live.economy.resolve(dying_root_handle).is_none(),
            "the hidden root generation is reclaimed at a following boundary");
        assert!(campaign.simulation().creature_page_sources().all(|entry| {
            entry.identity.handle != dying_root_handle && entry.parent != Some(dying_root_handle)
        }));
        assert!(
            live.economy
                .economy
                .authored_class5()
                .iter()
                .all(|source| source.source_entity_index != damaged_dragon_slot)
        );
        assert!(
            live.economy
                .economy
                .authored_dragon_parts()
                .iter()
                .all(|part| part.entity_id != damaged_dragon_slot)
        );
        let mut expected_death_sources = damaged_body_slots;
        expected_death_sources.push(damaged_dragon_slot);
        for source_slot in expected_death_sources {
            assert_eq!(
                live.economy
                    .economy
                    .events()
                    .iter()
                    .filter(|event| matches!(
                        event,
                        Level2EconomyEvent::ManaSphereSpawned {
                            source_entity_index,
                            ..
                        } if *source_entity_index == source_slot
                    ))
                    .count(),
                1,
                "each Dragon root/body row converts its own mana exactly once"
            );
            assert_eq!(
                live.economy
                    .economy
                    .events()
                    .iter()
                    .filter(|event| matches!(
                        event,
                        Level2EconomyEvent::DeathBurstSpawned {
                            parent_entity_index,
                            ..
                        } if *parent_entity_index == source_slot
                    ))
                    .count(),
                1,
                "each Dragon root/body row creates one death burst"
            );
        }

        // Continue one of those real package Dragons through its next
        // package-reached callbacks. Geometry and cadence are staged only to
        // avoid turning this focused behavior proof into a long flight route;
        // target selection, dispatch, NewEvent allocation, feedback, audio,
        // and the projectile scheduler remain the ordinary production path.
        let dragon_slot = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| {
                source.model == level2_class5::dragon::DRAGON_MODEL
                    && source.action == level2_class5::dragon::DRAGON_ROAM_ACTION
            })
            .expect("a real group-1 Dragon remains in ordinary roam")
            .source_entity_index;
        let dragon_before_target = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == dragon_slot)
            .copied()
            .expect("selected Dragon root");
        let terrain = &campaign.simulation().session.state.live.terrain;
        let target_transition = crate::ground_creature_motion::step_ground_creature_motion(
            dragon_before_target.position,
            dragon_before_target.yaw,
            dragon_before_target.roll,
            dragon_before_target.actual_speed,
            terrain,
            crate::ground_creature_motion::GroundCreatureMotionConfig {
                ground_clearance: 0,
                descent: -4,
                turn_limit: 34,
                terrain_mask: u32::MAX,
                maximum_tile_slope: 30,
                half_width: dragon_before_target.shift_rot_x,
                half_height: dragon_before_target.shift_rot_y,
            },
        );
        let mut target_position = target_transition.position;
        crate::move_entity(&mut target_position, target_transition.yaw, 0, 512);
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_attack_prerequisite_for_test(
                    dragon_slot,
                    dragon_before_target.position,
                    30,
                )
        );
        campaign
            .simulation_mut()
            .set_level2_entity_position(player_entity_index, target_position)
            .expect("stage the real player in the real Dragon view cone");
        let projectile_count_before = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .fireball_projectiles()
            .len();
        let journal_before_target = campaign.simulation().effect_journal().records().len();
        step(&mut campaign);
        let targeted = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == dragon_slot)
            .copied()
            .expect("targeting Dragon remains live");
        assert_eq!(
            (
                targeted.action,
                targeted.word_0x96_150,
                targeted.source_byte_3e,
            ),
            (
                level2_class5::dragon::DRAGON_ATTACK_ACTION,
                player_entity_index,
                31,
            )
        );
        assert_eq!(
            targeted.entity_rng,
            campaign_shared_families::next_source_rng16(
                campaign_shared_families::next_source_rng16(dragon_before_target.entity_rng)
            )
        );
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .fireball_projectiles()
                .len(),
            projectile_count_before,
            "action 1 only selects action 2; it does not recursively fire"
        );
        assert!(
            campaign.simulation().effect_journal().records()[journal_before_target..]
                .iter()
                .all(|record| !matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        #[cfg(test)]
                        audio_site: crate::MissionAudioSite::DragonFireball,
                        ..
                    })
                ))
        );

        let dragon_before_fire = targeted;
        let terrain = &campaign.simulation().session.state.live.terrain;
        let fire_transition = crate::ground_creature_motion::step_ground_creature_motion(
            dragon_before_fire.position,
            dragon_before_fire.yaw,
            dragon_before_fire.roll,
            dragon_before_fire.actual_speed,
            terrain,
            crate::ground_creature_motion::GroundCreatureMotionConfig {
                ground_clearance: 0,
                descent: -4,
                turn_limit: 34,
                terrain_mask: u32::MAX,
                maximum_tile_slope: 30,
                half_width: dragon_before_fire.shift_rot_x,
                half_height: dragon_before_fire.shift_rot_y,
            },
        );
        let mut fire_target_position = fire_transition.position;
        crate::move_entity(&mut fire_target_position, fire_transition.yaw, 0, 2_048);
        let mut expected_launch_position = fire_transition.position;
        expected_launch_position.z = expected_launch_position.z.wrapping_add(140);
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_attack_prerequisite_for_test(
                    dragon_slot,
                    dragon_before_fire.position,
                    60,
                )
        );
        campaign
            .simulation_mut()
            .set_level2_entity_position(player_entity_index, fire_target_position)
            .expect("stage the real target inside the Dragon fire range");
        let journal_before_fire = campaign.simulation().effect_journal().records().len();
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert!(player_entity_index < dragon_slot, "player source visit precedes Dragon fire");
        let source_target_position = live.core.state.position;
        let (expected_yaw, expected_pitch) = crate::level1_mission::projectile_guidance_angles(
            fire_transition.position,
            source_target_position,
        );
        let fired = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == dragon_slot)
            .expect("firing Dragon remains live");
        assert_eq!(
            (fired.action, fired.word_0x96_150, fired.source_byte_3e,),
            (
                level2_class5::dragon::DRAGON_ATTACK_ACTION,
                player_entity_index,
                61,
            )
        );
        let projectile = live
            .economy
            .economy
            .fireball_projectiles()
            .iter()
            .find(|projectile| {
                projectile.origin == FireballProjectileOrigin::Dragon
                    && projectile.owner_entity_index == dragon_slot
            })
            .expect("Dragon action 2 allocates the shared class-9 fireball");
        let projectile_visited = projectile.source_entity_index > dragon_slot;
        let mut expected_projectile_position = expected_launch_position;
        let mut expected_projectile_pitch = expected_pitch;
        if projectile_visited {
            // sub_1CC20 aims at the actor's position; the later sub_65820
            // visit guides toward the current actor's collision centre.
            let guidance_target = Position {
                z: source_target_position.z.wrapping_add(
                    live.economy.entities[usize::from(player_entity_index)].array_yaw(),
                ),
                ..source_target_position
            };
            let (_, desired_pitch) = crate::level1_mission::projectile_guidance_angles(
                expected_launch_position,
                guidance_target,
            );
            expected_projectile_pitch = expected_projectile_pitch.wrapping_add(crate::turn_toward(
                expected_projectile_pitch,
                desired_pitch,
                22,
            )) & 0x07ff;
            crate::move_entity(
                &mut expected_projectile_position,
                expected_yaw,
                expected_projectile_pitch,
                crate::level1_mission::FIREBALL_SPEED,
            );
        }
        assert_eq!(
            (
                projectile.source_class,
                projectile.source_model,
                projectile.action,
                projectile.payload,
                projectile.target_source_entity_index,
                projectile.position,
                projectile.yaw,
                projectile.pitch,
                projectile.acquisition_attempted,
            ),
            (
                9,
                0,
                0,
                500,
                player_entity_index,
                expected_projectile_position,
                expected_yaw,
                expected_projectile_pitch,
                // sub_1CC20 already bound word96; guided acquisition is not
                // attempted for that preselected source address.
                false,
            ),
            "Dragon source before={dragon_before_fire:?}, predicted_motion={fire_transition:?}, \
             target_before={fire_target_position:?}, target_after={:?}, source_after={fired:?}, \
             projectile_visited={projectile_visited}, projectile={projectile:?}",
            live.core.state.position,
        );
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        assert_eq!(
            receipts.iter().any(|receipt| matches!(
                receipt,
                ScheduleReceipt::CallbackCompleted { slot, .. }
                    if *slot == projectile.source_entity_index
            )),
            projectile_visited
        );
        assert_eq!(
            i16::from_le_bytes([
                live.economy.entities[usize::from(player_entity_index)].record[58],
                live.economy.entities[usize::from(player_entity_index)].record[59],
            ]),
            100,
            "sub_1CC20 applies target feedback only after allocation succeeds"
        );
        let launch_sounds = campaign.simulation().effect_journal().records()[journal_before_fire..]
            .iter()
            .filter(|record| {
                matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        #[cfg(test)]
                        audio_site: crate::MissionAudioSite::DragonFireball,
                        entity_index,
                        player_index: -1,
                        sound_id: 8,
                    }) if entity_index == dragon_slot
                )
            })
            .count();
        assert_eq!(launch_sounds, 1);
        assert_eq!(
            crate::SOURCE_AUDIO_CALL_BINDINGS
                .iter()
                .find(|(tag, _)| *tag == SourceAudioCallTag::DragonAction02Fireball)
                .map(|(_, hash)| *hash),
            Some("328391c4a0c9cdb021d471d00d68353a68074f1301c07fe1aa3bd6c47991aa8d")
        );

        // The preceding route proves the complete death and source-boundary
        // reclaim of one real Dragon. Stage only that already-proven terminal
        // hide on the one remaining package Dragon so this continuation owns
        // the downstream semantic objective, objective gate, authored group,
        // and terrain-strip command lifecycle—not a duplicate combat proof.
        let remaining_dragons = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class5()
            .iter()
            .filter(|source| source.model == level2_class5::dragon::DRAGON_MODEL)
            .map(|source| source.source_entity_index)
            .collect::<Vec<_>>();
        assert_eq!(remaining_dragons, [dragon_slot]);
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .core
                .runtime
                .objectives[0]
                .stage_selectors[1],
            1
        );
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .stage_authored_dragon_terminal_hide_for_test(dragon_slot)
        );
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert!(live.economy.economy.authored_dragons().is_empty());
        assert!(live.economy.economy.authored_dragon_parts().is_empty());
        assert_eq!(live.core.runtime.objectives[0].stage_selectors[1], 2);
        assert_eq!(live.core.runtime.objectives[0].text_selector, 2);
        assert!(
            live.economy
                .economy
                .terrain_strip_close_triggers()
                .is_empty()
        );
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 2, .. }
                ))
        );

        // The Dragon-extinction selector belongs to the package's real group-5
        // gate. On the following numeric pass it constructs exactly the eleven
        // Goats and eighteen Archers authored for Level 3. The Goat rows reuse
        // the one shared Goat behavior family; their generic class-5 records
        // remain the NewEvent/map/hash projection.
        const GROUP5_GATE_SLOT: u16 = 218;
        const TERRAIN_GATE_SLOT: u16 = 128;
        const TERRAIN_CONTROLLER_SLOT: u16 = 94;
        let group5_gate_phase_before = campaign.simulation().session.state.live.economy.entities
            [usize::from(GROUP5_GATE_SLOT)]
        .phase;
        step(&mut campaign);
        let events = campaign.simulation().dispatch_events();
        assert!(events.iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: GROUP5_GATE_SLOT,
                group: 5,
                authored_indices,
                ..
            } if authored_indices.as_ref() == (166_u16..=194).collect::<Vec<_>>().as_slice()
        )));
        assert!(events.iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated { group: 2, .. }
        )));
        let live = &campaign.simulation().session.state.live;
        let group5_gate = &live.economy.entities[usize::from(GROUP5_GATE_SLOT)];
        assert!(group5_gate.active && group5_gate.drawing_disabled());
        assert_eq!(group5_gate.phase, group5_gate_phase_before.wrapping_add(1));
        let goat_roots = live
            .economy
            .economy
            .authored_class5()
            .iter()
            .filter(|source| source.model == crate::goat::GOAT_MODEL)
            .copied()
            .collect::<Vec<_>>();
        assert_eq!(
            goat_roots
                .iter()
                .map(|source| source.authored_index)
                .collect::<Vec<_>>(),
            (166_u16..=176).collect::<Vec<_>>()
        );
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        for (constructor_phase, source) in goat_roots.iter().enumerate() {
            let goat = live
                .goats
                .goats()
                .iter()
                .find(|goat| goat.entity_index == source.source_entity_index)
                .expect("every authored Goat root has one behavior carrier");
            let visited = source.source_entity_index > GROUP5_GATE_SLOT;
            assert_eq!(
                receipts.iter().any(|receipt| matches!(
                    receipt,
                    ScheduleReceipt::CallbackCompleted { slot, .. }
                        if *slot == source.source_entity_index
                )),
                visited
            );
            assert_eq!(
                (
                    goat.source_id,
                    goat.action,
                    goat.max_life,
                    goat.life,
                    goat.mana,
                    goat.minimum_speed,
                    goat.maximum_speed,
                    goat.actual_speed,
                    goat.render_parameter_index,
                ),
                (
                    source.source_entity_index,
                    crate::goat::GOAT_CONSTRUCTOR_ACTION,
                    crate::goat::GOAT_CONSTRUCTOR_LIFE,
                    crate::goat::GOAT_CONSTRUCTOR_LIFE,
                    crate::goat::GOAT_CONSTRUCTOR_MANA,
                    crate::goat::GOAT_CONSTRUCTOR_MINIMUM_SPEED,
                    crate::goat::GOAT_CONSTRUCTOR_MAXIMUM_SPEED,
                    crate::goat::GOAT_CONSTRUCTOR_MAXIMUM_SPEED,
                    crate::goat::GOAT_RENDER_PARAMETER_INDEX,
                )
            );
            assert_eq!(
                (
                    goat.collision_half_width,
                    goat.collision_half_depth,
                    goat.collision_vertical_offset,
                    goat.collision_half_height,
                    goat.control_flags,
                    goat.phase,
                ),
                (
                    crate::goat::GOAT_CONSTRUCTOR_COLLISION_HALF_EXTENT,
                    crate::goat::GOAT_CONSTRUCTOR_COLLISION_HALF_EXTENT,
                    crate::goat::GOAT_CONSTRUCTOR_COLLISION_HALF_EXTENT,
                    crate::goat::GOAT_CONSTRUCTOR_COLLISION_HALF_EXTENT,
                    8_u32,
                    u8::try_from(constructor_phase)
                        .expect("eleven Goat phases fit u8")
                        .wrapping_add(u8::from(visited)),
                )
            );
            assert_eq!(
                (
                    source.entity_rng,
                    source.action,
                    source.source_byte_3e,
                    source.source_byte_39,
                    source.position,
                    source.active,
                    source.drawing_enabled,
                ),
                (
                    goat.rng,
                    goat.action,
                    goat.phase,
                    goat.proximity_countdown.cast_unsigned(),
                    goat.position,
                    true,
                    true,
                )
            );
        }
        assert_eq!(live.core.runtime.objectives[0].stage_selectors[2], 1);

        // The package's stage-2 Castle-mana selector is serviced post-pass.
        // Group 5 does not itself satisfy that objective, and its authored
        // model-32 gate (row 145) must remain inert until the objective phase
        // observes the real Castle and secured-mana carriers. Castle building
        // and mana collection are not under test here: stage only those two
        // upstream prerequisites, then leave objective timing, the imported
        // model-32 gate's dispatch, group construction, and cleanup to the
        // ordinary scheduler.
        let terrain_gate = &live.economy.entities[usize::from(TERRAIN_GATE_SLOT)];
        assert_eq!(
            (
                terrain_gate.class,
                terrain_gate.model,
                terrain_gate.action,
                terrain_gate.source_id,
                terrain_gate.level_gate,
            ),
            (11, 32, 32, 2, 2)
        );
        let terrain_gate_phase = terrain_gate.phase;
        let controller_position = campaign.simulation().session.state.live.economy.entities
            [usize::from(TERRAIN_CONTROLLER_SLOT)]
        .position;
        let expected_trigger_position = Position {
            z: live.terrain.ground_height(controller_position),
            ..controller_position
        };
        let player_entity_index = live.core.state.entity_index;
        let player_position = live.core.state.position;
        let denominator = live.economy.economy.owner_mana_global();
        assert!(denominator > 0);
        let castle_slot = campaign
            .simulation_mut()
            .economy_mut()
            .build_castle(player_position, player_entity_index)
            .expect("the package arena can stage the Castle-mana prerequisite");
        assert!(
            campaign
                .simulation_mut()
                .economy_mut()
                .set_castle_mana_prerequisite_for_test(castle_slot, denominator)
        );
        let staged_economy = campaign.simulation().economy();
        let staged_castle = staged_economy
            .castle()
            .expect("the staged Castle remains the player Castle authority");
        assert_eq!(staged_economy.player_castle_entity_index(), castle_slot);
        assert_eq!(staged_castle.owner_entity_index, player_entity_index);
        assert!(
            100_i32
                * staged_economy
                    .owner_mana_aggregate(player_entity_index)
                    .saturating_add(staged_castle.mana)
                / staged_economy.owner_mana_global()
                >= 30
        );

        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        let post_objective_economy = &live.economy.economy;
        let post_objective_castle = post_objective_economy
            .castle()
            .expect("the player Castle remains live through objective service");
        let post_objective_percent = 100_i32
            * post_objective_economy
                .owner_mana_aggregate(player_entity_index)
                .saturating_add(post_objective_castle.mana)
            / post_objective_economy.owner_mana_global();
        assert_eq!(
            live.core.runtime.objectives[0].stage_selectors[2], 2,
            "post-pass Castle-mana percent is {post_objective_percent}"
        );
        let terrain_gate = &live.economy.entities[usize::from(TERRAIN_GATE_SLOT)];
        assert!(terrain_gate.active && !terrain_gate.drawing_disabled());
        assert_eq!(terrain_gate.phase, terrain_gate_phase.wrapping_add(1));
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 2, .. }
                ))
        );

        // Objective completion happens after numeric callbacks, so row 145
        // sees the completed selector and constructs the model-63 command only
        // on this following source pass.
        step(&mut campaign);
        let events = campaign.simulation().dispatch_events();
        assert!(
            events.iter().any(|event| matches!(
                event,
                Mc2DispatchEvent::AuthoredGroupActivated {
                    source_slot,
                    group: 2,
                    authored_indices,
                    ..
                } if *source_slot == TERRAIN_GATE_SLOT
                    && authored_indices.as_ref() == [146]
            )),
            "the following numeric pass must expose real group-2 activation: {events:?}"
        );
        let live = &campaign.simulation().session.state.live;
        let hidden_terrain_gate = &live.economy.entities[usize::from(TERRAIN_GATE_SLOT)];
        assert!(hidden_terrain_gate.active && hidden_terrain_gate.drawing_disabled());
        assert_eq!(
            hidden_terrain_gate.phase,
            terrain_gate_phase.wrapping_add(2)
        );
        let trigger = *live
            .economy
            .economy
            .terrain_strip_close_triggers()
            .iter()
            .find(|source| source.authored_index == 146)
            .expect("group 2 constructs authored terrain-strip row 146");
        let trigger_visited = trigger.source_entity_index > TERRAIN_GATE_SLOT;
        assert_eq!(
            (
                trigger.class,
                trigger.model,
                trigger.action,
                trigger.max_life,
                trigger.life,
                trigger.position,
                trigger.control_flags,
                trigger.drawing_enabled,
                trigger.active,
            ),
            (
                10,
                63,
                68,
                1,
                1,
                expected_trigger_position,
                if trigger_visited { 0x405 } else { 5 },
                !trigger_visited,
                !trigger_visited,
            )
        );
        assert_eq!(
            trigger.source_byte_3e,
            (trigger.source_entity_index as u8).wrapping_add(u8::from(trigger_visited))
        );
        let trigger_generation = live.economy.slot_generation(trigger.source_entity_index);
        let is_trigger_visit = |plan: &Level2ResolvedSourcePlan| {
            plan.observed_dynamic_cursor_row().is_some_and(|row| {
                row.source_slot == trigger.source_entity_index
                    && row.generation == trigger_generation
                    && row.kind == Level2DynamicArenaKind::TerrainStripCloseTrigger
            })
        };
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        assert_eq!(
            receipts.iter().any(|receipt| matches!(
                receipt,
                ScheduleReceipt::CallbackCompleted { slot, selector, .. }
                    if *slot == trigger.source_entity_index && is_trigger_visit(selector)
            )),
            trigger_visited
        );

        if !trigger_visited {
            step(&mut campaign);
        }
        let live = &campaign.simulation().session.state.live;
        let hidden_trigger = live
            .economy
            .economy
            .terrain_strip_close_triggers()
            .iter()
            .find(|source| source.source_entity_index == trigger.source_entity_index)
            .expect("close command remains allocated through its epilogue");
        assert_eq!(
            (
                hidden_trigger.control_flags,
                hidden_trigger.drawing_enabled,
                hidden_trigger.active,
                hidden_trigger.source_byte_3e,
                live.economy.entities[usize::from(TERRAIN_CONTROLLER_SLOT)].life,
            ),
            (
                0x405,
                false,
                false,
                (trigger.source_entity_index as u8).wrapping_add(1),
                2,
            )
        );
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        assert!(receipts.iter().any(|receipt| matches!(
            receipt,
            ScheduleReceipt::CallbackCompleted { slot, selector, .. }
                if *slot == trigger.source_entity_index && is_trigger_visit(selector)
        )));
        assert!(receipts.iter().any(|receipt| matches!(
            receipt,
            ScheduleReceipt::EpilogueCompleted { slot, original, .. }
                if *slot == trigger.source_entity_index && is_trigger_visit(original)
        )));

        let terrain_before_close = campaign.terrain_hash();
        let journal_before_close = campaign.simulation().effect_journal().records().len();
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert!(
            live.economy
                .economy
                .terrain_strip_close_triggers()
                .iter()
                .all(|source| source.source_entity_index != trigger.source_entity_index)
        );
        assert!(!live.economy.entities[usize::from(TERRAIN_GATE_SLOT)].active);
        assert_ne!(campaign.terrain_hash(), terrain_before_close);
        assert!(
            campaign.simulation().effect_journal().records()[journal_before_close..]
                .iter()
                .any(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        entity_index: TERRAIN_CONTROLLER_SLOT,
                        sound_id: 47,
                        ..
                    })
                ))
        );

        campaign.reset();
        assert_eq!(campaign.state_hash(), baseline_hash);
        assert!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_dragons()
                .is_empty()
        );
        assert!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_dragon_parts()
                .is_empty()
        );
    }

    #[test]
    fn cf14_level3_bee_source_audio_preserves_callback_rng_and_cadence() {
        const BEE_ROW: u16 = 149;

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let player_entity_index = campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;
        let feature = campaign
            .simulation()
            .session
            .state
            .live
            .mission
            .authored_features()
            .iter()
            .find(|feature| feature.index == BEE_ROW)
            .copied()
            .expect("Level 3 package contains Bee row 149");
        let initial = campaign
            .simulation_mut()
            .allocate_level2_authored_bee_feature(feature)
            .expect("package-present Bee allocates through its ordinary constructor");
        let source_slot = initial.source_entity_index;

        let mut target_after_move = initial.position;
        crate::move_entity(&mut target_after_move, initial.yaw, 0, initial.actual_speed);
        campaign
            .simulation_mut()
            .set_level2_entity_position(player_entity_index, target_after_move)
            .expect("place the real player on the Bee's post-move awareness point");
        let mut action17 = initial;
        action17.action = 17;
        action17.source_byte_3e = 0;
        action17.source_byte_39 = 1;
        action17.target_entity_index = Some(player_entity_index);
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .replace_authored_bee_for_test(action17)
        );

        let action17_cursor = campaign.simulation().effect_journal().records().len();
        let _ = campaign.step(PlayerCommand::default(), 0);
        let first = level2_next_rng16(initial.entity_rng);
        let second = level2_next_rng16(first);
        let third = level2_next_rng16(second);
        let acquired = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| source.source_entity_index == source_slot)
            .copied()
            .expect("action-17 Bee remains live");
        assert_eq!((acquired.action, acquired.entity_rng), (18, third));
        let action17_sounds = campaign.simulation().effect_journal().records()[action17_cursor..]
            .iter()
            .filter_map(|record| match record.effect {
                crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                    audio_site: crate::MissionAudioSite::BeeAttack,
                    entity_index,
                    player_index: -1,
                    sound_id,
                }) if entity_index == source_slot => Some((record.sequence, sound_id)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(action17_sounds.len(), 1);
        assert_eq!(action17_sounds[0].1, (third & 1) + 12);

        let off_cadence_rng = acquired.entity_rng;
        let off_cadence_cursor = campaign.simulation().effect_journal().records().len();
        let _ = campaign.step(PlayerCommand::default(), 0);
        let off_cadence = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| source.source_entity_index == source_slot)
            .copied()
            .expect("off-cadence Bee remains live");
        assert_eq!(off_cadence.entity_rng, off_cadence_rng);
        assert!(
            campaign.simulation().effect_journal().records()[off_cadence_cursor..]
                .iter()
                .all(|record| !matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        FlightEvent::PrepareSound {
                            audio_site: crate::MissionAudioSite::BeeAttack,
                            entity_index,
                            ..
                        }
                    ) if entity_index == source_slot
                ))
        );

        let mut contact = off_cadence;
        contact.source_byte_3e = 0;
        contact.control_flags |= LEVEL2_BEE_MOVEMENT_SKIP_BIT;
        contact.target_entity_index = Some(player_entity_index);
        let live_player_position = campaign.simulation().session.state.live.core.state.position;
        contact.position = Position {
            x: live_player_position.x.wrapping_add(
                u16::try_from(LEVEL2_BEE_CONTACT_RADIUS - 1).expect("Bee contact radius fits u16"),
            ),
            y: live_player_position.y,
            z: live_player_position.z,
        };
        assert!(
            campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .replace_authored_bee_for_test(contact)
        );
        let contact_cursor = campaign.simulation().effect_journal().records().len();
        let _ = campaign.step(PlayerCommand::default(), 0);
        let contact_rng = level2_next_rng16(off_cadence_rng);
        let contacted = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| source.source_entity_index == source_slot)
            .copied()
            .expect("contacting Bee remains live");
        assert_eq!(contacted.entity_rng, contact_rng);
        let contact_sounds = campaign.simulation().effect_journal().records()[contact_cursor..]
            .iter()
            .filter_map(|record| match record.effect {
                crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                    audio_site: crate::MissionAudioSite::BeeAttack,
                    entity_index,
                    player_index: -1,
                    sound_id,
                }) if entity_index == source_slot => Some((record.sequence, sound_id)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(contact_sounds.len(), 1);
        assert_eq!(contact_sounds[0].1, (contact_rng & 1) + 12);
        assert!(action17_sounds[0].0 < contact_sounds[0].0);

        for (tag, expected_hash) in [
            (
                SourceAudioCallTag::BeeAction17Acquire,
                "2200cca745cfe455d9fbd0dc0624b00c43948b2f8e7ee9236b34fc4a0a86f4f4",
            ),
            (
                SourceAudioCallTag::BeeAction18Contact,
                "61ff6913f34e4284a2b98125cb5ea0915db5e5530e9ab5c567cb216e87cec4d6",
            ),
        ] {
            assert_eq!(
                crate::SOURCE_AUDIO_CALL_BINDINGS
                    .iter()
                    .find(|(candidate, _)| *candidate == tag)
                    .map(|(_, hash)| *hash),
                Some(expected_hash)
            );
        }
    }

    #[test]
    fn cf14_level3_reach_bees_morph_and_final_dragons_follow_package_order() {
        const REACH_GATE_SLOT: u16 = 129;
        const FINAL_GATE_SLOT: u16 = 132;
        const REACH_STAGE: usize = 3;
        const BEE_STAGE: usize = 4;
        const BEE_ROWS: [u16; 6] = [149, 150, 152, 153, 154, 155];
        const FINAL_DRAGON_ROWS: [u16; 3] = [128, 131, 132];

        #[track_caller]
        fn step_with_command(campaign: &mut CampaignSession, command: PlayerCommand) {
            let _ = campaign.step(command, 0);
            assert!(
                campaign
                    .simulation()
                    .dispatch_events()
                    .iter()
                    .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. })),
                "Level 3 final-chain dispatch errors: {:?}",
                campaign.simulation().dispatch_events()
            );
        }

        #[track_caller]
        fn step(campaign: &mut CampaignSession) {
            step_with_command(campaign, PlayerCommand::default());
        }

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let baseline_hash = campaign.state_hash();
        let player_entity_index = campaign
            .simulation()
            .session
            .state
            .live
            .core
            .state
            .entity_index;

        // Skeleton, Dragon, and Castle-mana behavior are proven separately.
        // Stage only those upstream objective results; this test begins at
        // the real reach-location predicate and retains every later producer,
        // numeric callback, objective pause, constructor, and acquisition.
        {
            let runtime = &mut campaign.simulation_mut().session.state.live.core.runtime;
            for stage_index in 0..REACH_STAGE {
                runtime.set_level2_objective_stage_selector_for(0, stage_index, 2);
            }
            runtime.set_level2_objective_text_selector_for(0, REACH_STAGE);
        }

        let target = Position {
            x: 110_u16.wrapping_mul(256),
            y: 110_u16.wrapping_mul(256),
            z: campaign
                .simulation()
                .session
                .state
                .live
                .core
                .state
                .position
                .z,
        };
        let outside = Position {
            x: target.x.wrapping_add(
                u16::try_from(LEVEL2_OBJECTIVE_POINT_RADIUS + 1)
                    .expect("Level 3 objective radius fits u16"),
            ),
            ..target
        };
        campaign
            .simulation_mut()
            .set_level2_entity_position(player_entity_index, outside)
            .expect("stage the real player just outside the reach radius");
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            live.core.runtime.objectives[0].stage_selectors[REACH_STAGE],
            1
        );
        assert!(live.economy.economy.bee_creatures().is_empty());
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 3, .. }
                ))
        );

        campaign
            .simulation_mut()
            .set_level2_entity_position(player_entity_index, target)
            .expect("move the real player onto the package reach point");
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            live.core.runtime.objectives[0].stage_selectors[REACH_STAGE],
            2
        );
        assert_eq!(
            live.core.runtime.objectives[0].text_selector,
            BEE_STAGE as u8
        );
        assert!(live.economy.economy.bee_creatures().is_empty());
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 3, .. }
                ))
        );

        // Objective evaluation is post-pass. The imported model-32 gate sees
        // the completed selector only on the following numeric visit, then
        // synchronously constructs the six package Bees in authored order.
        step(&mut campaign);
        let events = campaign.simulation().dispatch_events();
        assert!(events.iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: REACH_GATE_SLOT,
                group: 3,
                authored_indices,
                ..
            } if authored_indices.as_ref() == BEE_ROWS
        )));
        let live = &campaign.simulation().session.state.live;
        assert_eq!(
            live.core.runtime.objectives[0].stage_selectors[BEE_STAGE],
            1
        );
        let bees = live.economy.economy.bee_creatures();
        assert_eq!(
            bees.iter()
                .filter_map(BeeCreatureRuntime::authored_index)
                .collect::<Vec<_>>(),
            BEE_ROWS
        );
        let bee_slots = bees
            .iter()
            .map(|source| source.source_entity_index)
            .collect::<Vec<_>>();
        assert!(
            bee_slots.windows(2).all(|slots| slots[0] < slots[1]),
            "the shared allocator assigns the package rows in authored order: {bee_slots:?}"
        );
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        for (constructor_phase, bee) in bees.iter().enumerate() {
            let visited = bee.source_entity_index > REACH_GATE_SLOT;
            assert_eq!(
                (
                    bee.source_entity_index,
                    bee.action,
                    bee.stage_var1,
                    bee.stage_var2,
                    bee.stage_target,
                    bee.source_byte_3e,
                ),
                (
                    bee_slots[constructor_phase],
                    23,
                    3,
                    2,
                    Some(Position {
                        x: 111_u16.wrapping_mul(256),
                        y: 142_u16.wrapping_mul(256),
                        z: 0,
                    }),
                    u8::try_from(constructor_phase)
                        .expect("six Bee phases fit u8")
                        .wrapping_add(u8::from(visited)),
                )
            );
            assert_eq!(
                receipts.iter().any(|receipt| matches!(
                    receipt,
                    ScheduleReceipt::CallbackCompleted { slot, .. }
                        if *slot == bee.source_entity_index
                )),
                visited
            );
            assert_eq!(
                receipts.iter().any(|receipt| matches!(
                    receipt,
                    ScheduleReceipt::EpilogueCompleted { slot, .. }
                        if *slot == bee.source_entity_index
                )),
                visited
            );
        }

        // Supply source-shaped combat damage to each actual package Bee.
        // Their callbacks, death conversion, reclaim and the absence census
        // all run normally; no terminal hide or objective result is staged.
        let bee_lives = bees.iter().map(|bee| (bee.source_entity_index, bee.life))
            .collect::<Vec<_>>();
        let kill_credit_before = live.economy.economy.authored_bee_kill_census(player_entity_index);
        for &(slot, life) in &bee_lives {
            assert!(campaign.simulation_mut().economy_mut()
                .stage_bee_mailbox_damage_for_test(slot, player_entity_index, life + 1));
        }
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(live.core.runtime.objectives[0].stage_selectors[BEE_STAGE], 1,
            "the pass-start census still contains the Bees that consumed lethal damage");
        assert!(live.economy.economy.bee_creatures().iter().all(|bee|
            bee.life < 0 && bee.action == 20 && bee.drawing_enabled));
        step(&mut campaign);
        let live = &campaign.simulation().session.state.live;
        assert_eq!(live.economy.economy.bee_creatures().len(), BEE_ROWS.len());
        assert!(live.economy.economy.bee_creatures().iter().all(|bee|
            bee.life < 0 && bee.action == 21 && bee.drawing_enabled),
            "the absence census excludes dead Bees before their conversion and reclaim");
        assert_eq!(live.economy.economy.authored_bee_kill_census(player_entity_index),
            kill_credit_before + u32::try_from(BEE_ROWS.len()).unwrap());
        assert_eq!(
            live.core.runtime.objectives[0].stage_selectors[BEE_STAGE],
            2
        );
        assert!(
            campaign
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 4, .. }
                ))
        );

        step(&mut campaign);
        let events = campaign.simulation().dispatch_events();
        assert!(events.iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot: FINAL_GATE_SLOT,
                group: 4,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [127, 157]
        )));
        let live = &campaign.simulation().session.state.live;
        let final_switch = *live
            .economy
            .economy
            .authored_switch_producers()
            .iter()
            .find(|source| source.authored_index == 127)
            .expect("group 4 constructs its package model-0 switch");
        assert_eq!(
            (
                final_switch.source_class,
                final_switch.model,
                final_switch.action,
                final_switch.stage_tag,
                final_switch.position.x,
                final_switch.position.y,
            ),
            (
                11,
                0,
                0,
                12,
                target.x.wrapping_add(128),
                target.y.wrapping_add(128),
            )
        );
        let morph_slot = *live
            .shared_spells
            .authored_pickup_slots()
            .get(&157)
            .expect("group 4 constructs the package Morph pickup");
        let morph = live
            .shared_spells
            .dynamic_pickups()
            .iter()
            .find(|pickup| pickup.index == morph_slot)
            .expect("Morph pickup remains in the shared entity authority");
        assert_eq!((morph.class, morph.model, morph.action,), (15, 4, 13));
        assert_ne!(morph_slot, final_switch.source_entity_index);
        assert_eq!(
            (
                morph.subspell_index,
                morph.source_spell_word_30(),
                morph.mana_regen,
                morph.max_mana,
                morph.mana,
            ),
            (100, 201, 20_000, 5_000, 24)
        );
        assert!(events.iter().all(|event| !matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated { group: 12, .. }
        )));

        let journal_start = campaign.simulation().effect_journal().records().len();
        // Row 127 is not an eager area trigger. NewEvent may reuse any current
        // free slot, so pin the source rule rather than a stale slot number:
        // model-0 fires only on phase&7==0 and Morph acquires only on
        // phase&3==0. Every disallowed visit must remain inert.
        let mut saw_morph_acquisition = false;
        let mut firing_switch_phase = None;
        for _ in 0..8 {
            let live = &campaign.simulation().session.state.live;
            let switch = live
                .economy
                .economy
                .authored_switch_producers()
                .iter()
                .find(|source| source.source_entity_index == final_switch.source_entity_index)
                .expect("final switch remains allocated until its source cadence");
            let morph = live
                .shared_spells
                .dynamic_pickups()
                .iter()
                .find(|pickup| pickup.index == morph_slot)
                .expect("Morph pickup remains allocated through acquisition");
            let switch_may_fire = switch.phase & 7 == 0;
            let morph_may_acquire = morph.action == 13 && morph.phase & 3 == 0;
            let switch_phase = switch.phase;

            step(&mut campaign);
            let events = campaign.simulation().dispatch_events();
            let fired_group12 = events.iter().any(|event| {
                matches!(
                    event,
                    Mc2DispatchEvent::AuthoredGroupActivated { group: 12, .. }
                )
            });
            let acquired_morph = events.iter().any(|event| {
                matches!(
                    event,
                    Mc2DispatchEvent::SpellAcquisition {
                        source_slot,
                        family: 4,
                        result: Some(_),
                        ..
                    } if *source_slot == morph_slot
                )
            });
            assert_eq!(fired_group12, switch_may_fire);
            assert_eq!(acquired_morph, morph_may_acquire);
            saw_morph_acquisition |= acquired_morph;
            if fired_group12 {
                firing_switch_phase = Some(switch_phase);
                break;
            }
        }
        assert!(firing_switch_phase.is_some_and(|phase| phase & 7 == 0));

        let events = campaign.simulation().dispatch_events();
        assert!(events.iter().any(|event| matches!(
            event,
            Mc2DispatchEvent::AuthoredGroupActivated {
                source_slot,
                group: 12,
                authored_indices,
                ..
            } if *source_slot == final_switch.source_entity_index
                && authored_indices.as_ref() == FINAL_DRAGON_ROWS
        )));
        let hidden_switch = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_switch_producers()
            .iter()
            .find(|source| source.source_entity_index == final_switch.source_entity_index)
            .expect("final switch remains allocated through its firing epilogue");
        assert!(hidden_switch.fired && !hidden_switch.drawing_enabled);
        assert_eq!(
            hidden_switch.phase,
            firing_switch_phase
                .expect("the final switch fired")
                .wrapping_add(1)
        );

        // These two constructors have independent source phases. Reused
        // slots can put model0's phase&7 firing before the pickup's first
        // phase&3 acquisition visit; source 6F030 does not wait for Morph.
        // Keep the firing-pass epilogue checks above, then require the real
        // pickup to acquire on its next eligible ordinary callback.
        for _ in 0..4 {
            if saw_morph_acquisition {
                break;
            }
            let morph = campaign
                .simulation()
                .shared_spells()
                .pickup(morph_slot)
                .expect("Morph remains live until acquisition");
            let may_acquire = morph.action == 13 && morph.phase & 3 == 0;
            step(&mut campaign);
            let acquired = campaign.simulation().dispatch_events().iter().any(|event| {
                matches!(event, Mc2DispatchEvent::SpellAcquisition {
                    source_slot, family: 4, result: Some(_), ..
                } if *source_slot == morph_slot)
            });
            assert_eq!(acquired, may_acquire);
            assert!(
                !campaign.simulation().dispatch_events().iter().any(
                    |event| matches!(event, Mc2DispatchEvent::AuthoredGroupActivated {
                    source_slot, group: 12, ..
                } if *source_slot == final_switch.source_entity_index)
                ),
                "the consumed final switch must not fire again"
            );
            saw_morph_acquisition |= acquired;
        }
        assert!(saw_morph_acquisition);

        // The objective can advance while action21 bodies are still waiting
        // for their phase-gated conversion. Retain the already-observed group
        // 4 and group 12 events above while the ordinary cursor finishes them.
        for _ in 0..9 {
            if campaign.simulation().economy().bee_creatures().iter().all(|bee|
                !bee.authored_index().is_some_and(|row| BEE_ROWS.contains(&row))) { break; }
            step(&mut campaign);
        }
        assert!(campaign.simulation().economy().bee_creatures().iter().all(|bee|
            !bee.authored_index().is_some_and(|row| BEE_ROWS.contains(&row))),
            "all six original Bee bodies convert and reclaim on their own source cadence");

        let live = &campaign.simulation().session.state.live;
        let morph = live
            .shared_spells
            .dynamic_pickups()
            .iter()
            .find(|pickup| pickup.index == morph_slot)
            .expect("the acquired Morph holder keeps the same source slot");
        assert_eq!(
            (
                morph.model,
                morph.action,
                morph.source_spell_parent_entity_index()
            ),
            (4, 12, player_entity_index)
        );
        let player = live
            .core
            .players
            .iter()
            .find(|player| player.entity_index == player_entity_index)
            .expect("local Level 3 player authority");
        assert_eq!(player.enabled_spell_holders[4], morph_slot);
        assert_eq!(player.acquired_spell_flags[4], 1);
        assert_eq!(
            live.economy
                .economy
                .authored_class5()
                .iter()
                .filter(|source| source.model == level2_class5::dragon::DRAGON_MODEL)
                .map(|source| source.authored_index)
                .filter(|authored_index| FINAL_DRAGON_ROWS.contains(authored_index))
                .collect::<Vec<_>>(),
            FINAL_DRAGON_ROWS
        );
        let effects = &campaign.simulation().effect_journal().records()[journal_start..];
        let sound_sequence = effects
            .iter()
            .find_map(|record| match record.effect {
                crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                    entity_index,
                    sound_id: 18,
                    ..
                }) if entity_index == player_entity_index => Some(record.sequence),
                _ => None,
            })
            .expect("Morph pickup sound 18");
        let acquired_sequence = effects
            .iter()
            .find_map(|record| match record.effect {
                crate::campaign::journal::CampaignEffect::SharedSpell(
                    Level2SharedSpellEvent::SpellAcquired {
                        source_slot,
                        family: 4,
                        ..
                    },
                ) if source_slot == morph_slot => Some(record.sequence),
                _ => None,
            })
            .expect("Morph acquisition receipt");
        assert!(sound_sequence < acquired_sequence);

        // Stage only Morph's already-proven Castle-mana and caster-mana
        // prerequisites. The real acquired holder, public spell command,
        // numeric holder visit, shared arena allocation, and follower visit
        // remain production-owned below.
        let player_position = campaign.simulation().session.state.live.core.state.position;
        let castle_slot = campaign
            .simulation_mut()
            .economy_mut()
            .build_castle(player_position, player_entity_index)
            .expect("the package arena can stage Morph's Castle prerequisite");
        assert!(
            campaign
                .simulation_mut()
                .economy_mut()
                .set_castle_mana_prerequisite_for_test(castle_slot, 20_000)
        );
        {
            let live = &mut campaign.simulation_mut().session.state.live;
            live.economy.refresh_owner_mana_rows();
            live.shared_spells.player_entity.set_mana(5_000);
            let player_snapshot = live.shared_spells.player_entity.clone();
            for player in &mut live.shared_spells.player_entities {
                if player.index == player_entity_index {
                    *player = player_snapshot.clone();
                }
            }
            live.shared_spells.caster.mana = 5_000;
            live.shared_spells.player_mana = 5_000;
            live.economy.entities[usize::from(player_entity_index)].set_mana(5_000);
        }
        let pre_cast_bee_count = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_creatures()
            .len();
        let pre_cast_sound_cursor = campaign.simulation().effect_journal().records().len();
        let pre_cast_experience = campaign
            .simulation()
            .session
            .state
            .live
            .shared_spells
            .spell_experience()[4];
        assert!(morph_slot > player_entity_index,
            "after real Bee deaths the acquired holder follows the player in source order");
        // Preserve an idle clone for the isolated allocator-failure branch.
        // Its holder will be armed there at the handler boundary; the success
        // branch uses the actual public command and numeric scheduler.
        let mut allocation_failure = campaign.clone();
        let success_journal_cursor = pre_cast_sound_cursor;
        step_with_command(
            &mut campaign,
            PlayerCommand {
                opcode: 6,
                argument_1: 4,
                flags: 0x40,
                ..PlayerCommand::default()
            },
        );
        let player_mana_before_pulse = campaign
            .simulation()
            .session
            .state
            .live
            .shared_spells
            .player_entity
            .mana;
        let success_live = &campaign.simulation().session.state.live;
        let holder = success_live
            .shared_spells
            .dynamic_pickups()
            .iter()
            .find(|holder| holder.index == morph_slot)
            .expect("Morph holder remains live after its first pulse");
        assert_eq!(holder.active_value, 200);
        // Following-pass reclamation and earlier numeric callbacks share
        // NewEvent. The live holder relation, rather than a pre-pass free
        // stack prediction, names this constructor's actual body.
        let expected_bee_slot = holder.source_word_96();
        assert_ne!(expected_bee_slot, 0);
        let morph_bee = success_live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| {
                source.source_entity_index == expected_bee_slot
                    && source.origin
                        == BeeCreatureOrigin::MorphSpell {
                            holder_slot: morph_slot,
                        }
            })
            .copied()
            .expect("Morph's first pulse constructs one semantic Bee");
        assert_eq!(success_live.economy.economy.bee_creatures().len(), pre_cast_bee_count + 1);
        assert_eq!(morph_bee.parent_entity_index, player_entity_index);
        assert_eq!(morph_bee.entity_id, player_entity_index);
        let bee_visited_on_birth_pass = expected_bee_slot > morph_slot;
        assert_eq!(
            (
                morph_bee.source_class,
                morph_bee.model,
                morph_bee.action,
                morph_bee.stage_var1,
                morph_bee.stage_var2,
                morph_bee.parent_entity_index,
                morph_bee.control_flags,
            ),
            (5, 2, 23, 0, 12, player_entity_index, 13)
        );
        assert_eq!(
            (
                morph_bee.minimum_speed,
                morph_bee.maximum_speed,
                morph_bee.actual_speed,
                morph_bee.max_life,
                morph_bee.life,
                morph_bee.mana,
                morph_bee.subspell_index,
            ),
            (64, 30, 32, 3_000, 3_000, 1_500, 200,)
        );
        assert_eq!(morph_bee.phase, u8::from(bee_visited_on_birth_pass));
        let expected_angle = (morph_bee.entity_rng & 0x07ff) as i16 - 1;
        let followed_parent = success_live.core.state;
        assert_eq!(
            (morph_bee.yaw, morph_bee.pitch, morph_bee.roll),
            (
                if bee_visited_on_birth_pass {
                    followed_parent.yaw
                } else {
                    expected_angle
                },
                expected_angle,
                if bee_visited_on_birth_pass {
                    followed_parent.roll_accumulator
                } else {
                    expected_angle
                },
            )
        );
        assert_eq!(morph_bee.position, followed_parent.position);
        assert_eq!(
            success_live.shared_spells.spell_experience()[4],
            pre_cast_experience.wrapping_add(1)
        );
        assert_eq!(
            (
                success_live.shared_spells.player_entity.mana_regen,
                success_live
                    .shared_spells
                    .player_entities
                    .iter()
                    .find(|entity| entity.index == player_entity_index)
                    .expect("local shared player")
                    .mana_regen,
                success_live.economy.entities[usize::from(player_entity_index)].mana_regen,
            ),
            (-5_000, -5_000, -5_000),
            "the later holder leaves Morph's charge for the next player visit"
        );
        assert_eq!(
            (
                success_live.shared_spells.player_entity.mana,
                success_live
                    .shared_spells
                    .player_entities
                    .iter()
                    .find(|entity| entity.index == player_entity_index)
                    .expect("local shared player")
                    .mana,
                success_live.economy.entities[usize::from(player_entity_index)].mana,
            ),
            (
                player_mana_before_pulse,
                player_mana_before_pulse,
                player_mana_before_pulse,
            ),
            "the player has already visited before the holder charges regeneration"
        );
        assert_eq!(success_live.shared_spells.caster.control_flags & 0x21, 0x21);
        assert_eq!(
            success_live
                .core
                .context
                .spell_fire
                .as_ref()
                .expect("Morph command context")
                .caster
                .control_flags
                & 0x21,
            0x21
        );
        let success_effects =
            &campaign.simulation().effect_journal().records()[success_journal_cursor..];
        assert_eq!(
            success_effects
                .iter()
                .filter(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        FlightEvent::PrepareSound {
                            entity_index,
                            sound_id: 60,
                            ..
                        }
                    ) if entity_index == player_entity_index
                ))
                .count(),
            1
        );
        assert_eq!(
            crate::SOURCE_AUDIO_CALL_BINDINGS
                .iter()
                .find(|(tag, _)| *tag == SourceAudioCallTag::MorphSpellStart)
                .map(|(_, hash)| *hash),
            Some("51d9ecbc8c8301f053d666cd4dd85e983569ca314534fa5e57d0a2d5014eaeaf")
        );
        let receipts = campaign.simulation().cf10_production_schedule_receipts();
        let holder_callback = receipts
            .iter()
            .position(|receipt| {
                matches!(
                    receipt,
                    ScheduleReceipt::CallbackCompleted { slot, .. } if *slot == morph_slot
                )
            })
            .expect("Morph holder receives its numeric callback");
        let player_callback = receipts.iter().position(|receipt| matches!(receipt,
            ScheduleReceipt::CallbackCompleted { slot, .. } if *slot == player_entity_index))
            .expect("the player receives its numeric callback");
        assert!(player_callback < holder_callback);
        let bee_callback = receipts.iter().position(|receipt| {
            matches!(
                receipt,
                ScheduleReceipt::CallbackCompleted { slot, .. }
                    if *slot == expected_bee_slot
            )
        });
        assert_eq!(bee_callback.is_some(), bee_visited_on_birth_pass);
        if let Some(bee_callback) = bee_callback {
            assert!(holder_callback < bee_callback);
        }

        let mut non_expiry = campaign.clone();
        let non_expiry_effect_cursor = non_expiry.simulation().effect_journal().records().len();
        step(&mut non_expiry);
        let next_live = &non_expiry.simulation().session.state.live;
        assert_eq!(next_live.shared_spells.player_entity.mana,
            player_mana_before_pulse.wrapping_sub(5_000),
            "the next player visit consumes the holder's charge");
        assert_eq!((next_live.shared_spells.player_entity.mana_regen,
            next_live.shared_spells.player_entities.iter().find(|row| row.index == player_entity_index)
                .expect("local shared player").mana_regen,
            next_live.economy.entities[usize::from(player_entity_index)].mana_regen), (0, 0, 0),
            "the later active holder suppresses the positive rate selected by the player visit");
        assert!(
            non_expiry.simulation().effect_journal().records()[non_expiry_effect_cursor..]
                .iter()
                .all(|record| !matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        FlightEvent::PrepareSound {
                            entity_index,
                            sound_id: 60,
                            ..
                        }
                    ) if entity_index == player_entity_index
                )),
            "an ordinary non-expiry Morph pulse must not emit either terminal sound"
        );

        let mut morph_hash_negative = campaign.clone();
        let morph_hash = campaign.state_hash();
        morph_hash_negative
            .simulation_mut()
            .economy_mut()
            .bee_creatures
            .iter_mut()
            .find(|source| source.source_entity_index == expected_bee_slot)
            .expect("Morph Bee hash discriminator")
            .parent_entity_index ^= 1;
        assert_ne!(morph_hash_negative.state_hash(), morph_hash);

        // Stage only the terminal counter and queued SetSpell carrier on the
        // already-real holder/body relation. The ordinary holder visit must
        // disable the body, clear the parent flag, emit the expiry sound, and
        // only then install the queued tier. The next idle action-12 visit is
        // valid after installing the next source constructor tier.
        let mut queued_expiry = campaign.clone();
        let body_before_expiry = queued_expiry
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| source.source_entity_index == expected_bee_slot)
            .copied()
            .expect("live Morph body before expiry");
        {
            let holder = queued_expiry
                .simulation_mut()
                .session
                .state
                .live
                .shared_spells
                .pickup_mut(morph_slot)
                .expect("queued-expiry Morph holder");
            holder.active_value = 1;
            holder.record[50..52].copy_from_slice(&1_i16.to_le_bytes());
            holder.set_source_word_2c(2);
        }
        let expiry_effect_cursor = queued_expiry.simulation().effect_journal().records().len();
        step(&mut queued_expiry);
        let expired_live = &queued_expiry.simulation().session.state.live;
        let expired_holder = expired_live
            .shared_spells
            .pickup(morph_slot)
            .expect("expired Morph holder remains owned");
        assert_eq!(
            (
                expired_holder.active_value,
                expired_holder.level_gate,
                expired_holder.activation_value,
                expired_holder.source_word_2c(),
                expired_holder.source_word_96(),
            ),
            (0, 1, 301, 0, 0)
        );
        assert_eq!(expired_live.shared_spells.caster.control_flags & 0x20, 0);
        let expired_body = expired_live
            .economy
            .economy
            .bee_creatures()
            .iter()
            .find(|source| source.source_entity_index == expected_bee_slot)
            .expect("disabled Morph body remains until the next source boundary");
        assert!(expired_body.active && !expired_body.drawing_enabled);
        assert_eq!(
            queued_expiry
                .simulation()
                .creature_kind_for_source_slot(expected_bee_slot),
            Some(CreatureKind::Bee),
            "the terminal Morph origin remains dispatchable after expiry clears the holder back-reference"
        );
        assert_eq!(
            (expired_body.source_byte_3e, expired_body.phase),
            (
                body_before_expiry.source_byte_3e.wrapping_add(1),
                body_before_expiry.phase.wrapping_add(1),
            ),
            "the pre-existing Morph body gets exactly one numeric callback in the expiry pass; slot order decides whether it runs before or after the holder hide"
        );
        assert_eq!(
            queued_expiry.simulation().effect_journal().records()[expiry_effect_cursor..]
                .iter()
                .filter(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        FlightEvent::PrepareSound {
                            entity_index,
                            sound_id: 60,
                            ..
                        }
                    ) if entity_index == player_entity_index
                ))
                .count(),
            1
        );
        assert_eq!(
            crate::SOURCE_AUDIO_CALL_BINDINGS
                .iter()
                .find(|(tag, _)| *tag == SourceAudioCallTag::MorphSpellExpiry)
                .map(|(_, hash)| *hash),
            Some("687653fd4ce5b3a30b90f6928339af0e948c20a8ad7f048e005ca8885c7887c6")
        );
        assert!(
            queued_expiry
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. }))
        );
        step(&mut queued_expiry);
        assert!(
            queued_expiry
                .simulation()
                .dispatch_events()
                .iter()
                .all(|event| !matches!(event, Mc2DispatchEvent::Error { .. })),
            "an idle queued tier must not require an unimplemented Morph product"
        );
        assert!(
            queued_expiry
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .all(|source| source.source_entity_index != expected_bee_slot),
            "the following source boundary reclaims the disabled Morph body"
        );
        assert!(
            !queued_expiry
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .map_chains()
                .is_linked(expected_bee_slot)
        );
        assert!(
            queued_expiry
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .free_slots
                .contains(&expected_bee_slot),
            "Morph reclaim returns the exact NewEvent slot"
        );

        let mut severed_relation = campaign.clone();
        severed_relation
            .simulation_mut()
            .session
            .state
            .live
            .shared_spells
            .pickup_mut(morph_slot)
            .expect("Morph holder exists in the semantic negative")
            .clear_source_word_96();
        let _ = severed_relation.step(PlayerCommand::default(), 0);
        assert!(
            severed_relation
                .simulation()
                .dispatch_events()
                .iter()
                .any(|event| matches!(
                    event,
                    Mc2DispatchEvent::Error {
                        source_slot,
                        message,
                        ..
                    } if *source_slot == expected_bee_slot
                        && message.contains("no package-authored semantic identity")
                )),
            "a Morph Bee without its live holder relation must fail semantic dispatch"
        );

        // The selector-12 body follows the live player carrier and preserves
        // numeric ordering. A lower-slot body observes the preceding turn's
        // public orientation; a higher-slot body observes it in the same pass.
        let pre_turn_player = campaign.simulation().session.state.live.core.state;
        step_with_command(
            &mut campaign,
            PlayerCommand {
                roll: 127,
                ..PlayerCommand::default()
            },
        );
        if expected_bee_slot > player_entity_index {
            let live = &campaign.simulation().session.state.live;
            let follower = live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .find(|source| source.source_entity_index == expected_bee_slot)
                .expect("same-pass Morph follower");
            assert_eq!(
                (follower.position, follower.yaw, follower.roll),
                (
                    live.core.state.position,
                    live.core.state.yaw,
                    live.core.state.roll_accumulator,
                )
            );
        } else {
            let follower = campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .find(|source| source.source_entity_index == expected_bee_slot)
                .expect("pre-player Morph follower");
            assert_eq!(
                (follower.position, follower.yaw, follower.roll),
                (
                    pre_turn_player.position,
                    pre_turn_player.yaw,
                    pre_turn_player.roll_accumulator,
                )
            );
        }

        // Let the real player callback publish the staged resources and
        // Castle relation in this idle clone, as it did before the successful
        // holder visit. Then stage only the source arming write at the holder
        // boundary so no prepass can free a slot before allocation.
        step(&mut allocation_failure);
        {
            let holder = allocation_failure.simulation_mut().session.state.live.shared_spells
                .pickup_mut(morph_slot).expect("the acquired Morph holder survives in the clone");
            holder.active_value = holder.activation_value.cast_signed();
            holder.record[50..52].copy_from_slice(&holder.active_value.to_le_bytes());
        }
        let failure_mana_before_pulse = allocation_failure.simulation().shared_spells()
            .player_entity().mana;
        let failure_sound_cursor = allocation_failure
            .simulation()
            .effect_journal()
            .records()
            .len();
        let removed_slot = allocation_failure
            .simulation_mut()
            .session
            .state
            .live
            .economy
            .economy
            .exhaust_new_event_capacity_for_test()
            .expect("failure branch removes a real free slot");
        {
            let arena = &mut allocation_failure
                .simulation_mut()
                .session
                .state
                .live
                .economy;
            for row in &mut arena.entities {
                row.set_control_flags(
                    row.control_flags & !crate::level1_mission::SOURCE_REPLACEABLE_FLAG,
                );
            }
            arena.finish_source_group();
        }
        {
            let session = allocation_failure.simulation();
            let holder = session.shared_spells().pickup(morph_slot).unwrap();
            let parent = session.current_morph_parent(player_entity_index).unwrap().unwrap();
            let castle_mana = source_target::status_castle_mana(
                &session.session.state.live.economy,
                &session.session.state.live.shared_spells,
                &parent,
            ).unwrap();
            assert_eq!((holder.active_value, holder.activation_value), (201, 201));
            assert!(parent.life >= 0 && parent.mana >= holder.max_mana
                && castle_mana.is_some_and(|mana| mana >= holder.mana_regen),
                "failure branch must reach the same source gate as a paid first pulse: parent life={} mana={} cost={} castle={castle_mana:?} requirement={}",
                parent.life, parent.mana, holder.max_mana, holder.mana_regen);
        }
        let failure_constructor_phase = allocation_failure
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .bee_model2_constructor_phase;
        // Isolate failure at the actual handler boundary: an outer pass may
        // legitimately reclaim another address before this numeric visit.
        assert!(
            allocation_failure
                .simulation_mut()
                .step_dynamic_morph_holder(0, morph_slot)
        );
        allocation_failure.simulation_mut().flush_shared_effects();
        let failed_live = &allocation_failure.simulation().session.state.live;
        let failed_holder = failed_live
            .shared_spells
            .dynamic_pickups()
            .iter()
            .find(|holder| holder.index == morph_slot)
            .expect("failed allocation still consumes the Morph pulse");
        assert_eq!(
            (failed_holder.active_value, failed_holder.source_word_96()),
            (200, 0)
        );
        assert_eq!(
            failed_live.shared_spells.spell_experience()[4],
            pre_cast_experience.wrapping_add(1)
        );
        assert_eq!(failed_live.shared_spells.player_entity.mana_regen, -5_000);
        assert_eq!(
            failed_live.shared_spells.player_entity.mana,
            failure_mana_before_pulse
        );
        assert_eq!(
            failed_live.economy.economy.bee_model2_constructor_phase,
            failure_constructor_phase
        );
        assert_eq!(
            failed_live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .filter(|source| matches!(source.origin, BeeCreatureOrigin::MorphSpell { .. }))
                .count(),
            0
        );
        assert!(
            allocation_failure.simulation().effect_journal().records()[failure_sound_cursor..]
                .iter()
                .all(|record| !matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        sound_id: 60,
                        ..
                    })
                ))
        );
        assert!(
            allocation_failure
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .economy
                .restore_new_event_slot_for_test(removed_slot)
        );
        step(&mut allocation_failure);
        let failed_live = &allocation_failure.simulation().session.state.live;
        let failed_holder = failed_live
            .shared_spells
            .dynamic_pickups()
            .iter()
            .find(|holder| holder.index == morph_slot)
            .expect("Morph holder remains live after the failed first pulse");
        assert_eq!(
            (failed_holder.active_value, failed_holder.source_word_96()),
            (199, 0)
        );
        assert_eq!(
            failed_live.shared_spells.player_entity.mana,
            failure_mana_before_pulse.wrapping_sub(5_000),
            "the following ordinary player visit must consume the failed cast's charge"
        );
        assert_eq!(
            failed_live
                .economy
                .economy
                .bee_creatures()
                .iter()
                .filter(|source| matches!(source.origin, BeeCreatureOrigin::MorphSpell { .. }))
                .count(),
            0,
            "restoring capacity must not retry a consumed first pulse"
        );
        allocation_failure.reset();
        assert_eq!(allocation_failure.state_hash(), baseline_hash);

        // Group 12's Dragons are real combatants, but the package's last
        // objective is Bee absence, not Dragon absence. Exercise their death
        // and body cleanup independently from the exit branch below: the
        // already-proven damage mailbox is the only staged combat input.
        let mut dragon_combat = campaign.clone();
        let final_dragons = dragon_combat.simulation().economy().authored_class5().iter()
            .filter(|source| FINAL_DRAGON_ROWS.contains(&source.authored_index)
                && source.model == level2_class5::dragon::DRAGON_MODEL)
            .map(|source| (source.source_entity_index, source.life))
            .collect::<Vec<_>>();
        assert_eq!(final_dragons.len(), FINAL_DRAGON_ROWS.len());
        for &(slot, life) in &final_dragons {
            assert!(dragon_combat.simulation_mut().session.state.live.economy.economy
                .submit_authored_dragon_damage(slot, life + 1, player_entity_index));
        }
        let mut dragon_death_bursts = [false; 3];
        for _ in 0..32 {
            step(&mut dragon_combat);
            let economy = dragon_combat.simulation().economy();
            for (index, (slot, _)) in final_dragons.iter().enumerate() {
                dragon_death_bursts[index] |= economy.events().iter().any(|event| matches!(event,
                    Level2EconomyEvent::DeathBurstSpawned { parent_entity_index, .. }
                        if parent_entity_index == slot
                ));
            }
            if final_dragons.iter().all(|(slot, _)| {
                economy.authored_class5().iter().all(|root| root.source_entity_index != *slot)
                    && economy.authored_dragon_parts().iter().all(|part| part.entity_id != *slot)
            }) {
                break;
            }
        }
        let economy = dragon_combat.simulation().economy();
        for (index, (slot, _)) in final_dragons.iter().enumerate() {
            assert!(economy.authored_class5().iter().all(|root| root.source_entity_index != *slot));
            assert!(economy.authored_dragon_parts().iter().all(|part| part.entity_id != *slot));
            assert!(dragon_death_bursts[index], "each final Dragon root reaches its own death producer");
        }

        // Continue the unmodified objective branch. No selector, win flag,
        // or exit group is staged: the Bee census above must cause the real
        // objective and its authored producer to expose the package exit.
        for _ in 0..256 {
            if campaign.simulation().campaign_exit_objective_target().is_some() {
                break;
            }
            step(&mut campaign);
        }
        let session = campaign.simulation();
        assert_eq!(session.runtime().objectives[0].stage_selectors[BEE_STAGE], 2);
        assert_eq!(session.runtime().objectives[0].is_level_end, 1);
        assert_eq!(session.economy().authored_class5().iter().filter(|source|
            FINAL_DRAGON_ROWS.contains(&source.authored_index)
                && source.model == level2_class5::dragon::DRAGON_MODEL).count(), 3,
            "the final Dragons do not gate the Bee objective or exit");
        let (exit_slot, exit_position) = session.campaign_exit_objective_target()
            .expect("the completed Bee objective produces the live authored exit");
        assert!(session.economy().authored_switch_producers().iter().any(|source|
            source.source_entity_index == exit_slot && (source.model, source.action) == (12, 12)));
        campaign.simulation_mut().set_level2_entity_position(player_entity_index, exit_position)
            .expect("move the real player into the born exit trigger");
        for _ in 0..16 {
            if campaign.simulation().level_exit_sequence().active { break; }
            step(&mut campaign);
        }
        assert!(campaign.simulation().level_exit_sequence().active,
            "the real authored overlap starts the source exit sequence");
        for _ in 0..700 {
            if campaign.simulation().level_exit_sequence().complete { break; }
            step(&mut campaign);
        }
        let session = campaign.simulation();
        assert!(session.level_exit_sequence().complete);
        assert_eq!(session.level_exit_sequence().result_code, 10);
        assert_eq!(session.session.state.live.source_player_result.result_byte(), 0x0a);

        campaign.reset();
        assert_eq!(campaign.state_hash(), baseline_hash);
    }

    #[test]
    fn cf14_level3_ballistic_death_spawns_then_reclaims_on_production_boundaries() {
        fn arm_lethal_contact(campaign: &mut CampaignSession) -> (u8, u16, u32, usize) {
            let live = &mut campaign.simulation_mut().session.state.live;
            let source = &mut live.economy.entities[245];
            assert_eq!((source.class, source.model, source.action), (2, 8, 21));
            let mut position = source.position;
            position.z = live.terrain.ground_height(position);
            source.set_position(position);
            source.set_control_flags(0);
            source.set_actual_speed(0);
            source.set_source_word_2c(0);
            source.set_life(50);
            source.set_source_upkeep_payload(100);
            source.record[102..104].copy_from_slice(&7_u16.to_le_bytes());
            (
                source.phase,
                source.entity_rng,
                live.economy.global_rng,
                live.economy.economy.model59_smoke_children().len(),
            )
        }

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let reset_hash = campaign.state_hash();
        let (phase_before, entity_rng_before, global_rng_before, smoke_count_before) =
            arm_lethal_contact(&mut campaign);
        let next16 = |seed: u16| seed.wrapping_mul(9_377).wrapping_add(9_439);
        let next32 = |seed: u32| seed.wrapping_mul(9_377).wrapping_add(9_439);

        let first_evidence = campaign.step(PlayerCommand::default(), 0);
        let first_state_hash = campaign.state_hash();
        let first_events = campaign.events().to_vec();
        let source = &campaign.simulation().session.state.live.economy.entities[245];
        assert_eq!(source.life, -50);
        assert!(source.drawing_disabled());
        assert!(source.active, "hide is retained until the next prepass");
        assert_eq!(source.phase, phase_before.wrapping_add(1));
        assert_eq!(
            source.entity_rng,
            next16(next16(next16(entity_rng_before))),
            "grounded lethal contact consumes the exact three local draws"
        );
        assert_eq!(source.source_upkeep_word_62(), 0);
        assert_eq!(
            campaign.simulation().source_global_rng(),
            next32(next32(global_rng_before)),
            "UpdateEntities and the smoke constructor each consume one global draw"
        );
        let smoke_children = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .model59_smoke_children();
        assert_eq!(smoke_children.len(), smoke_count_before + 1);
        assert!(smoke_children.last().is_some_and(|child| child.active));

        let _ = campaign.step(PlayerCommand::default(), 0);
        let reclaimed = &campaign.simulation().session.state.live.economy.entities[245];
        assert!(!reclaimed.active);
        assert_eq!(reclaimed.class, 0);
        assert!(
            !campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .map_chains()
                .linked_entity_indices()
                .contains(&245)
        );

        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);
        let _ = arm_lethal_contact(&mut campaign);
        let replay_evidence = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(replay_evidence, first_evidence);
        assert_eq!(campaign.events(), first_events.as_slice());
        assert_eq!(campaign.state_hash(), first_state_hash);

        // `SetParticleSmoke3B` advances the global stream before NewEvent.
        // When both allocation paths are exhausted, the source still hides,
        // phase-advances, and reclaims the ballistic row; only the child is
        // absent and the constructor draw remains observable.
        campaign.reset();
        let (phase_before, entity_rng_before, global_rng_before, smoke_count_before) =
            arm_lethal_contact(&mut campaign);
        {
            let economy = &mut campaign.simulation_mut().session.state.live.economy.economy;
            economy.free_slots.clear();
            for _ in 0..1_000 {
                economy.decrement_replacement_cursor_after_player_contact();
            }
        }
        let _ = campaign.step(PlayerCommand::default(), 0);
        let live = &campaign.simulation().session.state.live;
        let source = &live.economy.entities[245];
        assert!(source.active && source.drawing_disabled());
        assert_eq!(source.phase, phase_before.wrapping_add(1));
        assert_eq!(source.entity_rng, next16(next16(next16(entity_rng_before))));
        assert_eq!(
            live.economy.economy.model59_smoke_children().len(),
            smoke_count_before
        );
        assert_eq!(
            live.economy.economy.global_rng,
            next32(next32(global_rng_before))
        );
        let _ = campaign.step(PlayerCommand::default(), 0);
        let source = &campaign.simulation().session.state.live.economy.entities[245];
        assert!(!source.active);
        assert_eq!(source.class, 0);
    }

    #[test]
    fn cf14_level3_countdown_fires_group_once_then_reclaims_on_production_boundary() {
        fn remove_blocking_roots(campaign: &mut CampaignSession) {
            let roots = campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .entities
                .iter()
                .filter(|row| row.active && row.class == 5 && row.model == 3 && row.action == 31)
                .map(|row| row.index)
                .collect::<Vec<_>>();
            assert_eq!(roots.len(), 5);
            for slot in roots {
                campaign
                    .simulation_mut()
                    .session
                    .state
                    .live
                    .economy
                    .entities[usize::from(slot)]
                .disable_drawing();
            }
        }

        fn fire(campaign: &mut CampaignSession) {
            remove_blocking_roots(campaign);
            for _ in 0..17 {
                let _ = campaign.step(PlayerCommand::default(), 0);
            }
        }

        fn exhaust_source_allocator(campaign: &mut CampaignSession) {
            let session = campaign.simulation_mut();
            std::sync::Arc::make_mut(&mut session.session.baseline)
                .economy
                .economy
                .free_slots
                .clear();
            let economy = &mut session.session.state.live.economy.economy;
            economy.free_slots.clear();
            for row in &mut economy.castle_children {
                row.control_flags &= !SOURCE_REPLACEABLE_FLAG;
            }
            macro_rules! make_nonreplaceable {
                ($rows:expr) => {
                    for row in &mut $rows {
                        row.control_flags &= !SOURCE_REPLACEABLE_FLAG;
                    }
                };
            }
            make_nonreplaceable!(economy.spheres);
            make_nonreplaceable!(economy.death_bursts);
            make_nonreplaceable!(economy.authored_model1);
            make_nonreplaceable!(economy.model59_smoke_children);
            make_nonreplaceable!(economy.authored_model5_water_splashes);
            make_nonreplaceable!(economy.authored_model13);
            make_nonreplaceable!(economy.authored_model6);
            make_nonreplaceable!(economy.model13_spawned_children);
            make_nonreplaceable!(economy.model17_spawned_children);
            make_nonreplaceable!(economy.model76_tail_spawns);
        }

        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let reset_hash = campaign.state_hash();
        let phase_before = campaign.simulation().session.state.live.economy.entities[247].phase;
        fire(&mut campaign);

        let producer = &campaign.simulation().session.state.live.economy.entities[247];
        assert_eq!(
            producer.source_dword_10(),
            1,
            "countdown events after the fire window: {:#?}",
            campaign.events()
        );
        assert!(producer.drawing_disabled());
        assert!(producer.active);
        assert_eq!(producer.phase, phase_before.wrapping_add(17));
        let constructed = campaign
            .simulation()
            .session
            .state
            .live
            .economy
            .economy
            .authored_class14()
            .iter()
            .filter(|row| (247..=256).contains(&row.authored_index))
            .count();
        assert_eq!(constructed, 10);

        let effects = campaign
            .effects_after(
                crate::campaign::journal::EffectCursor {
                    generation: campaign.generation(),
                    next_sequence: 0,
                },
                16_384,
            )
            .expect("complete countdown journal page");
        let sound_sequence = effects
            .records
            .iter()
            .find_map(|record| match record.effect {
                crate::campaign::journal::CampaignEffect::Flight(
                    crate::FlightEvent::PrepareSound {
                        entity_index: 247,
                        player_index: -1,
                        sound_id: 41,
                        ..
                    },
                ) => Some(record.sequence),
                _ => None,
            })
            .expect("countdown sound 41");
        let activation_sequence = effects
            .records
            .iter()
            .find_map(|record| match &record.effect {
                crate::campaign::journal::CampaignEffect::Dispatch(
                    crate::native_world::Mc2DispatchEvent::AuthoredGroupActivated {
                        source_slot: 247,
                        group: 11,
                        authored_indices,
                        ..
                    },
                ) if authored_indices.as_ref() == (247_u16..=256).collect::<Vec<_>>() => {
                    Some(record.sequence)
                }
                _ => None,
            })
            .expect("countdown group-11 activation");
        assert!(sound_sequence < activation_sequence);

        let _ = campaign.step(PlayerCommand::default(), 0);
        let final_hash = campaign.state_hash();
        let final_effects = campaign
            .effects_after(
                crate::campaign::journal::EffectCursor {
                    generation: campaign.generation(),
                    next_sequence: 0,
                },
                16_384,
            )
            .expect("complete post-cleanup journal page")
            .records;
        let producer = &campaign.simulation().session.state.live.economy.entities[247];
        assert!(!producer.active);
        assert_eq!(producer.class, 0);
        assert_eq!(
            final_effects
                .iter()
                .filter(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        crate::FlightEvent::PrepareSound {
                            entity_index: 247,
                            sound_id: 41,
                            ..
                        }
                    )
                ))
                .count(),
            1
        );

        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);
        fire(&mut campaign);
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(campaign.state_hash(), final_hash);
        assert_eq!(
            campaign
                .effects_after(
                    crate::campaign::journal::EffectCursor {
                        generation: campaign.generation(),
                        next_sequence: 0,
                    },
                    16_384,
                )
                .expect("replayed countdown journal")
                .records,
            final_effects
        );

        // `sub_4A1E0(id, 1)` consumes every authored row even when NewEvent
        // cannot allocate it. Exhaust both the reconstructed reset pool and
        // the live pool after the five multipart roots have been reclaimed;
        // the countdown still sounds, journals all ten attempted rows, hides,
        // phase-advances, and reclaims on the next source boundary.
        campaign.reset();
        remove_blocking_roots(&mut campaign);
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(
            campaign.simulation().session.state.live.economy.entities[247].source_dword_10(),
            16
        );
        {
            let live = &mut campaign.simulation_mut().session.state.live;
            for row in &mut live.economy.entities {
                if row.class == 5 && row.model == 3 {
                    row.reclaim_source_row();
                }
            }
            live.economy.entities[247].set_source_dword_10(1);
        }
        exhaust_source_allocator(&mut campaign);
        let _ = campaign.step(PlayerCommand::default(), 0);
        let producer = &campaign.simulation().session.state.live.economy.entities[247];
        assert!(producer.active && producer.drawing_disabled());
        assert_eq!(producer.phase, phase_before.wrapping_add(2));
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .economy
                .economy
                .authored_class14()
                .iter()
                .filter(|row| (247..=256).contains(&row.authored_index))
                .count(),
            0
        );
        let exhausted_effects = campaign
            .effects_after(
                crate::campaign::journal::EffectCursor {
                    generation: campaign.generation(),
                    next_sequence: 0,
                },
                16_384,
            )
            .expect("exhausted countdown journal")
            .records;
        assert!(exhausted_effects.iter().any(|record| matches!(
            &record.effect,
            crate::campaign::journal::CampaignEffect::Dispatch(
                crate::native_world::Mc2DispatchEvent::AuthoredGroupActivated {
                    source_slot: 247,
                    group: 11,
                    authored_indices,
                    ..
                }
            ) if authored_indices.as_ref() == (247_u16..=256).collect::<Vec<_>>()
        )));
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert!(!campaign.simulation().session.state.live.economy.entities[247].active);
    }

    #[test]
    fn cf14_level3_terrain_controller_preserves_rng_audio_and_reset() {
        let package = level_three_descriptor_fixture_path();
        let mut campaign = CampaignSession::open(&package, CampaignSelection::LEVEL3)
            .expect("qualified Level 3 descriptor opens");
        let reset_hash = campaign.state_hash();
        let terrain_rng = campaign
            .simulation()
            .session
            .state
            .live
            .terrain
            .terrain_rng();
        let controller_rng =
            campaign.simulation().session.state.live.economy.entities[94].entity_rng;

        // Group 2's real row-146 command is proven in the package-chain test.
        // Start at its resulting controller state here so this focused test
        // owns only the package-present controller callback and replay.
        {
            let controller = &mut campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .entities[94];
            controller.set_life(2);
        }
        let terrain_before = campaign.terrain_hash();
        let _ = campaign.step(PlayerCommand::default(), 0);
        let controller = &campaign.simulation().session.state.live.economy.entities[94];
        assert_eq!((controller.life, controller.subspell_index), (2, 47));
        assert_ne!(campaign.terrain_hash(), terrain_before);
        assert_eq!(controller.entity_rng, controller_rng);
        assert_eq!(
            campaign
                .simulation()
                .session
                .state
                .live
                .terrain
                .terrain_rng(),
            terrain_rng
        );
        assert!(
            campaign
                .effects_after(
                    crate::campaign::journal::EffectCursor {
                        generation: campaign.generation(),
                        next_sequence: 0,
                    },
                    16_384,
                )
                .expect("terrain close journal")
                .records
                .iter()
                .any(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(
                        crate::FlightEvent::PrepareSound {
                            entity_index: 94,
                            sound_id: 47,
                            ..
                        }
                    )
                ))
        );
        let close_hash = campaign.state_hash();
        let close_effects = campaign
            .effects_after(
                crate::campaign::journal::EffectCursor {
                    generation: campaign.generation(),
                    next_sequence: 0,
                },
                16_384,
            )
            .expect("complete terrain close replay journal")
            .records;

        campaign.reset();
        assert_eq!(campaign.state_hash(), reset_hash);
        {
            let controller = &mut campaign
                .simulation_mut()
                .session
                .state
                .live
                .economy
                .entities[94];
            controller.set_life(2);
        }
        let _ = campaign.step(PlayerCommand::default(), 0);
        assert_eq!(campaign.state_hash(), close_hash);
        assert_eq!(
            campaign
                .effects_after(
                    crate::campaign::journal::EffectCursor {
                        generation: campaign.generation(),
                        next_sequence: 0,
                    },
                    16_384,
                )
                .expect("replayed terrain close journal")
                .records,
            close_effects
        );
    }

